CREATE FUNCTION private.current_identity_id() RETURNS uuid LANGUAGE plpgsql STABLE
SECURITY INVOKER SET search_path = '' AS $$
DECLARE c jsonb := nullif(current_setting('request.jwt.claims',true),'')::jsonb;
