--
-- Name: acknowledge_tournament_document(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acknowledge_tournament_document(p_version_id uuid, p_confirm boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_document public.tournament_documents%rowtype;
  v_version public.tournament_document_versions%rowtype;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select version.* into v_version
  from public.tournament_document_versions version
  where version.id = p_version_id and version.status = 'published';
  select * into v_document
  from public.tournament_documents document
  where document.id = v_version.document_id
    and document.active_version_id = p_version_id
    and document.status = 'published';
  if v_document.id is null
    or not public.can_access_tournament_communications(v_document.tournament_id)
    or (
      v_document.category_id is not null
      and not public.can_read_tournament_participant_hub(
        v_document.tournament_id,v_document.category_id
      )
      and not public.has_tournament_communications_capability(
        v_document.organization_id,'documents.read'
      )
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_DOCUMENT_FORBIDDEN';
  end if;
  insert into public.tournament_document_acknowledgements (
    organization_id,document_id,version_id,user_id,status,confirmed_at
  ) values (
    v_document.organization_id,v_document.id,p_version_id,private.current_identity_id(),
    case when p_confirm then 'confirmed' else 'read' end,
    case when p_confirm then now() else null end
  )
  on conflict (version_id,user_id) do update set
    status = case when p_confirm then 'confirmed'
      else public.tournament_document_acknowledgements.status end,
    confirmed_at = case when p_confirm then
      coalesce(public.tournament_document_acknowledgements.confirmed_at,now())
      else public.tournament_document_acknowledgements.confirmed_at end;
  return jsonb_build_object(
    'documentId',v_document.id,'versionId',p_version_id,
    'status',case when p_confirm then 'confirmed' else 'read' end,
    'confirmationIsLegalAcceptance',false
  );
end;
$$;


--
-- Name: activate_verified_fake_tournament_purchase(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_verified_fake_tournament_purchase(p_purchase_id uuid, p_provider_payment_id text DEFAULT NULL::text, p_simulated_activation_error_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_environment text;
begin
  select provider_environment into v_environment
  from public.tournament_purchases where id = p_purchase_id;
  return public.activate_verified_tournament_purchase(
    p_purchase_id,'FAKE',v_environment,'approved',null,p_provider_payment_id,
    p_simulated_activation_error_code
  );
end;
$$;


--
-- Name: activate_verified_tournament_purchase(uuid, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_verified_tournament_purchase(p_purchase_id uuid, p_provider text, p_provider_environment text, p_provider_status text, p_provider_status_detail text DEFAULT NULL::text, p_provider_payment_id text DEFAULT NULL::text, p_simulated_activation_error_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_purchase public.tournament_purchases%rowtype;
  v_offer public.tournament_commercial_offers%rowtype;
  v_product public.tournament_commercial_products%rowtype;
  v_grant_id uuid;
  v_from_status text;
begin
  select * into v_purchase from public.tournament_purchases where id = p_purchase_id for update;
  if v_purchase.id is null or v_purchase.provider <> p_provider
    or v_purchase.provider_environment <> p_provider_environment
    or v_purchase.provider_preference_id is null
    or (p_provider = 'MERCADO_PAGO' and (p_provider_environment <> 'test' or p_provider_payment_id is null)) then
    raise exception using errcode = '22023', message = 'TORNEOS_PURCHASE_INVALID';
  end if;
  if v_purchase.status = 'approved' and v_purchase.entitlement_activated_at is not null then
    if p_provider_payment_id is not null
      and v_purchase.approved_provider_payment_id is distinct from p_provider_payment_id then
      raise exception using errcode = '55000', message = 'TORNEOS_PAYMENT_CONFLICT';
    end if;
    return public.tournament_purchase_projection(v_purchase) || jsonb_build_object('idempotentReplay',true);
  end if;
  if v_purchase.status not in ('preference_created','pending','approved') then
    raise exception using errcode = '55000', message = 'TORNEOS_PURCHASE_TRANSITION_INVALID';
  end if;
  v_from_status := v_purchase.status;
  update public.tournament_purchases
  set activation_attempts = activation_attempts + 1,last_verified_at = now()
  where id = v_purchase.id returning * into v_purchase;
  if p_simulated_activation_error_code is not null then
    update public.tournament_purchases
    set activation_error_code = left(p_simulated_activation_error_code,80)
    where id = v_purchase.id returning * into v_purchase;
    insert into public.tournament_purchase_events (
      purchase_id,organization_id,event_type,from_status,to_status,provider_status,actor_type,metadata
    ) values (
      v_purchase.id,v_purchase.organization_id,'activation.failed',v_purchase.status,
      v_purchase.status,p_provider_status,'service',
      jsonb_build_object('errorCode',v_purchase.activation_error_code,'seasonId',v_purchase.season_id)
    );
    return public.tournament_purchase_projection(v_purchase);
  end if;
  select * into v_offer from public.tournament_commercial_offers
  where product_code = v_purchase.product_code and offer_code = v_purchase.offer_code
    and offer_version = v_purchase.offer_version;
  select * into v_product from public.tournament_commercial_products
  where product_code = v_purchase.product_code;
  if v_offer.product_code is null or v_product.plan_code <> 'PREMIUM'
    or v_product.scope <> 'season' or v_product.billing_model <> 'one_time'
    or v_offer.list_amount <> v_purchase.list_amount_snapshot
    or v_offer.amount <> v_purchase.amount_snapshot
    or v_offer.currency <> v_purchase.currency then
    update public.tournament_purchases set activation_error_code = 'snapshot_mismatch'
    where id = v_purchase.id returning * into v_purchase;
    return public.tournament_purchase_projection(v_purchase);
  end if;
  v_grant_id := public.grant_tournament_season_premium(
    v_purchase.organization_id,v_purchase.season_id,v_purchase.id,
    'Pago ' || v_purchase.provider || ' verificado para la temporada y compra ' || v_purchase.id::text
  );
  insert into public.tournament_season_plan_grant_events (
    season_grant_id,purchase_id,event_type,reason_code,reason,actor_type
  ) select v_grant_id,v_purchase.id,'granted','payment_approved',
    'Premium de temporada activado por pago verificado','provider'
  where not exists (
    select 1 from public.tournament_season_plan_grant_events event
    where event.season_grant_id = v_grant_id and event.event_type = 'granted'
  );
  update public.tournament_purchases set
    status = 'approved',provider_status = left(btrim(p_provider_status),80),
    provider_status_detail = nullif(left(btrim(p_provider_status_detail),120),''),
    approved_provider_payment_id = coalesce(approved_provider_payment_id,p_provider_payment_id,'fake_pay_' || id::text),
    approved_at = coalesce(approved_at,now()),activation_error_code = null,
    entitlement_activated_at = coalesce(entitlement_activated_at,now()),last_verified_at = now()
  where id = v_purchase.id returning * into v_purchase;
  insert into public.tournament_purchase_events (
    purchase_id,organization_id,event_type,from_status,to_status,provider_status,
    provider_status_detail,actor_type,metadata
  ) values (
    v_purchase.id,v_purchase.organization_id,'payment.approved',v_from_status,'approved',
    v_purchase.provider_status,v_purchase.provider_status_detail,'provider',
    jsonb_build_object('providerPaymentId',v_purchase.approved_provider_payment_id,
      'seasonGrantId',v_grant_id,'seasonId',v_purchase.season_id)
  );
  insert into public.tournament_audit_log (
    organization_id,actor_user_id,actor_type,action,resource_type,resource_id,
    tournament_id,metadata
  ) values (
    v_purchase.organization_id,null,'system','billing.season_purchase_activated',
    'tournament_purchase',v_purchase.id,v_purchase.tournament_id,
    jsonb_build_object('seasonGrantId',v_grant_id,'seasonId',v_purchase.season_id)
  );
  return public.tournament_purchase_projection(v_purchase) || jsonb_build_object('idempotentReplay',false);
end;
$$;


--
-- Name: add_tournament_match_event(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_tournament_match_event(p_organization_id uuid, p_match_operation_id uuid, p_event jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_operation public.tournament_match_operations%rowtype;
  v_event public.tournament_match_events%rowtype;
  v_related_event public.tournament_match_events%rowtype;
  v_is_on_field boolean;
  v_sequence integer;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status <> 'draft'
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_events.create'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if (p_event->>'teamEntryId')::uuid not in (
    v_operation.home_team_entry_id, v_operation.away_team_entry_id
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_EVENT_TEAM_MISMATCH';
  end if;
  if p_event->>'rosterPlayerId' is not null and not exists (
    select 1 from public.tournament_match_operation_players player
    where player.match_operation_id = v_operation.id
      and player.roster_player_id = (p_event->>'rosterPlayerId')::uuid
      and (
        (p_event->>'eventType' = 'own_goal'
          and player.team_entry_id <> (p_event->>'teamEntryId')::uuid)
        or (p_event->>'eventType' <> 'own_goal'
          and player.team_entry_id = (p_event->>'teamEntryId')::uuid)
      )
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_EVENT_PLAYER_MISMATCH';
  end if;
  if p_event->>'relatedRosterPlayerId' is not null and not exists (
    select 1 from public.tournament_match_operation_players player
    where player.match_operation_id = v_operation.id
      and player.roster_player_id = (p_event->>'relatedRosterPlayerId')::uuid
      and player.team_entry_id = (p_event->>'teamEntryId')::uuid
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_EVENT_PLAYER_MISMATCH';
  end if;
  if p_event->>'eventType' not in ('assist', 'substitution_in')
    and (
      p_event->>'relatedEventId' is not null
      or p_event->>'relatedRosterPlayerId' is not null
    )
  then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_EVENT_RELATION_INVALID';
  end if;
  if p_event->>'eventType' = 'assist'
    and p_event->>'relatedRosterPlayerId' is not null
  then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_EVENT_RELATION_INVALID';
  end if;
  if p_event->>'eventType' = 'assist' and (
    p_event->>'relatedEventId' is null or not exists (
      select 1 from public.tournament_match_events goal
      where goal.id = (p_event->>'relatedEventId')::uuid
        and goal.match_operation_id = v_operation.id
        and goal.team_entry_id = (p_event->>'teamEntryId')::uuid
        and goal.event_type in ('goal', 'penalty_goal')
        and not (goal.event_type = 'penalty_goal' and goal.period = 'penalties')
        and goal.roster_player_id is not null
        and goal.roster_player_id <> (p_event->>'rosterPlayerId')::uuid
        and goal.voided_at is null
    )
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_ASSIST_WITHOUT_GOAL';
  end if;
  if p_event->>'rosterPlayerId' is not null and exists (
    select 1
    from public.tournament_match_operation_players player
    where player.match_operation_id = v_operation.id
      and player.roster_player_id = (p_event->>'rosterPlayerId')::uuid
      and player.attendance_status in ('absent', 'excused')
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_PLAYER_ABSENT';
  end if;
  if p_event->>'rosterPlayerId' is not null
    and p_event->>'eventType' not in ('incident', 'substitution_out')
    and exists (
      select 1 from public.tournament_match_events earlier
      where earlier.match_operation_id = v_operation.id
        and earlier.roster_player_id = (p_event->>'rosterPlayerId')::uuid
        and earlier.event_type in ('red_card', 'second_yellow')
        and earlier.voided_at is null
    )
  then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_PLAYER_ALREADY_SENT_OFF';
  end if;
  if p_event->>'eventType' = 'second_yellow' and not exists (
    select 1 from public.tournament_match_events earlier
    where earlier.match_operation_id = v_operation.id
      and earlier.roster_player_id = (p_event->>'rosterPlayerId')::uuid
      and earlier.event_type = 'yellow_card'
      and earlier.voided_at is null
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_SECOND_YELLOW_WITHOUT_FIRST';
  end if;
  if p_event->>'eventType' = 'substitution_out' then
    select (
      (
        player.lineup_status = 'starter'
        or exists (
          select 1
          from public.tournament_match_events entered
          where entered.match_operation_id = v_operation.id
            and entered.roster_player_id = player.roster_player_id
            and entered.event_type = 'substitution_in'
            and entered.voided_at is null
        )
      )
      and coalesce((
        select max(entered.sequence_number)
        from public.tournament_match_events entered
        where entered.match_operation_id = v_operation.id
          and entered.roster_player_id = player.roster_player_id
          and entered.event_type = 'substitution_in'
          and entered.voided_at is null
      ), 0) >= coalesce((
        select max(exited.sequence_number)
        from public.tournament_match_events exited
        where exited.match_operation_id = v_operation.id
          and exited.roster_player_id = player.roster_player_id
          and exited.event_type = 'substitution_out'
          and exited.voided_at is null
      ), 0)
    ) into v_is_on_field
    from public.tournament_match_operation_players player
    where player.match_operation_id = v_operation.id
      and player.roster_player_id = (p_event->>'rosterPlayerId')::uuid;
    if not coalesce(v_is_on_field, false) then
      raise exception using errcode = '23514', message = 'TORNEOS_MATCH_PLAYER_NOT_ON_FIELD';
    end if;
  end if;
  if p_event->>'eventType' = 'substitution_in' then
    if p_event->>'relatedEventId' is null
      or p_event->>'relatedRosterPlayerId' is null
      or (p_event->>'relatedRosterPlayerId')::uuid
        = (p_event->>'rosterPlayerId')::uuid
    then
      raise exception using errcode = '23514', message = 'TORNEOS_MATCH_SUBSTITUTION_INVALID';
    end if;
    select * into v_related_event
    from public.tournament_match_events
    where id = (p_event->>'relatedEventId')::uuid
      and match_operation_id = v_operation.id
      and team_entry_id = (p_event->>'teamEntryId')::uuid
      and roster_player_id = (p_event->>'relatedRosterPlayerId')::uuid
      and event_type = 'substitution_out'
      and voided_at is null;
    if v_related_event.id is null
      or v_related_event.minute is distinct from (p_event->>'minute')::smallint
      or v_related_event.period is distinct from coalesce(p_event->>'period', 'unknown')
    then
      raise exception using errcode = '23514', message = 'TORNEOS_MATCH_SUBSTITUTION_INVALID';
    end if;
    if exists (
      select 1
      from public.tournament_match_events entered
      where entered.match_operation_id = v_operation.id
        and entered.related_event_id = v_related_event.id
        and entered.event_type = 'substitution_in'
        and entered.voided_at is null
    ) then
      raise exception using errcode = '23514', message = 'TORNEOS_MATCH_SUBSTITUTION_INVALID';
    end if;
    select (
      (
        player.lineup_status = 'starter'
        or exists (
          select 1
          from public.tournament_match_events entered
          where entered.match_operation_id = v_operation.id
            and entered.roster_player_id = player.roster_player_id
            and entered.event_type = 'substitution_in'
            and entered.voided_at is null
        )
      )
      and coalesce((
        select max(entered.sequence_number)
        from public.tournament_match_events entered
        where entered.match_operation_id = v_operation.id
          and entered.roster_player_id = player.roster_player_id
          and entered.event_type = 'substitution_in'
          and entered.voided_at is null
      ), 0) >= coalesce((
        select max(exited.sequence_number)
        from public.tournament_match_events exited
        where exited.match_operation_id = v_operation.id
          and exited.roster_player_id = player.roster_player_id
          and exited.event_type = 'substitution_out'
          and exited.voided_at is null
      ), 0)
    ) into v_is_on_field
    from public.tournament_match_operation_players player
    where player.match_operation_id = v_operation.id
      and player.roster_player_id = (p_event->>'rosterPlayerId')::uuid;
    if coalesce(v_is_on_field, false) then
      raise exception using errcode = '23514', message = 'TORNEOS_MATCH_PLAYER_ALREADY_ON_FIELD';
    end if;
  end if;
  select coalesce(max(sequence_number), 0) + 1 into v_sequence
  from public.tournament_match_events where match_operation_id = v_operation.id;
  insert into public.tournament_match_events (
    organization_id, match_operation_id, match_id, team_entry_id,
    roster_player_id, related_roster_player_id, related_event_id,
    event_type, minute, period, sequence_number, unidentified_player_reason,
    metadata, created_by
  ) values (
    p_organization_id, v_operation.id, v_operation.match_id,
    (p_event->>'teamEntryId')::uuid,
    (p_event->>'rosterPlayerId')::uuid,
    (p_event->>'relatedRosterPlayerId')::uuid,
    (p_event->>'relatedEventId')::uuid,
    p_event->>'eventType', (p_event->>'minute')::smallint,
    coalesce(p_event->>'period', 'unknown'), v_sequence,
    nullif(btrim(p_event->>'unidentifiedPlayerReason'), ''),
    coalesce(p_event->'metadata', '{}'::jsonb), private.current_identity_id()
  ) returning * into v_event;
  if v_event.event_type = 'assist' and (
    v_event.related_event_id is null or not exists (
      select 1 from public.tournament_match_events goal
      where goal.id = v_event.related_event_id
        and goal.match_operation_id = v_operation.id
        and goal.team_entry_id = v_event.team_entry_id
        and goal.event_type in ('goal', 'penalty_goal')
        and not (goal.event_type = 'penalty_goal' and goal.period = 'penalties')
        and goal.roster_player_id is not null
        and goal.roster_player_id <> v_event.roster_player_id
        and goal.voided_at is null
    )
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_ASSIST_WITHOUT_GOAL';
  end if;
  perform public.append_tournament_audit(
    p_organization_id, 'match_event.added', 'match_event', v_event.id,
    v_event.team_entry_id, v_operation.tournament_id,
    jsonb_build_object('eventType', v_event.event_type, 'sequence', v_event.sequence_number)
  );
  return to_jsonb(v_event);
end;
$$;


--
-- Name: add_tournament_roster_player(uuid, uuid, uuid, uuid, uuid, text, text, smallint, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_tournament_roster_player(p_organization_id uuid, p_team_entry_id uuid, p_roster_id uuid, p_arma2_user_id uuid, p_provisional_player_id uuid, p_display_name text, p_avatar_url text, p_shirt_number smallint, p_primary_position text, p_secondary_position text, p_is_goalkeeper boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_entry public.tournament_team_entries%rowtype;
  v_roster public.tournament_rosters%rowtype;
  v_settings public.tournament_roster_settings%rowtype;
  v_player public.tournament_roster_players%rowtype;
  v_count integer;
  v_constraint_name text;
begin
  select * into v_entry from public.tournament_team_entries
  where id = p_team_entry_id and organization_id = p_organization_id;
  select * into v_roster from public.tournament_rosters
  where id = p_roster_id and team_entry_id = p_team_entry_id
    and organization_id = p_organization_id for update;
  if private.current_identity_id() is null or v_entry.id is null or v_roster.id is null
    or v_roster.status not in ('draft', 'changes_requested')
    or not public.can_edit_tournament_team_entry(
      p_organization_id,
      p_team_entry_id
    )
  then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  if num_nonnulls(p_arma2_user_id, p_provisional_player_id) <> 1 then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_PLAYER_IDENTITY';
  end if;
  select * into v_settings from public.tournament_roster_settings
  where tournament_id = v_entry.tournament_id
    and organization_id = p_organization_id;
  if v_settings.tournament_id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if p_provisional_player_id is not null then
    if not v_settings.allow_provisional_players
      or not v_settings.allow_players_without_account
      or not exists (
      select 1 from public.tournament_provisional_players
      where id = p_provisional_player_id and organization_id = p_organization_id
    ) then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  elsif not exists (select 1 from public.torneos_identity where id = p_arma2_user_id) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(p_roster_id::text, 0));
  select count(*) into v_count from public.tournament_roster_players
  where roster_id = p_roster_id and status = 'active';
  if v_count >= v_settings.maximum_players then
    raise exception using errcode = '23514', message = 'TORNEOS_ROSTER_MAXIMUM_REACHED';
  end if;
  if v_settings.unique_shirt_numbers and p_shirt_number is not null and exists (
    select 1 from public.tournament_roster_players
    where roster_id = p_roster_id and status = 'active' and shirt_number = p_shirt_number
  ) then raise exception using errcode = '23505', message = 'TORNEOS_DUPLICATE_SHIRT_NUMBER'; end if;
  insert into public.tournament_roster_players (
    organization_id, team_entry_id, roster_id, arma2_user_id,
    provisional_player_id, display_name, avatar_url, shirt_number,
    primary_position, secondary_position, is_goalkeeper, added_by
  ) values (
    p_organization_id, p_team_entry_id, p_roster_id, p_arma2_user_id,
    p_provisional_player_id, btrim(p_display_name), p_avatar_url, p_shirt_number,
    p_primary_position, p_secondary_position, coalesce(p_is_goalkeeper, false), private.current_identity_id()
  ) returning * into v_player;
  perform public.append_tournament_audit(
    p_organization_id, 'roster_player.added', 'roster_player', v_player.id,
    p_team_entry_id, v_entry.tournament_id,
    jsonb_build_object('identityType', case when p_arma2_user_id is null then 'provisional' else 'arma2_user' end)
  );
  return jsonb_build_object('id', v_player.id, 'displayName', v_player.display_name, 'status', v_player.status);
exception when unique_violation then
  get stacked diagnostics v_constraint_name = constraint_name;
  if v_constraint_name in (
    'tournament_roster_players_active_user_unique',
    'tournament_roster_players_active_provisional_unique'
  ) then
    raise exception using errcode = '23505', message = 'TORNEOS_DUPLICATE_PLAYER';
  end if;
  raise;
end;
$$;


--
-- Name: append_tournament_audit(uuid, text, text, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_tournament_audit(p_organization_id uuid, p_action text, p_resource_type text, p_resource_id uuid, p_team_entry_id uuid DEFAULT NULL::uuid, p_tournament_id uuid DEFAULT NULL::uuid, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_id bigint;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if jsonb_typeof(coalesce(p_metadata, '{}'::jsonb)) <> 'object'
    or pg_column_size(coalesce(p_metadata, '{}'::jsonb)) > 8192
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_AUDIT_METADATA';
  end if;
  insert into public.tournament_audit_log (
    organization_id, actor_user_id, actor_type, action, resource_type,
    resource_id, team_entry_id, tournament_id, metadata
  ) values (
    p_organization_id, private.current_identity_id(), 'user', p_action, p_resource_type,
    p_resource_id, p_team_entry_id, p_tournament_id, coalesce(p_metadata, '{}'::jsonb)
  ) returning id into v_id;
  return v_id;
end;
$$;


--
-- Name: append_tournament_playoff_phase(uuid, uuid, uuid, uuid, integer, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.append_tournament_playoff_phase(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_source_phase_id uuid, p_qualifier_count integer, p_double_leg boolean, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_version public.tournament_fixture_versions%rowtype;
  v_source_phase public.tournament_phases%rowtype;
  v_phase public.tournament_phases%rowtype;
  v_sources jsonb := '[]'::jsonb;
  v_index integer;
  v_sequence integer;
  v_participant_count integer;
  v_previous_phase_count integer;
  v_previous_round_count integer;
  v_previous_match_count integer;
  v_round_count integer;
  v_match_count integer;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;
  if p_qualifier_count not in (2, 4, 8, 16) then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_QUALIFIERS';
  end if;

  if not public.has_tournament_organization_capability(
    p_organization_id, 'fixture.publish'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournaments tournament
    where tournament.id = p_tournament_id
      and tournament.organization_id = p_organization_id
      and tournament.status in ('completed', 'archived')
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_COMPETITION_READ_ONLY';
  end if;

  perform public.assert_tournament_fixture_scope(
    p_organization_id, p_tournament_id, p_category_id,
    'fixture.publish', array['registration', 'scheduled', 'active']::text[]
  );
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:fixture:' || p_tournament_id::text || ':' || p_category_id::text, 0
  ));

  select fixture.* into v_version
  from public.tournament_fixture_versions fixture
  where fixture.organization_id = p_organization_id
    and fixture.tournament_id = p_tournament_id
    and fixture.category_id = p_category_id
    and fixture.status = 'published'
    and fixture.invalidated_at is null
  for update;
  if v_version.id is null then
    raise exception using errcode = '23514', message = 'TORNEOS_PUBLISHED_FIXTURE_REQUIRED';
  end if;

  select phase.* into v_phase
  from public.tournament_phases phase
  where phase.fixture_version_id = v_version.id
    and phase.configuration->>'appendOperationKey' = p_idempotency_key::text;
  if v_phase.id is not null then
    return jsonb_build_object(
      'tournamentId', p_tournament_id,
      'fixtureVersionId', v_version.id,
      'sourcePhaseId', v_phase.configuration->>'sourcePhaseId',
      'phaseId', v_phase.id,
      'status', 'published',
      'roundCount', (select count(*) from public.tournament_rounds where phase_id = v_phase.id),
      'matchCount', (select count(*) from public.tournament_matches where phase_id = v_phase.id)
    );
  end if;

  select phase.* into v_source_phase
  from public.tournament_phases phase
  where phase.id = p_source_phase_id
    and phase.organization_id = p_organization_id
    and phase.tournament_id = p_tournament_id
    and phase.category_id = p_category_id
    and phase.fixture_version_id = v_version.id
    and phase.phase_type = 'league'
    and phase.status <> 'archived'
  for share;
  if v_source_phase.id is null then
    raise exception using errcode = '23514', message = 'TORNEOS_PLAYOFF_SOURCE_INVALID';
  end if;

  if exists (
    select 1 from public.tournament_phases phase
    where phase.fixture_version_id = v_version.id
      and phase.phase_type in (
        'round_of_32', 'round_of_16', 'quarterfinal',
        'semifinal', 'third_place', 'final', 'custom_knockout'
      )
      and phase.status <> 'archived'
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_PLAYOFF_PHASE_EXISTS';
  end if;

  select count(*) into v_participant_count
  from public.tournament_competition_participants participant
  where participant.participant_set_id = v_version.participant_set_id
    and participant.status = 'active';
  if p_qualifier_count > v_participant_count then
    raise exception using errcode = '23514', message = 'TORNEOS_INVALID_QUALIFIERS';
  end if;

  select count(*) into v_previous_phase_count
  from public.tournament_phases where fixture_version_id = v_version.id;
  select count(*) into v_previous_round_count
  from public.tournament_rounds where fixture_version_id = v_version.id;
  select count(*) into v_previous_match_count
  from public.tournament_matches where fixture_version_id = v_version.id;
  select coalesce(max(phase.sequence_number), 0) + 1 into v_sequence
  from public.tournament_phases phase
  where phase.fixture_version_id = v_version.id;

  -- El builder distribuye la primera mitad en slots locales y la segunda en
  -- slots visitantes. Invertir esta última conserva el seeding 1-vs-N,
  -- 2-vs-(N-1), etc., sin hardcodear cruces ni materializar participantes.
  for v_index in 1..(p_qualifier_count / 2) loop
    v_sources := v_sources || jsonb_build_array(jsonb_build_object(
      'type', 'league_position',
      'phaseId', v_source_phase.id,
      'rankNumber', v_index
    ));
  end loop;
  for v_index in reverse p_qualifier_count..(p_qualifier_count / 2 + 1) loop
    v_sources := v_sources || jsonb_build_array(jsonb_build_object(
      'type', 'league_position',
      'phaseId', v_source_phase.id,
      'rankNumber', v_index
    ));
  end loop;

  insert into public.tournament_phases (
    organization_id, tournament_id, category_id, fixture_version_id,
    name, phase_type, sequence_number, status, configuration
  ) values (
    p_organization_id, p_tournament_id, p_category_id, v_version.id,
    'Playoffs', 'custom_knockout', v_sequence, 'generated',
    jsonb_build_object(
      'sourcePhaseId', v_source_phase.id,
      'qualifiers', p_qualifier_count,
      'seeding', 'league_ranking',
      'knockoutLegs', case when p_double_leg then 'double' else 'single' end,
      'appendOperationKey', p_idempotency_key
    )
  ) returning * into v_phase;

  perform public.build_tournament_knockout(
    v_version.id, v_phase.id, v_sources, coalesce(p_double_leg, false), false
  );

  select count(*) into v_round_count
  from public.tournament_rounds where phase_id = v_phase.id;
  select count(*) into v_match_count
  from public.tournament_matches where phase_id = v_phase.id;

  perform public.append_tournament_audit(
    p_organization_id, 'fixture.phase_appended', 'phase', v_phase.id,
    null, p_tournament_id,
    jsonb_build_object(
      'categoryId', p_category_id,
      'fixtureVersionId', v_version.id,
      'sourcePhaseId', v_source_phase.id,
      'qualifierCount', p_qualifier_count,
      'doubleLeg', coalesce(p_double_leg, false),
      'previousPhaseCount', v_previous_phase_count,
      'previousRoundCount', v_previous_round_count,
      'previousMatchCount', v_previous_match_count,
      'appendedRoundCount', v_round_count,
      'appendedMatchCount', v_match_count
    )
  );

  return jsonb_build_object(
    'tournamentId', p_tournament_id,
    'fixtureVersionId', v_version.id,
    'sourcePhaseId', v_source_phase.id,
    'phaseId', v_phase.id,
    'status', 'published',
    'roundCount', v_round_count,
    'matchCount', v_match_count
  );
end;
$$;


--
-- Name: FUNCTION append_tournament_playoff_phase(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_source_phase_id uuid, p_qualifier_count integer, p_double_leg boolean, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.append_tournament_playoff_phase(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_source_phase_id uuid, p_qualifier_count integer, p_double_leg boolean, p_idempotency_key uuid) IS 'Agrega Playoffs a la versión oficial sin reemplazar fases, partidos ni resultados previos y sin crear otra edición o licencia.';


--
-- Name: apply_fake_tournament_payment_status(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_fake_tournament_payment_status(p_purchase_id uuid, p_status text, p_provider_status_detail text DEFAULT NULL::text, p_provider_payment_id text DEFAULT NULL::text, p_simulated_activation_error_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_purchase public.tournament_purchases%rowtype; v_target text; v_from_status text;
begin
  if p_status = 'approved' then
    return public.activate_verified_fake_tournament_purchase(
      p_purchase_id,p_provider_payment_id,p_simulated_activation_error_code
    );
  end if;
  if p_status not in ('pending','rejected','expired') then
    raise exception using errcode = '22023', message = 'TORNEOS_FAKE_STATUS_INVALID';
  end if;
  select * into v_purchase from public.tournament_purchases where id = p_purchase_id for update;
  if v_purchase.id is null or v_purchase.provider <> 'FAKE'
    or v_purchase.status not in ('preference_created','pending') then
    raise exception using errcode = '55000', message = 'TORNEOS_PURCHASE_TRANSITION_INVALID';
  end if;
  v_from_status := v_purchase.status;
  v_target := p_status;
  update public.tournament_purchases set
    status = v_target,provider_status = p_status,
    provider_status_detail = nullif(left(btrim(p_provider_status_detail),120),''),
    last_verified_at = now(),
    cancelled_at = case when v_target = 'rejected' then now() else cancelled_at end
  where id = v_purchase.id returning * into v_purchase;
  insert into public.tournament_purchase_events (
    purchase_id,organization_id,event_type,from_status,to_status,provider_status,
    provider_status_detail,actor_type
  ) values (
    v_purchase.id,v_purchase.organization_id,'payment.' || v_target,
    v_from_status,
    v_target,p_status,v_purchase.provider_status_detail,'provider'
  );
  return public.tournament_purchase_projection(v_purchase);
end;
$$;


--
-- Name: apply_tournament_purchase_reversal(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_tournament_purchase_reversal(p_purchase_id uuid, p_action text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_purchase public.tournament_purchases%rowtype;
  v_grant public.tournament_season_plan_grants%rowtype;
  v_event_type text;
  v_reason_code text;
  v_from_status text;
begin
  if p_action not in ('refund','chargeback_disputed','chargeback_restored','chargeback_buyer_won')
    or p_reason is null or char_length(btrim(p_reason)) not between 8 and 500 then
    raise exception using errcode = '22023', message = 'TORNEOS_REVERSAL_INVALID';
  end if;
  select * into v_purchase from public.tournament_purchases where id = p_purchase_id for update;
  if v_purchase.id is null or v_purchase.entitlement_activated_at is null then
    raise exception using errcode = '22023', message = 'TORNEOS_PURCHASE_INVALID';
  end if;
  v_from_status := v_purchase.status;
  select * into v_grant from public.tournament_season_plan_grants
  where origin_purchase_id = v_purchase.id for update;
  if v_grant.id is null then
    raise exception using errcode = '55000', message = 'TORNEOS_PURCHASE_GRANT_MISSING';
  end if;
  v_event_type := case p_action
    when 'chargeback_disputed' then 'suspended'
    when 'chargeback_restored' then 'restored' else 'revoked' end;
  v_reason_code := case p_action
    when 'refund' then 'total_refund'
    when 'chargeback_disputed' then 'chargeback_disputed'
    when 'chargeback_restored' then 'chargeback_restored'
    else 'chargeback_buyer_won' end;
  if (select event_type from public.tournament_season_plan_grant_events
      where season_grant_id = v_grant.id order by id desc limit 1) = v_event_type then
    return public.tournament_purchase_projection(v_purchase) || jsonb_build_object('idempotentReplay',true);
  end if;
  insert into public.tournament_season_plan_grant_events (
    season_grant_id,purchase_id,event_type,reason_code,reason,actor_type
  ) values (v_grant.id,v_purchase.id,v_event_type,v_reason_code,btrim(p_reason),'provider');
  update public.tournament_purchases set
    status = case p_action when 'refund' then 'refunded'
      when 'chargeback_restored' then 'approved' else 'charged_back' end,
    provider_status = p_action,
    refunded_at = case when p_action = 'refund' then now() else refunded_at end,
    charged_back_at = case when p_action in ('chargeback_disputed','chargeback_buyer_won')
      then coalesce(charged_back_at,now()) else charged_back_at end,
    last_verified_at = now()
  where id = v_purchase.id returning * into v_purchase;
  insert into public.tournament_purchase_events (
    purchase_id,organization_id,event_type,from_status,to_status,provider_status,actor_type,metadata
  ) values (
    v_purchase.id,v_purchase.organization_id,'payment.' || p_action,v_from_status,
    v_purchase.status,p_action,'provider',
    jsonb_build_object('seasonGrantEvent',v_event_type,'seasonId',v_purchase.season_id)
  );
  return public.tournament_purchase_projection(v_purchase) || jsonb_build_object('idempotentReplay',false);
end;
$$;


--
-- Name: approve_tournament_team_entry(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.approve_tournament_team_entry(p_organization_id uuid, p_team_entry_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  return public.review_tournament_team_entry(
    p_organization_id,
    p_team_entry_id,
    'approved',
    p_reason,
    '[]'::jsonb
  );
end;
$$;


--
-- Name: archive_tournament_announcement(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_tournament_announcement(p_announcement_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_announcement public.tournament_announcements%rowtype;
begin
  select * into v_announcement
  from public.tournament_announcements announcement
  where announcement.id = p_announcement_id
  for update;
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if v_announcement.id is null
    or not public.has_tournament_communications_capability(
      v_announcement.organization_id,'announcements.archive'
    )
    or v_announcement.status not in ('published','superseded')
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  update public.tournament_announcements
  set status = 'archived',archived_at = now()
  where id = p_announcement_id;
  perform public.append_tournament_audit(
    v_announcement.organization_id,'communications.announcement_archive','announcement',
    p_announcement_id,null,v_announcement.tournament_id,'{}'::jsonb
  );
  return p_announcement_id;
end;
$$;


--
-- Name: archive_tournament_document(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_tournament_document(p_document_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_document public.tournament_documents%rowtype;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_document
  from public.tournament_documents document
  where document.id = p_document_id
  for update;
  if v_document.id is null
    or not public.has_tournament_communications_capability(
      v_document.organization_id,'documents.archive'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_DOCUMENT_FORBIDDEN';
  end if;
  update public.tournament_documents
  set status = 'archived',archived_at = now()
  where id = p_document_id;
  perform public.append_tournament_audit(
    v_document.organization_id,'communications.document_archive','tournament_document',
    p_document_id,null,v_document.tournament_id,'{}'::jsonb
  );
  return p_document_id;
end;
$$;


--
-- Name: archive_tournament_fixture(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_tournament_fixture(p_organization_id uuid, p_fixture_version_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_version public.tournament_fixture_versions%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if private.current_identity_id() is null or char_length(v_reason) not between 3 and 500
    or not public.has_tournament_organization_capability(
      p_organization_id, 'fixture.archive'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  update public.tournament_fixture_versions
  set status = 'archived', archived_at = now()
  where id = p_fixture_version_id
    and organization_id = p_organization_id
    and status = 'draft'
  returning * into v_version;
  if v_version.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  perform public.append_tournament_audit(
    p_organization_id, 'fixture.archived', 'fixture_version', v_version.id,
    null, v_version.tournament_id, jsonb_build_object('reason', v_reason)
  );
  return jsonb_build_object('fixtureVersionId', v_version.id, 'status', 'archived');
end;
$$;


--
-- Name: archive_tournament_team_entry(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_tournament_team_entry(p_organization_id uuid, p_team_entry_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_entry public.tournament_team_entries%rowtype;
begin
  if private.current_identity_id() is null or not public.has_tournament_organization_capability(
    p_organization_id,
    'team_entries.archive'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) not between 3 and 1200 then
    raise exception using errcode = '22023', message = 'TORNEOS_REASON_REQUIRED';
  end if;
  select * into v_entry
  from public.tournament_team_entries
  where id = p_team_entry_id
    and organization_id = p_organization_id
    and status <> 'archived'
  for update;
  if v_entry.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  update public.tournament_team_invitations
  set status = 'revoked', revoked_at = now()
  where team_entry_id = v_entry.id and status = 'pending';
  update public.tournament_team_entries
  set status = 'archived', archived_at = now()
  where id = v_entry.id
  returning * into v_entry;
  perform public.append_tournament_audit(
    p_organization_id,
    'team_entry.archived',
    'team_entry',
    v_entry.id,
    v_entry.id,
    v_entry.tournament_id,
    jsonb_build_object('reason', left(btrim(p_reason), 240))
  );
  return jsonb_build_object('entryId', v_entry.id, 'status', v_entry.status);
end;
$$;


--
-- Name: assert_tournament_fixture_scope(uuid, uuid, uuid, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_tournament_fixture_scope(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_capability text, p_allowed_statuses text[]) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(
    p_organization_id,
    p_capability
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  perform 1
  from public.tournament_organizations organization
  join public.tournaments tournament
    on tournament.organization_id = organization.id
  join public.tournament_seasons season
    on season.organization_id = organization.id
    and season.id = tournament.season_id
  join public.tournament_categories category
    on category.organization_id = organization.id
    and category.tournament_id = tournament.id
  where organization.id = p_organization_id
    and organization.status = 'active'
    and tournament.id = p_tournament_id
    and tournament.status = any(p_allowed_statuses)
    and season.status in ('draft', 'active')
    and category.id = p_category_id
    and category.status = 'active';
  if not found then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
end;
$$;


--
-- Name: assign_first_free_plan_on_tournament_insert(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_first_free_plan_on_tournament_insert() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(new.organization_id::text,41)
  );
  IF EXISTS (
    SELECT 1 FROM public.tournament_organization_plan_state state
    WHERE state.organization_id = new.organization_id
  ) THEN
    RETURN new;
  END IF;

  INSERT INTO public.tournament_organization_plan_state (
    organization_id,first_free_consumed_at,first_free_tournament_id,
    initialization_source
  ) VALUES (new.organization_id,now(),new.id,'first_free');

  INSERT INTO public.tournament_plan_grants (
    organization_id,tournament_id,plan_code,source,reason
  ) VALUES (
    new.organization_id,new.id,'FREE','first_free',
    'Primer torneo gratuito asignado automáticamente por el dominio'
  );
  RETURN new;
END;
$$;


--
-- Name: assign_tournament_media_photographer(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_tournament_media_photographer(p_gallery_id uuid, p_user_id uuid, p_revoke boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_gallery public.tournament_media_galleries%rowtype;
begin
  select * into v_gallery from public.tournament_media_galleries where id = p_gallery_id;
  if v_gallery.id is null or not public.has_tournament_media_capability(
    v_gallery.organization_id,'media.update_gallery'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_gallery.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_gallery_id::text,1)
  );
  select * into v_gallery
  from public.tournament_media_galleries
  where id = p_gallery_id
  for update;
  if not p_revoke and v_gallery.status not in ('draft','under_review') then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_GALLERY_IMMUTABLE';
  end if;
  if not exists (select 1 from public.torneos_identity where id = p_user_id) then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_ASSIGNMENT_INVALID';
  end if;
  insert into public.tournament_media_assignments (
    organization_id,tournament_id,gallery_id,user_id,status,
    assigned_by,revoked_at
  ) values (
    v_gallery.organization_id,v_gallery.tournament_id,p_gallery_id,p_user_id,
    case when p_revoke then 'revoked' else 'active' end,
    private.current_identity_id(),case when p_revoke then now() else null end
  ) on conflict (gallery_id,user_id) do update set
    can_upload = not p_revoke,
    status = case when p_revoke then 'revoked' else 'active' end,
    revoked_at = case when p_revoke then now() else null end,
    assigned_by = private.current_identity_id();
  perform public.append_tournament_audit(
    v_gallery.organization_id,
    case when p_revoke then 'media.photographer.revoked' else 'media.photographer.assigned' end,
    'media_gallery',p_gallery_id,null,v_gallery.tournament_id,
    jsonb_build_object('scope','upload_only')
  );
  if p_revoke then
    update public.tournament_media_upload_sessions
    set status = 'revoked'
    where gallery_id = p_gallery_id
      and requested_by = p_user_id
      and status = 'issued';
  end if;
  return jsonb_build_object(
    'galleryId',p_gallery_id,'status',case when p_revoke then 'revoked' else 'active' end
  );
end;
$$;


--
-- Name: assign_tournament_season_member(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_tournament_season_member(p_organization_id uuid, p_season_id uuid, p_membership_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_assignment public.tournament_season_member_assignments%rowtype;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_season_capability(
    p_organization_id,p_season_id,'members.invite'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_SEASON_ASSIGNMENT_FORBIDDEN';
  end if;
  insert into public.tournament_season_member_assignments (
    organization_id,season_id,membership_id,assigned_by
  ) values (p_organization_id,p_season_id,p_membership_id,private.current_identity_id())
  on conflict (season_id,membership_id) do update
    set assigned_by = public.tournament_season_member_assignments.assigned_by
  returning * into v_assignment;
  return jsonb_build_object('id',v_assignment.id,'organizationId',v_assignment.organization_id,
    'seasonId',v_assignment.season_id,'membershipId',v_assignment.membership_id,
    'assignedAt',v_assignment.assigned_at);
end;
$$;


--
-- Name: attest_tournament_media_service(text, text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.attest_tournament_media_service(p_service text, p_release text, p_capabilities jsonb, p_ttl_seconds integer DEFAULT 900) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_rejection text;
  v_expires timestamp with time zone;
begin
  if p_service is null or p_release is null then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_ATTESTATION_INVALID';
  end if;
  v_rejection := public.tournament_media_attestation_rejection(
    p_service, p_capabilities, p_ttl_seconds
  );
  if v_rejection is not null then
    -- The caller learns only that it was refused. A service that needs the
    -- reason calls `tournament_media_attestation_rejection` itself, which is
    -- read-only and service-only.
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_ATTESTATION_INVALID';
  end if;
  v_expires := now() + make_interval(secs => p_ttl_seconds);
  insert into public.tournament_media_service_attestations (
    service, release, capabilities, attested_at, expires_at
  ) values (
    p_service, p_release, p_capabilities, now(), v_expires
  ) on conflict (service) do update set
    release = excluded.release,
    capabilities = excluded.capabilities,
    attested_at = excluded.attested_at,
    expires_at = excluded.expires_at;
  return jsonb_build_object(
    'service',p_service,'release',p_release,'expiresAt',v_expires
  );
end;
$$;


--
-- Name: authorize_tournament_media_read(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.authorize_tournament_media_read(p_actor_user_id uuid, p_asset_id uuid, p_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_asset public.tournament_media_assets%rowtype;
  v_gallery public.tournament_media_galleries%rowtype;
  v_variant public.tournament_media_variants%rowtype;
  v_previous_claim text := coalesce(
    pg_catalog.current_setting('request.jwt.claim.sub', true), ''
  );
  v_is_staff boolean := false;
  v_owns_upload boolean := false;
  v_can_read_original boolean := false;
  v_is_participant boolean := false;
BEGIN
  IF p_actor_user_id IS NULL
    OR p_kind NOT IN ('thumbnail','grid','detail','original')
  THEN
    RAISE EXCEPTION USING
      errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  END IF;

  SELECT * INTO v_asset
  FROM public.tournament_media_assets
  WHERE id = p_asset_id;
  IF v_asset.id IS NULL
    OR v_asset.storage_state = 'storage_purged'
    OR (
      v_asset.storage_state = 'retention_marked'
      AND v_asset.retention_reason LIKE 'USER_REQUESTED_DELETE:%'
    )
  THEN
    RAISE EXCEPTION USING
      errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  END IF;

  SELECT * INTO v_gallery
  FROM public.tournament_media_galleries
  WHERE id = v_asset.gallery_id;
  PERFORM pg_catalog.set_config(
    'request.jwt.claim.sub', p_actor_user_id::text, true
  );
  BEGIN
    v_is_staff := public.has_tournament_media_capability(
      v_asset.organization_id, 'media.read'
    );
    v_owns_upload := v_asset.uploaded_by = p_actor_user_id AND EXISTS (
      SELECT 1
      FROM public.tournament_media_assignments assignment
      WHERE assignment.gallery_id = v_asset.gallery_id
        AND assignment.user_id = p_actor_user_id
        AND assignment.status = 'active'
        AND assignment.can_upload
    );
    v_can_read_original := v_owns_upload
      OR public.has_tournament_media_capability(
        v_asset.organization_id, 'media.review'
      );
    v_is_participant := v_asset.status = 'published'
      AND v_gallery.status = 'published'
      AND public.tournament_media_asset_has_internal_consent(p_asset_id)
      AND public.can_current_user_read_media_gallery(v_asset.gallery_id);
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_catalog.set_config(
      'request.jwt.claim.sub', v_previous_claim, true
    );
    RAISE;
  END;
  PERFORM pg_catalog.set_config(
    'request.jwt.claim.sub', v_previous_claim, true
  );

  IF p_kind = 'original' AND NOT v_can_read_original THEN
    RAISE EXCEPTION USING
      errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  END IF;
  IF NOT v_is_staff AND NOT v_owns_upload AND NOT v_is_participant THEN
    RAISE EXCEPTION USING
      errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  END IF;

  IF v_asset.processing_tier = 'mvp_simple' THEN
    RETURN jsonb_build_object(
      'assetId', p_asset_id,
      'kind', p_kind,
      'bucket', v_asset.bucket,
      'objectName', v_asset.internal_path,
      'width', v_asset.width,
      'height', v_asset.height,
      'contentType', v_asset.detected_mime,
      'audience', CASE
        WHEN v_is_staff OR v_owns_upload THEN 'manager'
        ELSE 'participant'
      END
    );
  END IF;

  SELECT * INTO v_variant
  FROM public.tournament_media_variants
  WHERE asset_id = p_asset_id
    AND kind = p_kind
    AND status = 'ready';
  IF v_variant.id IS NULL THEN
    RAISE EXCEPTION USING
      errcode = '22023', message = 'TORNEOS_MEDIA_PROCESSING_REQUIRED';
  END IF;

  RETURN jsonb_build_object(
    'assetId', p_asset_id,
    'kind', p_kind,
    'bucket', v_variant.bucket,
    'objectName', v_variant.internal_path,
    'width', v_variant.width,
    'height', v_variant.height,
    'contentType', v_variant.detected_mime,
    'audience', CASE
      WHEN v_is_staff OR v_owns_upload THEN 'manager'
      ELSE 'participant'
    END
  );
END;
$$;


--
-- Name: authorize_tournament_media_upload_target(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.authorize_tournament_media_upload_target(p_session_id uuid, p_token text, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_session public.tournament_media_upload_sessions%rowtype;
  v_gallery public.tournament_media_galleries%rowtype;
BEGIN
  SELECT * INTO v_session FROM public.tournament_media_upload_sessions
  WHERE id = p_session_id;
  IF v_session.id IS NULL OR v_session.status <> 'issued'
    OR v_session.expires_at <= now() OR p_actor_user_id IS NULL
    OR p_actor_user_id <> v_session.requested_by
    OR encode(public.digest(coalesce(p_token,''),'sha256'),'hex') <> v_session.token_hash
  THEN
    RAISE EXCEPTION USING errcode = '42501',
      message = 'TORNEOS_MEDIA_UPLOAD_SESSION_INVALID';
  END IF;
  PERFORM public.tournament_media_require_upload_tier(v_session.processing_tier);
  SELECT * INTO v_gallery FROM public.tournament_media_galleries
  WHERE id = v_session.gallery_id;
  IF v_gallery.status NOT IN ('draft','under_review')
    OR (v_session.processing_tier = 'mvp_simple'
      AND NOT public.tournament_media_mvp_user_can_upload(
        v_session.requested_by,v_session.gallery_id
      ))
    OR (v_session.processing_tier = 'processor_external'
      AND NOT public.tournament_media_user_can_upload(
        v_session.requested_by,v_session.gallery_id
      ))
    OR EXISTS (SELECT 1 FROM public.tournament_media_assets asset
      WHERE asset.internal_path = v_session.internal_path)
  THEN
    RAISE EXCEPTION USING errcode = '42501',
      message = 'TORNEOS_MEDIA_UPLOAD_SESSION_INVALID';
  END IF;
  RETURN jsonb_build_object(
    'sessionId',v_session.id,'bucket',v_session.bucket,
    'objectName',v_session.internal_path,'contentType',v_session.requested_mime,
    'maxBytes',v_session.max_size,'expectedBytes',v_session.requested_size,
    'expiresAt',v_session.expires_at,'organizationId',v_session.organization_id,
    'tournamentId',v_session.tournament_id,'galleryId',v_session.gallery_id,
    'processingTier',v_session.processing_tier
  );
END;
$$;


--
-- Name: authorize_tournament_player_portrait_read(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.authorize_tournament_player_portrait_read(p_actor_user_id uuid, p_portrait_id uuid, p_variant text, p_audience text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_portrait public.tournament_player_portraits%ROWTYPE;
BEGIN
  IF p_variant <> 'original' OR p_audience <> 'authenticated_roster' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_PORTRAIT_AUDIENCE_DISABLED';
  END IF;
  SELECT * INTO v_portrait FROM public.tournament_player_portraits portrait
  WHERE portrait.id = p_portrait_id AND portrait.lifecycle_status = 'active';
  IF v_portrait.id IS NULL OR NOT public.can_read_tournament_player_portrait_as(
    v_portrait.organization_id, v_portrait.roster_player_id, p_actor_user_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_PORTRAIT_FORBIDDEN';
  END IF;
  RETURN jsonb_build_object(
    'bucket', v_portrait.bucket, 'objectPath', v_portrait.object_path,
    'mimeType', v_portrait.mime_type, 'width', v_portrait.width,
    'height', v_portrait.height, 'focalX', v_portrait.focal_x,
    'focalY', v_portrait.focal_y, 'audience', p_audience
  );
END;
$$;


--
-- Name: authorize_tournament_social_export(uuid, uuid, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.authorize_tournament_social_export(p_organization_id uuid, p_tournament_id uuid, p_piece text, p_theme text, p_include_arma2_branding boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_season_id uuid;
  v_policy jsonb;
  v_premium boolean;
  v_effective_branding boolean;
begin
  select season_id into v_season_id from public.tournaments
  where organization_id=p_organization_id and id=p_tournament_id;
  if v_season_id is null
    or not public.has_tournament_season_access(p_organization_id,v_season_id)
    or not public.has_tournament_social_capability(p_organization_id,'social.export') then
    raise exception using errcode='42501',message='TORNEOS_SOCIAL_EXPORT_FORBIDDEN';
  end if;

  if p_theme not in ('base','heritage','street','scoreboard','editorial') then
    raise exception using errcode='22023',message='TORNEOS_SOCIAL_THEME_UNKNOWN';
  end if;
  if p_piece not in (
    'round_results','next_fixture','standings','mvp','final','champion',
    'scorers','discipline','best_eleven','round_summary','semifinals'
  ) then
    raise exception using errcode='22023',message='TORNEOS_SOCIAL_PIECE_UNKNOWN';
  end if;

  v_policy:=public.resolve_effective_tournament_season_entitlements_at(
    p_organization_id,v_season_id,now(),false,p_tournament_id
  );
  v_premium:=coalesce(
    (v_policy->'capabilities'->>'social_studio.premium')::boolean,
    false
  );

  if not v_premium and (
    p_theme <> 'base'
    or p_piece not in ('round_results','standings','next_fixture')
  ) then
    raise exception using errcode='42501',message='TORNEOS_SOCIAL_PREMIUM_REQUIRED';
  end if;

  if p_theme = 'base' then
    if not v_premium and not p_include_arma2_branding then
      raise exception using errcode='42501',message='TORNEOS_BRANDING_PREMIUM_REQUIRED';
    end if;
    v_effective_branding:=case when v_premium then p_include_arma2_branding else true end;
  else
    -- Every Premium theme is intrinsically white-label, irrespective of input.
    v_effective_branding:=false;
  end if;

  return jsonb_build_object(
    'authorized',true,
    'organizationId',p_organization_id,
    'seasonId',v_season_id,
    'tournamentId',p_tournament_id,
    'piece',p_piece,
    'theme',p_theme,
    'plan',v_policy->>'plan',
    'capability','social_studio.premium',
    'includeArma2Branding',v_effective_branding
  );
end;
$$;


--
-- Name: authorize_tournament_team_photo_read(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.authorize_tournament_team_photo_read(p_actor_user_id uuid, p_team_photo_id uuid, p_variant text, p_audience text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_photo public.tournament_team_photos%ROWTYPE;
  v_allowed boolean;
BEGIN
  IF p_variant <> 'original' OR p_audience <> 'authenticated_team' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_TEAM_PHOTO_AUDIENCE_DISABLED';
  END IF;
  SELECT * INTO v_photo
  FROM public.tournament_team_photos photo
  WHERE photo.id = p_team_photo_id
    AND photo.lifecycle_status = 'active';
  IF v_photo.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_TEAM_PHOTO_FORBIDDEN';
  END IF;
  v_allowed := CASE v_photo.editorial_status
    -- Vigente: la ve quien ya veía la inscripción.
    WHEN 'approved' THEN public.can_read_tournament_team_photo_as(
      v_photo.organization_id, v_photo.team_entry_id, p_actor_user_id)
    -- Candidata y rechazada: sólo quien gestiona o quien modera. Nadie más
    -- recibe una firma de material sin publicar.
    ELSE public.can_manage_tournament_team_visual_assets_as(
      v_photo.organization_id, v_photo.team_entry_id, p_actor_user_id,
      'team_entries.update')
      OR public.can_moderate_tournament_team_visual_assets_as(
        v_photo.organization_id, v_photo.team_entry_id, p_actor_user_id,
        'team_entries.update')
  END;
  IF v_allowed IS NOT TRUE THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_TEAM_PHOTO_FORBIDDEN';
  END IF;
  RETURN jsonb_build_object(
    'bucket', v_photo.bucket, 'objectPath', v_photo.object_path,
    'mimeType', v_photo.mime_type, 'width', v_photo.width,
    'height', v_photo.height, 'audience', p_audience
  );
END;
$$;


--
-- Name: auto_schedule_tournament_matches(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_schedule_tournament_matches(p_organization_id uuid, p_fixture_version_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_version public.tournament_fixture_versions%rowtype;
  v_tournament public.tournaments%rowtype;
  v_match record;
  v_candidate record;
  v_validation jsonb;
  v_scheduled integer := 0;
  v_unscheduled integer := 0;
  v_unscheduled_details jsonb := '[]'::jsonb;
  v_last_validation jsonb;
  v_done boolean;
begin
  if private.current_identity_id() is null or not public.has_tournament_organization_capability(
    p_organization_id, 'matches.schedule'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select version.* into v_version from public.tournament_fixture_versions version
  where version.id = p_fixture_version_id
    and version.organization_id = p_organization_id
    and version.status in ('draft', 'published')
    and version.invalidated_at is null;
  select tournament.* into v_tournament from public.tournaments tournament
  where tournament.id = v_version.tournament_id;
  if v_version.id is null or v_tournament.start_date is null or v_tournament.end_date is null
    or v_tournament.end_date - v_tournament.start_date > 366
  then
    raise exception using errcode = '23514', message = 'TORNEOS_AUTOSCHEDULE_RANGE_REQUIRED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:auto-schedule:' || v_version.id::text, 0
  ));
  for v_match in
    select match_row.*
    from public.tournament_matches match_row
    join public.tournament_rounds round_row on round_row.id = match_row.round_id
    join public.tournament_phases phase on phase.id = match_row.phase_id
    where match_row.fixture_version_id = v_version.id
      and match_row.status = 'unscheduled'
    order by phase.sequence_number, round_row.sort_order,
      round_row.round_number, match_row.match_number
  loop
    if v_match.home_participant_id is null or v_match.away_participant_id is null then
      v_unscheduled := v_unscheduled + 1;
      v_unscheduled_details := v_unscheduled_details || jsonb_build_array(
        jsonb_build_object(
          'matchId', v_match.id,
          'reason', 'unresolved_sources'
        )
      );
      continue;
    end if;
    v_done := false;
    v_last_validation := null;
    for v_candidate in
      with dates as (
        select day::date as slot_date
        from generate_series(
          v_tournament.start_date::timestamp,
          v_tournament.end_date::timestamp,
          interval '1 day'
        ) day
      )
      select
        schedule_window.id as schedule_window_id,
        schedule_window.venue_id,
        schedule_window.court_id,
        (
          dates.slot_date
          + schedule_window.starts_at
          + make_interval(
            mins => slot.step * (
              schedule_window.slot_duration_minutes + schedule_window.buffer_minutes
            )
          )
        ) at time zone venue.timezone as scheduled_at,
        schedule_window.slot_duration_minutes as duration_minutes
      from public.tournament_schedule_windows schedule_window
      join public.tournament_venues venue
        on venue.id = schedule_window.venue_id and venue.status = 'active'
      join public.tournament_courts court
        on court.id = schedule_window.court_id and court.status = 'active'
      cross join dates
      cross join lateral generate_series(
        0,
        greatest(
          floor(
            extract(epoch from (
              schedule_window.ends_at - schedule_window.starts_at
            )) / 60
            / (
              schedule_window.slot_duration_minutes + schedule_window.buffer_minutes
            )
          )::integer - 1,
          0
        )
      ) slot(step)
      where schedule_window.organization_id = p_organization_id
        and schedule_window.tournament_id = v_version.tournament_id
        and schedule_window.status = 'active'
        and schedule_window.window_type = 'availability'
        and schedule_window.court_id is not null
        and (
          schedule_window.category_id is null
          or schedule_window.category_id = v_version.category_id
        )
        and (
          schedule_window.specific_date = dates.slot_date
          or schedule_window.day_of_week = extract(isodow from dates.slot_date)::smallint
        )
        and court.sport_modality = v_tournament.sport_modality
      order by scheduled_at, schedule_window.court_id,
        schedule_window.id, slot.step
    loop
      v_validation := public.validate_tournament_match_schedule(
        p_organization_id, v_match.id, v_candidate.scheduled_at,
        v_candidate.venue_id, v_candidate.court_id, v_candidate.duration_minutes
      );
      v_last_validation := v_validation;
      if jsonb_array_length(v_validation->'blockers') = 0
        and jsonb_array_length(v_validation->'warnings') = 0
      then
        perform public.schedule_tournament_match(
          p_organization_id, v_match.id, v_candidate.scheduled_at,
          v_candidate.venue_id, v_candidate.court_id, v_candidate.duration_minutes,
          false, null
        );
        v_scheduled := v_scheduled + 1;
        v_done := true;
        exit;
      end if;
    end loop;
    if not v_done then
      v_unscheduled := v_unscheduled + 1;
      v_unscheduled_details := v_unscheduled_details || jsonb_build_array(
        jsonb_build_object(
          'matchId', v_match.id,
          'reason', 'no_valid_slot',
          'lastBlockers', coalesce(v_last_validation->'blockers', '[]'::jsonb),
          'lastWarnings', coalesce(v_last_validation->'warnings', '[]'::jsonb)
        )
      );
    end if;
  end loop;
  perform public.append_tournament_audit(
    p_organization_id, 'matches.auto_scheduled', 'fixture_version', v_version.id,
    null, v_version.tournament_id,
    jsonb_build_object('scheduledCount', v_scheduled, 'unscheduledCount', v_unscheduled)
  );
  return jsonb_build_object(
    'fixtureVersionId', v_version.id,
    'scheduledCount', v_scheduled,
    'unscheduledCount', v_unscheduled,
    'unscheduled', v_unscheduled_details
  );
end;
$$;


--
-- Name: begin_tournament_media_asset_delete(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_tournament_media_asset_delete(p_actor_user_id uuid, p_asset_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_asset public.tournament_media_assets%rowtype;
  v_previous_claim text := coalesce(
    pg_catalog.current_setting('request.jwt.claim.sub', true), ''
  );
  v_object_names jsonb;
BEGIN
  IF p_actor_user_id IS NULL OR p_asset_id IS NULL THEN
    RAISE EXCEPTION USING
      errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  END IF;

  SELECT * INTO v_asset
  FROM public.tournament_media_assets
  WHERE id = p_asset_id;
  IF v_asset.id IS NULL THEN
    RAISE EXCEPTION USING
      errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  END IF;

  PERFORM pg_catalog.set_config(
    'request.jwt.claim.sub', p_actor_user_id::text, true
  );
  BEGIN
    IF NOT public.has_tournament_media_capability(
      v_asset.organization_id, 'media.revoke'
    ) THEN
      RAISE EXCEPTION USING
        errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(v_asset.organization_id::text, 0)
    );
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(v_asset.gallery_id::text, 1)
    );
    SELECT * INTO v_asset
    FROM public.tournament_media_assets
    WHERE id = p_asset_id
    FOR UPDATE;
    IF v_asset.id IS NULL THEN
      RAISE EXCEPTION USING
        errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
    END IF;
    IF v_asset.status IN ('uploading', 'processing') THEN
      RAISE EXCEPTION USING
        errcode = '22023', message = 'TORNEOS_MEDIA_PROCESSING_REQUIRED';
    END IF;

    -- Object names are accepted only from the canonical tenant/tournament/
    -- gallery/UUID path contract. No user filename participates in security.
    IF v_asset.bucket <> 'tournament-media'
      OR v_asset.internal_path !~
        '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}(-(?:thumbnail|grid|detail|original))?\.(jpg|png|webp)$'
      OR EXISTS (
        SELECT 1
        FROM public.tournament_media_variants variant
        WHERE variant.asset_id = p_asset_id
          AND (
            variant.bucket <> 'tournament-media'
            OR variant.internal_path !~
              '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}-(thumbnail|grid|detail|original)\.(jpg|png|webp)$'
          )
      )
    THEN
      RAISE EXCEPTION USING
        errcode = '55000', message = 'TORNEOS_MEDIA_STORAGE_PATH_INVALID';
    END IF;

    IF v_asset.storage_state = 'active' THEN
      UPDATE public.tournament_media_assets
      SET storage_state = 'retention_marked',
          retention_marked_at = pg_catalog.now(),
          storage_purged_at = NULL,
          retention_reason = 'USER_REQUESTED_DELETE:' || v_asset.status,
          updated_at = pg_catalog.now()
      WHERE id = p_asset_id;
    ELSIF NOT (
      v_asset.storage_state = 'retention_marked'
      AND v_asset.retention_reason LIKE 'USER_REQUESTED_DELETE:%'
    ) THEN
      RAISE EXCEPTION USING
        errcode = '22023', message = 'TORNEOS_MEDIA_DELETE_INVALID';
    END IF;

    SELECT coalesce(jsonb_agg(name ORDER BY name), '[]'::jsonb)
    INTO v_object_names
    FROM (
      SELECT v_asset.internal_path AS name
      UNION
      SELECT variant.internal_path
      FROM public.tournament_media_variants variant
      WHERE variant.asset_id = p_asset_id
    ) objects;
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_catalog.set_config(
      'request.jwt.claim.sub', v_previous_claim, true
    );
    RAISE;
  END;
  PERFORM pg_catalog.set_config(
    'request.jwt.claim.sub', v_previous_claim, true
  );

  RETURN jsonb_build_object(
    'assetId', p_asset_id,
    'bucket', 'tournament-media',
    'objectNames', v_object_names,
    'deletePending', true
  );
END;
$_$;


--
-- Name: FUNCTION begin_tournament_media_asset_delete(p_actor_user_id uuid, p_asset_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.begin_tournament_media_asset_delete(p_actor_user_id uuid, p_asset_id uuid) IS 'Service-only phase 1: authorize actor, block new signed reads, and return DB-derived Storage object names.';


--
-- Name: begin_tournament_player_portrait_delete(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_tournament_player_portrait_delete(p_actor_user_id uuid, p_portrait_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_portrait public.tournament_player_portraits%ROWTYPE;
BEGIN
  SELECT * INTO v_portrait FROM public.tournament_player_portraits portrait
  WHERE portrait.id = p_portrait_id
    AND portrait.lifecycle_status IN ('active', 'delete_pending') FOR UPDATE;
  IF v_portrait.id IS NULL OR NOT public.can_manage_tournament_player_portrait_as(
    v_portrait.organization_id, v_portrait.roster_player_id, p_actor_user_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_PORTRAIT_FORBIDDEN';
  END IF;
  IF v_portrait.lifecycle_status = 'active' THEN
    UPDATE public.tournament_player_portraits
    SET lifecycle_status = 'delete_pending', publication_consent = 'revoked',
        consent_actor_user_id = p_actor_user_id, consent_changed_at = now(),
        updated_at = now()
    WHERE id = p_portrait_id;
  END IF;
  RETURN jsonb_build_object('bucket', v_portrait.bucket,
    'objectPath', v_portrait.object_path);
END;
$$;


--
-- Name: begin_tournament_team_photo_delete(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.begin_tournament_team_photo_delete(p_actor_user_id uuid, p_team_photo_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_photo public.tournament_team_photos%ROWTYPE;
  v_is_current boolean;
BEGIN
  SELECT * INTO v_photo
  FROM public.tournament_team_photos photo
  WHERE photo.id = p_team_photo_id
    AND photo.lifecycle_status IN ('active', 'delete_pending')
  FOR UPDATE;
  IF v_photo.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_TEAM_PHOTO_FORBIDDEN';
  END IF;
  v_is_current := v_photo.editorial_status = 'approved';
  IF NOT (
    CASE WHEN v_is_current
      THEN public.can_moderate_tournament_team_visual_assets_as(
        v_photo.organization_id, v_photo.team_entry_id, p_actor_user_id,
        'team_entries.update')
      ELSE public.can_manage_tournament_team_visual_assets_as(
        v_photo.organization_id, v_photo.team_entry_id, p_actor_user_id,
        'team_entries.update')
    END
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_TEAM_PHOTO_FORBIDDEN';
  END IF;
  IF v_photo.lifecycle_status = 'active' THEN
    UPDATE public.tournament_team_photos
    SET lifecycle_status = 'delete_pending', updated_at = now()
    WHERE id = p_team_photo_id;
  END IF;
  RETURN jsonb_build_object(
    'bucket', v_photo.bucket, 'objectPath', v_photo.object_path
  );
END;
$$;


--
-- Name: build_tournament_knockout(uuid, uuid, jsonb, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.build_tournament_knockout(p_fixture_version_id uuid, p_phase_id uuid, p_sources jsonb, p_double_leg boolean, p_third_place boolean) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_version public.tournament_fixture_versions%rowtype;
  v_source_count integer;
  v_bracket_size integer := 1;
  v_slots jsonb;
  v_round_size integer;
  v_round_number integer := 0;
  v_tie integer;
  v_leg integer;
  v_round_id uuid;
  v_match_id uuid;
  v_match_number integer;
  v_duration integer;
  v_home_source jsonb;
  v_away_source jsonb;
  v_previous_sources jsonb := '[]'::jsonb;
  v_current_sources jsonb;
  v_advancement_source jsonb;
  v_loser_source jsonb;
  v_semifinal_loser_sources jsonb := '[]'::jsonb;
  v_last_match_id uuid;
  v_tie_key text;
  v_index integer;
  v_legs integer;
begin
  select version.* into v_version
  from public.tournament_fixture_versions version
  where version.id = p_fixture_version_id
    and version.status in ('draft', 'published');
  if v_version.id is null or jsonb_typeof(p_sources) <> 'array' then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_KNOCKOUT';
  end if;
  v_source_count := jsonb_array_length(p_sources);
  if v_source_count < 2 or v_source_count > 64 then
    raise exception using errcode = '23514', message = 'TORNEOS_NOT_ENOUGH_PARTICIPANTS';
  end if;
  while v_bracket_size < v_source_count loop
    v_bracket_size := v_bracket_size * 2;
  end loop;
  v_slots := '[]'::jsonb;
  for v_index in 0..v_bracket_size - 1 loop
    v_slots := v_slots || jsonb_build_array(jsonb_build_object('type', 'bye'));
  end loop;
  for v_index in 0..v_source_count - 1 loop
    v_slots := jsonb_set(
      v_slots,
      array[case
        when v_index < (v_bracket_size / 2)
          then (v_index * 2)::text
        else ((v_index - (v_bracket_size / 2)) * 2 + 1)::text
      end],
      p_sources->v_index
    );
  end loop;
  select modality.suggested_duration_minutes into v_duration
  from public.tournaments tournament
  join public.tournament_sport_modalities modality
    on modality.code = tournament.sport_modality
  where tournament.id = v_version.tournament_id;
  select coalesce(max(match_row.match_number), 0) into v_match_number
  from public.tournament_matches match_row
  where match_row.fixture_version_id = p_fixture_version_id;
  v_round_size := v_bracket_size;
  while v_round_size >= 2 loop
    v_round_number := v_round_number + 1;
    insert into public.tournament_rounds (
      organization_id, tournament_id, category_id, fixture_version_id,
      phase_id, round_number, name, status, sort_order
    ) values (
      v_version.organization_id, v_version.tournament_id, v_version.category_id,
      v_version.id, p_phase_id, v_round_number,
      case v_round_size
        when 2 then 'Final'
        when 4 then 'Semifinal'
        when 8 then 'Cuartos de final'
        when 16 then 'Octavos de final'
        when 32 then 'Dieciseisavos de final'
        else 'Ronda de ' || v_round_size
      end,
      'draft', v_round_number - 1
    ) returning id into v_round_id;
    v_current_sources := '[]'::jsonb;
    for v_tie in 1..(v_round_size / 2) loop
      if v_round_number = 1 then
        v_home_source := v_slots->((v_tie - 1) * 2);
        v_away_source := v_slots->((v_tie - 1) * 2 + 1);
      else
        v_home_source := v_previous_sources->((v_tie - 1) * 2);
        v_away_source := v_previous_sources->((v_tie - 1) * 2 + 1);
      end if;
      if v_home_source->>'type' = 'bye' and v_away_source->>'type' = 'bye' then
        v_current_sources := v_current_sources
          || jsonb_build_array(jsonb_build_object('type', 'bye'));
        continue;
      elsif v_home_source->>'type' = 'bye' then
        v_current_sources := v_current_sources || jsonb_build_array(v_away_source);
        continue;
      elsif v_away_source->>'type' = 'bye' then
        v_current_sources := v_current_sources || jsonb_build_array(v_home_source);
        continue;
      end if;
      v_tie_key := v_version.id::text || ':' || v_round_number || ':' || v_tie;
      v_legs := case when p_double_leg and v_round_size > 2 then 2 else 1 end;
      for v_leg in 1..v_legs loop
        v_match_number := v_match_number + 1;
        insert into public.tournament_matches (
          organization_id, season_id, tournament_id, category_id,
          participant_set_id, fixture_version_id, phase_id, round_id,
          match_number, leg_number, tie_key, home_participant_id,
          away_participant_id, status, duration_minutes, created_by
        ) values (
          v_version.organization_id, v_version.season_id, v_version.tournament_id,
          v_version.category_id, v_version.participant_set_id, v_version.id,
          p_phase_id, v_round_id, v_match_number, v_leg,
          case when v_legs = 2 then v_tie_key else null end,
          case when v_leg = 1 and v_home_source->>'type' = 'participant'
            then (v_home_source->>'participantId')::uuid
            when v_leg = 2 and v_away_source->>'type' = 'participant'
            then (v_away_source->>'participantId')::uuid else null end,
          case when v_leg = 1 and v_away_source->>'type' = 'participant'
            then (v_away_source->>'participantId')::uuid
            when v_leg = 2 and v_home_source->>'type' = 'participant'
            then (v_home_source->>'participantId')::uuid else null end,
          'unscheduled', v_duration, v_version.created_by
        ) returning id into v_match_id;
        perform public.insert_tournament_match_source(
          v_match_id, 'home', case when v_leg = 2 then v_away_source else v_home_source end
        );
        perform public.insert_tournament_match_source(
          v_match_id, 'away', case when v_leg = 2 then v_home_source else v_away_source end
        );
        v_last_match_id := v_match_id;
      end loop;
      if v_legs = 2 then
        v_advancement_source := jsonb_build_object(
          'type', 'winner_of_tie', 'tieKey', v_tie_key
        );
        v_loser_source := jsonb_build_object(
          'type', 'loser_of_tie', 'tieKey', v_tie_key
        );
      else
        v_advancement_source := jsonb_build_object(
          'type', 'winner_of_match', 'matchId', v_last_match_id
        );
        v_loser_source := jsonb_build_object(
          'type', 'loser_of_match', 'matchId', v_last_match_id
        );
      end if;
      v_current_sources := v_current_sources || jsonb_build_array(v_advancement_source);
      if v_round_size = 4 then
        v_semifinal_loser_sources := v_semifinal_loser_sources
          || jsonb_build_array(v_loser_source);
      end if;
    end loop;
    v_previous_sources := v_current_sources;
    v_round_size := v_round_size / 2;
  end loop;
  if p_third_place and jsonb_array_length(v_semifinal_loser_sources) = 2 then
    v_round_number := v_round_number + 1;
    insert into public.tournament_rounds (
      organization_id, tournament_id, category_id, fixture_version_id,
      phase_id, round_number, name, status, sort_order
    ) values (
      v_version.organization_id, v_version.tournament_id, v_version.category_id,
      v_version.id, p_phase_id, v_round_number, 'Tercer puesto', 'draft', v_round_number - 1
    ) returning id into v_round_id;
    v_match_number := v_match_number + 1;
    insert into public.tournament_matches (
      organization_id, season_id, tournament_id, category_id,
      participant_set_id, fixture_version_id, phase_id, round_id,
      match_number, status, duration_minutes, created_by
    ) values (
      v_version.organization_id, v_version.season_id, v_version.tournament_id,
      v_version.category_id, v_version.participant_set_id, v_version.id,
      p_phase_id, v_round_id, v_match_number, 'unscheduled', v_duration, v_version.created_by
    ) returning id into v_match_id;
    perform public.insert_tournament_match_source(
      v_match_id, 'home', v_semifinal_loser_sources->0
    );
    perform public.insert_tournament_match_source(
      v_match_id, 'away', v_semifinal_loser_sources->1
    );
  end if;
end;
$$;


--
-- Name: build_tournament_round_robin(uuid, uuid, uuid, uuid[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.build_tournament_round_robin(p_fixture_version_id uuid, p_phase_id uuid, p_group_id uuid, p_participants uuid[], p_double_round boolean) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_version public.tournament_fixture_versions%rowtype;
  v_rotation uuid[] := p_participants;
  v_original uuid[];
  v_count integer;
  v_round_count integer;
  v_round_index integer;
  v_pair_index integer;
  v_leg integer;
  v_home uuid;
  v_away uuid;
  v_temp uuid;
  v_round_id uuid;
  v_match_id uuid;
  v_match_number integer;
  v_duration integer;
begin
  select version.* into v_version
  from public.tournament_fixture_versions version
  where version.id = p_fixture_version_id and version.status = 'draft';
  v_count := coalesce(array_length(v_rotation, 1), 0);
  if v_version.id is null or v_count < 2 then
    raise exception using errcode = '23514', message = 'TORNEOS_NOT_ENOUGH_PARTICIPANTS';
  end if;
  if mod(v_count, 2) = 1 then
    v_rotation := array_append(v_rotation, null::uuid);
    v_count := v_count + 1;
  end if;
  v_original := v_rotation;
  v_round_count := v_count - 1;
  select modality.suggested_duration_minutes into v_duration
  from public.tournaments tournament
  join public.tournament_sport_modalities modality
    on modality.code = tournament.sport_modality
  where tournament.id = v_version.tournament_id;
  select coalesce(max(match_row.match_number), 0) into v_match_number
  from public.tournament_matches match_row
  where match_row.fixture_version_id = p_fixture_version_id;
  for v_leg in 1..case when p_double_round then 2 else 1 end loop
    v_rotation := v_original;
    for v_round_index in 1..v_round_count loop
      insert into public.tournament_rounds (
        organization_id, tournament_id, category_id, fixture_version_id,
        phase_id, group_id, round_number, name, status, sort_order
      ) values (
        v_version.organization_id, v_version.tournament_id, v_version.category_id,
        v_version.id, p_phase_id, p_group_id,
        (v_leg - 1) * v_round_count + v_round_index,
        'Fecha ' || ((v_leg - 1) * v_round_count + v_round_index),
        'draft', (v_leg - 1) * v_round_count + v_round_index - 1
      ) returning id into v_round_id;
      for v_pair_index in 1..(v_count / 2) loop
        v_home := v_rotation[v_pair_index];
        v_away := v_rotation[v_count - v_pair_index + 1];
        if mod(v_round_index + v_pair_index, 2) = 1 then
          v_temp := v_home;
          v_home := v_away;
          v_away := v_temp;
        end if;
        if v_leg = 2 then
          v_temp := v_home;
          v_home := v_away;
          v_away := v_temp;
        end if;
        if v_home is not null and v_away is not null then
          v_match_number := v_match_number + 1;
          insert into public.tournament_matches (
            organization_id, season_id, tournament_id, category_id,
            participant_set_id, fixture_version_id, phase_id, group_id, round_id,
            match_number, leg_number, home_participant_id, away_participant_id, status,
            duration_minutes, created_by
          ) values (
            v_version.organization_id, v_version.season_id, v_version.tournament_id,
            v_version.category_id, v_version.participant_set_id, v_version.id,
            p_phase_id, p_group_id, v_round_id, v_match_number, v_leg, v_home, v_away,
            'unscheduled', v_duration, v_version.created_by
          ) returning id into v_match_id;
          perform public.insert_tournament_match_source(
            v_match_id, 'home',
            jsonb_build_object('type', 'participant', 'participantId', v_home)
          );
          perform public.insert_tournament_match_source(
            v_match_id, 'away',
            jsonb_build_object('type', 'participant', 'participantId', v_away)
          );
        end if;
      end loop;
      v_temp := v_rotation[v_count];
      for v_pair_index in reverse v_count..3 loop
        v_rotation[v_pair_index] := v_rotation[v_pair_index - 1];
      end loop;
      v_rotation[2] := v_temp;
    end loop;
  end loop;
end;
$$;


--
-- Name: bulk_schedule_tournament_matches(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.bulk_schedule_tournament_matches(p_organization_id uuid, p_assignments jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_assignment jsonb;
  v_result jsonb;
  v_results jsonb := '[]'::jsonb;
begin
  if private.current_identity_id() is null or jsonb_typeof(p_assignments) <> 'array'
    or jsonb_array_length(p_assignments) not between 1 and 100
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_SCHEDULE_BATCH';
  end if;
  for v_assignment in select value from jsonb_array_elements(p_assignments)
  loop
    v_result := public.schedule_tournament_match(
      p_organization_id,
      (v_assignment->>'matchId')::uuid,
      (v_assignment->>'scheduledAt')::timestamptz,
      (v_assignment->>'venueId')::uuid,
      (v_assignment->>'courtId')::uuid,
      (v_assignment->>'durationMinutes')::integer,
      coalesce((v_assignment->>'overrideWarnings')::boolean, false),
      v_assignment->>'overrideReason'
    );
    v_results := v_results || jsonb_build_array(v_result);
  end loop;
  return jsonb_build_object('scheduledCount', jsonb_array_length(v_results), 'results', v_results);
end;
$$;


--
-- Name: can_access_tournament_communications(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_tournament_communications(p_tournament_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.current_identity_id() is not null and exists (
    select 1
    from public.tournaments tournament
    join public.tournament_organizations organization
      on organization.id = tournament.organization_id
    where tournament.id = p_tournament_id
      and organization.status = 'active'
      and (
        exists (
          select 1
          from public.tournament_organization_members membership
          where membership.organization_id = tournament.organization_id
            and membership.user_id = private.current_identity_id()
            and membership.status = 'active'
        )
        or exists (
          select 1
          from public.tournament_categories category
          where category.organization_id = tournament.organization_id
            and category.tournament_id = tournament.id
            and category.status = 'active'
            and public.can_read_tournament_participant_hub(
              tournament.id,category.id
            )
        )
      )
  );
$$;


--
-- Name: can_current_user_access_tournament_announcement(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_current_user_access_tournament_announcement(p_announcement_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.current_identity_id() is not null and exists (
    select 1
    from public.resolve_tournament_announcement_recipients(p_announcement_id) recipient
    where recipient.user_id = private.current_identity_id()
  );
$$;


--
-- Name: can_current_user_read_media_gallery(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_current_user_read_media_gallery(p_gallery_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.current_identity_id() is not null and exists (
    select 1
    from public.tournament_media_galleries gallery
    where gallery.id = p_gallery_id
      and gallery.status = 'published'
      and gallery.visibility <> 'administrative_private'
      and public.can_read_tournament_participant_hub(
        gallery.tournament_id,
        gallery.category_id
      )
      and (
        (
          gallery.visibility = 'organization'
          and public.is_tournament_organization_member(gallery.organization_id)
        )
        or gallery.visibility = 'tournament_participants'
        or (
          gallery.visibility = 'match_participants'
          and gallery.match_id is not null
          and exists (
            select 1
            from public.tournament_matches match
            join public.tournament_competition_participants participant
              on participant.participant_set_id = match.participant_set_id
             and participant.id in (match.home_participant_id,match.away_participant_id)
            where match.id = gallery.match_id
              and public.current_user_has_media_team_relation(participant.team_entry_id)
          )
        )
        or (
          gallery.visibility = 'related_teams'
          and exists (
            select 1
            from public.tournament_media_gallery_items item
            join public.tournament_media_relations relation
              on relation.asset_id = item.asset_id
             and relation.relation_type in ('team','player')
            where item.gallery_id = gallery.id
              and public.current_user_has_media_team_relation(relation.team_entry_id)
          )
        )
      )
  );
$$;


--
-- Name: can_edit_tournament_team_entry(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_edit_tournament_team_entry(p_organization_id uuid, p_team_entry_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.current_identity_id() is not null and exists (
    select 1
    from public.tournament_team_entries entry
    join public.tournament_organizations organization
      on organization.id = entry.organization_id
    join public.tournaments tournament
      on tournament.id = entry.tournament_id
      and tournament.organization_id = entry.organization_id
    join public.tournament_categories category
      on category.id = entry.category_id
      and category.organization_id = entry.organization_id
      and category.tournament_id = entry.tournament_id
    left join public.tournament_roster_settings settings
      on settings.organization_id = entry.organization_id
      and settings.tournament_id = entry.tournament_id
    where entry.id = p_team_entry_id
      and entry.organization_id = p_organization_id
      and organization.status = 'active'
      and category.status = 'active'
      and entry.status in ('draft', 'invited', 'in_progress', 'changes_requested')
      and (
        public.has_tournament_organization_capability(
          p_organization_id,
          'team_entries.update'
        )
        or exists (
          select 1
          from public.tournament_team_managers manager
          where manager.team_entry_id = entry.id
            and manager.organization_id = entry.organization_id
            and manager.user_id = private.current_identity_id()
            and manager.status = 'active'
            and manager.role in ('captain', 'delegate')
        )
      )
      and (
        entry.status = 'changes_requested'
        or (
          tournament.status = 'registration'
          and (
            tournament.registration_opens_at is null
            or now() >= tournament.registration_opens_at
          )
          and (
            tournament.registration_closes_at is null
            or now() <= tournament.registration_closes_at
          )
          and (
            settings.roster_opens_at is null
            or now() >= settings.roster_opens_at
          )
          and (
            settings.roster_closes_at is null
            or now() <= settings.roster_closes_at
          )
        )
      )
  );
$$;


--
-- Name: can_manage_tournament_match_squad(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_manage_tournament_match_squad(p_organization_id uuid, p_match_id uuid, p_team_entry_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.current_identity_id() is not null
    and exists (
      select 1
      from public.tournament_matches match_row
      cross join lateral public.tournament_match_team_entries(match_row.id) teams
      where match_row.id = p_match_id
        and match_row.organization_id = p_organization_id
        and p_team_entry_id in (teams.home_team_entry_id, teams.away_team_entry_id)
    )
    and (
      public.has_tournament_organization_capability(
        p_organization_id, 'match_squads.manage'
      )
      or public.is_tournament_team_manager(p_team_entry_id, false)
    );
$$;


--
-- Name: can_manage_tournament_player_portrait(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_manage_tournament_player_portrait(p_organization_id uuid, p_roster_player_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT public.can_manage_tournament_player_portrait_as(
    p_organization_id, p_roster_player_id, private.current_identity_id()
  );
$$;


--
-- Name: can_manage_tournament_player_portrait_as(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_manage_tournament_player_portrait_as(p_organization_id uuid, p_roster_player_id uuid, p_actor_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.tournament_roster_players player
    WHERE player.organization_id = p_organization_id
      AND player.id = p_roster_player_id
      AND public.can_manage_tournament_team_visual_assets_as(
        p_organization_id, player.team_entry_id, p_actor_user_id,
        'roster_players.update'
      )
  );
$$;


--
-- Name: can_manage_tournament_team_visual_assets_as(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_manage_tournament_team_visual_assets_as(p_organization_id uuid, p_team_entry_id uuid, p_actor_user_id uuid, p_organization_capability text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT p_actor_user_id IS NOT NULL
    -- El parámetro es interno, pero se valida igual: una capability arbitraria
    -- no puede convertirse en una llave nueva.
    AND p_organization_capability IN ('team_entries.update', 'roster_players.update')
    AND EXISTS (
      SELECT 1
      FROM public.tournament_team_entries entry
      JOIN public.tournament_organizations organization
        ON organization.id = entry.organization_id
      JOIN public.tournaments tournament
        ON tournament.id = entry.tournament_id
       AND tournament.organization_id = entry.organization_id
      -- El par (organización, equipo) se valida en el WHERE: un team_entry_id
      -- de otro tenant no se vuelve alcanzable cambiando el organization_id.
      WHERE entry.id = p_team_entry_id
        AND entry.organization_id = p_organization_id
        AND entry.status <> 'archived'
        AND organization.status = 'active'
        AND tournament.status <> 'archived'
        AND (
          -- Rama 1: la organización. Independiente de la política.
          EXISTS (
            SELECT 1
            FROM public.tournament_organization_members membership
            WHERE membership.organization_id = p_organization_id
              AND membership.user_id = p_actor_user_id
              AND membership.status = 'active'
              AND p_organization_capability = ANY(
                public.tournament_role_capabilities(membership.role)
              )
          )
          -- Ramas 2 y 3: miembros de ESTE equipo. Las dos exigen además que la
          -- inscripción siga viva: una inscripción rechazada o retirada ya no
          -- es un equipo del torneo, y mantenerle la autogestión sería dejar
          -- permisos colgando de un vínculo que la organización ya cerró. La
          -- rama de organización no pasa por acá: conserva el alcance que ya
          -- tenía y sigue siendo el override.
          OR (
            entry.status NOT IN ('rejected', 'withdrawn')
            AND (
              -- Rama 2: responsables. `captain` y `delegate` son roles reales
              -- de tournament_team_managers; `assistant` no entra.
              (
                tournament.team_visual_management_policy IN ('delegates', 'roster')
                AND EXISTS (
                  SELECT 1
                  FROM public.tournament_team_managers manager
                  WHERE manager.organization_id = entry.organization_id
                    AND manager.team_entry_id = entry.id
                    AND manager.user_id = p_actor_user_id
                    AND manager.status = 'active'
                    AND manager.role IN ('captain', 'delegate')
                )
              )
              -- Rama 3: el plantel.
              OR (
                tournament.team_visual_management_policy = 'roster'
                AND public.is_tournament_team_roster_member_as(entry.id, p_actor_user_id)
              )
            )
          )
        )
    );
$$;


--
-- Name: FUNCTION can_manage_tournament_team_visual_assets_as(p_organization_id uuid, p_team_entry_id uuid, p_actor_user_id uuid, p_organization_capability text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.can_manage_tournament_team_visual_assets_as(p_organization_id uuid, p_team_entry_id uuid, p_actor_user_id uuid, p_organization_capability text) IS 'Fuente de verdad de la autogestión visual: organización siempre, más los miembros del propio equipo que la política del torneo habilite.';


--
-- Name: can_moderate_tournament_team_visual_assets_as(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_moderate_tournament_team_visual_assets_as(p_organization_id uuid, p_team_entry_id uuid, p_actor_user_id uuid, p_organization_capability text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT p_actor_user_id IS NOT NULL
    AND p_organization_capability IN ('team_entries.update', 'roster_players.update')
    AND EXISTS (
      SELECT 1
      FROM public.tournament_team_entries entry
      JOIN public.tournament_organizations organization
        ON organization.id = entry.organization_id
      JOIN public.tournaments tournament
        ON tournament.id = entry.tournament_id
       AND tournament.organization_id = entry.organization_id
      JOIN public.tournament_organization_members membership
        ON membership.organization_id = entry.organization_id
       AND membership.user_id = p_actor_user_id
       AND membership.status = 'active'
      WHERE entry.id = p_team_entry_id
        AND entry.organization_id = p_organization_id
        AND entry.status <> 'archived'
        AND organization.status = 'active'
        AND tournament.status <> 'archived'
        AND p_organization_capability = ANY(
          public.tournament_role_capabilities(membership.role)
        )
    );
$$;


--
-- Name: FUNCTION can_moderate_tournament_team_visual_assets_as(p_organization_id uuid, p_team_entry_id uuid, p_actor_user_id uuid, p_organization_capability text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.can_moderate_tournament_team_visual_assets_as(p_organization_id uuid, p_team_entry_id uuid, p_actor_user_id uuid, p_organization_capability text) IS 'Rama de organización sola. Gobierna moderación y consentimiento, que la autogestión no amplía en ningún valor de la política.';


--
-- Name: can_read_tournament_fixture_scope(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_read_tournament_fixture_scope(p_organization_id uuid, p_tournament_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.current_identity_id() is not null and exists (
    select 1
    from public.tournament_organizations organization
    join public.tournaments tournament
      on tournament.organization_id = organization.id
    where organization.id = p_organization_id
      and organization.status = 'active'
      and tournament.id = p_tournament_id
      and tournament.status <> 'archived'
      and public.has_tournament_organization_capability(
        p_organization_id,
        'fixture.read'
      )
  );
$$;


--
-- Name: can_read_tournament_match(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_read_tournament_match(p_match_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.current_identity_id() is not null and exists (
    select 1
    from public.tournament_matches match_row
    join public.tournament_organizations organization
      on organization.id = match_row.organization_id
    join public.tournaments tournament on tournament.id = match_row.tournament_id
    where match_row.id = p_match_id
      and organization.status = 'active'
      and tournament.status <> 'archived'
      and (
        public.has_tournament_organization_capability(
          match_row.organization_id, 'matches.read'
        )
        or exists (
          select 1
          from public.tournament_competition_participants participant
          join public.tournament_team_managers manager
            on manager.team_entry_id = participant.team_entry_id
            and manager.organization_id = participant.organization_id
          where participant.id in (
              match_row.home_participant_id,
              match_row.away_participant_id
            )
            and manager.user_id = private.current_identity_id()
            and manager.status = 'active'
            and not exists (
              select 1
              from public.tournament_organization_members blocked_membership
              where blocked_membership.organization_id = match_row.organization_id
                and blocked_membership.user_id = private.current_identity_id()
                and blocked_membership.status <> 'active'
            )
        )
      )
  );
$$;


--
-- Name: can_read_tournament_match_operation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_read_tournament_match_operation(p_organization_id uuid, p_match_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.current_identity_id() is not null
    and public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.read'
    )
    and exists (
    select 1
    from public.tournament_matches match_row
    where match_row.id = p_match_id
      and match_row.organization_id = p_organization_id
    );
$$;


--
-- Name: can_read_tournament_participant_hub(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_read_tournament_participant_hub(p_tournament_id uuid, p_category_id uuid DEFAULT NULL::uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.current_identity_id() is not null and exists (
    select 1
    from public.tournaments tournament
    join public.tournament_organizations organization
      on organization.id = tournament.organization_id
    where tournament.id = p_tournament_id
      and organization.status = 'active'
      and (
        p_category_id is null
        or exists (
          select 1
          from public.tournament_categories category
          where category.id = p_category_id
            and category.organization_id = tournament.organization_id
            and category.tournament_id = tournament.id
            and category.status = 'active'
        )
      )
      and (
        exists (
          select 1
          from public.tournament_organization_members membership
          where membership.organization_id = tournament.organization_id
            and membership.user_id = private.current_identity_id()
            and membership.status = 'active'
        )
        or exists (
          select 1
          from public.tournament_team_entries entry
          join public.tournament_team_managers manager
            on manager.organization_id = entry.organization_id
           and manager.team_entry_id = entry.id
          where entry.tournament_id = tournament.id
            and entry.organization_id = tournament.organization_id
            and entry.status = 'approved'
            and (p_category_id is null or entry.category_id = p_category_id)
            and manager.user_id = private.current_identity_id()
            and manager.status = 'active'
            and manager.role in ('captain', 'delegate')
        )
        or exists (
          select 1
          from public.tournament_team_entries entry
          join public.get_my_current_tournament_roster_players() player
            on player.team_entry_id = entry.id
          where entry.tournament_id = tournament.id
            and entry.organization_id = tournament.organization_id
            and entry.status = 'approved'
            and (p_category_id is null or entry.category_id = p_category_id)
        )
      )
  );
$$;


--
-- Name: can_read_tournament_player_portrait(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_read_tournament_player_portrait(p_organization_id uuid, p_roster_player_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT public.can_read_tournament_player_portrait_as(
    p_organization_id, p_roster_player_id, private.current_identity_id()
  );
$$;


--
-- Name: can_read_tournament_player_portrait_as(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_read_tournament_player_portrait_as(p_organization_id uuid, p_roster_player_id uuid, p_actor_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT p_actor_user_id IS NOT NULL AND (
    EXISTS (
      SELECT 1
      FROM public.tournament_roster_players player
      JOIN public.tournament_team_entries entry
        ON entry.organization_id = player.organization_id
       AND entry.id = player.team_entry_id
      JOIN public.tournament_organizations organization
        ON organization.id = player.organization_id
      WHERE player.organization_id = p_organization_id
        AND player.id = p_roster_player_id
        AND organization.status = 'active'
        AND entry.status <> 'archived'
        AND (
          EXISTS (
            SELECT 1
            FROM public.tournament_organization_members membership
            WHERE membership.organization_id = p_organization_id
              AND membership.user_id = p_actor_user_id
              AND membership.status = 'active'
              AND 'roster_players.read' = ANY(
                public.tournament_role_capabilities(membership.role)
              )
          )
          OR EXISTS (
            SELECT 1
            FROM public.tournament_team_managers manager
            WHERE manager.organization_id = p_organization_id
              AND manager.team_entry_id = player.team_entry_id
              AND manager.user_id = p_actor_user_id
              AND manager.status = 'active'
          )
          OR player.arma2_user_id = p_actor_user_id
          OR EXISTS (
            SELECT 1
            FROM public.tournament_provisional_players provisional
            WHERE provisional.organization_id = player.organization_id
              AND provisional.id = player.provisional_player_id
              AND provisional.claim_status = 'claimed'
              AND provisional.claimed_by_user_id = p_actor_user_id
          )
        )
    )
    OR public.can_manage_tournament_player_portrait_as(
      p_organization_id, p_roster_player_id, p_actor_user_id
    )
  );
$$;


--
-- Name: can_read_tournament_projection_scope(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_read_tournament_projection_scope(p_organization_id uuid, p_tournament_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.current_identity_id() is not null and exists (
    select 1
    from public.tournament_organizations organization
    join public.tournaments tournament
      on tournament.organization_id = organization.id
    where organization.id = p_organization_id
      and tournament.id = p_tournament_id
      and organization.status = 'active'
      and tournament.status <> 'archived'
      and (
        public.has_tournament_organization_capability(p_organization_id, 'standings.read')
        or exists (
          select 1
          from public.tournament_team_entries entry
          join public.tournament_team_managers manager on manager.team_entry_id = entry.id
          where entry.organization_id = p_organization_id
            and entry.tournament_id = p_tournament_id
            and entry.status = 'approved'
            and manager.user_id = private.current_identity_id()
            and manager.status = 'active'
        )
        or exists (
          select 1
          from public.tournament_team_entries entry
          join public.tournament_roster_players player on player.team_entry_id = entry.id
          where entry.organization_id = p_organization_id
            and entry.tournament_id = p_tournament_id
            and entry.status = 'approved'
            and player.arma2_user_id = private.current_identity_id()
            and player.status = 'active'
        )
      )
  );
$$;


--
-- Name: can_read_tournament_team_entry(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_read_tournament_team_entry(p_organization_id uuid, p_team_entry_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.current_identity_id() is not null and exists (
    select 1
    from public.tournament_team_entries entry
    join public.tournament_organizations organization
      on organization.id = entry.organization_id
    join public.tournaments tournament
      on tournament.id = entry.tournament_id
      and tournament.organization_id = entry.organization_id
    join public.tournament_categories category
      on category.id = entry.category_id
      and category.organization_id = entry.organization_id
      and category.tournament_id = entry.tournament_id
    where entry.id = p_team_entry_id
      and entry.organization_id = p_organization_id
      and entry.status <> 'archived'
      and organization.status = 'active'
      and tournament.status <> 'archived'
      and category.status = 'active'
      and (
        public.has_tournament_organization_capability(
          p_organization_id,
          'team_entries.read'
        )
        or public.is_tournament_team_manager(p_team_entry_id, false)
      )
  );
$$;


--
-- Name: can_read_tournament_team_photo_as(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_read_tournament_team_photo_as(p_organization_id uuid, p_team_entry_id uuid, p_actor_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT p_actor_user_id IS NOT NULL AND (
    EXISTS (
      SELECT 1
      FROM public.tournament_team_entries entry
      JOIN public.tournament_organizations organization
        ON organization.id = entry.organization_id
      JOIN public.tournaments tournament
        ON tournament.id = entry.tournament_id
       AND tournament.organization_id = entry.organization_id
      WHERE entry.id = p_team_entry_id
        AND entry.organization_id = p_organization_id
        AND entry.status <> 'archived'
        AND organization.status = 'active'
        AND tournament.status <> 'archived'
        AND (
          EXISTS (
            SELECT 1
            FROM public.tournament_organization_members membership
            WHERE membership.organization_id = p_organization_id
              AND membership.user_id = p_actor_user_id
              AND membership.status = 'active'
              AND 'team_entries.read' = ANY(
                public.tournament_role_capabilities(membership.role)
              )
          )
          OR EXISTS (
            SELECT 1
            FROM public.tournament_team_managers manager
            WHERE manager.organization_id = p_organization_id
              AND manager.team_entry_id = entry.id
              AND manager.user_id = p_actor_user_id
              AND manager.status = 'active'
          )
        )
    )
    OR public.can_manage_tournament_team_visual_assets_as(
      p_organization_id, p_team_entry_id, p_actor_user_id, 'team_entries.update'
    )
  );
$$;


--
-- Name: FUNCTION can_read_tournament_team_photo_as(p_organization_id uuid, p_team_entry_id uuid, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.can_read_tournament_team_photo_as(p_organization_id uuid, p_team_entry_id uuid, p_actor_user_id uuid) IS 'Quién ve la foto VIGENTE de un equipo. La candidata y la rechazada exigen gestión o moderación, no esto.';


--
-- Name: can_update_tournament_team_branding(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_update_tournament_team_branding(p_organization_id uuid, p_team_entry_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT EXISTS (
    SELECT 1
    FROM public.tournament_team_entries entry
    WHERE entry.id = p_team_entry_id
      AND entry.organization_id = p_organization_id
      AND entry.status IN (
        'draft', 'invited', 'in_progress', 'changes_requested', 'approved'
      )
  ) AND public.can_manage_tournament_team_visual_assets_as(
    p_organization_id, p_team_entry_id, private.current_identity_id(), 'team_entries.update'
  );
$$;


--
-- Name: can_write_tournament_branding_object(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_write_tournament_branding_object(p_name text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_organization_id uuid;
  v_entity_id uuid;
  v_kind text;
BEGIN
  IF private.current_identity_id() IS NULL OR NOT public.is_tournament_branding_path(p_name) THEN
    RETURN false;
  END IF;

  v_organization_id := split_part(p_name, '/', 1)::uuid;
  v_kind := split_part(p_name, '/', 2);
  v_entity_id := split_part(p_name, '/', 3)::uuid;

  IF v_kind = 'organizations' THEN
    RETURN v_entity_id = v_organization_id
      AND public.has_tournament_organization_capability(
        v_organization_id,
        'organization.update'
      );
  END IF;

  IF v_kind = 'tournaments' THEN
    RETURN public.has_tournament_organization_capability(
      v_organization_id,
      'tournaments.update'
    ) AND EXISTS (
      SELECT 1
      FROM public.tournaments tournament
      WHERE tournament.id = v_entity_id
        AND tournament.organization_id = v_organization_id
        AND tournament.status <> 'archived'
    );
  END IF;

  IF v_kind = 'teams' THEN
    RETURN public.can_update_tournament_team_branding(
      v_organization_id,
      v_entity_id
    );
  END IF;

  RETURN false;
END;
$$;


--
-- Name: cancel_tournament_match(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_tournament_match(p_organization_id uuid, p_match_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_match public.tournament_matches%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if private.current_identity_id() is null or char_length(v_reason) not between 3 and 500
    or not public.has_tournament_organization_capability(
      p_organization_id, 'matches.cancel'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select match_row.* into v_match
  from public.tournament_matches match_row
  join public.tournament_fixture_versions version
    on version.id = match_row.fixture_version_id
    and version.status in ('draft', 'published')
    and version.invalidated_at is null
  where match_row.id = p_match_id
    and match_row.organization_id = p_organization_id
    and match_row.status in ('scheduled', 'postponed')
  for update of match_row;
  if v_match.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  update public.tournament_matches
  set status = 'cancelled',
      cancelled_at = now(),
      cancelled_by = private.current_identity_id(),
      cancellation_reason_code = 'manual_cancellation',
      cancellation_reason_text = v_reason
  where id = v_match.id;
  perform public.append_tournament_audit(
    p_organization_id, 'match.cancelled', 'match', v_match.id,
    null, v_match.tournament_id,
    jsonb_build_object(
      'reason', v_reason, 'previousStatus',
      v_match.status, 'reasonCode', 'manual_cancellation'
    )
  );
  return jsonb_build_object('matchId', v_match.id, 'status', 'cancelled');
end;
$$;


--
-- Name: cancel_tournament_media_upload_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_tournament_media_upload_session(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_session public.tournament_media_upload_sessions%rowtype;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_session
  from public.tournament_media_upload_sessions
  where id = p_session_id;
  if v_session.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_session.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_session.gallery_id::text,1)
  );
  select * into v_session
  from public.tournament_media_upload_sessions
  where id = p_session_id
  for update;
  if v_session.requested_by <> private.current_identity_id()
    and not public.has_tournament_media_capability(
      v_session.organization_id,'media.update_gallery'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  if v_session.status = 'revoked' then
    return jsonb_build_object('sessionId',p_session_id,'status','revoked');
  end if;
  if v_session.status <> 'issued' then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_UPLOAD_SESSION_INVALID';
  end if;
  update public.tournament_media_upload_sessions
  set status = 'revoked'
  where id = p_session_id;
  perform public.append_tournament_audit(
    v_session.organization_id,'media.upload_session.cancelled',
    'media_upload_session',p_session_id,null,v_session.tournament_id,
    jsonb_build_object('galleryId',v_session.gallery_id)
  );
  return jsonb_build_object('sessionId',p_session_id,'status','revoked');
end;
$$;


--
-- Name: cancel_tournament_purchase(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_tournament_purchase(p_purchase_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_purchase public.tournament_purchases%rowtype; v_from_status text;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_purchase from public.tournament_purchases
  where id = p_purchase_id for update;
  if v_purchase.id is null or not (
    v_purchase.buyer_user_id = private.current_identity_id()
    or public.has_tournament_organization_capability(v_purchase.organization_id,'billing.manage')
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_PURCHASE_FORBIDDEN';
  end if;
  if v_purchase.status = 'cancelled' then
    return public.tournament_purchase_projection(v_purchase) || jsonb_build_object('idempotentReplay',true);
  end if;
  if v_purchase.status not in ('created','preference_created','pending') then
    raise exception using errcode = '55000', message = 'TORNEOS_PURCHASE_TRANSITION_INVALID';
  end if;
  v_from_status := v_purchase.status;
  update public.tournament_purchases set
    status = 'cancelled',provider_status = 'cancelled',cancelled_at = now()
  where id = v_purchase.id returning * into v_purchase;
  insert into public.tournament_purchase_events (
    purchase_id,organization_id,event_type,from_status,to_status,provider_status,
    actor_type,actor_user_id
  ) values (
    v_purchase.id,v_purchase.organization_id,'purchase.cancelled',v_from_status,
    'cancelled','cancelled','user',private.current_identity_id()
  );
  return public.tournament_purchase_projection(v_purchase) || jsonb_build_object('idempotentReplay',false);
end;
$$;


--
-- Name: change_tournament_media_gallery_state(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.change_tournament_media_gallery_state(p_gallery_id uuid, p_action text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_gallery public.tournament_media_galleries%rowtype;
  v_status text;
  v_capability text;
begin
  select * into v_gallery
  from public.tournament_media_galleries where id = p_gallery_id;
  if v_gallery.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_gallery.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_gallery_id::text,1)
  );
  select * into v_gallery
  from public.tournament_media_galleries where id = p_gallery_id for update;
  v_status := case p_action when 'archive' then 'archived' when 'revoke' then 'revoked' end;
  v_capability := case p_action when 'archive' then 'media.archive' when 'revoke' then 'media.revoke' end;
  if v_gallery.id is null or v_status is null
    or not public.has_tournament_media_capability(v_gallery.organization_id,v_capability)
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  if v_gallery.status in ('archived','revoked') then
    if v_gallery.status = v_status then
      return jsonb_build_object('galleryId',p_gallery_id,'status',v_status);
    end if;
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_TRANSITION_INVALID';
  end if;
  if p_reason is null or char_length(btrim(p_reason)) < 3 then
    raise exception using errcode = '22023', message = 'TORNEOS_REASON_REQUIRED';
  end if;
  update public.tournament_media_galleries
  set status = v_status,
      archived_at = case when v_status = 'archived' then now() else null end,
      revoked_at = case when v_status = 'revoked' then now() else null end,
      version = version + 1
  where id = p_gallery_id;
  update public.tournament_media_assets
  set status = case when v_status = 'revoked' then 'revoked' else 'hidden' end,
      hidden_at = case when v_status = 'archived' then now() else hidden_at end,
      revoked_at = case when v_status = 'revoked' then now() else revoked_at end
  where gallery_id = p_gallery_id
    and status in (
      'uploading','processing','pending_review','approved','published','hidden'
    );
  update public.tournament_media_upload_sessions
  set status = 'revoked'
  where gallery_id = p_gallery_id
    and status = 'issued';
  perform public.append_tournament_audit(
    v_gallery.organization_id,'media.gallery.' || p_action,'media_gallery',
    p_gallery_id,null,v_gallery.tournament_id,jsonb_build_object('reason',btrim(p_reason))
  );
  return jsonb_build_object('galleryId',p_gallery_id,'status',v_status);
end;
$$;


--
-- Name: change_tournament_status(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.change_tournament_status(p_organization_id uuid, p_tournament_id uuid, p_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tournament public.tournaments%rowtype;
  v_checklist jsonb;
  v_capability text := case
    when p_status = 'archived' then 'tournaments.archive'
    else 'tournaments.change_status'
  end;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(
    p_organization_id,
    v_capability
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  select tournament.* into v_tournament
  from public.tournaments tournament
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
  for update;

  if v_tournament.id is null
    or not (
      (v_tournament.status = 'draft' and p_status in ('registration', 'archived'))
      or (v_tournament.status = 'registration' and p_status in ('draft', 'archived'))
    )
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_TOURNAMENT_TRANSITION';
  end if;

  if p_status = 'registration' then
    v_checklist := public.tournament_registration_checklist(
      p_organization_id,
      p_tournament_id
    );
    if not (v_checklist->>'ready')::boolean then
      raise exception using
        errcode = '23514',
        message = 'TORNEOS_REGISTRATION_INCOMPLETE';
    end if;
  end if;

  update public.tournaments
  set status = p_status,
      archived_at = case when p_status = 'archived' then now() else null end
  where id = p_tournament_id
  returning * into v_tournament;

  if p_status = 'archived' then
    update public.user_tournament_context_preferences
    set active_tournament_id = null
    where organization_id = p_organization_id
      and active_tournament_id = p_tournament_id;
  end if;

  return jsonb_build_object(
    'id', v_tournament.id,
    'status', v_tournament.status,
    'checklist', case
      when p_status = 'archived' then null
      else coalesce(
        v_checklist,
        public.tournament_registration_checklist(
          p_organization_id,
          p_tournament_id
        )
      )
    end
  );
end;
$$;


--
-- Name: cleanup_tournament_media_processing_jobs(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_tournament_media_processing_jobs(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_requeued jsonb;
  v_purgeable jsonb;
begin
  if p_limit is null or p_limit < 1 or p_limit > 1000 then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_FILTER_INVALID';
  end if;
  with stale as (
    select job.id
    from public.tournament_media_processing_jobs job
    where job.status = 'leased' and job.lease_expires_at <= now()
    order by job.lease_expires_at
    limit p_limit
    for update skip locked
  ), requeued as (
    update public.tournament_media_processing_jobs job
    set status = case when job.attempts >= job.max_attempts
          then 'abandoned' else 'queued' end,
        lease_token = null, lease_expires_at = null,
        last_error = 'LEASE_EXPIRED', updated_at = now()
    from stale
    where job.id = stale.id
    returning job.id, job.status
  )
  select coalesce(jsonb_agg(jsonb_build_object('jobId',id,'status',status)),'[]'::jsonb)
  into v_requeued from requeued;

  select coalesce(jsonb_agg(jsonb_build_object(
    'bucket',job.bucket,'objectName',job.quarantine_path
  )),'[]'::jsonb) into v_purgeable
  from public.tournament_media_processing_jobs job
  where job.status = 'abandoned'
    and not exists (
      select 1 from public.tournament_media_assets asset
      where asset.internal_path = job.quarantine_path
    )
  limit p_limit;

  return jsonb_build_object(
    'requeued',v_requeued,'purgeable',v_purgeable,'checkedAt',now()
  );
end;
$$;


--
-- Name: cleanup_tournament_media_upload_sessions(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_tournament_media_upload_sessions(p_limit integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_expired jsonb;
  v_purgeable jsonb;
begin
  if p_limit is null or p_limit < 1 or p_limit > 1000 then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_FILTER_INVALID';
  end if;
  with stale as (
    select id
    from public.tournament_media_upload_sessions
    where status = 'issued' and expires_at <= now()
    order by expires_at
    limit p_limit
    for update skip locked
  ), expired as (
    update public.tournament_media_upload_sessions session
    set status = 'expired'
    from stale
    where session.id = stale.id
    returning session.id, session.bucket, session.internal_path
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'sessionId',id,'bucket',bucket,'objectName',internal_path
  )),'[]'::jsonb) into v_expired from expired;

  -- Everything that may be deleted from the bucket: object names reserved by a
  -- session that will never be consumed, and whose name was not adopted by an
  -- asset. An asset's own paths are never purgeable through this contract.
  select coalesce(jsonb_agg(jsonb_build_object(
    'bucket',session.bucket,'objectName',session.internal_path
  )),'[]'::jsonb) into v_purgeable
  from public.tournament_media_upload_sessions session
  where session.status in ('expired','revoked','failed')
    and not exists (
      select 1 from public.tournament_media_assets asset
      where asset.internal_path = session.internal_path
    )
  limit p_limit;

  return jsonb_build_object(
    'expired',v_expired,'purgeable',v_purgeable,'checkedAt',now()
  );
end;
$$;


--
-- Name: clear_tournament_entitlement_override(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_tournament_entitlement_override(p_organization_id uuid, p_tournament_id uuid, p_capability text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_override_id uuid;
BEGIN
  IF p_tournament_id IS NULL THEN
    DELETE FROM public.tournament_organization_entitlement_overrides override_row
    WHERE override_row.organization_id = p_organization_id
      AND override_row.capability = p_capability
    RETURNING id INTO v_override_id;
  ELSE
    DELETE FROM public.tournament_entitlement_overrides override_row
    WHERE override_row.organization_id = p_organization_id
      AND override_row.tournament_id = p_tournament_id
      AND override_row.capability = p_capability
    RETURNING id INTO v_override_id;
  END IF;
  IF v_override_id IS NULL THEN
    RETURN false;
  END IF;
  INSERT INTO public.tournament_audit_log (
    organization_id,actor_user_id,actor_type,action,resource_type,
    resource_id,tournament_id,metadata
  ) VALUES (
    p_organization_id,NULL,'system','entitlement.override_removed',
    'entitlement_override',v_override_id,p_tournament_id,
    jsonb_build_object('capability',p_capability)
  );
  RETURN true;
END;
$$;


--
-- Name: complete_tournament_media_asset_delete(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_tournament_media_asset_delete(p_actor_user_id uuid, p_asset_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_asset public.tournament_media_assets%rowtype;
  v_gallery public.tournament_media_galleries%rowtype;
  v_previous_claim text := coalesce(
    pg_catalog.current_setting('request.jwt.claim.sub', true), ''
  );
  v_replacement uuid;
BEGIN
  IF p_actor_user_id IS NULL OR p_asset_id IS NULL THEN
    RAISE EXCEPTION USING
      errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  END IF;

  SELECT * INTO v_asset
  FROM public.tournament_media_assets
  WHERE id = p_asset_id;
  IF v_asset.id IS NULL THEN
    RAISE EXCEPTION USING
      errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  END IF;

  PERFORM pg_catalog.set_config(
    'request.jwt.claim.sub', p_actor_user_id::text, true
  );
  BEGIN
    IF NOT public.has_tournament_media_capability(
      v_asset.organization_id, 'media.revoke'
    ) THEN
      RAISE EXCEPTION USING
        errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
    END IF;

    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(v_asset.organization_id::text, 0)
    );
    PERFORM pg_catalog.pg_advisory_xact_lock(
      pg_catalog.hashtextextended(v_asset.gallery_id::text, 1)
    );
    SELECT * INTO v_gallery
    FROM public.tournament_media_galleries
    WHERE id = v_asset.gallery_id
    FOR UPDATE;
    SELECT * INTO v_asset
    FROM public.tournament_media_assets
    WHERE id = p_asset_id
    FOR UPDATE;
    IF v_asset.id IS NULL THEN
      RAISE EXCEPTION USING
        errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
    END IF;
    IF NOT (
      v_asset.storage_state = 'retention_marked'
      AND v_asset.retention_reason LIKE 'USER_REQUESTED_DELETE:%'
    ) THEN
      RAISE EXCEPTION USING
        errcode = '22023', message = 'TORNEOS_MEDIA_DELETE_INVALID';
    END IF;

    IF v_gallery.cover_asset_id = p_asset_id THEN
      SELECT asset.id INTO v_replacement
      FROM public.tournament_media_gallery_items item
      JOIN public.tournament_media_assets asset ON asset.id = item.asset_id
      WHERE item.gallery_id = v_gallery.id
        AND asset.id <> p_asset_id
        AND asset.status IN ('approved', 'published')
        AND asset.storage_state = 'active'
      ORDER BY item.sort_order, asset.created_at
      LIMIT 1;

      UPDATE public.tournament_media_galleries
      SET cover_asset_id = v_replacement,
          status = CASE
            WHEN status = 'published' AND v_replacement IS NULL THEN 'archived'
            ELSE status
          END,
          archived_at = CASE
            WHEN status = 'published' AND v_replacement IS NULL
              THEN pg_catalog.now()
            ELSE archived_at
          END,
          version = version + 1,
          updated_at = pg_catalog.now()
      WHERE id = v_gallery.id;
    END IF;

    DELETE FROM public.tournament_media_gallery_items
    WHERE asset_id = p_asset_id;
    DELETE FROM public.tournament_media_consent_events
    WHERE asset_id = p_asset_id;
    DELETE FROM public.tournament_media_consents
    WHERE asset_id = p_asset_id;
    DELETE FROM public.tournament_media_reports
    WHERE asset_id = p_asset_id;
    DELETE FROM public.tournament_media_relations
    WHERE asset_id = p_asset_id;
    DELETE FROM public.tournament_media_moderation_actions
    WHERE asset_id = p_asset_id;
    DELETE FROM public.tournament_media_variants
    WHERE asset_id = p_asset_id;
    DELETE FROM public.tournament_media_processing_jobs
    WHERE asset_id = p_asset_id
       OR session_id IN (
         SELECT session.id
         FROM public.tournament_media_upload_sessions session
         WHERE session.asset_id = p_asset_id
       );
    DELETE FROM public.tournament_media_upload_sessions
    WHERE asset_id = p_asset_id;
    DELETE FROM public.tournament_media_assets
    WHERE id = p_asset_id;

    -- Domain rows are removed, while the general audit survives without a
    -- foreign key to the deleted asset.
    PERFORM public.append_tournament_audit(
      v_asset.organization_id,
      'media.asset.deleted',
      'media_asset',
      p_asset_id,
      NULL,
      v_asset.tournament_id,
      jsonb_build_object(
        'galleryId', v_asset.gallery_id,
        'storagePurged', true
      )
    );
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_catalog.set_config(
      'request.jwt.claim.sub', v_previous_claim, true
    );
    RAISE;
  END;
  PERFORM pg_catalog.set_config(
    'request.jwt.claim.sub', v_previous_claim, true
  );

  RETURN jsonb_build_object('assetId', p_asset_id, 'deleted', true);
END;
$$;


--
-- Name: FUNCTION complete_tournament_media_asset_delete(p_actor_user_id uuid, p_asset_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.complete_tournament_media_asset_delete(p_actor_user_id uuid, p_asset_id uuid) IS 'Service-only phase 2 after Storage removal: transactionally remove asset metadata and retain general audit.';


--
-- Name: complete_tournament_media_processing_job(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_tournament_media_processing_job(p_job_id uuid, p_lease_token text, p_asset_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_job public.tournament_media_processing_jobs%rowtype;
  v_ready integer;
begin
  -- A worker that lost its attestation between leasing and calling back may
  -- not publish anything.
  perform public.tournament_media_require_pipeline_ready();
  select * into v_job
  from public.tournament_media_processing_jobs
  where id = p_job_id for update;
  if v_job.id is null
    or v_job.status <> 'leased'
    or v_job.lease_expires_at <= now()
    or p_lease_token is null
    or v_job.lease_token is distinct from p_lease_token
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_JOB_LEASE_INVALID';
  end if;
  -- The job may only close over an asset that already has its four final,
  -- metadata-stripped variants. A partially ready asset can never be reported
  -- as a success.
  select count(*) into v_ready
  from public.tournament_media_variants variant
  where variant.asset_id = p_asset_id
    and variant.kind in ('thumbnail','grid','detail','original')
    and variant.status = 'ready'
    and variant.metadata_stripped;
  if v_ready <> 4 then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_PROCESSING_REQUIRED';
  end if;
  update public.tournament_media_processing_jobs
  set status = 'succeeded', asset_id = p_asset_id, lease_token = null,
      lease_expires_at = null, last_error = null, updated_at = now()
  where id = p_job_id;
  return jsonb_build_object('jobId',p_job_id,'status','succeeded','assetId',p_asset_id);
end;
$$;


--
-- Name: complete_tournament_media_simple_upload(uuid, uuid, text, text, bigint, integer, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_tournament_media_simple_upload(p_actor_user_id uuid, p_session_id uuid, p_token text, p_detected_mime text, p_byte_size bigint, p_width integer, p_height integer, p_checksum_sha256 text, p_metadata_stripped boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_session public.tournament_media_upload_sessions%rowtype;
  v_gallery public.tournament_media_galleries%rowtype;
  v_asset_id uuid;
  v_sort integer;
BEGIN
  SELECT * INTO v_session FROM public.tournament_media_upload_sessions
  WHERE id = p_session_id;
  IF v_session.id IS NULL OR v_session.processing_tier <> 'mvp_simple' THEN
    RAISE EXCEPTION USING errcode = '42501',
      message = 'TORNEOS_MEDIA_UPLOAD_SESSION_INVALID';
  END IF;
  PERFORM public.tournament_media_require_upload_tier('mvp_simple');
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_session.organization_id::text,0)
  );
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_session.gallery_id::text,1)
  );
  SELECT * INTO v_gallery FROM public.tournament_media_galleries
  WHERE id = v_session.gallery_id FOR SHARE;
  SELECT * INTO v_session FROM public.tournament_media_upload_sessions
  WHERE id = p_session_id FOR UPDATE;
  IF v_session.status <> 'issued' OR v_session.expires_at <= now()
    OR p_actor_user_id IS NULL OR p_actor_user_id <> v_session.requested_by
    OR encode(public.digest(coalesce(p_token,''),'sha256'),'hex') <> v_session.token_hash
    OR v_gallery.status NOT IN ('draft','under_review')
    OR NOT public.tournament_media_mvp_user_can_upload(
      v_session.requested_by,v_session.gallery_id
    )
  THEN
    RAISE EXCEPTION USING errcode = '42501',
      message = 'TORNEOS_MEDIA_UPLOAD_SESSION_INVALID';
  END IF;
  -- Sin veredicto afirmativo no hay asset. Fail-closed ante NULL o false.
  IF p_metadata_stripped IS NOT TRUE THEN
    UPDATE public.tournament_media_upload_sessions SET status = 'failed'
    WHERE id = p_session_id;
    RAISE EXCEPTION USING errcode = '22023',
      message = 'TORNEOS_MEDIA_METADATA_NOT_STRIPPED';
  END IF;
  IF p_detected_mime <> v_session.requested_mime
    OR p_detected_mime NOT IN ('image/jpeg','image/png','image/webp')
    OR p_byte_size <> v_session.requested_size OR p_byte_size > 4194304
    OR p_width NOT BETWEEN 1 AND 1600 OR p_height NOT BETWEEN 1 AND 1600
    OR p_width::bigint * p_height::bigint > 2560000
    OR p_checksum_sha256 !~ '^[0-9a-f]{64}$'
  THEN
    UPDATE public.tournament_media_upload_sessions SET status = 'failed'
    WHERE id = p_session_id;
    RAISE EXCEPTION USING errcode = '22023', message = 'TORNEOS_MEDIA_FILE_INVALID';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.tournament_media_assets asset
    WHERE asset.organization_id = v_session.organization_id
      AND asset.checksum_sha256 = p_checksum_sha256 AND asset.status <> 'revoked'
  ) THEN
    RAISE EXCEPTION USING errcode = '23505', message = 'TORNEOS_MEDIA_DUPLICATE';
  END IF;

  INSERT INTO public.tournament_media_assets (
    organization_id,tournament_id,gallery_id,internal_path,safe_name,
    detected_mime,byte_size,width,height,checksum_sha256,status,uploaded_by,
    processing_tier,metadata_stripped,normalization_verified_at
  ) VALUES (
    v_session.organization_id,v_session.tournament_id,v_session.gallery_id,
    v_session.internal_path,v_session.safe_name,p_detected_mime,p_byte_size,
    p_width,p_height,p_checksum_sha256,'pending_review',v_session.requested_by,
    'mvp_simple',true,now()
  ) RETURNING id INTO v_asset_id;
  SELECT coalesce(max(sort_order),-1) + 1 INTO v_sort
  FROM public.tournament_media_gallery_items WHERE gallery_id = v_session.gallery_id;
  INSERT INTO public.tournament_media_gallery_items (
    organization_id,tournament_id,gallery_id,asset_id,sort_order,added_by
  ) VALUES (
    v_session.organization_id,v_session.tournament_id,v_session.gallery_id,
    v_asset_id,v_sort,v_session.requested_by
  );
  UPDATE public.tournament_media_upload_sessions
  SET status = 'consumed',consumed_at = now(),asset_id = v_asset_id
  WHERE id = p_session_id;
  INSERT INTO public.tournament_audit_log (
    organization_id,actor_user_id,actor_type,action,resource_type,
    resource_id,tournament_id,metadata
  ) VALUES (
    v_session.organization_id,v_session.requested_by,'system',
    'media.upload.simple_verified','media_asset',v_asset_id,v_session.tournament_id,
    jsonb_build_object(
      'galleryId',v_session.gallery_id,'byteSize',p_byte_size,
      'processingTier','mvp_simple','structuralValidation',true,
      'metadataStripped',true,
      'checksumSha256',p_checksum_sha256
    )
  );
  RETURN jsonb_build_object(
    'assetId',v_asset_id,'galleryId',v_session.gallery_id,
    'safeName',v_session.safe_name,'status','pending_review',
    'processingTier','mvp_simple','metadataStripped',true
  );
END;
$_$;


--
-- Name: complete_tournament_media_upload(uuid, text, text, bigint, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_tournament_media_upload(p_session_id uuid, p_token text, p_detected_mime text, p_byte_size bigint, p_width integer, p_height integer, p_checksum_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_session public.tournament_media_upload_sessions%rowtype;
  v_gallery public.tournament_media_galleries%rowtype;
  v_asset_id uuid;
  v_sort integer;
  v_extension text;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_session
  from public.tournament_media_upload_sessions
  where id = p_session_id;
  if v_session.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_UPLOAD_SESSION_INVALID';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_session.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_session.gallery_id::text,1)
  );
  select * into v_gallery
  from public.tournament_media_galleries
  where id = v_session.gallery_id
  for share;
  select * into v_session
  from public.tournament_media_upload_sessions
  where id = p_session_id
  for update;
  if v_session.id is null
    or v_session.status <> 'issued'
    or v_session.expires_at <= now()
    or encode(public.digest(coalesce(p_token,''),'sha256'),'hex') <> v_session.token_hash
    or private.current_identity_id() <> v_session.requested_by
    or v_gallery.status not in ('draft','under_review')
    or not public.tournament_media_user_can_upload(
      v_session.requested_by,v_session.gallery_id
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_UPLOAD_SESSION_INVALID';
  end if;
  if p_detected_mime <> v_session.requested_mime
    or p_byte_size <> v_session.requested_size
    or p_detected_mime not in ('image/jpeg','image/png','image/webp')
    or p_width < 1 or p_height < 1
    or p_width > 12000 or p_height > 12000
    or p_width::bigint * p_height::bigint > 36000000
    or p_checksum_sha256 !~ '^[0-9a-f]{64}$'
  then
    update public.tournament_media_upload_sessions set status = 'failed'
    where id = p_session_id;
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_FILE_INVALID';
  end if;
  v_extension := case p_detected_mime
    when 'image/jpeg' then 'jpg' when 'image/png' then 'png' else 'webp' end;
  if right(v_session.internal_path,char_length(v_extension) + 1) <> '.' || v_extension then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_FILE_INVALID';
  end if;
  if exists (
    select 1 from public.tournament_media_assets asset
    where asset.organization_id = v_session.organization_id
      and asset.checksum_sha256 = p_checksum_sha256
      and asset.status <> 'revoked'
  ) then
    raise exception using errcode = '23505', message = 'TORNEOS_MEDIA_DUPLICATE';
  end if;

  insert into public.tournament_media_assets (
    organization_id,tournament_id,gallery_id,internal_path,safe_name,
    detected_mime,byte_size,width,height,checksum_sha256,status,uploaded_by
  ) values (
    v_session.organization_id,v_session.tournament_id,v_session.gallery_id,
    v_session.internal_path,v_session.safe_name,p_detected_mime,p_byte_size,
    p_width,p_height,p_checksum_sha256,'pending_review',v_session.requested_by
  ) returning id into v_asset_id;
  select coalesce(max(sort_order),-1) + 1 into v_sort
  from public.tournament_media_gallery_items
  where gallery_id = v_session.gallery_id;
  insert into public.tournament_media_gallery_items (
    organization_id,tournament_id,gallery_id,asset_id,sort_order,added_by
  ) values (
    v_session.organization_id,v_session.tournament_id,v_session.gallery_id,
    v_asset_id,v_sort,v_session.requested_by
  );
  insert into public.tournament_media_variants (
    organization_id,tournament_id,asset_id,kind,internal_path,
    detected_mime,byte_size,width,height,checksum_sha256,status
  ) values (
    v_session.organization_id,v_session.tournament_id,v_asset_id,'original',
    regexp_replace(v_session.internal_path,'\.(jpg|png|webp)$','-original.' || v_extension),
    p_detected_mime,p_byte_size,p_width,p_height,p_checksum_sha256,'ready'
  );
  insert into public.tournament_media_variants (
    organization_id,tournament_id,asset_id,kind,internal_path,
    detected_mime,byte_size,width,height,checksum_sha256,status
  )
  select
    v_session.organization_id,v_session.tournament_id,v_asset_id,variant.kind,
    regexp_replace(
      v_session.internal_path,
      '\.(jpg|png|webp)$',
      '-' || variant.kind || '.' || v_extension
    ),
    p_detected_mime,null,null,null,null,'processing'
  from unnest(array['thumbnail','grid','detail']::text[]) variant(kind);
  update public.tournament_media_upload_sessions
  set status = 'consumed',consumed_at = now(),asset_id = v_asset_id
  where id = p_session_id;
  insert into public.tournament_audit_log (
    organization_id,actor_user_id,actor_type,action,resource_type,
    resource_id,tournament_id,metadata
  ) values (
    v_session.organization_id,v_session.requested_by,'system',
    'media.upload.verified','media_asset',v_asset_id,v_session.tournament_id,
    jsonb_build_object('galleryId',v_session.gallery_id,'byteSize',p_byte_size)
  );
  return jsonb_build_object(
    'assetId',v_asset_id,'galleryId',v_session.gallery_id,
    'safeName',v_session.safe_name,'status','pending_review'
  );
end;
$_$;


--
-- Name: complete_tournament_media_upload_for_actor(uuid, uuid, text, text, bigint, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_tournament_media_upload_for_actor(p_actor_user_id uuid, p_session_id uuid, p_token text, p_detected_mime text, p_byte_size bigint, p_width integer, p_height integer, p_checksum_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_previous_claim text := coalesce(
    pg_catalog.current_setting('request.jwt.claim.sub', true), ''
  );
  v_result jsonb;
begin
  if p_actor_user_id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  perform public.tournament_media_require_pipeline_ready();
  perform pg_catalog.set_config(
    'request.jwt.claim.sub', p_actor_user_id::text, true
  );
  begin
    v_result := public.complete_tournament_media_upload(
      p_session_id, p_token, p_detected_mime, p_byte_size,
      p_width, p_height, p_checksum_sha256
    );
  exception when others then
    perform pg_catalog.set_config('request.jwt.claim.sub', v_previous_claim, true);
    raise;
  end;
  perform pg_catalog.set_config('request.jwt.claim.sub', v_previous_claim, true);
  return v_result;
end;
$$;


--
-- Name: complete_tournament_media_upload_for_job(uuid, text, text, bigint, integer, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_tournament_media_upload_for_job(p_job_id uuid, p_lease_token text, p_detected_mime text, p_byte_size bigint, p_width integer, p_height integer, p_checksum_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_job public.tournament_media_processing_jobs%rowtype;
  v_session public.tournament_media_upload_sessions%rowtype;
  v_token text := encode(public.gen_random_bytes(32),'hex');
begin
  perform public.tournament_media_require_pipeline_ready();
  select * into v_job
  from public.tournament_media_processing_jobs
  where id = p_job_id for update;
  if v_job.id is null
    or v_job.status <> 'leased'
    or v_job.lease_expires_at <= now()
    or p_lease_token is null
    or v_job.lease_token is distinct from p_lease_token
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_JOB_LEASE_INVALID';
  end if;
  select * into v_session
  from public.tournament_media_upload_sessions
  where id = v_job.session_id for update;
  if v_session.id is null
    or v_session.status <> 'issued'
    or v_session.expires_at <= now()
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_UPLOAD_SESSION_INVALID';
  end if;
  if p_byte_size is null
    or p_byte_size < 1
    or p_byte_size > v_session.max_size
  then
    update public.tournament_media_upload_sessions set status = 'failed'
    where id = v_session.id;
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_FILE_INVALID';
  end if;
  update public.tournament_media_upload_sessions
  set token_hash = encode(public.digest(v_token,'sha256'),'hex'),
      requested_size = p_byte_size
  where id = v_session.id;
  return public.complete_tournament_media_upload_for_actor(
    v_session.requested_by, v_session.id, v_token, p_detected_mime,
    p_byte_size, p_width, p_height, p_checksum_sha256
  );
end;
$$;


--
-- Name: complete_tournament_player_portrait_delete(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_tournament_player_portrait_delete(p_actor_user_id uuid, p_portrait_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_portrait public.tournament_player_portraits%ROWTYPE;
BEGIN
  SELECT * INTO v_portrait FROM public.tournament_player_portraits portrait
  WHERE portrait.id = p_portrait_id AND portrait.lifecycle_status = 'delete_pending'
  FOR UPDATE;
  IF v_portrait.id IS NULL OR NOT public.can_manage_tournament_player_portrait_as(
    v_portrait.organization_id, v_portrait.roster_player_id, p_actor_user_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_PORTRAIT_FORBIDDEN';
  END IF;
  UPDATE public.tournament_player_portraits
  SET lifecycle_status = 'removed', removed_at = now(),
      storage_purged_at = now(), updated_at = now()
  WHERE id = p_portrait_id;
  INSERT INTO public.tournament_audit_log (
    organization_id, actor_user_id, actor_type, action, resource_type,
    resource_id, team_entry_id, tournament_id, metadata
  ) VALUES (
    v_portrait.organization_id, p_actor_user_id, 'user', 'portrait.removed',
    'player_portrait', v_portrait.id, v_portrait.team_entry_id,
    v_portrait.tournament_id,
    jsonb_build_object('rosterPlayerId', v_portrait.roster_player_id)
  );
  RETURN jsonb_build_object('portraitId', p_portrait_id, 'deleted', true);
END;
$$;


--
-- Name: complete_tournament_team_photo_delete(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_tournament_team_photo_delete(p_actor_user_id uuid, p_team_photo_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_photo public.tournament_team_photos%ROWTYPE;
BEGIN
  SELECT * INTO v_photo
  FROM public.tournament_team_photos photo
  WHERE photo.id = p_team_photo_id
    AND photo.lifecycle_status = 'delete_pending'
  FOR UPDATE;
  IF v_photo.id IS NULL OR NOT (
    public.can_manage_tournament_team_visual_assets_as(
      v_photo.organization_id, v_photo.team_entry_id, p_actor_user_id,
      'team_entries.update')
    OR public.can_moderate_tournament_team_visual_assets_as(
      v_photo.organization_id, v_photo.team_entry_id, p_actor_user_id,
      'team_entries.update')
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_TEAM_PHOTO_FORBIDDEN';
  END IF;
  UPDATE public.tournament_team_photos
  SET lifecycle_status = 'removed', removed_at = now(),
      storage_purged_at = now(), updated_at = now()
  WHERE id = p_team_photo_id;
  INSERT INTO public.tournament_audit_log (
    organization_id, actor_user_id, actor_type, action, resource_type,
    resource_id, team_entry_id, tournament_id, metadata
  ) VALUES (
    v_photo.organization_id, p_actor_user_id, 'user', 'team_photo.removed',
    'team_photo', v_photo.id, v_photo.team_entry_id, v_photo.tournament_id,
    jsonb_build_object('editorialStatus', v_photo.editorial_status)
  );
  RETURN jsonb_build_object('teamPhotoId', p_team_photo_id, 'deleted', true);
END;
$$;


--
-- Name: create_fake_tournament_purchase(uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_fake_tournament_purchase(p_organization_id uuid, p_tournament_id uuid, p_product_code text, p_idempotency_key uuid, p_provider_environment text DEFAULT 'local'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_offer public.tournament_commercial_offers%rowtype;
  v_purchase public.tournament_purchases%rowtype;
  v_product public.tournament_commercial_products%rowtype;
  v_id uuid := gen_random_uuid();
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(p_organization_id,'billing.manage') then
    raise exception using errcode = '42501', message = 'TORNEOS_BILLING_FORBIDDEN';
  end if;
  if p_idempotency_key is null or p_provider_environment not in ('local','qa') then
    raise exception using errcode = '22023', message = 'TORNEOS_PURCHASE_INVALID';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    p_organization_id::text || ':' || p_tournament_id::text || ':' || p_product_code,79
  ));

  if not exists (
    select 1 from public.tournaments tournament
    where tournament.organization_id = p_organization_id and tournament.id = p_tournament_id
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_PURCHASE_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournament_plan_grants grant_row
    where grant_row.organization_id = p_organization_id
      and grant_row.tournament_id = p_tournament_id
      and grant_row.plan_code = 'PREMIUM'
      and public.is_tournament_plan_grant_effective(grant_row.id)
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_ALREADY_PREMIUM';
  end if;

  select * into v_purchase from public.tournament_purchases
  where buyer_user_id = private.current_identity_id() and idempotency_key = p_idempotency_key;
  if v_purchase.id is not null then
    return public.tournament_purchase_projection(v_purchase)
      || jsonb_build_object('idempotentReplay',true,'existingOpenPurchase',false);
  end if;

  select * into v_purchase from public.tournament_purchases
  where organization_id = p_organization_id and tournament_id = p_tournament_id
    and product_code = p_product_code
    and status in ('created','preference_created','pending')
  order by created_at limit 1 for update;
  if v_purchase.id is not null then
    return public.tournament_purchase_projection(v_purchase)
      || jsonb_build_object('idempotentReplay',false,'existingOpenPurchase',true);
  end if;

  select * into v_product from public.tournament_commercial_products
  where product_code = p_product_code and status = 'active';
  if v_product.product_code is null or v_product.plan_code <> 'PREMIUM'
    or v_product.scope <> 'tournament' or v_product.billing_model <> 'one_time' then
    raise exception using errcode = '22023', message = 'TORNEOS_PRODUCT_UNAVAILABLE';
  end if;
  select * into v_offer from public.tournament_commercial_offers offer
  where offer.product_code = p_product_code
    and offer.availability = 'available'
    and offer.valid_from <= statement_timestamp()
    and (offer.valid_until is null or offer.valid_until > statement_timestamp())
  order by offer.valid_from desc,offer.offer_version desc limit 1;
  if v_offer.product_code is null then
    raise exception using errcode = '22023', message = 'TORNEOS_OFFER_UNAVAILABLE';
  end if;

  insert into public.tournament_purchases (
    id,organization_id,tournament_id,buyer_user_id,product_code,offer_code,offer_version,
    list_amount_snapshot,amount_snapshot,currency,provider,provider_environment,
    provider_preference_id,external_reference,idempotency_key,status,provider_status,
    preference_expires_at
  ) values (
    v_id,p_organization_id,p_tournament_id,private.current_identity_id(),p_product_code,
    v_offer.offer_code,v_offer.offer_version,v_offer.list_amount,v_offer.amount,
    v_offer.currency,'FAKE',p_provider_environment,null,
    'arma2:tournament:purchase:' || v_id::text,p_idempotency_key,
    'created',null,now() + interval '30 minutes'
  ) returning * into v_purchase;

  insert into public.tournament_purchase_events (
    purchase_id,organization_id,event_type,from_status,to_status,provider_status,
    actor_type,actor_user_id
  ) values
    (v_purchase.id,p_organization_id,'purchase.created',null,'created',null,'user',private.current_identity_id());

  update public.tournament_purchases set
    status = 'preference_created',provider_status = 'created',
    provider_preference_id = 'fake_pref_' || v_id::text
  where id = v_id returning * into v_purchase;
  insert into public.tournament_purchase_events (
    purchase_id,organization_id,event_type,from_status,to_status,provider_status,
    actor_type,actor_user_id
  ) values (
    v_purchase.id,p_organization_id,'preference.created','created','preference_created',
    'created','service',private.current_identity_id()
  );

  return public.tournament_purchase_projection(v_purchase)
    || jsonb_build_object('idempotentReplay',false,'existingOpenPurchase',false);
end;
$$;


--
-- Name: create_fake_tournament_season_purchase(uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_fake_tournament_season_purchase(p_organization_id uuid, p_season_id uuid, p_product_code text, p_idempotency_key uuid, p_provider_environment text DEFAULT 'local'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_purchase jsonb;
begin
  v_purchase := public.create_tournament_season_purchase(
    p_organization_id,p_season_id,p_product_code,p_idempotency_key,
    'FAKE',p_provider_environment
  );
  if v_purchase->>'status' = 'created' then
    v_purchase := public.record_tournament_purchase_preference(
      (v_purchase->>'id')::uuid,'FAKE',p_provider_environment,
      'fake_pref_' || (v_purchase->>'id'),
      (v_purchase->>'preferenceExpiresAt')::timestamptz
    ) || jsonb_build_object(
      'existingOpenPurchase',coalesce((v_purchase->>'existingOpenPurchase')::boolean,false),
      'idempotentReplay',coalesce((v_purchase->>'idempotentReplay')::boolean,false)
    );
  end if;
  return v_purchase;
end;
$$;


--
-- Name: create_manual_fixture_version(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_manual_fixture_version(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_source_fixture_version_id uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_set public.tournament_participant_sets%rowtype;
  v_source public.tournament_fixture_versions%rowtype;
  v_version public.tournament_fixture_versions%rowtype;
  v_number integer;
  v_phase record;
  v_group record;
  v_round record;
  v_match record;
  v_source_row record;
  v_new_id uuid;
  v_phase_map jsonb := '{}'::jsonb;
  v_group_map jsonb := '{}'::jsonb;
  v_round_map jsonb := '{}'::jsonb;
  v_match_map jsonb := '{}'::jsonb;
begin
  perform public.assert_tournament_fixture_scope(
    p_organization_id, p_tournament_id, p_category_id,
    'fixture.create_manual', array['registration', 'scheduled']::text[]
  );
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:fixture:' || p_tournament_id::text || ':' || p_category_id::text, 0
  ));
  select version.* into v_version
  from public.tournament_fixture_versions version
  where version.organization_id = p_organization_id
    and version.created_by = private.current_identity_id()
    and version.idempotency_key = p_idempotency_key;
  if v_version.id is not null then
    return jsonb_build_object(
      'fixtureVersionId', v_version.id,
      'versionNumber', v_version.version_number,
      'status', v_version.status
    );
  end if;
  select participant_set.* into v_set
  from public.tournament_participant_sets participant_set
  where participant_set.organization_id = p_organization_id
    and participant_set.tournament_id = p_tournament_id
    and participant_set.category_id = p_category_id
    and participant_set.status = 'frozen'
  for update;
  if v_set.id is null then
    raise exception using errcode = '23514', message = 'TORNEOS_PARTICIPANTS_NOT_FROZEN';
  end if;
  if p_source_fixture_version_id is not null then
    select source.* into v_source
    from public.tournament_fixture_versions source
    where source.id = p_source_fixture_version_id
      and source.organization_id = p_organization_id
      and source.tournament_id = p_tournament_id
      and source.category_id = p_category_id
      and source.participant_set_id = v_set.id
      and source.status in ('published', 'superseded')
    for share;
    if v_source.id is null then
      raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
    end if;
  end if;
  select coalesce(max(version.version_number), 0) + 1 into v_number
  from public.tournament_fixture_versions version
  where version.tournament_id = p_tournament_id and version.category_id = p_category_id;
  insert into public.tournament_fixture_versions (
    organization_id, season_id, tournament_id, category_id, participant_set_id,
    version_number, status, generation_method, seed, participant_fingerprint,
    configuration_snapshot, created_by, idempotency_key
  ) values (
    p_organization_id, v_set.season_id, p_tournament_id, p_category_id, v_set.id,
    v_number, 'draft', 'manual', v_source.seed, v_set.participant_fingerprint,
    coalesce(v_source.configuration_snapshot, '{}'::jsonb)
      || jsonb_build_object('copiedFromVersionId', v_source.id),
    private.current_identity_id(), p_idempotency_key
  ) returning * into v_version;
  if v_source.id is not null then
    for v_phase in
      select * from public.tournament_phases
      where fixture_version_id = v_source.id order by sequence_number
    loop
      insert into public.tournament_phases (
        organization_id, tournament_id, category_id, fixture_version_id,
        name, phase_type, sequence_number, status, configuration
      ) values (
        v_phase.organization_id, v_phase.tournament_id, v_phase.category_id,
        v_version.id, v_phase.name, v_phase.phase_type, v_phase.sequence_number,
        'generated', v_phase.configuration
      ) returning id into v_new_id;
      v_phase_map := v_phase_map || jsonb_build_object(v_phase.id::text, v_new_id);
    end loop;
    for v_group in
      select * from public.tournament_groups
      where fixture_version_id = v_source.id order by sort_order, code
    loop
      insert into public.tournament_groups (
        organization_id, tournament_id, category_id, participant_set_id,
        fixture_version_id, phase_id, name, code, sort_order, status, draw_seed
      ) values (
        v_group.organization_id, v_group.tournament_id, v_group.category_id,
        v_group.participant_set_id, v_version.id,
        (v_phase_map->>v_group.phase_id::text)::uuid,
        v_group.name, v_group.code, v_group.sort_order, 'published', v_group.draw_seed
      ) returning id into v_new_id;
      v_group_map := v_group_map || jsonb_build_object(v_group.id::text, v_new_id);
      insert into public.tournament_group_members (group_id, participant_id, position_seed)
      select v_new_id, member.participant_id, member.position_seed
      from public.tournament_group_members member where member.group_id = v_group.id;
    end loop;
    for v_round in
      select * from public.tournament_rounds
      where fixture_version_id = v_source.id order by sort_order, round_number
    loop
      insert into public.tournament_rounds (
        organization_id, tournament_id, category_id, fixture_version_id,
        phase_id, group_id, round_number, name, status, starts_at, ends_at, sort_order
      ) values (
        v_round.organization_id, v_round.tournament_id, v_round.category_id,
        v_version.id, (v_phase_map->>v_round.phase_id::text)::uuid,
        case when v_round.group_id is null then null
          else (v_group_map->>v_round.group_id::text)::uuid end,
        v_round.round_number, v_round.name,
        case when v_round.status = 'locked' then 'scheduled' else v_round.status end,
        v_round.starts_at, v_round.ends_at, v_round.sort_order
      ) returning id into v_new_id;
      v_round_map := v_round_map || jsonb_build_object(v_round.id::text, v_new_id);
    end loop;
    for v_match in
      select * from public.tournament_matches
      where fixture_version_id = v_source.id order by match_number
    loop
      insert into public.tournament_matches (
        organization_id, season_id, tournament_id, category_id,
        participant_set_id, fixture_version_id, phase_id, group_id, round_id,
        match_number, leg_number, tie_key, home_participant_id, away_participant_id,
        status, scheduled_at, venue_id, court_id, duration_minutes, created_by,
        postponed_at, cancelled_at
      ) values (
        v_match.organization_id, v_match.season_id, v_match.tournament_id,
        v_match.category_id, v_match.participant_set_id, v_version.id,
        (v_phase_map->>v_match.phase_id::text)::uuid,
        case when v_match.group_id is null then null
          else (v_group_map->>v_match.group_id::text)::uuid end,
        (v_round_map->>v_match.round_id::text)::uuid,
        v_match.match_number, v_match.leg_number,
        case when v_match.tie_key is null then null
          else replace(v_match.tie_key, v_source.id::text, v_version.id::text) end,
        v_match.home_participant_id, v_match.away_participant_id,
        case when v_match.status in ('ready', 'in_progress', 'completed', 'awarded', 'suspended')
          then 'scheduled' else v_match.status end,
        v_match.scheduled_at, v_match.venue_id, v_match.court_id,
        v_match.duration_minutes, private.current_identity_id(),
        case when v_match.status = 'postponed' then v_match.postponed_at else null end,
        case when v_match.status = 'cancelled' then v_match.cancelled_at else null end
      ) returning id into v_new_id;
      v_match_map := v_match_map || jsonb_build_object(v_match.id::text, v_new_id);
    end loop;
    for v_source_row in
      select * from public.tournament_match_sources
      where fixture_version_id = v_source.id order by created_at, id
    loop
      insert into public.tournament_match_sources (
        organization_id, tournament_id, category_id, fixture_version_id,
        match_id, side, source_type, participant_id, source_match_id,
        group_id, source_phase_id, source_tie_key,
        position_number, seed_number, rank_number
      ) values (
        v_source_row.organization_id, v_source_row.tournament_id,
        v_source_row.category_id, v_version.id,
        (v_match_map->>v_source_row.match_id::text)::uuid,
        v_source_row.side, v_source_row.source_type, v_source_row.participant_id,
        case when v_source_row.source_match_id is null then null
          else (v_match_map->>v_source_row.source_match_id::text)::uuid end,
        case when v_source_row.group_id is null then null
          else (v_group_map->>v_source_row.group_id::text)::uuid end,
        case when v_source_row.source_phase_id is null then null
          else (v_phase_map->>v_source_row.source_phase_id::text)::uuid end,
        case when v_source_row.source_tie_key is null then null
          else replace(
            v_source_row.source_tie_key,
            v_source.id::text,
            v_version.id::text
          ) end,
        v_source_row.position_number, v_source_row.seed_number, v_source_row.rank_number
      );
    end loop;
  end if;
  perform public.append_tournament_audit(
    p_organization_id, 'fixture.manual_created', 'fixture_version', v_version.id,
    null, p_tournament_id,
    jsonb_build_object(
      'categoryId', p_category_id,
      'versionNumber', v_number,
      'sourceFixtureVersionId', v_source.id
    )
  );
  return jsonb_build_object(
    'fixtureVersionId', v_version.id,
    'versionNumber', v_number,
    'status', 'draft',
    'sourceFixtureVersionId', v_source.id
  );
end;
$$;


--
-- Name: create_tournament_announcement_draft(uuid, uuid, uuid, text, text, text, text, text, text, timestamp with time zone, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_tournament_announcement_draft(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_announcement_type text, p_title text, p_summary text, p_body text, p_priority text, p_acknowledgement_mode text, p_scheduled_for timestamp with time zone, p_supersedes_id uuid, p_correction_reason text, p_idempotency_key uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tournament public.tournaments%rowtype;
  v_existing public.tournament_announcements%rowtype;
  v_id uuid;
  v_version integer := 1;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;
  if not public.has_tournament_communications_capability(
    p_organization_id,'announcements.create'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  select * into v_tournament
  from public.tournaments tournament
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
    and tournament.status <> 'archived';
  if v_tournament.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  if p_category_id is not null and not exists (
    select 1 from public.tournament_categories category
    where category.id = p_category_id
      and category.organization_id = p_organization_id
      and category.tournament_id = p_tournament_id
      and category.status = 'active'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  if p_scheduled_for is not null
    and not public.has_tournament_communications_capability(
      p_organization_id,'announcements.schedule'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  if (select count(*) from public.tournament_announcements announcement
      where announcement.organization_id = p_organization_id
        and announcement.author_user_id = private.current_identity_id()
        and announcement.status in ('draft','scheduled')) >= 100
  then
    raise exception using errcode = '54000', message = 'TORNEOS_DRAFT_LIMIT_REACHED';
  end if;

  select * into v_existing
  from public.tournament_announcements announcement
  where announcement.organization_id = p_organization_id
    and announcement.author_user_id = private.current_identity_id()
    and announcement.idempotency_key = p_idempotency_key;
  if v_existing.id is not null then
    if v_existing.tournament_id <> p_tournament_id
      or v_existing.category_id is distinct from p_category_id
      or v_existing.announcement_type <> p_announcement_type
      or v_existing.title <> btrim(p_title)
      or v_existing.summary <> btrim(p_summary)
      or v_existing.body <> btrim(p_body)
      or v_existing.priority <> coalesce(p_priority,'normal')
      or v_existing.acknowledgement_mode <> coalesce(p_acknowledgement_mode,'none')
      or v_existing.scheduled_for is distinct from p_scheduled_for
      or v_existing.supersedes_id is distinct from p_supersedes_id
      or v_existing.correction_reason is distinct from
        nullif(btrim(coalesce(p_correction_reason,'')),'')
    then
      raise exception using errcode = '23514', message = 'TORNEOS_IDEMPOTENCY_CONFLICT';
    end if;
    return v_existing.id;
  end if;

  if p_supersedes_id is not null then
    select coalesce(max(announcement.version),0) + 1 into v_version
    from public.tournament_announcements announcement
    where announcement.id = p_supersedes_id
      and announcement.organization_id = p_organization_id
      and announcement.tournament_id = p_tournament_id
      and announcement.status = 'published';
    if v_version = 1
      or p_correction_reason is null
      or char_length(btrim(p_correction_reason)) < 4
    then
      raise exception using errcode = '22023', message = 'TORNEOS_INVALID_CORRECTION';
    end if;
  end if;

  insert into public.tournament_announcements (
    organization_id,season_id,tournament_id,category_id,author_user_id,status,
    announcement_type,title,summary,body,priority,acknowledgement_mode,
    scheduled_for,version,supersedes_id,correction_reason,idempotency_key
  ) values (
    p_organization_id,v_tournament.season_id,p_tournament_id,p_category_id,
    private.current_identity_id(),case when p_scheduled_for is null then 'draft' else 'scheduled' end,
    p_announcement_type,btrim(p_title),btrim(p_summary),btrim(p_body),
    coalesce(p_priority,'normal'),coalesce(p_acknowledgement_mode,'none'),
    p_scheduled_for,v_version,p_supersedes_id,
    nullif(btrim(coalesce(p_correction_reason,'')),''),p_idempotency_key
  ) returning id into v_id;

  perform public.append_tournament_audit(
    p_organization_id,'communications.announcement_create','announcement',
    v_id,null,p_tournament_id,
    jsonb_build_object(
      'type',p_announcement_type,'scheduled',p_scheduled_for is not null,
      'supersedesId',p_supersedes_id
    )
  );
  return v_id;
end;
$$;


--
-- Name: create_tournament_court(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_tournament_court(p_organization_id uuid, p_venue_id uuid, p_name text, p_sport_modality text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_court public.tournament_courts%rowtype;
begin
  if private.current_identity_id() is null
    or not public.has_tournament_organization_capability(p_organization_id, 'courts.create')
    or not exists (
      select 1 from public.tournament_venues venue
      where venue.id = p_venue_id and venue.organization_id = p_organization_id
        and venue.status = 'active'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  insert into public.tournament_courts (
    organization_id, venue_id, name, sport_modality, notes
  ) values (
    p_organization_id, p_venue_id, btrim(p_name), p_sport_modality,
    nullif(btrim(coalesce(p_notes, '')), '')
  ) returning * into v_court;
  perform public.append_tournament_audit(
    p_organization_id, 'court.created', 'court', v_court.id,
    null, null, jsonb_build_object('venueId', p_venue_id, 'name', v_court.name)
  );
  return jsonb_build_object(
    'id', v_court.id, 'venueId', v_court.venue_id,
    'name', v_court.name, 'status', v_court.status
  );
end;
$$;


--
-- Name: create_tournament_disciplinary_override(uuid, text, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_tournament_disciplinary_override(p_suspension_id uuid, p_action text, p_matches integer, p_reason text, p_idempotency_key uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_suspension public.tournament_player_suspensions%rowtype;
  v_override public.tournament_disciplinary_overrides%rowtype;
  v_previous jsonb;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_suspension from public.tournament_player_suspensions
  where id = p_suspension_id;
  if v_suspension.id is null or not public.has_tournament_organization_capability(
    v_suspension.organization_id, 'discipline.override'
  ) or not exists (
    select 1
    from public.tournament_standings_revisions revision
    where revision.id = v_suspension.revision_id
      and revision.status = 'published'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_DISCIPLINE_FORBIDDEN';
  end if;
  if p_action not in ('reduce', 'revoke', 'add_match')
    or char_length(btrim(coalesce(p_reason, ''))) < 3
    or p_idempotency_key is null
  then
    raise exception using errcode = '22023', message = 'TORNEOS_DISCIPLINE_OVERRIDE_INVALID';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    v_suspension.organization_id::text || ':' || v_suspension.tournament_id::text || ':'
    || v_suspension.category_id::text || ':' || v_suspension.phase_id::text || ':'
    || coalesce(v_suspension.group_id::text, 'all'),
    0
  ));
  select * into strict v_suspension from public.tournament_player_suspensions
  where id = p_suspension_id for update;
  if not exists (
    select 1
    from public.tournament_standings_revisions revision
    where revision.id = v_suspension.revision_id
      and revision.status = 'published'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_DISCIPLINE_FORBIDDEN';
  end if;
  select * into v_override from public.tournament_disciplinary_overrides
  where organization_id = v_suspension.organization_id
    and actor_user_id = private.current_identity_id()
    and idempotency_key = p_idempotency_key;
  if v_override.id is not null then
    if v_override.suspension_id <> p_suspension_id
      or v_override.action <> p_action
      or v_override.reason <> btrim(p_reason)
      or (
        p_action = 'reduce'
        and (v_override.new_state->>'totalMatches')::integer <> p_matches
      )
      or (
        p_action = 'add_match'
        and (
          (v_override.new_state->>'totalMatches')::integer
          - (v_override.previous_state->>'totalMatches')::integer
        ) <> p_matches
      )
    then
      raise exception using errcode = '23514', message = 'TORNEOS_IDEMPOTENCY_CONFLICT';
    end if;
    return v_override.id;
  end if;
  v_previous := jsonb_build_object(
    'status', v_suspension.status, 'totalMatches', v_suspension.total_matches,
    'servedMatches', v_suspension.served_matches
  );

  if p_action = 'revoke' then
    update public.tournament_player_suspensions
    set status = 'revoked', updated_at = now()
    where id = v_suspension.id;
  elsif p_action = 'reduce' then
    if p_matches is null or p_matches < v_suspension.served_matches
      or p_matches >= v_suspension.total_matches
    then
      raise exception using errcode = '22023', message = 'TORNEOS_DISCIPLINE_OVERRIDE_INVALID';
    end if;
    update public.tournament_player_suspensions
    set total_matches = p_matches,
      status = case when served_matches >= p_matches then 'served' else 'reduced' end,
      updated_at = now()
    where id = v_suspension.id;
  else
    if p_matches is null or p_matches < 1
      or v_suspension.total_matches + p_matches > 24
    then
      raise exception using errcode = '22023', message = 'TORNEOS_DISCIPLINE_OVERRIDE_INVALID';
    end if;
    update public.tournament_player_suspensions
    set total_matches = total_matches + p_matches, status = 'active', updated_at = now()
    where id = v_suspension.id;
  end if;

  select * into v_suspension from public.tournament_player_suspensions
  where id = p_suspension_id;
  insert into public.tournament_disciplinary_overrides (
    organization_id, tournament_id, suspension_id, action, previous_state,
    new_state, reason, actor_user_id, idempotency_key
  ) values (
    v_suspension.organization_id, v_suspension.tournament_id, v_suspension.id,
    p_action, v_previous,
    jsonb_build_object(
      'status', v_suspension.status, 'totalMatches', v_suspension.total_matches,
      'servedMatches', v_suspension.served_matches
    ),
    btrim(p_reason), private.current_identity_id(), p_idempotency_key
  ) returning * into v_override;

  perform public.append_tournament_audit(
    v_suspension.organization_id, 'discipline.override', 'player_suspension',
    v_suspension.id, v_suspension.team_entry_id, v_suspension.tournament_id,
    jsonb_build_object(
      'action', p_action, 'previous', v_previous,
      'new', v_override.new_state, 'reason', btrim(p_reason)
    )
  );
  return v_override.id;
end;
$$;


--
-- Name: create_tournament_document(uuid, uuid, uuid, text, text, text, text, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_tournament_document(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_document_type text, p_title text, p_summary text, p_body text, p_acknowledgement_mode text, p_effective_at timestamp with time zone, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tournament public.tournaments%rowtype;
  v_document_id uuid;
  v_version_id uuid;
  v_existing public.tournament_documents%rowtype;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;
  if not public.has_tournament_communications_capability(
    p_organization_id,'documents.create'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_DOCUMENT_FORBIDDEN';
  end if;
  select * into v_tournament
  from public.tournaments tournament
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
    and tournament.status <> 'archived';
  if v_tournament.id is null
    or (p_category_id is not null and not exists (
      select 1 from public.tournament_categories category
      where category.id = p_category_id
        and category.organization_id = p_organization_id
        and category.tournament_id = p_tournament_id
        and category.status = 'active'
    ))
  then
    raise exception using errcode = '42501', message = 'TORNEOS_DOCUMENT_FORBIDDEN';
  end if;
  select * into v_existing
  from public.tournament_documents document
  where document.organization_id = p_organization_id
    and document.created_by = private.current_identity_id()
    and document.idempotency_key = p_idempotency_key;
  if v_existing.id is not null then
    if v_existing.tournament_id <> p_tournament_id
      or v_existing.category_id is distinct from p_category_id
      or v_existing.document_type <> p_document_type
      or v_existing.title <> btrim(p_title)
      or v_existing.acknowledgement_mode <>
        coalesce(p_acknowledgement_mode,'none')
    then
      raise exception using errcode = '23514',
        message = 'TORNEOS_IDEMPOTENCY_CONFLICT';
    end if;
    select version.id into v_version_id
    from public.tournament_document_versions version
    where version.document_id = v_existing.id
      and version.version = 1;
    return jsonb_build_object(
      'documentId',v_existing.id,'versionId',v_version_id
    );
  end if;

  insert into public.tournament_documents (
    organization_id,season_id,tournament_id,category_id,document_type,title,
    acknowledgement_mode,created_by,idempotency_key
  ) values (
    p_organization_id,v_tournament.season_id,p_tournament_id,p_category_id,
    p_document_type,btrim(p_title),coalesce(p_acknowledgement_mode,'none'),
    private.current_identity_id(),p_idempotency_key
  ) returning id into v_document_id;
  insert into public.tournament_document_versions (
    organization_id,document_id,version,status,summary,body,effective_at,created_by
  ) values (
    p_organization_id,v_document_id,1,'draft',btrim(p_summary),btrim(p_body),
    p_effective_at,private.current_identity_id()
  ) returning id into v_version_id;
  perform public.append_tournament_audit(
    p_organization_id,'communications.document_create','tournament_document',
    v_document_id,null,p_tournament_id,
    jsonb_build_object('versionId',v_version_id,'type',p_document_type)
  );
  return jsonb_build_object('documentId',v_document_id,'versionId',v_version_id);
end;
$$;


--
-- Name: create_tournament_document_version(uuid, text, text, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_tournament_document_version(p_document_id uuid, p_summary text, p_body text, p_effective_at timestamp with time zone, p_correction_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_document public.tournament_documents%rowtype;
  v_version integer;
  v_id uuid;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_document
  from public.tournament_documents document
  where document.id = p_document_id
  for update;
  if v_document.id is null
    or v_document.status = 'archived'
    or not public.has_tournament_communications_capability(
      v_document.organization_id,'documents.update_draft'
    )
    or p_correction_reason is null
    or char_length(btrim(p_correction_reason)) < 4
  then
    raise exception using errcode = '42501', message = 'TORNEOS_DOCUMENT_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournament_document_versions version
    where version.document_id = p_document_id and version.status = 'draft'
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_DOCUMENT_DRAFT_EXISTS';
  end if;
  select coalesce(max(version),0) + 1 into v_version
  from public.tournament_document_versions
  where document_id = p_document_id;
  insert into public.tournament_document_versions (
    organization_id,document_id,version,status,summary,body,effective_at,
    correction_reason,created_by,source_version_id
  ) values (
    v_document.organization_id,p_document_id,v_version,'draft',
    btrim(p_summary),btrim(p_body),p_effective_at,btrim(p_correction_reason),
    private.current_identity_id(),v_document.active_version_id
  ) returning id into v_id;
  return v_id;
end;
$$;


--
-- Name: create_tournament_match_correction(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_tournament_match_correction(p_organization_id uuid, p_match_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_source public.tournament_match_operations%rowtype;
  v_new public.tournament_match_operations%rowtype;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('torneos:match-correction:' || p_match_operation_id, 0));
  select * into v_source from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_source.id is null or v_source.status <> 'official'
    or not exists (
      select 1
      from public.tournament_match_reviews review
      where review.match_operation_id = v_source.id
        and review.review_type = 'correction'
        and review.status = 'open'
    )
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.correct'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournament_match_operations
    where source_operation_id = v_source.id and status <> 'voided'
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_MATCH_CORRECTION_EXISTS';
  end if;
  insert into public.tournament_match_operations (
    organization_id, season_id, tournament_id, category_id, fixture_version_id,
    phase_id, round_id, match_id, home_team_entry_id, away_team_entry_id,
    status, match_status, operation_version, source_operation_id,
    match_snapshot, home_team_snapshot, away_team_snapshot, notes,
    opened_by, reopened_at, reopened_by
  ) select
    organization_id, season_id, tournament_id, category_id, fixture_version_id,
    phase_id, round_id, match_id, home_team_entry_id, away_team_entry_id,
    'draft', case (
      select outcome.outcome_type
      from public.tournament_match_outcomes outcome
      where outcome.match_operation_id = v_source.id
    )
      when 'played' then 'played'
      when 'suspended' then 'suspended'
      when 'abandoned' then 'abandoned'
      when 'home_no_show' then 'administrative'
      when 'away_no_show' then 'administrative'
      when 'double_no_show' then 'administrative'
      when 'walkover_home' then 'administrative'
      when 'walkover_away' then 'administrative'
      when 'administrative_result' then 'administrative'
      else 'ready'
    end,
    (
      select coalesce(max(existing.operation_version), 0) + 1
      from public.tournament_match_operations existing
      where existing.match_id = v_source.match_id
    ), id, match_snapshot, home_team_snapshot,
    away_team_snapshot, notes, private.current_identity_id(), now(), private.current_identity_id()
  from public.tournament_match_operations where id = v_source.id
  returning * into v_new;
  insert into public.tournament_match_operation_players (
    organization_id, match_operation_id, match_id, team_entry_id, roster_player_id,
    display_name_snapshot, avatar_url_snapshot, shirt_number_snapshot,
    position_snapshot, is_goalkeeper, is_captain, lineup_status, attendance_status
  ) select
    organization_id, v_new.id, match_id, team_entry_id, roster_player_id,
    display_name_snapshot, avatar_url_snapshot, shirt_number_snapshot,
    position_snapshot, is_goalkeeper, is_captain, lineup_status, attendance_status
  from public.tournament_match_operation_players where match_operation_id = v_source.id;
  insert into public.tournament_match_outcomes (
    match_operation_id, organization_id, match_id, outcome_type, started_at,
    ended_at, suspension_minute, suspension_period, events_remain_valid,
    reason_code, reason_text, administrative_home_score, administrative_away_score,
    counts_for_standings, counts_for_player_stats, requires_resolution,
    resolved_by, resolved_at
  ) select
    v_new.id, organization_id, match_id, outcome_type, started_at, ended_at,
    suspension_minute, suspension_period, events_remain_valid, reason_code,
    reason_text, administrative_home_score, administrative_away_score,
    counts_for_standings, counts_for_player_stats, requires_resolution,
    resolved_by, resolved_at
  from public.tournament_match_outcomes where match_operation_id = v_source.id;
  insert into public.tournament_match_scores (
    match_operation_id, organization_id, match_id, home_score, away_score,
    home_score_first_half, away_score_first_half, home_penalties, away_penalties,
    score_type
  ) select
    v_new.id, organization_id, match_id, home_score, away_score,
    home_score_first_half, away_score_first_half, home_penalties, away_penalties,
    score_type
  from public.tournament_match_scores where match_operation_id = v_source.id;
  insert into public.tournament_match_events (
    organization_id, match_operation_id, match_id, team_entry_id,
    roster_player_id, related_roster_player_id, event_type, minute, period,
    sequence_number, unidentified_player_reason, metadata, created_by
  ) select
    organization_id, v_new.id, match_id, team_entry_id,
    roster_player_id, related_roster_player_id, event_type, minute, period,
    sequence_number, unidentified_player_reason,
    metadata || jsonb_build_object(
      'copiedFromEventId', id,
      'copiedFromRelatedEventId', related_event_id
    ), private.current_identity_id()
  from public.tournament_match_events
  where match_operation_id = v_source.id and voided_at is null
  order by sequence_number;
  update public.tournament_match_events copied
  set related_event_id = copied_goal.id
  from public.tournament_match_events copied_goal
  where copied.match_operation_id = v_new.id
    and copied.event_type in ('assist', 'substitution_in')
    and copied_goal.match_operation_id = v_new.id
    and copied_goal.metadata->>'copiedFromEventId'
      = copied.metadata->>'copiedFromRelatedEventId';
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.correction_created',
    'match_operation', v_new.id, null, v_new.tournament_id,
    jsonb_build_object(
      'sourceOperationId', v_source.id,
      'operationVersion', v_new.operation_version
    )
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_new.id);
end;
$$;


--
-- Name: create_tournament_media_gallery(uuid, uuid, uuid, uuid, uuid, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_tournament_media_gallery(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_round_id uuid, p_match_id uuid, p_title text, p_description text, p_visibility text, p_idempotency_key uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_scope record;
  v_existing public.tournament_media_galleries%rowtype;
  v_id uuid;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;

  if not public.has_tournament_media_capability(
    p_organization_id, 'media.create_gallery'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      p_organization_id::text || ':' || private.current_identity_id()::text || ':' || p_idempotency_key::text,
      3
    )
  );

  select tournament.season_id
  into v_scope
  from public.tournaments tournament
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
    and tournament.status <> 'archived';
  if v_scope.season_id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  if p_category_id is not null and not exists (
    select 1 from public.tournament_categories category
    where category.id = p_category_id
      and category.organization_id = p_organization_id
      and category.tournament_id = p_tournament_id
      and category.status = 'active'
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_SCOPE_INVALID';
  end if;
  if p_round_id is not null and not exists (
    select 1
    from public.tournament_rounds round
    join public.tournament_fixture_versions fixture
      on fixture.id = round.fixture_version_id
    where round.id = p_round_id
      and round.organization_id = p_organization_id
      and round.tournament_id = p_tournament_id
      and (p_category_id is null or round.category_id = p_category_id)
      and fixture.status = 'published'
      and fixture.invalidated_at is null
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_SCOPE_INVALID';
  end if;
  if p_match_id is not null and not exists (
    select 1
    from public.tournament_matches match
    join public.tournament_fixture_versions fixture
      on fixture.id = match.fixture_version_id
    where match.id = p_match_id
      and match.organization_id = p_organization_id
      and match.tournament_id = p_tournament_id
      and (p_category_id is null or match.category_id = p_category_id)
      and (p_round_id is null or match.round_id = p_round_id)
      and fixture.status = 'published'
      and fixture.invalidated_at is null
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_SCOPE_INVALID';
  end if;
  if p_visibility = 'match_participants' and p_match_id is null then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_VISIBILITY_INVALID';
  end if;

  select * into v_existing
  from public.tournament_media_galleries gallery
  where gallery.organization_id = p_organization_id
    and gallery.created_by = private.current_identity_id()
    and gallery.idempotency_key = p_idempotency_key;
  if v_existing.id is not null then
    if v_existing.tournament_id is distinct from p_tournament_id
      or v_existing.category_id is distinct from p_category_id
      or v_existing.round_id is distinct from p_round_id
      or v_existing.match_id is distinct from p_match_id
      or v_existing.title is distinct from btrim(p_title)
      or v_existing.description is distinct from nullif(btrim(p_description),'')
      or v_existing.visibility is distinct from p_visibility
    then
      raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_IDEMPOTENCY_CONFLICT';
    end if;
    return v_existing.id;
  end if;

  insert into public.tournament_media_galleries (
    organization_id,season_id,tournament_id,category_id,round_id,match_id,
    title,description,visibility,created_by,idempotency_key
  ) values (
    p_organization_id,v_scope.season_id,p_tournament_id,p_category_id,p_round_id,
    p_match_id,btrim(p_title),nullif(btrim(p_description),''),
    p_visibility,private.current_identity_id(),p_idempotency_key
  ) returning id into v_id;
  perform public.append_tournament_audit(
    p_organization_id,'media.gallery.created','media_gallery',v_id,
    null,p_tournament_id,jsonb_build_object('visibility',p_visibility)
  );
  return v_id;
end;
$$;


--
-- Name: create_tournament_organization(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_tournament_organization(p_name text, p_slug text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_user_id uuid := private.current_identity_id();
  v_name text := btrim(coalesce(p_name, ''));
  v_slug text := public.normalize_tournament_organization_slug(p_slug);
  v_organization public.tournament_organizations%rowtype;
  v_membership public.tournament_organization_members%rowtype;
  v_created_recently integer;
  v_constraint_name text;
  v_reserved_slugs constant text[] := array[
    'admin', 'api', 'app', 'auth', 'login', 'logout', 'profile',
    'torneos', 'tournaments', 'settings', 'support', 'www'
  ];
begin
  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'TORNEOS_AUTH_REQUIRED';
  end if;

  if p_idempotency_key is null then
    raise exception using
      errcode = '22023',
      message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;

  if char_length(v_name) not between 3 and 80 then
    raise exception using
      errcode = '22023',
      message = 'TORNEOS_INVALID_NAME';
  end if;

  if char_length(v_slug) not between 3 and 48
    or v_slug !~ '^[a-z0-9](?:[a-z0-9-]{1,46}[a-z0-9])$'
    or v_slug = any(v_reserved_slugs)
  then
    raise exception using
      errcode = '22023',
      message = 'TORNEOS_INVALID_SLUG';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(v_user_id::text, 0)
  );

  select organization.*
  into v_organization
  from public.tournament_organizations organization
  where organization.created_by = v_user_id
    and organization.creation_key = p_idempotency_key;

  if v_organization.id is null then
    select count(*)
    into v_created_recently
    from public.tournament_organizations organization
    where organization.created_by = v_user_id
      and organization.created_at > now() - interval '10 minutes';

    if v_created_recently >= 5 then
      raise exception using
        errcode = 'P0001',
        message = 'TORNEOS_CREATION_RATE_LIMITED';
    end if;

    begin
      insert into public.tournament_organizations (
        name,
        slug,
        status,
        created_by,
        creation_key
      )
      values (
        v_name,
        v_slug,
        'active',
        v_user_id,
        p_idempotency_key
      )
      returning * into v_organization;
    exception
      when unique_violation then
        get stacked diagnostics v_constraint_name = constraint_name;
        if v_constraint_name = 'tournament_organizations_slug_unique' then
          raise exception using
            errcode = '23505',
            message = 'TORNEOS_SLUG_TAKEN';
        elsif v_constraint_name = 'tournament_organizations_creation_unique' then
          select organization.*
          into v_organization
          from public.tournament_organizations organization
          where organization.created_by = v_user_id
            and organization.creation_key = p_idempotency_key;
          if v_organization.id is null then
            raise;
          end if;
        else
          raise;
        end if;
    end;

    if not exists (
      select 1
      from public.tournament_organization_members membership
      where membership.organization_id = v_organization.id
        and membership.user_id = v_user_id
    ) then
      insert into public.tournament_organization_members (
        organization_id,
        user_id,
        role,
        status,
        joined_at
      )
      values (
        v_organization.id,
        v_user_id,
        'owner',
        'active',
        now()
      )
      returning * into v_membership;
    end if;
  end if;

  if v_membership.id is null then
    select membership.*
    into v_membership
    from public.tournament_organization_members membership
    where membership.organization_id = v_organization.id
      and membership.user_id = v_user_id
      and membership.status = 'active';
  end if;

  if v_membership.id is null
    or v_membership.role <> 'owner'
    or v_membership.status <> 'active'
  then
    raise exception using
      errcode = '23514',
      message = 'TORNEOS_ACTIVE_OWNER_REQUIRED';
  end if;

  insert into public.user_workspace_preferences (
    user_id,
    workspace_type,
    active_organization_id
  )
  values (
    v_user_id,
    'tournament_organization',
    v_organization.id
  )
  on conflict (user_id) do update
  set workspace_type = excluded.workspace_type,
      active_organization_id = excluded.active_organization_id;

  return jsonb_build_object(
    'organization', jsonb_build_object(
      'id', v_organization.id,
      'name', v_organization.name,
      'slug', v_organization.slug,
      'logoPath', v_organization.logo_path,
      'status', v_organization.status,
      'createdAt', v_organization.created_at
    ),
    'membership', jsonb_build_object(
      'role', v_membership.role,
      'status', v_membership.status,
      'joinedAt', v_membership.joined_at,
      'capabilities', to_jsonb(
        public.tournament_role_capabilities(v_membership.role)
      )
    ),
    'preference', jsonb_build_object(
      'workspaceType', 'tournament_organization',
      'activeOrganizationId', v_organization.id
    )
  );
end;
$_$;


--
-- Name: FUNCTION create_tournament_organization(p_name text, p_slug text, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.create_tournament_organization(p_name text, p_slug text, p_idempotency_key uuid) IS 'Atomically creates an organization, its owner membership, and the active preference.';


--
-- Name: create_tournament_points_adjustment(uuid, uuid, uuid, uuid, uuid, integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_tournament_points_adjustment(p_organization_id uuid, p_fixture_version_id uuid, p_phase_id uuid, p_group_id uuid, p_participant_id uuid, p_points integer, p_reason text, p_idempotency_key uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_fixture public.tournament_fixture_versions%rowtype;
  v_adjustment public.tournament_points_adjustments%rowtype;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;

  select * into v_fixture
  from public.tournament_fixture_versions
  where id = p_fixture_version_id
    and organization_id = p_organization_id
    and status = 'published';
  if v_fixture.id is null
    or not public.has_tournament_organization_capability(
      p_organization_id, 'standings.override'
    )
    or not exists (
      select 1 from public.tournament_scoring_rules scoring
      where scoring.tournament_id = v_fixture.tournament_id
        and scoring.organization_id = p_organization_id
        and scoring.allow_manual_points_adjustment
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_STANDINGS_FORBIDDEN';
  end if;
  if p_points is null or p_points = 0 or p_points not between -99 and 99
    or p_idempotency_key is null
    or char_length(btrim(coalesce(p_reason, ''))) < 3
    or not exists (
      select 1
      from public.tournament_phases phase
      join public.tournament_competition_participants participant
        on participant.organization_id = phase.organization_id
        and participant.tournament_id = phase.tournament_id
        and participant.category_id = phase.category_id
        and participant.participant_set_id = v_fixture.participant_set_id
      where phase.id = p_phase_id
        and phase.fixture_version_id = v_fixture.id
        and participant.id = p_participant_id
        and (
          p_group_id is null
          or exists (
            select 1 from public.tournament_group_members member
            where member.group_id = p_group_id
              and member.participant_id = participant.id
          )
        )
    )
  then
    raise exception using errcode = '22023', message = 'TORNEOS_STANDINGS_SCOPE_INVALID';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    p_organization_id::text || ':' || v_fixture.tournament_id::text || ':'
    || v_fixture.category_id::text || ':' || p_phase_id::text || ':'
    || coalesce(p_group_id::text, 'all'),
    0
  ));
  perform 1
  from public.tournament_fixture_versions fixture
  where fixture.id = v_fixture.id
    and fixture.organization_id = p_organization_id
    and fixture.status = 'published'
  for share;
  if not found then
    raise exception using errcode = '42501', message = 'TORNEOS_STANDINGS_FORBIDDEN';
  end if;

  select * into v_adjustment
  from public.tournament_points_adjustments
  where organization_id = p_organization_id
    and actor_user_id = private.current_identity_id()
    and idempotency_key = p_idempotency_key;
  if v_adjustment.id is not null then
    if v_adjustment.fixture_version_id <> v_fixture.id
      or v_adjustment.phase_id <> p_phase_id
      or v_adjustment.group_id is distinct from p_group_id
      or v_adjustment.participant_id <> p_participant_id
      or v_adjustment.points <> p_points
      or v_adjustment.reason <> btrim(p_reason)
    then
      raise exception using errcode = '23514', message = 'TORNEOS_IDEMPOTENCY_CONFLICT';
    end if;
    return v_adjustment.id;
  end if;

  insert into public.tournament_points_adjustments (
    organization_id, tournament_id, category_id, participant_set_id,
    fixture_version_id, phase_id, group_id, participant_id, points,
    reason, actor_user_id, idempotency_key
  ) values (
    p_organization_id, v_fixture.tournament_id, v_fixture.category_id,
    v_fixture.participant_set_id, v_fixture.id, p_phase_id, p_group_id,
    p_participant_id, p_points, btrim(p_reason), private.current_identity_id(), p_idempotency_key
  ) returning * into v_adjustment;

  perform public.append_tournament_audit(
    p_organization_id, 'standings.points_adjust', 'points_adjustment',
    v_adjustment.id, null, v_fixture.tournament_id,
    jsonb_build_object(
      'participantId', p_participant_id, 'points', p_points,
      'phaseId', p_phase_id, 'groupId', p_group_id, 'reason', btrim(p_reason)
    )
  );
  return v_adjustment.id;
end;
$$;


--
-- Name: create_tournament_provisional_player(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_tournament_provisional_player(p_organization_id uuid, p_team_entry_id uuid, p_display_name text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_player public.tournament_provisional_players%rowtype;
  v_entry public.tournament_team_entries%rowtype;
begin
  select * into v_entry from public.tournament_team_entries
  where id = p_team_entry_id and organization_id = p_organization_id;
  if private.current_identity_id() is null or v_entry.id is null
    or not public.can_edit_tournament_team_entry(
      p_organization_id,
      p_team_entry_id
    )
  then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  if char_length(btrim(coalesce(p_display_name, ''))) not between 2 and 100 then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_PLAYER';
  end if;
  insert into public.tournament_provisional_players (
    organization_id, display_name, normalized_name, created_by
  ) values (
    p_organization_id, btrim(p_display_name),
    public.normalize_tournament_person_name(p_display_name), private.current_identity_id()
  ) returning * into v_player;
  perform public.append_tournament_audit(
    p_organization_id, 'provisional_player.created', 'provisional_player',
    v_player.id, p_team_entry_id, v_entry.tournament_id, '{}'::jsonb
  );
  return jsonb_build_object('id', v_player.id, 'displayName', v_player.display_name, 'claimStatus', v_player.claim_status);
end;
$$;


--
-- Name: create_tournament_season(uuid, text, text, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_tournament_season(p_organization_id uuid, p_name text, p_slug text, p_start_date date, p_end_date date, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := private.current_identity_id();
  v_name text := btrim(coalesce(p_name, ''));
  v_slug text := public.normalize_tournament_competition_slug(p_slug);
  v_season public.tournament_seasons%rowtype;
  v_constraint_name text;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(
    p_organization_id,
    'seasons.create'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;
  if char_length(v_name) not between 3 and 80
    or char_length(v_slug) not between 3 and 48
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_SEASON';
  end if;
  if p_start_date is not null and p_end_date is not null and p_end_date < p_start_date then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_DATES';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    p_organization_id::text || ':' || v_user_id::text || ':season',
    0
  ));

  perform 1
  from public.tournament_organizations organization
  where organization.id = p_organization_id
    and organization.status = 'active'
  for share;

  if not found then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  select season.* into v_season
  from public.tournament_seasons season
  where season.organization_id = p_organization_id
    and season.created_by = v_user_id
    and season.creation_key = p_idempotency_key;

  if v_season.id is not null and v_season.status = 'archived' then
    raise exception using errcode = '23514', message = 'TORNEOS_IDEMPOTENCY_CONFLICT';
  end if;

  if v_season.id is null then
    begin
      insert into public.tournament_seasons (
        organization_id,
        name,
        slug,
        status,
        start_date,
        end_date,
        created_by,
        creation_key
      )
      values (
        p_organization_id,
        v_name,
        v_slug,
        'draft',
        p_start_date,
        p_end_date,
        v_user_id,
        p_idempotency_key
      )
      returning * into v_season;
    exception when unique_violation then
      get stacked diagnostics v_constraint_name = constraint_name;
      if v_constraint_name = 'tournament_seasons_slug_unique' then
        raise exception using errcode = '23505', message = 'TORNEOS_SEASON_SLUG_TAKEN';
      elsif v_constraint_name = 'tournament_seasons_creation_unique' then
        select season.* into v_season
        from public.tournament_seasons season
        where season.organization_id = p_organization_id
          and season.created_by = v_user_id
          and season.creation_key = p_idempotency_key;
      else
        raise;
      end if;
    end;
  end if;

  insert into public.user_tournament_context_preferences (
    user_id,
    organization_id,
    active_season_id,
    active_tournament_id
  )
  values (v_user_id, p_organization_id, v_season.id, null)
  on conflict (user_id, organization_id) do update
  set active_season_id = excluded.active_season_id,
      active_tournament_id = null;

  return jsonb_build_object(
    'id', v_season.id,
    'organizationId', v_season.organization_id,
    'name', v_season.name,
    'slug', v_season.slug,
    'status', v_season.status,
    'startDate', v_season.start_date,
    'endDate', v_season.end_date,
    'createdAt', v_season.created_at,
    'updatedAt', v_season.updated_at
  );
end;
$$;


--
-- Name: create_tournament_season_purchase(uuid, uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_tournament_season_purchase(p_organization_id uuid, p_season_id uuid, p_product_code text, p_idempotency_key uuid, p_provider text, p_provider_environment text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_offer public.tournament_commercial_offers%rowtype;
  v_purchase public.tournament_purchases%rowtype;
  v_product public.tournament_commercial_products%rowtype;
  v_id uuid := gen_random_uuid();
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(p_organization_id,'billing.manage') then
    raise exception using errcode = '42501', message = 'TORNEOS_BILLING_FORBIDDEN';
  end if;
  if p_idempotency_key is null or not (
    (p_provider = 'FAKE' and p_provider_environment in ('local','qa'))
    or (p_provider = 'MERCADO_PAGO' and p_provider_environment = 'test')
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_PURCHASE_INVALID';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_organization_id::text || ':' || p_season_id::text || ':' || p_product_code,79)
  );
  if not exists (
    select 1 from public.tournament_seasons season
    where season.organization_id = p_organization_id and season.id = p_season_id
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_PURCHASE_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournament_season_plan_grants grant_row
    where grant_row.organization_id = p_organization_id
      and grant_row.season_id = p_season_id
      and public.is_tournament_season_plan_grant_effective(grant_row.id)
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_SEASON_ALREADY_PREMIUM';
  end if;
  select * into v_purchase from public.tournament_purchases
  where buyer_user_id = private.current_identity_id() and idempotency_key = p_idempotency_key;
  if v_purchase.id is not null then
    if v_purchase.organization_id <> p_organization_id
      or v_purchase.season_id <> p_season_id
      or v_purchase.product_code <> p_product_code
      or v_purchase.provider <> p_provider
      or v_purchase.provider_environment <> p_provider_environment then
      raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_CONFLICT';
    end if;
    return public.tournament_purchase_projection(v_purchase)
      || jsonb_build_object('idempotentReplay',true,'existingOpenPurchase',false);
  end if;
  select * into v_purchase from public.tournament_purchases
  where organization_id = p_organization_id and season_id = p_season_id
    and product_code = p_product_code and status in ('created','preference_created','pending')
  order by created_at limit 1 for update;
  if v_purchase.id is not null then
    if v_purchase.provider <> p_provider
      or v_purchase.provider_environment <> p_provider_environment then
      raise exception using errcode = '55000', message = 'TORNEOS_OPEN_PURCHASE_PROVIDER_CONFLICT';
    end if;
    return public.tournament_purchase_projection(v_purchase)
      || jsonb_build_object('idempotentReplay',false,'existingOpenPurchase',true);
  end if;
  select * into v_product from public.tournament_commercial_products
  where product_code = p_product_code and status = 'active';
  if v_product.product_code is null or v_product.plan_code <> 'PREMIUM'
    or v_product.scope <> 'season' or v_product.billing_model <> 'one_time' then
    raise exception using errcode = '22023', message = 'TORNEOS_PRODUCT_UNAVAILABLE';
  end if;
  select * into v_offer from public.tournament_commercial_offers offer
  where offer.product_code = p_product_code and offer.availability = 'available'
    and offer.valid_from <= statement_timestamp()
    and (offer.valid_until is null or offer.valid_until > statement_timestamp())
  order by offer.valid_from desc,offer.offer_version desc limit 1;
  if v_offer.product_code is null then
    raise exception using errcode = '22023', message = 'TORNEOS_OFFER_UNAVAILABLE';
  end if;
  insert into public.tournament_purchases (
    id,organization_id,season_id,tournament_id,buyer_user_id,product_code,
    offer_code,offer_version,list_amount_snapshot,amount_snapshot,currency,
    provider,provider_environment,external_reference,idempotency_key,status,
    preference_expires_at
  ) values (
    v_id,p_organization_id,p_season_id,null,private.current_identity_id(),p_product_code,
    v_offer.offer_code,v_offer.offer_version,v_offer.list_amount,v_offer.amount,
    v_offer.currency,p_provider,p_provider_environment,
    'arma2:season:purchase:' || v_id::text,p_idempotency_key,'created',
    now() + interval '30 minutes'
  ) returning * into v_purchase;
  insert into public.tournament_purchase_events (
    purchase_id,organization_id,event_type,from_status,to_status,actor_type,actor_user_id,
    metadata
  ) values (
    v_purchase.id,p_organization_id,'purchase.created',null,'created','user',private.current_identity_id(),
    jsonb_build_object('seasonId',p_season_id)
  );
  return public.tournament_purchase_projection(v_purchase)
    || jsonb_build_object('idempotentReplay',false,'existingOpenPurchase',false);
end;
$$;


--
-- Name: create_tournament_team_entry(uuid, uuid, uuid, uuid, text, text, text, text, text, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_tournament_team_entry(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_arma2_team_id uuid, p_name text, p_short_name text, p_primary_color text, p_secondary_color text, p_registration_source text, p_manager_user_id uuid, p_manager_email text, p_manager_display_name text, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_uid uuid := private.current_identity_id();
  v_tournament public.tournaments%rowtype;
  v_category public.tournament_categories%rowtype;

  v_entry public.tournament_team_entries%rowtype;
  v_roster public.tournament_rosters%rowtype;
  v_manager public.tournament_team_managers%rowtype;
  v_name text := btrim(coalesce(p_name, ''));
  v_slug text;
  v_source text := coalesce(p_registration_source, case when p_arma2_team_id is null then 'provisional' else 'arma2_team' end);
  v_email text := nullif(lower(btrim(coalesce(p_manager_email, ''))), '');
  v_primary_color text := p_primary_color;
  v_secondary_color text := p_secondary_color;
begin
  if v_uid is null then raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED'; end if;
  if not public.has_tournament_organization_capability(p_organization_id, 'team_entries.create') then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  -- Phase 2A: organization membership alone does not authorize this season.
  if not exists (
    select 1 from public.tournaments scoped_tournament
    where scoped_tournament.id = p_tournament_id
      and scoped_tournament.organization_id = p_organization_id
      and public.has_tournament_season_access(p_organization_id, scoped_tournament.season_id)
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if p_idempotency_key is null then raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED'; end if;

  perform pg_advisory_xact_lock(hashtextextended(p_organization_id::text || ':' || p_tournament_id::text, 0));
  select * into v_entry from public.tournament_team_entries
  where organization_id = p_organization_id and created_by = v_uid
    and idempotency_key = p_idempotency_key;
  if v_entry.id is not null then
    select * into v_roster from public.tournament_rosters where team_entry_id = v_entry.id order by version desc limit 1;
    return jsonb_build_object('entryId', v_entry.id, 'rosterId', v_roster.id, 'status', v_entry.status);
  end if;

  select * into v_tournament from public.tournaments
  where id = p_tournament_id and organization_id = p_organization_id
    and status = 'registration' and archived_at is null
    and (registration_opens_at is null or now() >= registration_opens_at)
    and (registration_closes_at is null or now() <= registration_closes_at);
  select * into v_category from public.tournament_categories
  where id = p_category_id and organization_id = p_organization_id
    and tournament_id = p_tournament_id and status = 'active';
  if v_tournament.id is null or v_category.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_REGISTRATION_CLOSED';
  end if;
  if v_source not in ('manual', 'invitation', 'arma2_team', 'provisional')
    or ((v_source = 'arma2_team') <> (p_arma2_team_id is not null))
  then raise exception using errcode = '22023', message = 'TORNEOS_INVALID_TEAM_ENTRY'; end if;
  if p_manager_user_id is not null then
    raise exception using errcode = '22023', message = 'TORNEOS_MANAGER_INVITATION_REQUIRED';
  end if;
  if p_arma2_team_id is not null then
    raise SQLSTATE '0A000' using message='TORNEOS_CORE_TEAM_IMPORT_CONTRACT_PENDING';
  end if;
  if char_length(v_name) not between 2 and 100 then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_TEAM_ENTRY';
  end if;

  v_slug := public.normalize_tournament_competition_slug(v_name);
  if char_length(v_slug) < 2 then v_slug := 'equipo-' || substr(replace(public.gen_random_uuid()::text, '-', ''), 1, 8); end if;
  if exists (
    select 1 from public.tournament_team_entries
    where tournament_id = p_tournament_id and category_id = p_category_id and slug = v_slug
  ) then v_slug := left(v_slug, 54) || '-' || substr(replace(public.gen_random_uuid()::text, '-', ''), 1, 8); end if;

  insert into public.tournament_team_entries (
    organization_id, season_id, tournament_id, category_id, arma2_team_id,
    name, slug, short_name, primary_color, secondary_color, status,
    registration_source, created_by, idempotency_key
  ) values (
    p_organization_id, v_tournament.season_id, p_tournament_id, p_category_id,
    p_arma2_team_id, v_name, v_slug, nullif(btrim(coalesce(p_short_name, '')), ''),
    v_primary_color, v_secondary_color, 'draft',
    v_source, v_uid, p_idempotency_key
  ) returning * into v_entry;

  insert into public.tournament_rosters (
    organization_id, team_entry_id, version, status, created_by
  ) values (p_organization_id, v_entry.id, 1, 'draft', v_uid)
  returning * into v_roster;

  insert into public.tournament_roster_settings (
    tournament_id, organization_id, minimum_players, maximum_players,
    minimum_goalkeepers, roster_opens_at, roster_closes_at
  ) values (
    p_tournament_id, p_organization_id, v_tournament.team_size,
    least(80, v_tournament.team_size + coalesce(v_tournament.substitutes_limit, v_tournament.team_size)),
    1, v_tournament.registration_opens_at, v_tournament.registration_closes_at
  ) on conflict (tournament_id) do nothing;

  if v_email is not null then
    if char_length(btrim(coalesce(p_manager_display_name, ''))) not between 2 and 100 then
      raise exception using errcode = '22023', message = 'TORNEOS_INVALID_MANAGER';
    end if;
    insert into public.tournament_team_managers (
      organization_id, team_entry_id, user_id, email_normalized, display_name,
      role, status, invited_by, accepted_at
    ) values (
      p_organization_id, v_entry.id, null, v_email,
      btrim(p_manager_display_name), 'captain', 'pending',
      v_uid, null
    ) returning * into v_manager;
  end if;

  perform public.append_tournament_audit(
    p_organization_id, 'team_entry.created', 'team_entry', v_entry.id,
    v_entry.id, p_tournament_id,
    jsonb_build_object('source', v_source, 'categoryId', p_category_id, 'linked', p_arma2_team_id is not null)
  );
  return jsonb_build_object(
    'entryId', v_entry.id, 'rosterId', v_roster.id,
    'managerId', v_manager.id, 'status', v_entry.status
  );
exception when unique_violation then
  if p_arma2_team_id is not null then
    raise exception using errcode = '23505', message = 'TORNEOS_TEAM_ALREADY_REGISTERED';
  end if;
  raise;
end;
$$;


--
-- Name: create_tournament_venue(uuid, text, text, text, double precision, double precision, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_tournament_venue(p_organization_id uuid, p_name text, p_address text, p_place_id text DEFAULT NULL::text, p_latitude double precision DEFAULT NULL::double precision, p_longitude double precision DEFAULT NULL::double precision, p_locality text DEFAULT NULL::text, p_timezone text DEFAULT 'America/Argentina/Buenos_Aires'::text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_venue public.tournament_venues%rowtype;
begin
  if private.current_identity_id() is null
    or not public.has_tournament_organization_capability(p_organization_id, 'venues.create')
    or not exists (
      select 1 from public.tournament_organizations organization
      where organization.id = p_organization_id and organization.status = 'active'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if not exists (
    select 1 from pg_catalog.pg_timezone_names zone where zone.name = p_timezone
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_TIMEZONE';
  end if;
  insert into public.tournament_venues (
    organization_id, name, address, place_id, latitude, longitude,
    locality, timezone, notes
  ) values (
    p_organization_id, btrim(p_name), btrim(p_address),
    nullif(btrim(coalesce(p_place_id, '')), ''), p_latitude, p_longitude,
    nullif(btrim(coalesce(p_locality, '')), ''), p_timezone,
    nullif(btrim(coalesce(p_notes, '')), '')
  ) returning * into v_venue;
  perform public.append_tournament_audit(
    p_organization_id, 'venue.created', 'venue', v_venue.id,
    null, null, jsonb_build_object('name', v_venue.name)
  );
  return jsonb_build_object(
    'id', v_venue.id, 'name', v_venue.name, 'status', v_venue.status
  );
end;
$$;


--
-- Name: create_tournament_with_defaults(uuid, uuid, text, text, text, text, text, text, date, date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_tournament_with_defaults(p_organization_id uuid, p_season_id uuid, p_name text, p_slug text, p_description text, p_sport_modality text, p_competition_format text, p_gender_category text, p_start_date date, p_end_date date, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := private.current_identity_id();
  v_name text := btrim(coalesce(p_name, ''));
  v_slug text := public.normalize_tournament_competition_slug(p_slug);
  v_tournament public.tournaments%rowtype;
  v_team_size smallint;
  v_substitutes smallint;
  v_constraint_name text;
  v_format_settings jsonb;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(
    p_organization_id,
    'tournaments.create'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;
  if char_length(v_name) not between 3 and 100
    or char_length(v_slug) not between 3 and 64
    or p_gender_category not in ('male', 'female', 'mixed', 'open')
    or p_competition_format not in (
      'league',
      'knockout',
      'groups',
      'groups_and_playoffs',
      'league_and_playoffs'
    )
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_TOURNAMENT';
  end if;
  if p_start_date is not null and p_end_date is not null and p_end_date < p_start_date then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_DATES';
  end if;

  select modality.team_size, modality.recommended_substitutes
  into v_team_size, v_substitutes
  from public.tournament_sport_modalities modality
  where modality.code = p_sport_modality;

  if v_team_size is null then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_MODALITY';
  end if;

  v_format_settings := case p_competition_format
    when 'league' then '{"rounds":"single","qualifiers":0}'::jsonb
    when 'knockout' then '{"legs":"single","thirdPlace":false}'::jsonb
    when 'groups' then '{"groupCount":2,"qualifiersPerGroup":1,"rounds":"single"}'::jsonb
    when 'groups_and_playoffs' then '{"groupCount":2,"qualifiersPerGroup":1,"groupRounds":"single","knockoutLegs":"single"}'::jsonb
    else '{"leagueRounds":"single","qualifiers":2,"knockoutLegs":"single"}'::jsonb
  end;

  perform pg_advisory_xact_lock(hashtextextended(
    p_organization_id::text || ':' || v_user_id::text || ':tournament',
    0
  ));

  perform 1
  from public.tournament_seasons season
  join public.tournament_organizations organization
    on organization.id = season.organization_id
  where season.id = p_season_id
    and season.organization_id = p_organization_id
    and season.status <> 'archived'
    and organization.status = 'active'
  for share of season, organization;

  if not found then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  select tournament.* into v_tournament
  from public.tournaments tournament
  where tournament.organization_id = p_organization_id
    and tournament.created_by = v_user_id
    and tournament.creation_key = p_idempotency_key;

  if v_tournament.id is not null and v_tournament.status = 'archived' then
    raise exception using errcode = '23514', message = 'TORNEOS_IDEMPOTENCY_CONFLICT';
  end if;

  if v_tournament.id is null then
    begin
      insert into public.tournaments (
        organization_id,
        season_id,
        name,
        slug,
        description,
        status,
        sport_modality,
        competition_format,
        gender_category,
        team_size,
        substitutes_limit,
        start_date,
        end_date,
        format_settings,
        created_by,
        creation_key
      )
      values (
        p_organization_id,
        p_season_id,
        v_name,
        v_slug,
        nullif(btrim(coalesce(p_description, '')), ''),
        'draft',
        p_sport_modality,
        p_competition_format,
        p_gender_category,
        v_team_size,
        v_substitutes,
        p_start_date,
        p_end_date,
        v_format_settings,
        v_user_id,
        p_idempotency_key
      )
      returning * into v_tournament;
    exception when unique_violation then
      get stacked diagnostics v_constraint_name = constraint_name;
      if v_constraint_name = 'tournaments_slug_unique' then
        raise exception using errcode = '23505', message = 'TORNEOS_TOURNAMENT_SLUG_TAKEN';
      elsif v_constraint_name = 'tournaments_creation_unique' then
        select tournament.* into v_tournament
        from public.tournaments tournament
        where tournament.organization_id = p_organization_id
          and tournament.created_by = v_user_id
          and tournament.creation_key = p_idempotency_key;
      else
        raise;
      end if;
    end;

    insert into public.tournament_scoring_rules (
      tournament_id,
      organization_id
    )
    values (v_tournament.id, p_organization_id);

    insert into public.tournament_tiebreak_rules (
      organization_id,
      tournament_id,
      criterion,
      sort_order
    )
    values
      (p_organization_id, v_tournament.id, 'goal_difference', 1),
      (p_organization_id, v_tournament.id, 'goals_for', 2),
      (p_organization_id, v_tournament.id, 'head_to_head', 3),
      (p_organization_id, v_tournament.id, 'fair_play', 4);

    insert into public.tournament_discipline_rules (
      tournament_id,
      organization_id
    )
    values (v_tournament.id, p_organization_id);
  end if;

  insert into public.user_tournament_context_preferences (
    user_id,
    organization_id,
    active_season_id,
    active_tournament_id
  )
  values (v_user_id, p_organization_id, v_tournament.season_id, v_tournament.id)
  on conflict (user_id, organization_id) do update
  set active_season_id = excluded.active_season_id,
      active_tournament_id = excluded.active_tournament_id;

  return jsonb_build_object(
    'id', v_tournament.id,
    'organizationId', v_tournament.organization_id,
    'seasonId', v_tournament.season_id,
    'name', v_tournament.name,
    'slug', v_tournament.slug,
    'status', v_tournament.status
  );
end;
$$;


--
-- Name: current_user_has_media_team_relation(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_has_media_team_relation(p_team_entry_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.current_identity_id() is not null and (
    exists (
      select 1 from public.tournament_team_managers manager
      where manager.team_entry_id = p_team_entry_id
        and manager.user_id = private.current_identity_id()
        and manager.status = 'active'
        and manager.role in ('captain','delegate')
    )
    or exists (
      select 1
      from public.get_my_current_tournament_roster_players() player
      where player.team_entry_id = p_team_entry_id
    )
  );
$$;


--
-- Name: current_user_tournament_social_capabilities(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.current_user_tournament_social_capabilities(p_organization_id uuid) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce((
    select public.tournament_social_role_capabilities(membership.role)
      || case
        when membership.role = 'collaborator' and coalesce(grant_row.can_export, false)
        then array['social.create','social.export','social.editorial_text']::text[]
        else array[]::text[]
      end
    from public.tournament_organization_members membership
    join public.tournament_organizations organization
      on organization.id = membership.organization_id
    left join public.tournament_social_permissions grant_row
      on grant_row.organization_id = membership.organization_id
     and grant_row.user_id = membership.user_id
    where membership.organization_id = p_organization_id
      and membership.user_id = private.current_identity_id()
      -- Suspended and removed members hold nothing, whatever their grant says.
      and membership.status = 'active'
      and organization.status = 'active'
  ), array[]::text[]);
$$;


--
-- Name: digest(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.digest(data text, type text) RETURNS bytea
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$ SELECT extensions.digest(data, type) $$;


--
-- Name: enforce_tournament_media_gallery_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_tournament_media_gallery_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_season_id uuid;
  v_policy jsonb;
  v_limit integer;
  v_count integer;
begin
  select season_id into v_season_id from public.tournaments
  where organization_id = new.organization_id and id = new.tournament_id;
  if v_season_id is null then
    raise exception using errcode='22023',message='TORNEOS_MEDIA_SCOPE_INVALID';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(new.organization_id::text || ':' || v_season_id::text,43)
  );
  v_policy := public.resolve_effective_tournament_season_entitlements_at(
    new.organization_id,v_season_id,now(),false,new.tournament_id
  );
  v_limit := (v_policy->'media'->>'galleryAssetLimit')::integer;
  select
    (select count(*)
     from public.tournament_media_assets asset
     join public.tournaments tournament
       on tournament.organization_id=asset.organization_id and tournament.id=asset.tournament_id
     where asset.organization_id=new.organization_id and tournament.season_id=v_season_id
       and asset.status not in ('rejected','revoked','failed')
       and asset.storage_state <> 'storage_purged')
    +
    (select count(*)
     from public.tournament_media_upload_sessions session
     join public.tournaments tournament
       on tournament.organization_id=session.organization_id and tournament.id=session.tournament_id
     where session.organization_id=new.organization_id and tournament.season_id=v_season_id
       and session.status in ('issued','uploaded') and session.expires_at>now())
  into v_count;
  if v_limit is not null and v_count>=v_limit then
    raise exception using errcode='22023',message='TORNEOS_SEASON_MEDIA_QUOTA_EXCEEDED',
      detail=jsonb_build_object('seasonId',v_season_id,'usage',v_count,'limit',v_limit,
        'upgradeRequired',v_policy->>'plan'='FREE')::text;
  end if;
  new.quota_snapshot := coalesce(new.quota_snapshot,'{}'::jsonb) || jsonb_build_object(
    'scope','season','seasonId',v_season_id,'plan',v_policy->>'plan',
    'galleryAssetLimit',v_limit,'galleryAssetUsage',v_count
  );
  return new;
end;
$$;


--
-- Name: enforce_tournament_media_matchday_limit(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_tournament_media_matchday_limit() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_round_id uuid;
  v_policy jsonb;
  v_max integer;
  v_count integer;
BEGIN
  v_round_id := public.tournament_media_gallery_sports_round(new.gallery_id);
  IF v_round_id IS NULL THEN
    RETURN new;
  END IF;
  -- Serialize the count/check/insert boundary for one official sports date.
  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(
      new.organization_id::text || ':' || new.tournament_id::text || ':' || v_round_id::text,
      23
    )
  );
  v_policy := public.resolve_effective_tournament_entitlements_at(
    new.organization_id,new.tournament_id,now(),false
  );
  v_max := (v_policy->'media'->>'maxPhotosPerMatchday')::integer;
  IF v_max IS NULL THEN
    RETURN new;
  END IF;

  SELECT
    (SELECT count(*)
     FROM public.tournament_media_assets asset
     WHERE asset.organization_id = new.organization_id
       AND asset.tournament_id = new.tournament_id
       AND asset.status <> 'revoked'
       AND asset.storage_state <> 'storage_purged'
       AND public.tournament_media_gallery_sports_round(asset.gallery_id) = v_round_id)
    +
    (SELECT count(*)
     FROM public.tournament_media_upload_sessions session
     WHERE session.organization_id = new.organization_id
       AND session.tournament_id = new.tournament_id
       AND session.status = 'issued'
       AND session.expires_at > now()
       AND public.tournament_media_gallery_sports_round(session.gallery_id) = v_round_id)
  INTO v_count;

  IF v_count >= v_max THEN
    RAISE EXCEPTION USING errcode = '22023', message = 'TORNEOS_MEDIA_QUOTA_EXCEEDED';
  END IF;
  RETURN new;
END;
$$;


--
-- Name: enforce_tournament_premium_gate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_tournament_premium_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_organization_id uuid; v_tournament_id uuid;
begin
  v_organization_id := new.organization_id;
  v_tournament_id := new.tournament_id;
  if public.tournament_requires_premium(v_organization_id,v_tournament_id) then
    raise exception using errcode = '42501', message = 'TORNEOS_PREMIUM_REQUIRED';
  end if;
  return new;
end;
$$;


--
-- Name: enforce_tournament_purchase_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_tournament_purchase_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.status = old.status then return new; end if;
  if not (
    (old.status = 'created' and new.status in ('preference_created','cancelled'))
    or (old.status = 'preference_created' and new.status in ('pending','approved','rejected','cancelled','expired'))
    or (old.status = 'pending' and new.status in ('approved','rejected','cancelled','expired'))
    or (old.status = 'approved' and new.status in ('refunded','charged_back'))
    or (old.status = 'charged_back' and new.status = 'approved')
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_PURCHASE_TRANSITION_INVALID';
  end if;
  return new;
end;
$$;


--
-- Name: enforce_tournament_season_purchase_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_tournament_season_purchase_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if private.current_identity_id() is not null and not public.has_tournament_season_capability(
    new.organization_id,new.season_id,'billing.manage'
  ) then raise exception using errcode='42501',message='TORNEOS_BILLING_FORBIDDEN'; end if;
  return new;
end;
$$;


--
-- Name: enforce_tournament_season_root_write_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_tournament_season_root_write_scope() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_row jsonb := case when tg_op = 'DELETE' then to_jsonb(old) else to_jsonb(new) end;
declare v_organization_id uuid := (v_row->>'organization_id')::uuid;
declare v_season_id uuid;
begin
  if private.current_identity_id() is null then return case when tg_op = 'DELETE' then old else new end; end if;
  if tg_table_name = 'tournament_seasons' then
    v_season_id := (v_row->>'id')::uuid;
  elsif v_row ? 'season_id' then
    v_season_id := (v_row->>'season_id')::uuid;
  elsif v_row ? 'tournament_id' then
    select season_id into v_season_id from public.tournaments
    where organization_id = v_organization_id and id = (v_row->>'tournament_id')::uuid;
  end if;
  if v_season_id is null or not public.has_tournament_season_access(v_organization_id,v_season_id) then
    raise exception using errcode = '42501', message = 'TORNEOS_SEASON_SCOPE_FORBIDDEN';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


--
-- Name: enforce_tournament_status_premium_gate(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_tournament_status_premium_gate() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if new.status not in ('draft','archived')
    and public.tournament_requires_premium(new.organization_id,new.id) then
    raise exception using errcode = '42501', message = 'TORNEOS_PREMIUM_REQUIRED';
  end if;
  return new;
end;
$$;


--
-- Name: enqueue_tournament_media_processing_job(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_tournament_media_processing_job(p_session_id uuid, p_token text, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_target jsonb;
  v_job public.tournament_media_processing_jobs%rowtype;
  v_job_id uuid;
BEGIN
  v_target := public.authorize_tournament_media_upload_target(
    p_session_id,p_token,p_actor_user_id
  );
  IF coalesce(v_target->>'processingTier','') <> 'processor_external' THEN
    RAISE EXCEPTION USING errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  END IF;
  SELECT * INTO v_job FROM public.tournament_media_processing_jobs
  WHERE session_id = p_session_id;
  IF v_job.id IS NOT NULL THEN
    RETURN jsonb_build_object(
      'jobId',v_job.id,'status',v_job.status,'created',false
    );
  END IF;
  INSERT INTO public.tournament_media_processing_jobs (
    session_id,organization_id,tournament_id,gallery_id,requested_by,
    quarantine_path,declared_mime,expected_bytes
  ) VALUES (
    p_session_id,(v_target->>'organizationId')::uuid,
    (v_target->>'tournamentId')::uuid,(v_target->>'galleryId')::uuid,
    p_actor_user_id,v_target->>'objectName',v_target->>'contentType',
    (v_target->>'expectedBytes')::bigint
  ) RETURNING id INTO v_job_id;
  INSERT INTO public.tournament_audit_log (
    organization_id,actor_user_id,actor_type,action,resource_type,
    resource_id,tournament_id,metadata
  ) VALUES (
    (v_target->>'organizationId')::uuid,p_actor_user_id,'system',
    'media.processing_job.queued','media_processing_job',v_job_id,
    (v_target->>'tournamentId')::uuid,
    jsonb_build_object('galleryId',v_target->>'galleryId')
  );
  RETURN jsonb_build_object('jobId',v_job_id,'status','queued','created',true);
END;
$$;


--
-- Name: execute_tournament_group_draw(uuid, uuid, uuid, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.execute_tournament_group_draw(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_group_count integer, p_seed text, p_publish boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_set public.tournament_participant_sets%rowtype;
  v_participant record;
  v_group record;
  v_group_id uuid;
  v_count integer;
  v_min_size integer;
  v_max_size integer;
  v_seed text := btrim(coalesce(p_seed, ''));
begin
  perform public.assert_tournament_fixture_scope(
    p_organization_id, p_tournament_id, p_category_id,
    case when p_publish then 'draw.publish' else 'draw.execute' end,
    array['registration', 'scheduled']::text[]
  );
  if p_group_count not between 2 and 32 or char_length(v_seed) not between 1 and 160 then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_DRAW';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:draw:' || p_tournament_id::text || ':' || p_category_id::text, 0
  ));
  select participant_set.* into v_set
  from public.tournament_participant_sets participant_set
  where participant_set.organization_id = p_organization_id
    and participant_set.tournament_id = p_tournament_id
    and participant_set.category_id = p_category_id
    and participant_set.status = 'frozen'
  for update;
  select count(*) into v_count
  from public.tournament_competition_participants participant
  where participant.participant_set_id = v_set.id and participant.status = 'active';
  if v_set.id is null or v_count < p_group_count then
    raise exception using errcode = '23514', message = 'TORNEOS_INVALID_GROUP_COUNT';
  end if;
  if exists (
    select 1 from public.tournament_groups group_row
    where group_row.participant_set_id = v_set.id
      and group_row.fixture_version_id is null
      and group_row.status = 'published'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_DRAW_NOT_EDITABLE';
  end if;
  delete from public.tournament_group_members member
  using public.tournament_groups group_row
  where member.group_id = group_row.id
    and group_row.participant_set_id = v_set.id
    and group_row.fixture_version_id is null
    and group_row.status = 'draft';
  delete from public.tournament_groups group_row
  where group_row.participant_set_id = v_set.id
    and group_row.fixture_version_id is null
    and group_row.status = 'draft';
  for v_count in 1..p_group_count loop
    insert into public.tournament_groups (
      organization_id, tournament_id, category_id, participant_set_id,
      name, code, sort_order, status, draw_seed
    ) values (
      p_organization_id, p_tournament_id, p_category_id, v_set.id,
      'Grupo ' || v_count, 'G' || lpad(v_count::text, 2, '0'),
      v_count - 1, case when p_publish then 'published' else 'draft' end, v_seed
    );
  end loop;
  for v_participant in
    select participant.id, coalesce(participant.pot_number, 2147483647) as pot_number
    from public.tournament_competition_participants participant
    where participant.participant_set_id = v_set.id and participant.status = 'active'
    order by coalesce(participant.pot_number, 2147483647),
      encode(public.digest(v_seed || ':' || participant.id::text, 'sha256'), 'hex'),
      participant.id
  loop
    select candidate.id into v_group_id
    from public.tournament_groups candidate
    where candidate.participant_set_id = v_set.id
      and candidate.fixture_version_id is null
      and candidate.status = case when p_publish then 'published' else 'draft' end
    order by
      exists (
        select 1
        from public.tournament_group_members existing_member
        join public.tournament_competition_participants existing_participant
          on existing_participant.id = existing_member.participant_id
        where existing_member.group_id = candidate.id
          and coalesce(existing_participant.pot_number, 2147483647) = v_participant.pot_number
      ),
      (select count(*) from public.tournament_group_members size_member
       where size_member.group_id = candidate.id),
      encode(public.digest(v_seed || ':group:' || candidate.sort_order::text, 'sha256'), 'hex')
    limit 1;
    insert into public.tournament_group_members (group_id, participant_id)
    values (v_group_id, v_participant.id);
  end loop;
  select min(size), max(size) into v_min_size, v_max_size
  from (
    select count(member.participant_id)::integer as size
    from public.tournament_groups group_row
    left join public.tournament_group_members member on member.group_id = group_row.id
    where group_row.participant_set_id = v_set.id
      and group_row.fixture_version_id is null
      and group_row.status = case when p_publish then 'published' else 'draft' end
    group by group_row.id
  ) sizes;
  if v_max_size - v_min_size > 1 then
    raise exception using errcode = '23514', message = 'TORNEOS_GROUP_DRAW_IMPOSSIBLE';
  end if;
  perform public.append_tournament_audit(
    p_organization_id,
    case when p_publish then 'draw.published' else 'draw.executed' end,
    'participant_set', v_set.id, null, p_tournament_id,
    jsonb_build_object(
      'categoryId', p_category_id,
      'groupCount', p_group_count,
      'seed', v_seed,
      'participantFingerprint', v_set.participant_fingerprint
    )
  );
  return jsonb_build_object(
    'participantSetId', v_set.id,
    'status', case when p_publish then 'published' else 'draft' end,
    'groupCount', p_group_count,
    'seed', v_seed,
    'participantFingerprint', v_set.participant_fingerprint
  );
end;
$$;


--
-- Name: fail_tournament_media_processing_job(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_tournament_media_processing_job(p_job_id uuid, p_lease_token text, p_failure_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_job public.tournament_media_processing_jobs%rowtype;
  v_next text;
begin
  if p_failure_code is null or p_failure_code !~ '^[A-Z][A-Z0-9_]{2,80}$' then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_FAILURE_CODE_INVALID';
  end if;
  select * into v_job
  from public.tournament_media_processing_jobs
  where id = p_job_id for update;
  if v_job.id is null
    or v_job.status <> 'leased'
    or p_lease_token is null
    or v_job.lease_token is distinct from p_lease_token
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_JOB_LEASE_INVALID';
  end if;
  v_next := case when v_job.attempts >= v_job.max_attempts
    then 'abandoned' else 'queued' end;
  update public.tournament_media_processing_jobs
  set status = v_next, lease_token = null, lease_expires_at = null,
      last_error = p_failure_code, updated_at = now()
  where id = p_job_id;
  -- The last attempt closes the session too, which is what makes the
  -- quarantined object purgeable through the existing sweeper.
  if v_next = 'abandoned' then
    perform public.fail_tournament_media_upload_session(
      v_job.session_id, p_failure_code
    );
  end if;
  return jsonb_build_object(
    'jobId',p_job_id,'status',v_next,'attempts',v_job.attempts,
    'maxAttempts',v_job.max_attempts
  );
end;
$_$;


--
-- Name: fail_tournament_media_upload_session(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_tournament_media_upload_session(p_session_id uuid, p_failure_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_session public.tournament_media_upload_sessions%rowtype;
begin
  if p_failure_code is null or p_failure_code !~ '^[A-Z][A-Z0-9_]{2,80}$' then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_FAILURE_CODE_INVALID';
  end if;
  select * into v_session
  from public.tournament_media_upload_sessions
  where id = p_session_id for update;
  if v_session.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_UPLOAD_SESSION_INVALID';
  end if;
  if v_session.status <> 'issued' then
    return jsonb_build_object(
      'sessionId',p_session_id,'status',v_session.status,'changed',false
    );
  end if;
  update public.tournament_media_upload_sessions
  set status = 'failed' where id = p_session_id;
  insert into public.tournament_audit_log (
    organization_id, actor_user_id, actor_type, action, resource_type,
    resource_id, tournament_id, metadata
  ) values (
    v_session.organization_id, v_session.requested_by, 'system',
    'media.upload.failed', 'media_upload_session', p_session_id,
    v_session.tournament_id,
    jsonb_build_object('galleryId', v_session.gallery_id, 'failureCode', p_failure_code)
  );
  return jsonb_build_object(
    'sessionId',p_session_id,'status','failed','changed',true,
    'objectName',v_session.internal_path,'bucket',v_session.bucket
  );
end;
$_$;


--
-- Name: fail_tournament_player_portrait_upload(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_tournament_player_portrait_upload(p_actor_user_id uuid, p_portrait_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  UPDATE public.tournament_player_portraits portrait
  SET lifecycle_status = 'upload_failed', updated_at = now()
  WHERE portrait.id = p_portrait_id
    AND portrait.uploaded_by = p_actor_user_id
    AND portrait.lifecycle_status = 'upload_pending';
END;
$$;


--
-- Name: fail_tournament_team_photo_upload(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_tournament_team_photo_upload(p_actor_user_id uuid, p_team_photo_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  UPDATE public.tournament_team_photos photo
  SET lifecycle_status = 'upload_failed', updated_at = now()
  WHERE photo.id = p_team_photo_id
    AND photo.uploaded_by = p_actor_user_id
    AND photo.lifecycle_status = 'upload_pending';
END;
