--
-- Name: finalize_tournament_media_variants(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_tournament_media_variants(p_asset_id uuid, p_variants jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_asset public.tournament_media_assets%rowtype;
  v_kind text;
  v_entry jsonb;
  v_expected jsonb;
  v_extension text;
  v_ready integer;
begin
  perform public.tournament_media_require_pipeline_ready();
  if jsonb_typeof(coalesce(p_variants,'null'::jsonb)) <> 'object' then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_VARIANT_PAYLOAD_INVALID';
  end if;
  select * into v_asset
  from public.tournament_media_assets where id = p_asset_id;
  if v_asset.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_asset.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_asset.gallery_id::text,1)
  );
  select * into v_asset
  from public.tournament_media_assets where id = p_asset_id for update;
  if v_asset.status not in ('pending_review','processing') then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_TRANSITION_INVALID';
  end if;
  v_extension := case v_asset.detected_mime
    when 'image/jpeg' then 'jpg' when 'image/png' then 'png' else 'webp' end;

  foreach v_kind in array array['thumbnail','grid','detail'] loop
    v_entry := p_variants -> v_kind;
    v_expected := public.tournament_media_variant_geometry(
      v_kind, v_asset.width, v_asset.height
    );
    if v_entry is null or jsonb_typeof(v_entry) <> 'object' then
      raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_VARIANT_PAYLOAD_INVALID';
    end if;
    if coalesce(v_entry->>'detectedMime','') <> v_asset.detected_mime
      or coalesce((v_entry->>'width')::integer, -1) <> (v_expected->>'width')::integer
      or coalesce((v_entry->>'height')::integer, -1) <> (v_expected->>'height')::integer
      or coalesce((v_entry->>'byteSize')::bigint, 0) < 1
      or coalesce((v_entry->>'byteSize')::bigint, 0) > 12582912
      or coalesce(v_entry->>'checksumSha256','') !~ '^[0-9a-f]{64}$'
      or coalesce((v_entry->>'metadataStripped')::boolean, false) is not true
      -- The worker states, per object, that it re-encoded from decoded pixels
      -- and that the object passed the scanner. A payload without both is a
      -- browser rendition, and browser renditions are no longer publishable.
      or coalesce((v_entry->>'pixelTranscoded')::boolean, false) is not true
      or coalesce((v_entry->>'antivirusClean')::boolean, false) is not true
    then
      raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_VARIANT_PAYLOAD_INVALID';
    end if;
    update public.tournament_media_variants variant
    set byte_size = (v_entry->>'byteSize')::bigint,
        width = (v_expected->>'width')::integer,
        height = (v_expected->>'height')::integer,
        checksum_sha256 = v_entry->>'checksumSha256',
        detected_mime = v_asset.detected_mime,
        metadata_stripped = true,
        status = 'ready'
    where variant.asset_id = p_asset_id
      and variant.kind = v_kind
      and variant.status = 'processing'
      and variant.internal_path = regexp_replace(
        v_asset.internal_path, '\.(jpg|png|webp)$', '-' || v_kind || '.' || v_extension
      );
    if not found then
      raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_VARIANT_SLOT_INVALID';
    end if;
  end loop;

  select count(*) into v_ready
  from public.tournament_media_variants variant
  where variant.asset_id = p_asset_id
    and variant.kind in ('thumbnail','grid','detail','original')
    and variant.status = 'ready'
    and variant.metadata_stripped;
  if v_ready <> 4 then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_PROCESSING_REQUIRED';
  end if;

  insert into public.tournament_audit_log (
    organization_id, actor_user_id, actor_type, action, resource_type,
    resource_id, tournament_id, metadata
  ) values (
    v_asset.organization_id, v_asset.uploaded_by, 'system',
    'media.variants.ready', 'media_asset', p_asset_id, v_asset.tournament_id,
    jsonb_build_object('galleryId', v_asset.gallery_id, 'variants', 3)
  );
  return jsonb_build_object(
    'assetId',p_asset_id,'variantsReady',v_ready,'status',v_asset.status
  );
end;
$_$;


--
-- Name: finalize_tournament_player_portrait_upload(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_tournament_player_portrait_upload(p_actor_user_id uuid, p_portrait_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_portrait public.tournament_player_portraits%ROWTYPE;
  v_previous_id uuid;
BEGIN
  SELECT * INTO v_portrait
  FROM public.tournament_player_portraits portrait
  WHERE portrait.id = p_portrait_id
    AND portrait.lifecycle_status = 'upload_pending'
  FOR UPDATE;
  IF v_portrait.id IS NULL
    OR v_portrait.uploaded_by IS DISTINCT FROM p_actor_user_id
    OR NOT public.can_manage_tournament_player_portrait_as(
      v_portrait.organization_id, v_portrait.roster_player_id, p_actor_user_id
    )
  THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_PORTRAIT_FORBIDDEN';
  END IF;

  PERFORM 1 FROM public.tournament_roster_players player
  WHERE player.id = v_portrait.roster_player_id FOR UPDATE;

  SELECT portrait.id INTO v_previous_id
  FROM public.tournament_player_portraits portrait
  WHERE portrait.roster_player_id = v_portrait.roster_player_id
    AND portrait.lifecycle_status = 'active'
  FOR UPDATE;

  IF v_previous_id IS NOT NULL THEN
    UPDATE public.tournament_player_portraits
    SET lifecycle_status = 'replaced', replaced_by_id = v_portrait.id,
        replaced_at = now(), updated_at = now()
    WHERE id = v_previous_id;
  END IF;
  UPDATE public.tournament_player_portraits
  SET lifecycle_status = 'active', updated_at = now()
  WHERE id = v_portrait.id;

  INSERT INTO public.tournament_audit_log (
    organization_id, actor_user_id, actor_type, action, resource_type,
    resource_id, team_entry_id, tournament_id, metadata
  ) VALUES (
    v_portrait.organization_id, p_actor_user_id, 'user',
    CASE WHEN v_previous_id IS NULL THEN 'portrait.uploaded' ELSE 'portrait.replaced' END,
    'player_portrait', v_portrait.id, v_portrait.team_entry_id,
    v_portrait.tournament_id,
    jsonb_build_object('rosterPlayerId', v_portrait.roster_player_id,
      'replacedPortraitId', v_previous_id)
  );
  RETURN jsonb_build_object(
    'imageRef', jsonb_build_object(
      'kind', 'player_portrait', 'id', v_portrait.id, 'variant', 'original'
    ),
    'replacedPortraitId', v_previous_id
  );
END;
$$;


--
-- Name: finalize_tournament_team_photo_upload(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finalize_tournament_team_photo_upload(p_actor_user_id uuid, p_team_photo_id uuid, p_checksum_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_photo public.tournament_team_photos%ROWTYPE;
  v_previous_candidate_id uuid;
  v_current_id uuid;
BEGIN
  IF p_checksum_sha256 IS NULL OR p_checksum_sha256 !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TORNEOS_TEAM_PHOTO_CHECKSUM_INVALID';
  END IF;
  SELECT * INTO v_photo
  FROM public.tournament_team_photos photo
  WHERE photo.id = p_team_photo_id
    AND photo.lifecycle_status = 'upload_pending'
  FOR UPDATE;
  IF v_photo.id IS NULL
    OR v_photo.uploaded_by IS DISTINCT FROM p_actor_user_id
    OR NOT public.can_manage_tournament_team_visual_assets_as(
      v_photo.organization_id, v_photo.team_entry_id, p_actor_user_id,
      'team_entries.update'
    )
  THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_TEAM_PHOTO_FORBIDDEN';
  END IF;

  -- El equipo es el recurso que se serializa: dos cargas simultáneas del mismo
  -- equipo se ordenan acá y no en el índice único.
  PERFORM 1 FROM public.tournament_team_entries entry
  WHERE entry.id = v_photo.team_entry_id FOR UPDATE;

  SELECT photo.id INTO v_previous_candidate_id
  FROM public.tournament_team_photos photo
  WHERE photo.team_entry_id = v_photo.team_entry_id
    AND photo.lifecycle_status = 'active'
    AND photo.editorial_status IN ('pending_review', 'rejected')
  FOR UPDATE;

  IF v_previous_candidate_id IS NOT NULL THEN
    UPDATE public.tournament_team_photos
    SET lifecycle_status = 'replaced', replaced_by_id = v_photo.id,
        replaced_at = now(), updated_at = now()
    WHERE id = v_previous_candidate_id;
  END IF;

  SELECT photo.id INTO v_current_id
  FROM public.tournament_team_photos photo
  WHERE photo.team_entry_id = v_photo.team_entry_id
    AND photo.lifecycle_status = 'active'
    AND photo.editorial_status = 'approved';

  UPDATE public.tournament_team_photos
  SET lifecycle_status = 'active', checksum_sha256 = p_checksum_sha256,
      updated_at = now()
  WHERE id = v_photo.id;

  INSERT INTO public.tournament_audit_log (
    organization_id, actor_user_id, actor_type, action, resource_type,
    resource_id, team_entry_id, tournament_id, metadata
  ) VALUES (
    v_photo.organization_id, p_actor_user_id, 'user', 'team_photo.uploaded',
    'team_photo', v_photo.id, v_photo.team_entry_id, v_photo.tournament_id,
    jsonb_build_object(
      'replacedCandidateId', v_previous_candidate_id,
      'currentTeamPhotoId', v_current_id,
      'checksumSha256', p_checksum_sha256
    )
  );

  RETURN jsonb_build_object(
    'imageRef', jsonb_build_object(
      'kind', 'team_photo', 'id', v_photo.id, 'variant', 'original'
    ),
    'editorialStatus', 'pending_review',
    'replacedCandidateId', v_previous_candidate_id,
    -- Que la vigente siga siendo la vigente no es un detalle de implementación:
    -- es la promesa del producto, y viaja en la respuesta para que la pantalla
    -- lo pueda afirmar sin recalcularlo.
    'currentTeamPhotoId', v_current_id
  );
END;
$_$;


--
-- Name: finish_tournament_competition(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.finish_tournament_competition(p_organization_id uuid, p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tournament public.tournaments%rowtype;
  v_pending integer;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(
    p_organization_id, 'tournaments.finish'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:competition-lifecycle:' || p_tournament_id::text, 0
  ));

  select tournament.* into v_tournament
  from public.tournaments tournament
  join public.tournament_organizations organization
    on organization.id = tournament.organization_id
    and organization.status = 'active'
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
  for update of tournament;

  if v_tournament.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  if v_tournament.status = 'completed' then
    return jsonb_build_object(
      'id', v_tournament.id,
      'status', v_tournament.status,
      'completedAt', v_tournament.completed_at,
      'alreadyCompleted', true,
      'pendingCommitments', 0
    );
  end if;

  if v_tournament.status <> 'active' then
    raise exception using errcode = '22023',
      message = 'TORNEOS_INVALID_TOURNAMENT_TRANSITION';
  end if;

  select count(*) into v_pending
  from public.tournament_competition_open_commitments(
    p_organization_id, p_tournament_id
  );

  if v_pending > 0 then
    raise exception using errcode = '22023',
      message = 'TORNEOS_COMPETITION_HAS_PENDING_COMMITMENTS',
      detail = v_pending::text;
  end if;

  update public.tournaments
  set status = 'completed',
      completed_at = now()
  where id = p_tournament_id
  returning * into v_tournament;

  perform public.append_tournament_audit(
    p_organization_id, 'tournament.finished', 'tournament', v_tournament.id,
    null, v_tournament.id,
    jsonb_build_object(
      'previousStatus', 'active',
      'nextStatus', 'completed'
    )
  );

  return jsonb_build_object(
    'id', v_tournament.id,
    'status', v_tournament.status,
    'completedAt', v_tournament.completed_at,
    'alreadyCompleted', false,
    'pendingCommitments', 0
  );
end;
$$;


--
-- Name: FUNCTION finish_tournament_competition(p_organization_id uuid, p_tournament_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.finish_tournament_competition(p_organization_id uuid, p_tournament_id uuid) IS 'Finaliza la competencia. Si todavía quedan compromisos abiertos rechaza la operación como error del cliente e informa en el detalle cuántos partidos faltan resolver.';


--
-- Name: freeze_tournament_participants(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.freeze_tournament_participants(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_set public.tournament_participant_sets%rowtype;
  v_tournament public.tournaments%rowtype;
  v_count integer;
  v_fingerprint text;
  v_version integer;
  v_entry_ids uuid[];
begin
  perform public.assert_tournament_fixture_scope(
    p_organization_id, p_tournament_id, p_category_id,
    'participants.freeze', array['registration']::text[]
  );
  if p_idempotency_key is null then
    raise exception using errcode = '22023', message = 'TORNEOS_IDEMPOTENCY_REQUIRED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:participants:' || p_tournament_id::text || ':' || p_category_id::text,
    0
  ));
  select participant_set.* into v_set
  from public.tournament_participant_sets participant_set
  where participant_set.organization_id = p_organization_id
    and participant_set.frozen_by = private.current_identity_id()
    and participant_set.idempotency_key = p_idempotency_key;
  if v_set.id is not null then
    return jsonb_build_object(
      'participantSetId', v_set.id,
      'versionNumber', v_set.version_number,
      'status', v_set.status,
      'participantFingerprint', v_set.participant_fingerprint,
      'participantCount', (
        select count(*) from public.tournament_competition_participants participant
        where participant.participant_set_id = v_set.id
      )
    );
  end if;
  if exists (
    select 1 from public.tournament_participant_sets participant_set
    where participant_set.tournament_id = p_tournament_id
      and participant_set.category_id = p_category_id
      and participant_set.status = 'frozen'
  ) then
    raise exception using errcode = '23505', message = 'TORNEOS_PARTICIPANTS_ALREADY_FROZEN';
  end if;
  if exists (
    select 1
    from public.tournament_team_entries entry
    where entry.organization_id = p_organization_id
      and entry.tournament_id = p_tournament_id
      and entry.category_id = p_category_id
      and entry.status in ('submitted', 'changes_requested')
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_PENDING_REGISTRATIONS';
  end if;
  select array_agg(eligible.id order by eligible.id)
  into v_entry_ids
  from (
    select entry.id
    from public.tournament_team_entries entry
    where entry.organization_id = p_organization_id
      and entry.tournament_id = p_tournament_id
      and entry.category_id = p_category_id
      and entry.status = 'approved'
      and exists (
        select 1 from public.tournament_rosters roster
        where roster.team_entry_id = entry.id
          and roster.status in ('approved', 'locked')
      )
    order by entry.id
    for share of entry
  ) eligible;
  v_count := coalesce(array_length(v_entry_ids, 1), 0);
  v_fingerprint := encode(public.digest(
    array_to_string(v_entry_ids, '|'),
    'sha256'
  ), 'hex');
  if v_count < 2 then
    raise exception using errcode = '23514', message = 'TORNEOS_NOT_ENOUGH_PARTICIPANTS';
  end if;
  select tournament.* into v_tournament
  from public.tournaments tournament
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
  for update;
  select coalesce(max(participant_set.version_number), 0) + 1
  into v_version
  from public.tournament_participant_sets participant_set
  where participant_set.tournament_id = p_tournament_id
    and participant_set.category_id = p_category_id;
  update public.tournament_participant_sets
  set status = 'superseded', invalidated_at = coalesce(invalidated_at, now())
  where tournament_id = p_tournament_id
    and category_id = p_category_id
    and status = 'reopened';
  insert into public.tournament_participant_sets (
    organization_id, season_id, tournament_id, category_id, version_number,
    status, participant_fingerprint, frozen_by, idempotency_key
  ) values (
    p_organization_id, v_tournament.season_id, p_tournament_id, p_category_id,
    v_version, 'frozen', v_fingerprint, private.current_identity_id(), p_idempotency_key
  ) returning * into v_set;
  insert into public.tournament_competition_participants (
    organization_id, season_id, tournament_id, category_id, participant_set_id,
    team_entry_id, status, snapshot_name, snapshot_short_name,
    snapshot_shield_path, snapshot_primary_color, snapshot_secondary_color, frozen_at
  )
  select
    entry.organization_id, entry.season_id, entry.tournament_id, entry.category_id,
    v_set.id, entry.id, 'active', entry.name, entry.short_name, entry.shield_path,
    entry.primary_color, entry.secondary_color, v_set.frozen_at
  from public.tournament_team_entries entry
  where entry.id = any(v_entry_ids)
  order by entry.id;
  perform public.append_tournament_audit(
    p_organization_id, 'participants.frozen', 'participant_set', v_set.id,
    null, p_tournament_id,
    jsonb_build_object(
      'categoryId', p_category_id,
      'versionNumber', v_version,
      'participantCount', v_count,
      'participantFingerprint', v_fingerprint
    )
  );
  return jsonb_build_object(
    'participantSetId', v_set.id,
    'versionNumber', v_version,
    'status', 'frozen',
    'participantFingerprint', v_fingerprint,
    'participantCount', v_count,
    'frozenAt', v_set.frozen_at
  );
end;
$$;


--
-- Name: gen_random_bytes(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gen_random_bytes(p_length integer) RETURNS bytea
    LANGUAGE sql
    SET search_path TO ''
    AS $$ SELECT extensions.gen_random_bytes(p_length) $$;


--
-- Name: generate_tournament_fixture(uuid, uuid, uuid, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_tournament_fixture(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_seed text, p_configuration jsonb, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_set public.tournament_participant_sets%rowtype;
  v_tournament public.tournaments%rowtype;
  v_version public.tournament_fixture_versions%rowtype;
  v_version_number integer;
  v_phase_id uuid;
  v_knockout_phase_id uuid;
  v_participants uuid[];
  v_sources jsonb := '[]'::jsonb;
  v_group record;
  v_new_group_id uuid;
  v_group_participants uuid[];
  v_group_map jsonb := '{}'::jsonb;
  v_group_count integer;
  v_qualifiers integer;
  v_index integer;
  v_double boolean;
  v_knockout_double boolean;
  v_snapshot jsonb;
  v_effective_seed text;
  v_draw_seed text;
  v_distinct_draw_seeds integer;
begin
  perform public.assert_tournament_fixture_scope(
    p_organization_id, p_tournament_id, p_category_id,
    'fixture.generate', array['registration', 'scheduled']::text[]
  );
  if p_idempotency_key is null
    or jsonb_typeof(coalesce(p_configuration, '{}'::jsonb)) <> 'object'
    or coalesce((p_configuration->>'minimumRestMinutes')::integer, 720)
      not between 1 and 10080
    or coalesce((p_configuration->>'maximumConsecutiveHome')::integer, 3)
      not between 1 and 20
    or coalesce((p_configuration->>'maximumMatchesPerDay')::integer, 1)
      not between 1 and 10
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_FIXTURE_CONFIGURATION';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:fixture:' || p_tournament_id::text || ':' || p_category_id::text, 0
  ));
  select version.* into v_version
  from public.tournament_fixture_versions version
  where version.organization_id = p_organization_id
    and version.created_by = private.current_identity_id()
    and version.idempotency_key = p_idempotency_key;
  if v_version.id is not null then
    return jsonb_build_object(
      'fixtureVersionId', v_version.id,
      'versionNumber', v_version.version_number,
      'status', v_version.status
    );
  end if;
  select participant_set.* into v_set
  from public.tournament_participant_sets participant_set
  where participant_set.organization_id = p_organization_id
    and participant_set.tournament_id = p_tournament_id
    and participant_set.category_id = p_category_id
    and participant_set.status = 'frozen'
  for update;
  select tournament.* into v_tournament
  from public.tournaments tournament
  where tournament.organization_id = p_organization_id
    and tournament.id = p_tournament_id
  for update;
  if v_set.id is null or v_tournament.id is null then
    raise exception using errcode = '23514', message = 'TORNEOS_PARTICIPANTS_NOT_FROZEN';
  end if;
  select array_agg(participant.id order by participant.seed_number nulls last, participant.id)
  into v_participants
  from public.tournament_competition_participants participant
  where participant.participant_set_id = v_set.id and participant.status = 'active';
  if coalesce(array_length(v_participants, 1), 0) < 2 then
    raise exception using errcode = '23514', message = 'TORNEOS_NOT_ENOUGH_PARTICIPANTS';
  end if;
  v_effective_seed := nullif(btrim(coalesce(p_seed, '')), '');
  if v_tournament.competition_format in ('groups', 'groups_and_playoffs') then
    select
      min(nullif(btrim(group_row.draw_seed), '')),
      count(distinct nullif(btrim(group_row.draw_seed), ''))
    into v_draw_seed, v_distinct_draw_seeds
    from public.tournament_groups group_row
    where group_row.participant_set_id = v_set.id
      and group_row.fixture_version_id is null
      and group_row.status = 'published';
    if v_draw_seed is null or v_distinct_draw_seeds <> 1 then
      raise exception using errcode = '23514', message = 'TORNEOS_GROUP_DRAW_SEED_INVALID';
    end if;
    if v_effective_seed is not null and v_effective_seed <> v_draw_seed then
      raise exception using errcode = '23514', message = 'TORNEOS_GROUP_DRAW_SEED_MISMATCH';
    end if;
    v_effective_seed := v_draw_seed;
  end if;
  select coalesce(max(version.version_number), 0) + 1 into v_version_number
  from public.tournament_fixture_versions version
  where version.tournament_id = p_tournament_id and version.category_id = p_category_id;
  v_snapshot := jsonb_build_object(
    'competitionFormat', v_tournament.competition_format,
    'formatSettings', v_tournament.format_settings,
    'requestedConfiguration', coalesce(p_configuration, '{}'::jsonb),
    'minimumRestMinutes', coalesce((p_configuration->>'minimumRestMinutes')::integer, 720),
    'maximumConsecutiveHome', coalesce((p_configuration->>'maximumConsecutiveHome')::integer, 3),
    'maximumMatchesPerDay', coalesce((p_configuration->>'maximumMatchesPerDay')::integer, 1)
  );
  insert into public.tournament_fixture_versions (
    organization_id, season_id, tournament_id, category_id, participant_set_id,
    version_number, status, generation_method, seed, participant_fingerprint,
    configuration_snapshot, created_by, idempotency_key
  ) values (
    p_organization_id, v_set.season_id, p_tournament_id, p_category_id, v_set.id,
    v_version_number, 'draft',
    case when v_tournament.competition_format in ('groups', 'groups_and_playoffs')
      then 'draw' else 'automatic' end,
    v_effective_seed, v_set.participant_fingerprint,
    v_snapshot, private.current_identity_id(), p_idempotency_key
  ) returning * into v_version;

  if v_tournament.competition_format in ('league', 'league_and_playoffs') then
    insert into public.tournament_phases (
      organization_id, tournament_id, category_id, fixture_version_id,
      name, phase_type, sequence_number, status, configuration
    ) values (
      p_organization_id, p_tournament_id, p_category_id, v_version.id,
      'Liga', 'league', 1, 'generated', v_tournament.format_settings
    ) returning id into v_phase_id;
    v_double := coalesce(
      v_tournament.format_settings->>'rounds',
      v_tournament.format_settings->>'leagueRounds',
      'single'
    ) = 'double';
    perform public.build_tournament_round_robin(
      v_version.id, v_phase_id, null, v_participants, v_double
    );
  end if;

  if v_tournament.competition_format in ('groups', 'groups_and_playoffs') then
    select count(*) into v_group_count
    from public.tournament_groups group_row
    where group_row.participant_set_id = v_set.id
      and group_row.fixture_version_id is null
      and group_row.status = 'published';
    if v_group_count < 2 then
      raise exception using errcode = '23514', message = 'TORNEOS_GROUP_DRAW_REQUIRED';
    end if;
    insert into public.tournament_phases (
      organization_id, tournament_id, category_id, fixture_version_id,
      name, phase_type, sequence_number, status, configuration
    ) values (
      p_organization_id, p_tournament_id, p_category_id, v_version.id,
      'Fase de grupos', 'groups', 1, 'generated', v_tournament.format_settings
    ) returning id into v_phase_id;
    for v_group in
      select group_row.*
      from public.tournament_groups group_row
      where group_row.participant_set_id = v_set.id
        and group_row.fixture_version_id is null
        and group_row.status = 'published'
      order by group_row.sort_order, group_row.code
    loop
      insert into public.tournament_groups (
        organization_id, tournament_id, category_id, participant_set_id,
        fixture_version_id, phase_id, name, code, sort_order, status, draw_seed
      ) values (
        p_organization_id, p_tournament_id, p_category_id, v_set.id,
        v_version.id, v_phase_id, v_group.name, v_group.code, v_group.sort_order,
        'published', v_group.draw_seed
      ) returning id into v_new_group_id;
      insert into public.tournament_group_members (group_id, participant_id, position_seed)
      select v_new_group_id, member.participant_id, member.position_seed
      from public.tournament_group_members member
      where member.group_id = v_group.id
      order by member.position_seed nulls last, member.participant_id;
      v_group_map := v_group_map || jsonb_build_object(v_group.id::text, v_new_group_id);
      select array_agg(member.participant_id order by member.position_seed nulls last, member.participant_id)
      into v_group_participants
      from public.tournament_group_members member
      where member.group_id = v_group.id;
      v_double := coalesce(
        v_tournament.format_settings->>'rounds',
        v_tournament.format_settings->>'groupRounds',
        'single'
      ) = 'double';
      perform public.build_tournament_round_robin(
        v_version.id, v_phase_id, v_new_group_id, v_group_participants, v_double
      );
    end loop;
  end if;

  if v_tournament.competition_format = 'knockout' then
    for v_index in 1..array_length(v_participants, 1) loop
      v_sources := v_sources || jsonb_build_array(jsonb_build_object(
        'type', 'participant', 'participantId', v_participants[v_index]
      ));
    end loop;
    insert into public.tournament_phases (
      organization_id, tournament_id, category_id, fixture_version_id,
      name, phase_type, sequence_number, status, configuration
    ) values (
      p_organization_id, p_tournament_id, p_category_id, v_version.id,
      'Eliminación directa', 'custom_knockout', 1, 'generated', v_tournament.format_settings
    ) returning id into v_phase_id;
    perform public.build_tournament_knockout(
      v_version.id, v_phase_id, v_sources,
      coalesce(v_tournament.format_settings->>'legs', 'single') = 'double',
      coalesce((v_tournament.format_settings->>'thirdPlace')::boolean, false)
    );
  elsif v_tournament.competition_format = 'groups_and_playoffs' then
    v_sources := '[]'::jsonb;
    v_qualifiers := coalesce((v_tournament.format_settings->>'qualifiersPerGroup')::integer, 2);
    if v_qualifiers < 1 or exists (
      select 1
      from public.tournament_groups group_row
      where group_row.fixture_version_id = v_version.id
        and (
          select count(*)
          from public.tournament_group_members member
          where member.group_id = group_row.id
        ) < v_qualifiers
    ) then
      raise exception using errcode = '23514', message = 'TORNEOS_INVALID_QUALIFIERS';
    end if;
    for v_group in
      select group_row.id
      from public.tournament_groups group_row
      where group_row.fixture_version_id = v_version.id
      order by group_row.sort_order, group_row.code
    loop
      for v_index in 1..v_qualifiers loop
        v_sources := v_sources || jsonb_build_array(jsonb_build_object(
          'type', 'group_position', 'groupId', v_group.id, 'positionNumber', v_index
        ));
      end loop;
    end loop;
    insert into public.tournament_phases (
      organization_id, tournament_id, category_id, fixture_version_id,
      name, phase_type, sequence_number, status, configuration
    ) values (
      p_organization_id, p_tournament_id, p_category_id, v_version.id,
      'Playoffs', 'custom_knockout', 2, 'generated', v_tournament.format_settings
    ) returning id into v_knockout_phase_id;
    perform public.build_tournament_knockout(
      v_version.id, v_knockout_phase_id, v_sources,
      coalesce(v_tournament.format_settings->>'knockoutLegs', 'single') = 'double',
      false
    );
  elsif v_tournament.competition_format = 'league_and_playoffs' then
    v_sources := '[]'::jsonb;
    v_qualifiers := coalesce((v_tournament.format_settings->>'qualifiers')::integer, 4);
    if v_qualifiers < 2 or v_qualifiers > array_length(v_participants, 1) then
      raise exception using errcode = '23514', message = 'TORNEOS_INVALID_QUALIFIERS';
    end if;
    for v_index in 1..v_qualifiers loop
      v_sources := v_sources || jsonb_build_array(jsonb_build_object(
        'type', 'league_position', 'phaseId', v_phase_id, 'rankNumber', v_index
      ));
    end loop;
    insert into public.tournament_phases (
      organization_id, tournament_id, category_id, fixture_version_id,
      name, phase_type, sequence_number, status, configuration
    ) values (
      p_organization_id, p_tournament_id, p_category_id, v_version.id,
      'Playoffs', 'custom_knockout', 2, 'generated', v_tournament.format_settings
    ) returning id into v_knockout_phase_id;
    perform public.build_tournament_knockout(
      v_version.id, v_knockout_phase_id, v_sources,
      coalesce(v_tournament.format_settings->>'knockoutLegs', 'single') = 'double',
      false
    );
  end if;
  perform public.append_tournament_audit(
    p_organization_id, 'fixture.generated', 'fixture_version', v_version.id,
    null, p_tournament_id,
    jsonb_build_object(
      'categoryId', p_category_id,
      'versionNumber', v_version_number,
      'method', v_version.generation_method,
      'seed', v_version.seed,
      'participantFingerprint', v_set.participant_fingerprint,
      'matchCount', (
        select count(*) from public.tournament_matches match_row
        where match_row.fixture_version_id = v_version.id
      )
    )
  );
  return jsonb_build_object(
    'fixtureVersionId', v_version.id,
    'versionNumber', v_version_number,
    'status', 'draft',
    'phaseCount', (
      select count(*) from public.tournament_phases phase
      where phase.fixture_version_id = v_version.id
    ),
    'roundCount', (
      select count(*) from public.tournament_rounds round_row
      where round_row.fixture_version_id = v_version.id
    ),
    'matchCount', (
      select count(*) from public.tournament_matches match_row
      where match_row.fixture_version_id = v_version.id
    )
  );
end;
$$;


--
-- Name: get_effective_tournament_entitlements(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_effective_tournament_entitlements(p_organization_id uuid, p_tournament_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_season_id uuid; v_result jsonb; v_usage integer;
begin
  if private.current_identity_id() is null or p_tournament_id is null then
    raise exception using errcode='42501',message='TORNEOS_ENTITLEMENTS_FORBIDDEN';
  end if;
  select season_id into v_season_id from public.tournaments
  where organization_id=p_organization_id and id=p_tournament_id;
  if v_season_id is null or not public.has_tournament_season_access(p_organization_id,v_season_id) then
    raise exception using errcode='42501',message='TORNEOS_ENTITLEMENTS_FORBIDDEN';
  end if;
  v_result := public.resolve_effective_tournament_season_entitlements_at(
    p_organization_id,v_season_id,now(),false,p_tournament_id
  );
  select count(*)::integer into v_usage from public.tournament_season_member_assignments
  where organization_id=p_organization_id and season_id=v_season_id;
  return jsonb_set(v_result,'{administration,currentAdministrativeSeatUsage}',to_jsonb(v_usage),true);
end;
$$;


--
-- Name: get_effective_tournament_season_entitlements(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_effective_tournament_season_entitlements(p_organization_id uuid, p_season_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_result jsonb; v_usage integer;
begin
  if private.current_identity_id() is null then raise exception using errcode='42501',message='TORNEOS_AUTH_REQUIRED'; end if;
  if not public.has_tournament_season_access(p_organization_id,p_season_id) then
    raise exception using errcode='42501',message='TORNEOS_ENTITLEMENTS_FORBIDDEN';
  end if;
  v_result := public.resolve_effective_tournament_season_entitlements_at(
    p_organization_id,p_season_id,now(),false,null
  );
  select count(*)::integer into v_usage
  from public.tournament_season_member_assignments
  where organization_id=p_organization_id and season_id=p_season_id;
  return jsonb_set(v_result,'{administration,currentAdministrativeSeatUsage}',to_jsonb(v_usage),true);
end;
$$;


--
-- Name: get_managed_tournament_matches(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_managed_tournament_matches() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'matchId', match_row.id,
    'organizationId', match_row.organization_id,
    'tournamentId', match_row.tournament_id,
    'categoryId', match_row.category_id,
    'teamEntryId', manager.team_entry_id,
    'teamName', own_entry.name,
    'opponentName', opponent_entry.name,
    'isHome', manager.team_entry_id = teams.home_team_entry_id,
    'scheduledAt', match_row.scheduled_at,
    'status', match_row.status,
    'venue', venue.name,
    'court', court.name,
    'squadStatus', squad.status,
    'canManageSquad', manager.role in ('captain', 'delegate'),
    'officialScore', case when operation.status = 'official'
      then jsonb_build_object('home', score.home_score, 'away', score.away_score)
      else null end
  ) order by match_row.scheduled_at nulls last), '[]'::jsonb)
  from public.tournament_team_managers manager
  join public.tournament_competition_participants own_participant
    on own_participant.team_entry_id = manager.team_entry_id
    and own_participant.status = 'active'
  join public.tournament_matches match_row
    on own_participant.id in (match_row.home_participant_id, match_row.away_participant_id)
  join public.tournament_fixture_versions fixture
    on fixture.id = match_row.fixture_version_id and fixture.status = 'published'
  cross join lateral public.tournament_match_team_entries(match_row.id) teams
  join public.tournament_team_entries own_entry on own_entry.id = manager.team_entry_id
  join public.tournament_team_entries opponent_entry
    on opponent_entry.id = case
      when manager.team_entry_id = teams.home_team_entry_id then teams.away_team_entry_id
      else teams.home_team_entry_id end
  left join public.tournament_venues venue on venue.id = match_row.venue_id
  left join public.tournament_courts court on court.id = match_row.court_id
  left join public.tournament_match_squads squad
    on squad.match_id = match_row.id and squad.team_entry_id = manager.team_entry_id
    and squad.status <> 'superseded'
  left join public.tournament_match_operations operation
    on operation.match_id = match_row.id and operation.status = 'official'
  left join public.tournament_match_scores score
    on score.match_operation_id = operation.id
  where private.current_identity_id() is not null
    and manager.user_id = private.current_identity_id()
    and manager.status = 'active'
    and manager.role in ('captain', 'delegate')
    and match_row.status in ('scheduled', 'ready', 'postponed', 'cancelled');
$$;


--
-- Name: get_match_squad_context(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_match_squad_context(p_organization_id uuid, p_match_id uuid, p_team_entry_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when not (
      public.has_tournament_organization_capability(
        p_organization_id, 'match_squads.read'
      )
      or public.can_manage_tournament_match_squad(
        p_organization_id, p_match_id, p_team_entry_id
      )
    )
      then public.raise_tournament_match_error('TORNEOS_MATCH_FORBIDDEN')
    else jsonb_build_object(
      'matchId', match_row.id,
      'teamEntryId', p_team_entry_id,
      'teamName', entry.name,
      'status', match_row.status,
      'teamSize', coalesce(category.team_size, tournament.team_size),
      'substitutesLimit', coalesce(tournament.substitutes_limit, tournament.team_size),
      'squad', (
        select jsonb_build_object(
          'id', squad.id,
          'status', squad.status,
          'submittedAt', squad.submitted_at,
          'lockedAt', squad.locked_at
        ) from public.tournament_match_squads squad
        where squad.match_id = match_row.id
          and squad.team_entry_id = p_team_entry_id
          and squad.status <> 'superseded'
      ),
      'players', coalesce((
        select jsonb_agg(jsonb_build_object(
          'rosterPlayerId', player.id,
          'displayName', player.display_name,
          'avatarUrl', player.avatar_url,
          'shirtNumber', player.shirt_number,
          'position', player.primary_position,
          'isGoalkeeper', player.is_goalkeeper,
          'eligibilityStatus', player.eligibility_status,
          'availability', availability.response,
          'selection', case when selection.id is null then null else jsonb_build_object(
            'callup_status', selection.callup_status,
            'lineup_status', selection.lineup_status,
            'is_goalkeeper', selection.is_goalkeeper,
            'is_captain', selection.is_captain,
            'attendance_status', selection.attendance_status
          ) end
        ) order by player.display_name)
        from public.tournament_roster_players player
        join public.tournament_rosters roster
          on roster.id = player.roster_id and roster.status in ('approved', 'locked')
        left join public.tournament_match_availability_responses availability
          on availability.match_id = match_row.id and availability.roster_player_id = player.id
        left join public.tournament_match_squads squad
          on squad.match_id = match_row.id and squad.team_entry_id = p_team_entry_id
          and squad.status <> 'superseded'
        left join public.tournament_match_squad_players selection
          on selection.match_squad_id = squad.id and selection.roster_player_id = player.id
        where player.team_entry_id = p_team_entry_id and player.status = 'active'
      ), '[]'::jsonb)
    )
  end
  from public.tournament_matches match_row
  join public.tournament_categories category on category.id = match_row.category_id
  join public.tournaments tournament on tournament.id = match_row.tournament_id
  join public.tournament_team_entries entry on entry.id = p_team_entry_id
  cross join lateral public.tournament_match_team_entries(match_row.id) teams
  where match_row.id = p_match_id and match_row.organization_id = p_organization_id
    and p_team_entry_id in (teams.home_team_entry_id, teams.away_team_entry_id);
$$;


--
-- Name: get_my_current_tournament_roster_players(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_current_tournament_roster_players() RETURNS TABLE(roster_player_id uuid, team_entry_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select player.id, player.team_entry_id
  from public.tournament_roster_players player
  join public.tournament_rosters roster
    on roster.id = player.roster_id
   and roster.organization_id = player.organization_id
   and roster.team_entry_id = player.team_entry_id
   and roster.status in ('approved', 'locked')
  where player.arma2_user_id = private.current_identity_id()
    and player.status = 'active'
  union all
  select player.id, player.team_entry_id
  from public.tournament_provisional_players provisional
  join public.tournament_roster_players player
    on player.organization_id = provisional.organization_id
   and player.provisional_player_id = provisional.id
   and player.status = 'active'
  join public.tournament_rosters roster
    on roster.id = player.roster_id
   and roster.organization_id = player.organization_id
   and roster.team_entry_id = player.team_entry_id
   and roster.status in ('approved', 'locked')
  where provisional.claimed_by_user_id = private.current_identity_id()
    and provisional.claim_status = 'claimed';
$$;


--
-- Name: get_my_managed_match_squad_context(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_managed_match_squad_context(p_match_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.get_match_squad_context(
    match_row.organization_id,
    match_row.id,
    manager.team_entry_id
  ) || jsonb_build_object(
    'organizationId', match_row.organization_id,
    'tournamentId', match_row.tournament_id,
    'homeName', home_entry.name,
    'awayName', away_entry.name,
    'scheduledAt', match_row.scheduled_at,
    'venue', venue.name,
    'court', court.name
  )
  from public.tournament_matches match_row
  cross join lateral public.tournament_match_team_entries(match_row.id) teams
  join public.tournament_team_managers manager
    on manager.team_entry_id in (teams.home_team_entry_id, teams.away_team_entry_id)
    and manager.user_id = private.current_identity_id()
    and manager.status = 'active'
    and manager.role in ('captain', 'delegate')
  join public.tournament_team_entries home_entry
    on home_entry.id = teams.home_team_entry_id
  join public.tournament_team_entries away_entry
    on away_entry.id = teams.away_team_entry_id
  left join public.tournament_venues venue on venue.id = match_row.venue_id
  left join public.tournament_courts court on court.id = match_row.court_id
  where private.current_identity_id() is not null and match_row.id = p_match_id
  limit 1;
$$;


--
-- Name: get_my_tournament_memberships(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_tournament_memberships(p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 20), 1), 50);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_result jsonb;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;

  with authorized_relations as (
    select
      tournament.organization_id,
      tournament.id tournament_id,
      category.id category_id,
      membership.role organization_role
    from public.tournaments tournament
    join public.tournament_organizations organization
      on organization.id = tournament.organization_id
     and organization.status = 'active'
    join public.tournament_categories category
      on category.organization_id = tournament.organization_id
     and category.tournament_id = tournament.id
     and category.status = 'active'
    join public.tournament_organization_members membership
      on membership.organization_id = tournament.organization_id
     and membership.user_id = private.current_identity_id()
     and membership.status = 'active'
    union all
    select
      entry.organization_id,
      entry.tournament_id,
      entry.category_id,
      null::text
    from public.tournament_team_entries entry
    join public.tournament_team_managers manager
      on manager.organization_id = entry.organization_id
     and manager.team_entry_id = entry.id
     and manager.user_id = private.current_identity_id()
     and manager.status = 'active'
     and manager.role in ('captain', 'delegate')
    join public.tournament_organizations organization
      on organization.id = entry.organization_id
     and organization.status = 'active'
    where entry.status = 'approved'
    union all
    select
      entry.organization_id,
      entry.tournament_id,
      entry.category_id,
      null::text
    from public.tournament_team_entries entry
    join public.get_my_current_tournament_roster_players() player
      on player.team_entry_id = entry.id
    join public.tournament_organizations organization
      on organization.id = entry.organization_id
     and organization.status = 'active'
    where entry.status = 'approved'
  ),
  authorized_categories as (
    select
      relation.organization_id,
      relation.tournament_id,
      relation.category_id,
      max(relation.organization_role) organization_role
    from authorized_relations relation
    group by
      relation.organization_id,
      relation.tournament_id,
      relation.category_id
  ),
  scoped as (
    select
      access.organization_id,
      access.tournament_id,
      access.category_id,
      organization.name organization_name,
      organization.logo_path organization_logo_path,
      tournament.name tournament_name,
      tournament.status tournament_status,
      tournament.start_date,
      tournament.end_date,
      season.name season_name,
      season.status season_status,
      category.name category_name,
      coalesce(
        access.organization_role,
        membership.role
      ) organization_role,
      own_team.team_entry_id,
      own_team.team_name,
      own_team.team_short_name,
      own_team.team_shield_path,
      own_team.primary_color,
      own_team.manager_role,
      own_team.roster_player_id,
      case
        when own_team.manager_role is not null then own_team.manager_role
        when own_team.roster_player_id is not null then 'player'
        else coalesce(access.organization_role, membership.role)
      end relation_role,
      fixture.id fixture_version_id
    from authorized_categories access
    join public.tournament_organizations organization
      on organization.id = access.organization_id
    join public.tournaments tournament
      on tournament.organization_id = access.organization_id
     and tournament.id = access.tournament_id
    join public.tournament_seasons season
      on season.organization_id = tournament.organization_id
     and season.id = tournament.season_id
    join public.tournament_categories category
      on category.organization_id = access.organization_id
     and category.tournament_id = access.tournament_id
     and category.id = access.category_id
    left join public.tournament_organization_members membership
      on membership.organization_id = access.organization_id
     and membership.user_id = private.current_identity_id()
     and membership.status = 'active'
    left join lateral (
      select
        entry.id team_entry_id,
        entry.name team_name,
        entry.short_name team_short_name,
        entry.shield_path team_shield_path,
        entry.primary_color,
        manager.role manager_role,
        player.roster_player_id
      from public.tournament_team_entries entry
      left join public.tournament_team_managers manager
        on manager.organization_id = entry.organization_id
       and manager.team_entry_id = entry.id
       and manager.user_id = private.current_identity_id()
       and manager.status = 'active'
       and manager.role in ('captain', 'delegate')
      left join public.get_my_current_tournament_roster_players() player
        on player.team_entry_id = entry.id
      where entry.organization_id = access.organization_id
        and entry.tournament_id = access.tournament_id
        and entry.category_id = access.category_id
        and entry.status = 'approved'
        and (
          manager.id is not null
          or player.roster_player_id is not null
        )
      order by
        (player.roster_player_id is not null) desc,
        (manager.id is not null) desc,
        entry.name
      limit 1
    ) own_team on true
    left join public.tournament_fixture_versions fixture
      on fixture.organization_id = access.organization_id
     and fixture.tournament_id = access.tournament_id
     and fixture.category_id = access.category_id
     and fixture.status = 'published'
  ),
  enriched as (
    select
      scoped.*,
      upcoming.match_payload next_match,
      standing.position
    from scoped
    left join lateral (
      select jsonb_build_object(
        'matchId', match_row.id,
        'scheduledAt', match_row.scheduled_at,
        'status', match_row.status,
        'roundName', round_row.name,
        'homeName', home.snapshot_name,
        'awayName', away.snapshot_name,
        'isMyTeam', scoped.team_entry_id is not null and (
          home.team_entry_id = scoped.team_entry_id
          or away.team_entry_id = scoped.team_entry_id
        )
      ) match_payload
      from public.tournament_matches match_row
      join public.tournament_rounds round_row on round_row.id = match_row.round_id
      left join public.tournament_competition_participants home
        on home.id = match_row.home_participant_id
      left join public.tournament_competition_participants away
        on away.id = match_row.away_participant_id
      where match_row.fixture_version_id = scoped.fixture_version_id
        and match_row.status in ('scheduled', 'ready', 'postponed')
        and (
          scoped.team_entry_id is null
          or home.team_entry_id = scoped.team_entry_id
          or away.team_entry_id = scoped.team_entry_id
        )
        and (match_row.scheduled_at is null or match_row.scheduled_at >= now())
      order by match_row.scheduled_at nulls last, match_row.match_number
      limit 1
    ) upcoming on true
    left join lateral (
      select standings.position
      from public.tournament_standings_revisions revision
      join public.tournament_phases phase on phase.id = revision.phase_id
      join public.tournament_team_standings standings
        on standings.revision_id = revision.id
       and standings.team_entry_id = scoped.team_entry_id
      where revision.fixture_version_id = scoped.fixture_version_id
        and revision.status = 'published'
      order by phase.sequence_number desc, revision.group_id nulls first,
        revision.revision_number desc
      limit 1
    ) standing on true
  ),
  ordered as (
    select enriched.*,
      count(*) over () total_count
    from enriched
    order by
      case enriched.tournament_status
        when 'active' then 0
        when 'scheduled' then 1
        when 'registration' then 2
        when 'completed' then 3
        when 'archived' then 4
        else 5
      end,
      enriched.start_date desc nulls last,
      enriched.tournament_name,
      enriched.category_name
    limit v_limit offset v_offset
  )
  select jsonb_build_object(
    'items',
    coalesce(jsonb_agg(jsonb_build_object(
      'organizationId', organization_id,
      'organizationName', organization_name,
      'logoPath', organization_logo_path,
      'tournamentId', tournament_id,
      'tournamentName', tournament_name,
      'tournamentStatus', tournament_status,
      'seasonName', season_name,
      'seasonStatus', season_status,
      'categoryId', category_id,
      'categoryName', category_name,
      'teamEntryId', team_entry_id,
      'teamName', team_name,
      'teamShortName', team_short_name,
      'teamShieldPath', team_shield_path,
      'primaryColor', primary_color,
      'role', relation_role,
      'organizationRole', organization_role,
      'position', position,
      'nextMatch', next_match,
      'hasPublishedFixture', fixture_version_id is not null,
      'readOnly', tournament_status in ('completed', 'archived')
    ) order by
      case tournament_status
        when 'active' then 0
        when 'scheduled' then 1
        when 'registration' then 2
        when 'completed' then 3
        when 'archived' then 4
        else 5
      end,
      start_date desc nulls last,
      tournament_name,
      category_name), '[]'::jsonb),
    'pagination', jsonb_build_object(
      'limit', v_limit,
      'offset', v_offset,
      'total', coalesce(max(total_count), 0),
      'hasMore', v_offset + count(*) < coalesce(max(total_count), 0)
    )
  )
  into v_result
  from ordered;

  return coalesce(v_result, jsonb_build_object(
    'items', '[]'::jsonb,
    'pagination', jsonb_build_object(
      'limit', v_limit,
      'offset', v_offset,
      'total', 0,
      'hasMore', false
    )
  ));
end;
$$;


--
-- Name: get_my_tournament_notification_preferences(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_my_tournament_notification_preferences(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tournament public.tournaments%rowtype;
  v_preference public.tournament_notification_preferences%rowtype;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.can_access_tournament_communications(p_tournament_id) then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  select * into v_tournament from public.tournaments where id = p_tournament_id;
  select * into v_preference
  from public.tournament_notification_preferences preference
  where preference.tournament_id = p_tournament_id
    and preference.user_id = private.current_identity_id();
  return jsonb_build_object(
    'tournamentId',p_tournament_id,
    'general',coalesce(v_preference.general_enabled,true),
    'matchChanges',coalesce(v_preference.match_changes_enabled,true),
    'callups',coalesce(v_preference.callups_enabled,true),
    'discipline',coalesce(v_preference.discipline_enabled,true),
    'documents',coalesce(v_preference.documents_enabled,true),
    'summaries',coalesce(v_preference.summaries_enabled,true),
    'mandatoryInbox',jsonb_build_array('own_match_urgent','own_discipline','required_document'),
    'channels',jsonb_build_object('internal',true,'push',false,'email',false)
  );
end;
$$;


--
-- Name: get_player_tournament_matches(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_player_tournament_matches() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(jsonb_build_object(
    'matchId', match_row.id,
    'organizationId', match_row.organization_id,
    'tournamentId', match_row.tournament_id,
    'categoryId', match_row.category_id,
    'teamEntryId', player.team_entry_id,
    'teamName', own_entry.name,
    'opponentName', opponent_entry.name,
    'isHome', player.team_entry_id = teams.home_team_entry_id,
    'scheduledAt', match_row.scheduled_at,
    'status', match_row.status,
    'venue', venue.name,
    'court', court.name,
    'availability', availability.response,
    'callupStatus', squad_player.callup_status,
    'lineupStatus', squad_player.lineup_status,
    'squadStatus', squad.status,
    'officialScore', case when operation.status = 'official'
      then jsonb_build_object('home', score.home_score, 'away', score.away_score)
      else null end
  ) order by match_row.scheduled_at nulls last), '[]'::jsonb)
  from public.tournament_roster_players player
  join public.tournament_rosters roster
    on roster.id = player.roster_id and roster.status in ('approved', 'locked')
  join public.tournament_competition_participants own_participant
    on own_participant.team_entry_id = player.team_entry_id
    and own_participant.status = 'active'
  join public.tournament_matches match_row
    on own_participant.id in (match_row.home_participant_id, match_row.away_participant_id)
  join public.tournament_fixture_versions fixture
    on fixture.id = match_row.fixture_version_id and fixture.status = 'published'
  cross join lateral public.tournament_match_team_entries(match_row.id) teams
  join public.tournament_team_entries own_entry on own_entry.id = player.team_entry_id
  join public.tournament_team_entries opponent_entry
    on opponent_entry.id = case
      when player.team_entry_id = teams.home_team_entry_id then teams.away_team_entry_id
      else teams.home_team_entry_id end
  left join public.tournament_venues venue on venue.id = match_row.venue_id
  left join public.tournament_courts court on court.id = match_row.court_id
  left join public.tournament_match_availability_responses availability
    on availability.match_id = match_row.id
    and availability.roster_player_id = player.id
  left join public.tournament_match_squads squad
    on squad.match_id = match_row.id and squad.team_entry_id = player.team_entry_id
    and squad.status <> 'superseded'
  left join public.tournament_match_squad_players squad_player
    on squad_player.match_squad_id = squad.id and squad_player.roster_player_id = player.id
  left join public.tournament_match_operations operation
    on operation.match_id = match_row.id and operation.status = 'official'
  left join public.tournament_match_scores score
    on score.match_operation_id = operation.id
  where private.current_identity_id() is not null
    and player.arma2_user_id = private.current_identity_id()
    and player.status = 'active'
    and player.eligibility_status = 'eligible'
    and match_row.status in ('scheduled', 'ready', 'postponed', 'cancelled');
$$;


--
-- Name: get_player_tournament_statistics(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_player_tournament_statistics(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'revisionId', stats.revision_id, 'rosterPlayerId', stats.roster_player_id,
      'teamEntryId', stats.team_entry_id, 'goals', stats.goals,
      'assists', stats.assists, 'appearances', stats.appearances,
      'starts', stats.starts, 'yellowCards', stats.yellow_cards,
      'secondYellows', stats.second_yellows, 'redCards', stats.red_cards
    ) order by revision.published_at desc)
    from public.tournament_player_statistics stats
    join public.tournament_roster_players player
      on player.id = stats.roster_player_id
      and player.arma2_user_id = private.current_identity_id()
      and player.status = 'active'
    join public.tournament_standings_revisions revision
      on revision.id = stats.revision_id and revision.status = 'published'
    where stats.tournament_id = p_tournament_id
      and public.can_read_tournament_projection_scope(
        revision.organization_id, revision.tournament_id
      )
  ), '[]'::jsonb);
end;
$$;


--
-- Name: get_player_tournament_suspensions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_player_tournament_suspensions(p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', suspension.id, 'teamEntryId', suspension.team_entry_id,
      'sourceType', suspension.source_type, 'reason', suspension.reason,
      'totalMatches', suspension.total_matches,
      'servedMatches', suspension.served_matches, 'status', suspension.status,
      'servedIn', coalesce((
        select jsonb_agg(served.match_id order by served.marked_at)
        from public.tournament_suspension_served_matches served
        where served.suspension_id = suspension.id
      ), '[]'::jsonb)
    ) order by suspension.created_at desc)
    from public.tournament_player_suspensions suspension
    join public.tournament_roster_players player
      on player.id = suspension.roster_player_id
      and player.arma2_user_id = private.current_identity_id()
      and player.status = 'active'
    join public.tournament_standings_revisions revision
      on revision.id = suspension.revision_id and revision.status = 'published'
    where suspension.tournament_id = p_tournament_id
      and suspension.status <> 'superseded'
      and public.can_read_tournament_projection_scope(
        revision.organization_id, revision.tournament_id
      )
  ), '[]'::jsonb);
end;
$$;


--
-- Name: get_public_tournament_branding(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_tournament_branding(p_public_slug text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_result jsonb;
BEGIN
  IF p_public_slug IS NULL
    OR char_length(p_public_slug) NOT BETWEEN 3 AND 96
    OR p_public_slug !~ '^[a-z0-9](?:[a-z0-9-]{1,94}[a-z0-9])$'
  THEN
    RETURN NULL;
  END IF;

  SELECT jsonb_build_object(
    'organization', jsonb_build_object(
      'id', organization.id,
      'name', organization.name,
      'logoPath', organization.logo_path
    ),
    'tournament', jsonb_build_object(
      'id', tournament.id,
      'name', tournament.name,
      'logoPath', tournament.logo_path
    )
  )
  INTO v_result
  FROM public.tournament_public_pages page
  JOIN public.tournaments tournament
    ON tournament.id = page.tournament_id
   AND tournament.organization_id = page.organization_id
   AND tournament.status IN ('registration', 'scheduled', 'active', 'completed')
  JOIN public.tournament_organizations organization
    ON organization.id = page.organization_id
   AND organization.status = 'active'
  JOIN public.tournament_seasons season
    ON season.id = tournament.season_id
   AND season.organization_id = tournament.organization_id
   AND season.status <> 'archived'
  WHERE page.public_slug = p_public_slug
    AND page.status = 'published';

  RETURN v_result;
END;
$_$;


--
-- Name: get_public_tournament_commercial_catalog(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_tournament_commercial_catalog(p_version integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_result jsonb;
begin
  if p_version <> 1 then
    raise exception using errcode = '22023', message = 'TORNEOS_CATALOG_VERSION_UNSUPPORTED';
  end if;
  select jsonb_build_object(
    'schemaVersion',1,
    'productCode',product.product_code,
    'productName',product.product_name,
    'scope',product.scope,
    'billingModel',product.billing_model,
    'currency',offer.currency,
    'listPrice',offer.list_amount,
    'effectivePrice',offer.amount,
    'offerCode',offer.offer_code,
    'offerVersion',offer.offer_version,
    'offerLabel',offer.offer_label,
    'offerValidUntil',offer.valid_until,
    'availability',offer.availability,
    'capabilities',product.public_capabilities
  ) into v_result
  from public.tournament_commercial_products product
  join lateral (
    select candidate.*
    from public.tournament_commercial_offers candidate
    where candidate.product_code = product.product_code
      and candidate.valid_from <= statement_timestamp()
      and (candidate.valid_until is null or candidate.valid_until > statement_timestamp())
    order by (candidate.availability = 'available') desc,
      candidate.valid_from desc,candidate.offer_version desc
    limit 1
  ) offer on true
  where product.product_code = 'torneos_premium' and product.status = 'active';
  return v_result;
end;
$$;


--
-- Name: get_public_tournament_page(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_public_tournament_page(p_public_slug text, p_category_slug text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_page public.tournament_public_pages%ROWTYPE;
  v_organization public.tournament_organizations%ROWTYPE;
  v_season public.tournament_seasons%ROWTYPE;
  v_tournament public.tournaments%ROWTYPE;
  v_category public.tournament_categories%ROWTYPE;
  v_fixture public.tournament_fixture_versions%ROWTYPE;
  v_categories jsonb := '[]'::jsonb;
  v_matches jsonb := '[]'::jsonb;
  v_teams jsonb := '[]'::jsonb;
  v_competition jsonb := '[]'::jsonb;
BEGIN
  IF p_public_slug IS NULL
    OR char_length(p_public_slug) NOT BETWEEN 3 AND 96
    OR p_public_slug !~ '^[a-z0-9](?:[a-z0-9-]{1,94}[a-z0-9])$'
    OR (
      p_category_slug IS NOT NULL
      AND (
        char_length(p_category_slug) NOT BETWEEN 2 AND 48
        OR p_category_slug !~ '^[a-z0-9](?:[a-z0-9-]{0,46}[a-z0-9])$'
      )
    )
  THEN
    RETURN NULL;
  END IF;

  SELECT page.*
  INTO v_page
  FROM public.tournament_public_pages page
  WHERE page.public_slug = p_public_slug
    AND page.status = 'published';
  IF v_page.tournament_id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT tournament.*
  INTO v_tournament
  FROM public.tournaments tournament
  WHERE tournament.id = v_page.tournament_id
    AND tournament.organization_id = v_page.organization_id
    AND tournament.status IN ('registration', 'scheduled', 'active', 'completed');
  IF v_tournament.id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT organization.*
  INTO v_organization
  FROM public.tournament_organizations organization
  WHERE organization.id = v_page.organization_id
    AND organization.status = 'active';
  SELECT season.*
  INTO v_season
  FROM public.tournament_seasons season
  WHERE season.id = v_tournament.season_id
    AND season.organization_id = v_page.organization_id
    AND season.status <> 'archived';
  IF v_organization.id IS NULL OR v_season.id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT category.*
  INTO v_category
  FROM public.tournament_categories category
  WHERE category.tournament_id = v_tournament.id
    AND category.organization_id = v_page.organization_id
    AND category.status = 'active'
    AND (p_category_slug IS NULL OR category.slug = p_category_slug)
  ORDER BY category.sort_order, category.name
  LIMIT 1;
  IF p_category_slug IS NOT NULL AND v_category.id IS NULL THEN
    RETURN NULL;
  END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'name', category.name,
    'slug', category.slug,
    'description', category.description,
    'hasPublishedFixture', EXISTS (
      SELECT 1
      FROM public.tournament_fixture_versions fixture
      WHERE fixture.tournament_id = v_tournament.id
        AND fixture.category_id = category.id
        AND fixture.status = 'published'
        AND fixture.invalidated_at IS NULL
    )
  ) ORDER BY category.sort_order, category.name), '[]'::jsonb)
  INTO v_categories
  FROM public.tournament_categories category
  WHERE category.tournament_id = v_tournament.id
    AND category.organization_id = v_page.organization_id
    AND category.status = 'active';

  IF v_category.id IS NOT NULL THEN
    SELECT fixture.*
    INTO v_fixture
    FROM public.tournament_fixture_versions fixture
    WHERE fixture.tournament_id = v_tournament.id
      AND fixture.category_id = v_category.id
      AND fixture.status = 'published'
      AND fixture.invalidated_at IS NULL
    ORDER BY fixture.published_at DESC, fixture.version_number DESC
    LIMIT 1;
  END IF;

  IF v_fixture.id IS NOT NULL THEN
    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'matchNumber', feed.match_number,
      'status', CASE WHEN feed.operation_id IS NOT NULL THEN 'official' ELSE feed.status END,
      'scheduledAt', feed.scheduled_at,
      'durationMinutes', feed.duration_minutes,
      'round', jsonb_build_object(
        'number', feed.round_number,
        'name', feed.round_name
      ),
      'phaseName', feed.phase_name,
      'groupName', feed.group_name,
      'venue', CASE WHEN feed.venue_name IS NULL THEN NULL ELSE jsonb_build_object(
        'name', feed.venue_name,
        'courtName', feed.court_name
      ) END,
      'home', jsonb_build_object(
        'name', feed.home_name,
        'shortName', feed.home_short_name,
        'shieldPath', feed.home_shield_path,
        'primaryColor', feed.home_primary_color,
        'secondaryColor', feed.home_secondary_color
      ),
      'away', jsonb_build_object(
        'name', feed.away_name,
        'shortName', feed.away_short_name,
        'shieldPath', feed.away_shield_path,
        'primaryColor', feed.away_primary_color,
        'secondaryColor', feed.away_secondary_color
      ),
      'result', CASE WHEN feed.operation_id IS NULL THEN NULL ELSE jsonb_build_object(
        'home', feed.home_score,
        'away', feed.away_score,
        'homePenalties', feed.home_penalties,
        'awayPenalties', feed.away_penalties,
        'outcomeType', feed.outcome_type,
        'officialAt', feed.official_at
      ) END
    ) ORDER BY feed.round_number, feed.match_number), '[]'::jsonb)
    INTO v_matches
    FROM (
      SELECT
        match_row.match_number,
        match_row.status,
        match_row.scheduled_at,
        match_row.duration_minutes,
        round_row.round_number,
        round_row.name AS round_name,
        phase.name AS phase_name,
        group_row.name AS group_name,
        venue.name AS venue_name,
        court.name AS court_name,
        home.snapshot_name AS home_name,
        home.snapshot_short_name AS home_short_name,
        home.snapshot_shield_path AS home_shield_path,
        home.snapshot_primary_color AS home_primary_color,
        home.snapshot_secondary_color AS home_secondary_color,
        away.snapshot_name AS away_name,
        away.snapshot_short_name AS away_short_name,
        away.snapshot_shield_path AS away_shield_path,
        away.snapshot_primary_color AS away_primary_color,
        away.snapshot_secondary_color AS away_secondary_color,
        operation.id AS operation_id,
        operation.official_at,
        outcome.outcome_type,
        score.home_score,
        score.away_score,
        score.home_penalties,
        score.away_penalties
      FROM public.tournament_matches match_row
      JOIN public.tournament_rounds round_row ON round_row.id = match_row.round_id
      JOIN public.tournament_phases phase ON phase.id = match_row.phase_id
      LEFT JOIN public.tournament_groups group_row ON group_row.id = match_row.group_id
      LEFT JOIN public.tournament_venues venue ON venue.id = match_row.venue_id
      LEFT JOIN public.tournament_courts court ON court.id = match_row.court_id
      LEFT JOIN public.tournament_competition_participants home
        ON home.id = match_row.home_participant_id
      LEFT JOIN public.tournament_competition_participants away
        ON away.id = match_row.away_participant_id
      LEFT JOIN LATERAL (
        SELECT official.id, official.official_at
        FROM public.tournament_match_operations official
        WHERE official.match_id = match_row.id
          AND official.status = 'official'
        ORDER BY official.operation_version DESC
        LIMIT 1
      ) operation ON true
      LEFT JOIN public.tournament_match_outcomes outcome
        ON outcome.match_operation_id = operation.id
      LEFT JOIN public.tournament_match_scores score
        ON score.match_operation_id = operation.id
      WHERE match_row.fixture_version_id = v_fixture.id
        AND match_row.status <> 'draft'
    ) feed;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'name', participant.snapshot_name,
      'shortName', participant.snapshot_short_name,
      'shieldPath', participant.snapshot_shield_path,
      'primaryColor', participant.snapshot_primary_color,
      'secondaryColor', participant.snapshot_secondary_color,
      'status', participant.status
    ) ORDER BY participant.snapshot_name), '[]'::jsonb)
    INTO v_teams
    FROM public.tournament_competition_participants participant
    WHERE participant.participant_set_id = v_fixture.participant_set_id
      AND participant.status IN ('active', 'withdrawn');

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'scopeKey', 'phase-' || phase.sequence_number::text || COALESCE(
        '-group-' || lower(group_row.code),
        ''
      ),
      'label', phase.name || COALESCE(' · ' || group_row.name, ''),
      'phaseName', phase.name,
      'groupName', group_row.name,
      'publishedAt', revision.published_at,
      'standings', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'position', standing.position,
          'teamName', participant.snapshot_name,
          'shortName', participant.snapshot_short_name,
          'shieldPath', participant.snapshot_shield_path,
          'played', standing.played,
          'won', standing.won,
          'drawn', standing.drawn,
          'lost', standing.lost,
          'goalsFor', standing.goals_for,
          'goalsAgainst', standing.goals_against,
          'goalDifference', standing.goal_difference,
          'points', standing.points
        ) ORDER BY standing.position, participant.snapshot_name)
        FROM public.tournament_team_standings standing
        JOIN public.tournament_competition_participants participant
          ON participant.id = standing.participant_id
        WHERE standing.revision_id = revision.id
      ), '[]'::jsonb),
      'players', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'name', player.display_name,
          'teamName', participant.snapshot_name,
          'goals', statistic.goals,
          'assists', statistic.assists,
          'appearances', statistic.appearances,
          'yellowCards', statistic.yellow_cards,
          'redCards', statistic.red_cards + statistic.second_yellows
        ) ORDER BY statistic.goals DESC, statistic.assists DESC, player.display_name)
        FROM public.tournament_player_statistics statistic
        JOIN public.tournament_roster_players player
          ON player.id = statistic.roster_player_id
        JOIN public.tournament_competition_participants participant
          ON participant.participant_set_id = v_fixture.participant_set_id
         AND participant.team_entry_id = statistic.team_entry_id
        WHERE statistic.revision_id = revision.id
      ), '[]'::jsonb),
      'discipline', COALESCE((
        SELECT jsonb_agg(jsonb_build_object(
          'name', player.display_name,
          'teamName', participant.snapshot_name,
          'yellowCards', ledger.yellow_cards,
          'redCards', ledger.direct_reds + ledger.second_yellows,
          'suspensions', COALESCE((
            SELECT jsonb_agg(jsonb_build_object(
              'remainingMatches', greatest(
                suspension.total_matches - suspension.served_matches,
                0
              )
            ) ORDER BY suspension.created_at)
            FROM public.tournament_player_suspensions suspension
            WHERE suspension.revision_id = revision.id
              AND suspension.roster_player_id = ledger.roster_player_id
              AND suspension.status IN ('active', 'reduced', 'served')
          ), '[]'::jsonb)
        ) ORDER BY ledger.fair_play_points DESC, player.display_name)
        FROM public.tournament_discipline_ledgers ledger
        JOIN public.tournament_roster_players player
          ON player.id = ledger.roster_player_id
        JOIN public.tournament_competition_participants participant
          ON participant.participant_set_id = v_fixture.participant_set_id
         AND participant.team_entry_id = ledger.team_entry_id
        WHERE ledger.revision_id = revision.id
      ), '[]'::jsonb)
    ) ORDER BY phase.sequence_number, group_row.sort_order NULLS FIRST), '[]'::jsonb)
    INTO v_competition
    FROM public.tournament_standings_revisions revision
    JOIN public.tournament_phases phase
      ON phase.id = revision.phase_id
     AND phase.fixture_version_id = v_fixture.id
     AND phase.status <> 'archived'
    LEFT JOIN public.tournament_groups group_row
      ON group_row.id = revision.group_id
     AND group_row.status = 'published'
    WHERE revision.fixture_version_id = v_fixture.id
      AND revision.status = 'published';
  END IF;

  RETURN jsonb_build_object(
    'publicSlug', v_page.public_slug,
    'organization', jsonb_build_object('name', v_organization.name),
    'season', jsonb_build_object('name', v_season.name),
    'tournament', jsonb_build_object(
      'name', v_tournament.name,
      'description', v_tournament.description,
      'status', v_tournament.status,
      'sportModality', v_tournament.sport_modality,
      'competitionFormat', v_tournament.competition_format,
      'genderCategory', v_tournament.gender_category,
      'startDate', v_tournament.start_date,
      'endDate', v_tournament.end_date
    ),
    'categories', v_categories,
    'selectedCategory', CASE WHEN v_category.id IS NULL THEN NULL ELSE jsonb_build_object(
      'name', v_category.name,
      'slug', v_category.slug,
      'description', v_category.description
    ) END,
    'hasPublishedFixture', v_fixture.id IS NOT NULL,
    'matches', v_matches,
    'teams', v_teams,
    'competition', v_competition
  );
END;
$_$;


--
-- Name: FUNCTION get_public_tournament_page(p_public_slug text, p_category_slug text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_public_tournament_page(p_public_slug text, p_category_slug text) IS 'Anonymous public-safe sporting projection. Returns NULL unless publication and lifecycle checks pass.';


--
-- Name: get_published_tournament_documents(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_published_tournament_documents(p_tournament_id uuid, p_category_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_can_manage boolean := false;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select public.has_tournament_communications_capability(
    tournament.organization_id,'documents.read'
  ) into v_can_manage
  from public.tournaments tournament where tournament.id = p_tournament_id;
  if not v_can_manage and not public.can_access_tournament_communications(p_tournament_id) then
    raise exception using errcode = '42501', message = 'TORNEOS_DOCUMENT_FORBIDDEN';
  end if;
  return (
    select jsonb_build_object(
      'items',coalesce(jsonb_agg(jsonb_build_object(
        'id',document.id,
        'type',document.document_type,
        'title',document.title,
        'acknowledgementMode',document.acknowledgement_mode,
        'categoryId',document.category_id,
        'categoryName',category.name,
        'version',version.version,
        'versionId',version.id,
        'summary',version.summary,
        'body',version.body,
        'effectiveAt',version.effective_at,
        'publishedAt',version.published_at,
        'correctionReason',version.correction_reason,
        'acknowledgement',case when acknowledgement.id is null then null else
          jsonb_build_object(
            'status',acknowledgement.status,
            'readAt',acknowledgement.read_at,
            'confirmedAt',acknowledgement.confirmed_at
          ) end
      ) order by version.published_at desc,document.id),'[]'::jsonb),
      'canManage',v_can_manage
    )
    from public.tournament_documents document
    join public.tournament_document_versions version
      on version.id = document.active_version_id
     and version.status = 'published'
    left join public.tournament_categories category
      on category.id = document.category_id
    left join public.tournament_document_acknowledgements acknowledgement
      on acknowledgement.document_id = document.id
     and acknowledgement.version_id = version.id
     and acknowledgement.user_id = private.current_identity_id()
    where document.tournament_id = p_tournament_id
      and document.status = 'published'
      and (document.category_id is null or document.category_id = p_category_id)
      and (
        v_can_manage
        or document.category_id is null
        or public.can_read_tournament_participant_hub(
          document.tournament_id,document.category_id
        )
      )
  );
end;
$$;


--
-- Name: get_published_tournament_matches(uuid, uuid, text, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_published_tournament_matches(p_tournament_id uuid, p_category_id uuid, p_view text DEFAULT 'all'::text, p_team_entry_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_fixture_id uuid;
  v_limit integer := least(greatest(coalesce(p_limit, 20), 1), 50);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_is_historical boolean := false;
  v_result jsonb;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if coalesce(p_view, 'all') not in ('all', 'upcoming', 'results') then
    raise exception using errcode = '22023', message = 'TORNEOS_HUB_INVALID_FILTER';
  end if;
  if not public.can_read_tournament_participant_hub(
    p_tournament_id,
    p_category_id
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_HUB_FORBIDDEN';
  end if;

  select
    tournament.status in ('completed', 'archived')
      or season.status = 'archived'
  into v_is_historical
  from public.tournaments tournament
  join public.tournament_seasons season
    on season.organization_id = tournament.organization_id
   and season.id = tournament.season_id
  where tournament.id = p_tournament_id;

  select fixture.id
  into v_fixture_id
  from public.tournament_fixture_versions fixture
  where fixture.tournament_id = p_tournament_id
    and fixture.category_id = p_category_id
    and fixture.status = 'published';

  if p_team_entry_id is not null and not exists (
    select 1
    from public.tournament_team_entries entry
    where entry.id = p_team_entry_id
      and entry.tournament_id = p_tournament_id
      and entry.category_id = p_category_id
      and entry.status = 'approved'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_HUB_FORBIDDEN';
  end if;

  with feed as (
    select
      match_row.id match_id,
      match_row.match_number,
      match_row.status,
      match_row.scheduled_at,
      match_row.duration_minutes,
      round_row.id round_id,
      round_row.round_number,
      round_row.name round_name,
      phase.id phase_id,
      phase.name phase_name,
      group_row.id group_id,
      group_row.name group_name,
      venue.name venue_name,
      venue.address venue_address,
      court.name court_name,
      home.id home_participant_id,
      home.team_entry_id home_team_entry_id,
      home.snapshot_name home_name,
      home.snapshot_short_name home_short_name,
      home.snapshot_shield_path home_shield_path,
      away.id away_participant_id,
      away.team_entry_id away_team_entry_id,
      away.snapshot_name away_name,
      away.snapshot_short_name away_short_name,
      away.snapshot_shield_path away_shield_path,
      operation.id operation_id,
      operation.official_at,
      outcome.outcome_type,
      score.home_score,
      score.away_score,
      score.home_penalties,
      score.away_penalties,
      self_player.roster_player_id my_roster_player_id,
      self_player.team_entry_id my_team_entry_id,
      availability.response my_availability,
      squad_player.callup_status my_callup_status,
      squad_player.lineup_status my_lineup_status,
      count(*) over () total_count
    from public.tournament_matches match_row
    join public.tournament_rounds round_row on round_row.id = match_row.round_id
    join public.tournament_phases phase on phase.id = match_row.phase_id
    left join public.tournament_groups group_row on group_row.id = match_row.group_id
    left join public.tournament_venues venue on venue.id = match_row.venue_id
    left join public.tournament_courts court on court.id = match_row.court_id
    left join public.tournament_competition_participants home
      on home.id = match_row.home_participant_id
    left join public.tournament_competition_participants away
      on away.id = match_row.away_participant_id
    left join lateral (
      select official.id, official.official_at
      from public.tournament_match_operations official
      where official.match_id = match_row.id
        and official.status = 'official'
      limit 1
    ) operation on true
    left join public.tournament_match_outcomes outcome
      on outcome.match_operation_id = operation.id
    left join public.tournament_match_scores score
      on score.match_operation_id = operation.id
    left join lateral (
      select
        player.roster_player_id,
        player.team_entry_id
      from public.get_my_current_tournament_roster_players() player
      where player.team_entry_id in (home.team_entry_id, away.team_entry_id)
      order by player.team_entry_id
      limit 1
    ) self_player on true
    left join public.tournament_match_availability_responses availability
      on availability.match_id = match_row.id
     and availability.roster_player_id = self_player.roster_player_id
    left join public.tournament_match_squads squad
      on squad.match_id = match_row.id
     and squad.team_entry_id = self_player.team_entry_id
     and squad.status in ('submitted', 'locked')
    left join public.tournament_match_squad_players squad_player
      on squad_player.match_squad_id = squad.id
     and squad_player.roster_player_id = self_player.roster_player_id
    where match_row.fixture_version_id = v_fixture_id
      and (
        p_team_entry_id is null
        or home.team_entry_id = p_team_entry_id
        or away.team_entry_id = p_team_entry_id
      )
      and (
        p_view = 'all'
        or (
          p_view = 'upcoming'
          and operation.id is null
          and match_row.status in ('scheduled', 'ready', 'postponed')
        )
        or (p_view = 'results' and operation.id is not null)
      )
  ),
  paged as (
    select *
    from feed
    order by
      case when operation_id is null then 0 else 1 end,
      case when operation_id is null then scheduled_at end asc nulls last,
      official_at desc nulls last,
      match_number
    limit v_limit offset v_offset
  )
  select jsonb_build_object(
    'items', coalesce(jsonb_agg(jsonb_build_object(
      'matchId', match_id,
      'matchNumber', match_number,
      'status', case when operation_id is not null then 'official' else status end,
      'scheduledAt', scheduled_at,
      'durationMinutes', duration_minutes,
      'round', jsonb_build_object(
        'id', round_id,
        'number', round_number,
        'name', round_name
      ),
      'phase', jsonb_build_object('id', phase_id, 'name', phase_name),
      'group', case when group_id is null then null else jsonb_build_object(
        'id', group_id,
        'name', group_name
      ) end,
      'venue', case when venue_name is null then null else jsonb_build_object(
        'name', venue_name,
        'address', venue_address,
        'courtName', court_name
      ) end,
      'home', jsonb_build_object(
        'participantId', home_participant_id,
        'teamEntryId', home_team_entry_id,
        'name', home_name,
        'shortName', home_short_name,
        'shieldPath', home_shield_path
      ),
      'away', jsonb_build_object(
        'participantId', away_participant_id,
        'teamEntryId', away_team_entry_id,
        'name', away_name,
        'shortName', away_short_name,
        'shieldPath', away_shield_path
      ),
      'result', case when operation_id is null then null else jsonb_build_object(
        'home', home_score,
        'away', away_score,
        'homePenalties', home_penalties,
        'awayPenalties', away_penalties,
        'outcomeType', outcome_type,
        'officialAt', official_at
      ) end,
      'isMyTeam', my_team_entry_id is not null,
      'myTeamEntryId', my_team_entry_id,
      'myAvailability', case
        when v_is_historical then null
        else my_availability
      end,
      'myCallupStatus', case
        when v_is_historical then null
        else my_callup_status
      end,
      'myLineupStatus', case
        when v_is_historical then null
        else my_lineup_status
      end
    ) order by
      case when operation_id is null then 0 else 1 end,
      case when operation_id is null then scheduled_at end asc nulls last,
      official_at desc nulls last,
      match_number), '[]'::jsonb),
    'pagination', jsonb_build_object(
      'limit', v_limit,
      'offset', v_offset,
      'total', coalesce(max(total_count), 0),
      'hasMore', v_offset + count(*) < coalesce(max(total_count), 0)
    ),
    'hasPublishedFixture', v_fixture_id is not null
  )
  into v_result
  from paged;

  return coalesce(v_result, jsonb_build_object(
    'items', '[]'::jsonb,
    'pagination', jsonb_build_object(
      'limit', v_limit,
      'offset', v_offset,
      'total', 0,
      'hasMore', false
    ),
    'hasPublishedFixture', v_fixture_id is not null
  ));
end;
$$;


--
-- Name: get_published_tournament_media(uuid, uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_published_tournament_media(p_tournament_id uuid, p_category_id uuid DEFAULT NULL::uuid, p_match_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
  v_readiness jsonb := public.tournament_media_pipeline_readiness();
  v_delivery jsonb;
begin
  if private.current_identity_id() is null or not public.can_read_tournament_participant_hub(
    p_tournament_id,p_category_id
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  if p_limit < 1 or p_limit > 50 or p_offset < 0 then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_FILTER_INVALID';
  end if;
  if p_match_id is not null and not exists (
    select 1 from public.tournament_matches match
    where match.id = p_match_id and match.tournament_id = p_tournament_id
      and (p_category_id is null or match.category_id = p_category_id)
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  -- Reading requires the signer only. A missing processor blocks new uploads
  -- but must not hide media that was already published.
  v_delivery := jsonb_build_object(
    'status',case
      when (v_readiness->>'storageReady')::boolean
        and (v_readiness->>'signerReady')::boolean
      then 'signed_urls' else 'staging_required' end,
    'signedUrlTtlSeconds',300,'originalsRestricted',true
  );
  select jsonb_build_object(
    'delivery',v_delivery,
    'items',coalesce(jsonb_agg(jsonb_build_object(
      'id',gallery.id,'title',gallery.title,'description',gallery.description,
      'visibility',gallery.visibility,'matchId',gallery.match_id,
      'publishedAt',gallery.published_at,'coverAssetId',gallery.cover_asset_id,
      'assets',(
        select coalesce(jsonb_agg(jsonb_build_object(
          'id',asset.id,'safeName',asset.safe_name,
          'width',asset.width,'height',asset.height,
          'caption',item.caption,'sortOrder',item.sort_order,
          'thumbnailUrl',null,'gridUrl',null,'detailUrl',null,
          'originalAvailable',false
        ) order by item.sort_order),'[]'::jsonb)
        from public.tournament_media_gallery_items item
        join public.tournament_media_assets asset on asset.id = item.asset_id
        where item.gallery_id = gallery.id and asset.status = 'published'
      )
    ) order by gallery.published_at desc),'[]'::jsonb)
  ) into v_result
  from (
    select *
    from public.tournament_media_galleries gallery_page
    where gallery_page.tournament_id = p_tournament_id
      and gallery_page.status = 'published'
      and (p_category_id is null or gallery_page.category_id is null
        or gallery_page.category_id = p_category_id)
      and (p_match_id is null or gallery_page.match_id = p_match_id)
      and public.can_current_user_read_media_gallery(gallery_page.id)
    order by gallery_page.published_at desc
    limit p_limit offset p_offset
  ) gallery;
  return coalesce(v_result,jsonb_build_object(
    'delivery',v_delivery,'items','[]'::jsonb
  ));
end;
$$;


--
-- Name: get_published_tournament_standings(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_published_tournament_standings(p_tournament_id uuid, p_category_id uuid, p_phase_id uuid, p_group_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_fixture_id uuid;
  v_revision_id uuid;
  v_result jsonb;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.can_read_tournament_participant_hub(
    p_tournament_id,
    p_category_id
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_HUB_FORBIDDEN';
  end if;

  select fixture.id
  into v_fixture_id
  from public.tournament_fixture_versions fixture
  join public.tournament_phases phase
    on phase.fixture_version_id = fixture.id
   and phase.id = p_phase_id
   and phase.status <> 'archived'
  where fixture.tournament_id = p_tournament_id
    and fixture.category_id = p_category_id
    and fixture.status = 'published'
    and (
      p_group_id is null
      or exists (
        select 1
        from public.tournament_groups group_row
        where group_row.id = p_group_id
          and group_row.fixture_version_id = fixture.id
          and group_row.phase_id = phase.id
          and group_row.status = 'published'
      )
    );

  if v_fixture_id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_HUB_FORBIDDEN';
  end if;

  select revision.id
  into v_revision_id
  from public.tournament_standings_revisions revision
  where revision.fixture_version_id = v_fixture_id
    and revision.phase_id = p_phase_id
    and revision.group_id is not distinct from p_group_id
    and revision.status = 'published'
  order by revision.revision_number desc
  limit 1;

  select jsonb_build_object(
    'revision', case
      when revision.id is null then null
      else jsonb_build_object(
        'id', revision.id,
        'number', revision.revision_number,
        'status', 'published',
        'publishedAt', revision.published_at
      )
    end,
    'standings', coalesce((
      select jsonb_agg(jsonb_build_object(
        'position', standing.position,
        'participantId', standing.participant_id,
        'teamEntryId', standing.team_entry_id,
        'teamName', participant.snapshot_name,
        'shortName', participant.snapshot_short_name,
        'shieldPath', participant.snapshot_shield_path,
        'played', standing.played,
        'won', standing.won,
        'drawn', standing.drawn,
        'lost', standing.lost,
        'goalsFor', standing.goals_for,
        'goalsAgainst', standing.goals_against,
        'goalDifference', standing.goal_difference,
        'points', standing.points,
        'classificationStatus', standing.classification_status
      ) order by standing.position)
      from public.tournament_team_standings standing
      join public.tournament_competition_participants participant
        on participant.id = standing.participant_id
      where standing.revision_id = revision.id
    ), '[]'::jsonb)
  )
  into v_result
  from public.tournament_standings_revisions revision
  where revision.id = v_revision_id;

  return coalesce(v_result, jsonb_build_object(
    'revision', null,
    'standings', '[]'::jsonb
  ));
end;
$$;


--
-- Name: get_published_tournament_statistics(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_published_tournament_statistics(p_tournament_id uuid, p_category_id uuid, p_phase_id uuid, p_group_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_fixture_id uuid;
  v_revision_id uuid;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.can_read_tournament_participant_hub(
    p_tournament_id,
    p_category_id
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_HUB_FORBIDDEN';
  end if;

  select fixture.id
  into v_fixture_id
  from public.tournament_fixture_versions fixture
  join public.tournament_phases phase
    on phase.fixture_version_id = fixture.id
   and phase.id = p_phase_id
   and phase.status <> 'archived'
  where fixture.tournament_id = p_tournament_id
    and fixture.category_id = p_category_id
    and fixture.status = 'published'
    and (
      p_group_id is null
      or exists (
        select 1
        from public.tournament_groups group_row
        where group_row.id = p_group_id
          and group_row.fixture_version_id = fixture.id
          and group_row.phase_id = phase.id
          and group_row.status = 'published'
      )
    );

  if v_fixture_id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_HUB_FORBIDDEN';
  end if;

  select revision.id
  into v_revision_id
  from public.tournament_standings_revisions revision
  where revision.fixture_version_id = v_fixture_id
    and revision.phase_id = p_phase_id
    and revision.group_id is not distinct from p_group_id
    and revision.status = 'published'
  order by revision.revision_number desc
  limit 1;

  return jsonb_build_object(
    'revisionId', v_revision_id,
    'players', coalesce((
      select jsonb_agg(jsonb_build_object(
        'rosterPlayerId', statistic.roster_player_id,
        'teamEntryId', statistic.team_entry_id,
        'name', player.display_name,
        'goals', statistic.goals,
        'ownGoals', statistic.own_goals,
        'assists', statistic.assists,
        'appearances', statistic.appearances,
        'starts', statistic.starts,
        'substituteAppearances', statistic.substitute_appearances,
        'yellowCards', statistic.yellow_cards,
        'secondYellows', statistic.second_yellows,
        'redCards', statistic.red_cards,
        'captaincies', statistic.captaincies
      ) order by
        statistic.goals desc,
        statistic.assists desc,
        player.display_name,
        statistic.roster_player_id)
      from public.tournament_player_statistics statistic
      join public.tournament_roster_players player
        on player.id = statistic.roster_player_id
      where statistic.revision_id = v_revision_id
    ), '[]'::jsonb),
    'teams', coalesce((
      select jsonb_agg(jsonb_build_object(
        'participantId', statistic.participant_id,
        'teamEntryId', statistic.team_entry_id,
        'teamName', participant.snapshot_name,
        'shortName', participant.snapshot_short_name,
        'shieldPath', participant.snapshot_shield_path,
        'goals', statistic.goals,
        'yellowCards', statistic.yellow_cards,
        'secondYellows', statistic.second_yellows,
        'redCards', statistic.red_cards,
        'homePlayed', statistic.home_played,
        'awayPlayed', statistic.away_played
      ) order by statistic.goals desc, participant.snapshot_name)
      from public.tournament_team_statistics statistic
      join public.tournament_competition_participants participant
        on participant.id = statistic.participant_id
      where statistic.revision_id = v_revision_id
    ), '[]'::jsonb),
    'discipline', coalesce((
      select jsonb_agg(jsonb_build_object(
        'rosterPlayerId', ledger.roster_player_id,
        'teamEntryId', ledger.team_entry_id,
        'name', player.display_name,
        'yellowCards', ledger.yellow_cards,
        'secondYellows', ledger.second_yellows,
        'directReds', ledger.direct_reds,
        'fairPlayPoints', ledger.fair_play_points,
        'automaticSuspensions', ledger.automatic_suspensions,
        'suspensions', coalesce((
          select jsonb_agg(jsonb_build_object(
            'id', suspension.id,
            'sourceType', suspension.source_type,
            'totalMatches', suspension.total_matches,
            'servedMatches', suspension.served_matches,
            'remainingMatches', greatest(
              suspension.total_matches - suspension.served_matches,
              0
            ),
            'status', suspension.status
          ) order by suspension.created_at)
          from public.tournament_player_suspensions suspension
          where suspension.revision_id = ledger.revision_id
            and suspension.roster_player_id = ledger.roster_player_id
            and suspension.status in ('active', 'reduced', 'served')
        ), '[]'::jsonb)
      ) order by ledger.fair_play_points desc, player.display_name)
      from public.tournament_discipline_ledgers ledger
      join public.tournament_roster_players player
        on player.id = ledger.roster_player_id
      where ledger.revision_id = v_revision_id
    ), '[]'::jsonb)
  );
end;
$$;


--
-- Name: get_published_tournament_teams(uuid, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_published_tournament_teams(p_tournament_id uuid, p_category_id uuid, p_limit integer DEFAULT 16, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_fixture_id uuid;
  v_revision_id uuid;
  v_my_team_id uuid;
  v_limit integer := least(greatest(coalesce(p_limit, 16), 1), 32);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_result jsonb;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.can_read_tournament_participant_hub(
    p_tournament_id,
    p_category_id
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_HUB_FORBIDDEN';
  end if;

  select fixture.id
  into v_fixture_id
  from public.tournament_fixture_versions fixture
  where fixture.tournament_id = p_tournament_id
    and fixture.category_id = p_category_id
    and fixture.status = 'published';

  select entry.id
  into v_my_team_id
  from public.tournament_team_entries entry
  left join public.get_my_current_tournament_roster_players() player
    on player.team_entry_id = entry.id
  left join public.tournament_team_managers manager
    on manager.organization_id = entry.organization_id
   and manager.team_entry_id = entry.id
   and manager.user_id = private.current_identity_id()
   and manager.status = 'active'
   and manager.role in ('captain', 'delegate')
  where entry.tournament_id = p_tournament_id
    and entry.category_id = p_category_id
    and entry.status = 'approved'
    and (
      player.roster_player_id is not null
      or manager.id is not null
    )
  order by (player.roster_player_id is not null) desc, entry.name
  limit 1;

  select revision.id
  into v_revision_id
  from public.tournament_standings_revisions revision
  join public.tournament_phases phase on phase.id = revision.phase_id
  where revision.fixture_version_id = v_fixture_id
    and revision.status = 'published'
  order by phase.sequence_number desc, revision.group_id nulls first,
    revision.revision_number desc
  limit 1;

  with roster_payloads as (
    select
      roster.team_entry_id,
      jsonb_agg(jsonb_build_object(
        'id', player.id,
        'displayName', player.display_name,
        'shirtNumber', player.shirt_number,
        'primaryPosition', player.primary_position,
        'isGoalkeeper', player.is_goalkeeper
      ) order by player.shirt_number nulls last, player.display_name) roster
    from public.tournament_rosters roster
    join public.tournament_roster_players player
      on player.roster_id = roster.id
     and player.status = 'active'
    where roster.status in ('approved', 'locked')
      and roster.version = (
        select max(latest.version)
        from public.tournament_rosters latest
        where latest.team_entry_id = roster.team_entry_id
          and latest.status in ('approved', 'locked')
      )
    group by roster.team_entry_id
  ),
  feed as (
    select
      participant.id participant_id,
      participant.team_entry_id,
      participant.snapshot_name name,
      participant.snapshot_short_name short_name,
      participant.snapshot_shield_path shield_path,
      participant.snapshot_primary_color primary_color,
      participant.snapshot_secondary_color secondary_color,
      participant.status,
      coalesce(roster.roster, '[]'::jsonb) roster,
      standing.position,
      standing.played,
      standing.points,
      next_match.payload next_match,
      count(*) over () total_count
    from public.tournament_competition_participants participant
    left join roster_payloads roster
      on roster.team_entry_id = participant.team_entry_id
    left join public.tournament_team_standings standing
      on standing.revision_id = v_revision_id
     and standing.team_entry_id = participant.team_entry_id
    left join lateral (
      select jsonb_build_object(
        'matchId', match_row.id,
        'scheduledAt', match_row.scheduled_at,
        'status', match_row.status,
        'roundName', round_row.name,
        'homeName', home.snapshot_name,
        'awayName', away.snapshot_name
      ) payload
      from public.tournament_matches match_row
      join public.tournament_rounds round_row on round_row.id = match_row.round_id
      left join public.tournament_competition_participants home
        on home.id = match_row.home_participant_id
      left join public.tournament_competition_participants away
        on away.id = match_row.away_participant_id
      where match_row.fixture_version_id = v_fixture_id
        and match_row.status in ('scheduled', 'ready', 'postponed')
        and (
          home.team_entry_id = participant.team_entry_id
          or away.team_entry_id = participant.team_entry_id
        )
        and (match_row.scheduled_at is null or match_row.scheduled_at >= now())
      order by match_row.scheduled_at nulls last, match_row.match_number
      limit 1
    ) next_match on true
    where participant.participant_set_id = (
      select fixture.participant_set_id
      from public.tournament_fixture_versions fixture
      where fixture.id = v_fixture_id
    )
      and participant.status in ('active', 'withdrawn')
  ),
  paged as (
    select *
    from feed
    order by position nulls last, name, participant_id
    limit v_limit offset v_offset
  )
  select jsonb_build_object(
    'items', coalesce(jsonb_agg(jsonb_build_object(
      'participantId', participant_id,
      'teamEntryId', team_entry_id,
      'name', name,
      'shortName', short_name,
      'shieldPath', shield_path,
      'primaryColor', primary_color,
      'secondaryColor', secondary_color,
      'status', status,
      'roster', case
        when status = 'active' then roster
        else '[]'::jsonb
      end,
      'position', position,
      'played', played,
      'points', points,
      'nextMatch', next_match,
      'isMyTeam', team_entry_id = v_my_team_id
    ) order by position nulls last, name, participant_id), '[]'::jsonb),
    'pagination', jsonb_build_object(
      'limit', v_limit,
      'offset', v_offset,
      'total', coalesce(max(total_count), 0),
      'hasMore', v_offset + count(*) < coalesce(max(total_count), 0)
    ),
    'hasPublishedFixture', v_fixture_id is not null
  )
  into v_result
  from paged;

  return coalesce(v_result, jsonb_build_object(
    'items', '[]'::jsonb,
    'pagination', jsonb_build_object(
      'limit', v_limit,
      'offset', v_offset,
      'total', 0,
      'hasMore', false
    ),
    'hasPublishedFixture', v_fixture_id is not null
  ));
end;
$$;


--
-- Name: get_team_registration_context(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_team_registration_context(p_organization_id uuid, p_team_entry_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
  v_is_privileged boolean;
begin
  -- Quien ya podía leer la inscripción la sigue leyendo entera. La política
  -- `roster` suma una segunda puerta, y sólo esa: el jugador entra a la misma
  -- pantalla que el delegado, pero sin el historial de revisión, sin la
  -- auditoría y sin la lista de responsables, que no son datos suyos.
  v_is_privileged := public.can_read_tournament_team_entry(
    p_organization_id, p_team_entry_id
  );
  if private.current_identity_id() is null or not (
    v_is_privileged
    or public.can_manage_tournament_team_visual_assets_as(
      p_organization_id, p_team_entry_id, private.current_identity_id(), 'roster_players.update'
    )
  ) then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  select jsonb_build_object(
    'entry', jsonb_build_object(
      'id', entry.id, 'organizationId', entry.organization_id,
      'seasonId', entry.season_id, 'tournamentId', entry.tournament_id,
      'categoryId', entry.category_id, 'name', entry.name, 'slug', entry.slug,
      'shortName', entry.short_name, 'shieldPath', entry.shield_path,
      'primaryColor', entry.primary_color, 'secondaryColor', entry.secondary_color,
      'status', entry.status, 'registrationSource', entry.registration_source,
      'linked', entry.arma2_team_id is not null, 'submittedAt', entry.submitted_at
    ),
    'tournament', jsonb_build_object(
      'id', tournament.id, 'name', tournament.name, 'status', tournament.status,
      'registrationClosesAt', tournament.registration_closes_at
    ),
    'category', jsonb_build_object('id', category.id, 'name', category.name),
    'settings', (
      select jsonb_build_object(
        'minimumPlayers', settings.minimum_players,
        'maximumPlayers', settings.maximum_players,
        'shirtNumberRequired', settings.shirt_number_required,
        'uniqueShirtNumbers', settings.unique_shirt_numbers,
        'positionRequired', settings.position_required,
        'minimumGoalkeepers', settings.minimum_goalkeepers,
        'allowProvisionalPlayers', settings.allow_provisional_players
      ) from public.tournament_roster_settings settings
      where settings.tournament_id = entry.tournament_id
    ),
    'managers', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', manager.id, 'displayName', manager.display_name,
        'role', manager.role, 'status', manager.status,
        'isCurrentUser', manager.user_id = private.current_identity_id()
      ) order by manager.created_at)
      from public.tournament_team_managers manager
      where v_is_privileged
        and manager.team_entry_id = entry.id and manager.status <> 'revoked'
    ), '[]'::jsonb),
    'roster', (
      select jsonb_build_object(
        'id', roster.id, 'version', roster.version, 'status', roster.status,
        'players', coalesce((
          select jsonb_agg(jsonb_build_object(
            'id', player.id, 'arma2UserId', player.arma2_user_id,
            'provisionalPlayerId', player.provisional_player_id,
            'displayName', player.display_name, 'avatarUrl', player.avatar_url,
            'shirtNumber', player.shirt_number,
            'primaryPosition', player.primary_position,
            'secondaryPosition', player.secondary_position,
            'isGoalkeeper', player.is_goalkeeper,
            'eligibilityStatus', player.eligibility_status
          ) order by player.shirt_number nulls last, player.display_name)
          from public.tournament_roster_players player
          where player.roster_id = roster.id and player.status = 'active'
        ), '[]'::jsonb)
      )
      from public.tournament_rosters roster
      where roster.team_entry_id = entry.id order by roster.version desc limit 1
    ),
    -- Con qué alcance entró el que mira. `full` es la inscripción entera de
    -- siempre; `visual` es el jugador o el responsable que entra sólo por la
    -- política de autogestión, y para el que `managers`, `reviews` y `audit`
    -- vienen vacíos porque no son datos suyos. Sin este dato la pantalla no
    -- puede distinguir «no hay responsables» de «no te los muestro», y termina
    -- afirmando lo primero cuando lo cierto es lo segundo.
    'viewer', jsonb_build_object(
      'scope', case when v_is_privileged then 'full' else 'visual' end
    ),
    -- La capacidad viaja desde el mismo predicado que después autoriza la
    -- escritura. Es lo que impide pintar un CTA que el servidor va a rechazar.
    'visualAssets', jsonb_build_object(
      'policy', tournament.team_visual_management_policy,
      'canManageShield', public.can_update_tournament_team_branding(
        p_organization_id, entry.id
      ),
      'canManagePortraits', public.can_manage_tournament_team_visual_assets_as(
        p_organization_id, entry.id, private.current_identity_id(), 'roster_players.update'
      )
    ),
    'reviews', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', review.id, 'decision', review.decision, 'reason', review.reason,
        'issues', review.issues, 'createdAt', review.created_at
      ) order by review.created_at desc)
      from public.tournament_team_reviews review
      where v_is_privileged and review.team_entry_id = entry.id
    ), '[]'::jsonb),
    'audit', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', audit.id, 'action', audit.action, 'resourceType', audit.resource_type,
        'metadata', audit.metadata, 'createdAt', audit.created_at
      ) order by audit.created_at desc)
      from (
        select * from public.tournament_audit_log
        where v_is_privileged and team_entry_id = entry.id
        order by created_at desc limit 50
      ) audit
    ), '[]'::jsonb)
  ) into v_result
  from public.tournament_team_entries entry
  join public.tournaments tournament on tournament.id = entry.tournament_id
  join public.tournament_categories category on category.id = entry.category_id
  where entry.id = p_team_entry_id and entry.organization_id = p_organization_id;
  if v_result is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  return v_result;
end;
$$;


--
-- Name: get_tournament_announcement(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_announcement(p_announcement_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_delivery public.tournament_announcement_deliveries%rowtype;
  v_announcement public.tournament_announcements%rowtype;
  v_can_manage boolean;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_announcement
  from public.tournament_announcements announcement
  where announcement.id = p_announcement_id;
  v_can_manage := v_announcement.id is not null
    and public.has_tournament_communications_capability(
      v_announcement.organization_id,'announcements.read'
    );
  select * into v_delivery
  from public.tournament_announcement_deliveries delivery
  where delivery.announcement_id = p_announcement_id
    and delivery.recipient_user_id = private.current_identity_id()
    and delivery.status <> 'archived';
  if v_announcement.id is null
    or (
      v_delivery.id is not null
      and not v_can_manage
      and not public.can_current_user_access_tournament_announcement(
        v_announcement.id
      )
    )
    or (v_delivery.id is null and not v_can_manage)
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  return (
    select jsonb_build_object(
      'id',announcement.id,
      'status',announcement.status,
      'type',announcement.announcement_type,
      'title',announcement.title,
      'summary',announcement.summary,
      'body',announcement.body,
      'priority',announcement.priority,
      'acknowledgementMode',announcement.acknowledgement_mode,
      'publishedAt',announcement.published_at,
      'scheduledFor',case when v_can_manage then announcement.scheduled_for else null end,
      'version',announcement.version,
      'updatedFromId',announcement.supersedes_id,
      'correctionReason',announcement.correction_reason,
      'tournament',jsonb_build_object('id',tournament.id,'name',tournament.name),
      'category',case when category.id is null then null else
        jsonb_build_object('id',category.id,'name',category.name) end,
      'organization',jsonb_build_object('id',organization.id,'name',organization.name),
      'delivery',case when v_delivery.id is null then null else jsonb_build_object(
        'status',v_delivery.status,'readAt',v_delivery.read_at,
        'confirmedAt',v_delivery.confirmed_at
      ) end,
      'links',coalesce((
        select jsonb_agg(jsonb_build_object(
          'id',link.id,'type',link.link_type,'label',link.label,
          'resourceId',link.resource_id,'externalUrl',link.external_url,
          'externalDomain',case when link.external_url is null then null
            else split_part(split_part(link.external_url,'//',2),'/',1) end
        ) order by link.sort_order,link.id)
        from public.tournament_announcement_links link
        where link.announcement_id = announcement.id
      ),'[]'::jsonb),
      'canManage',v_can_manage
    )
    from public.tournament_announcements announcement
    join public.tournaments tournament on tournament.id = announcement.tournament_id
    join public.tournament_organizations organization
      on organization.id = announcement.organization_id
    left join public.tournament_categories category
      on category.id = announcement.category_id
    where announcement.id = p_announcement_id
  );
end;
$$;


--
-- Name: get_tournament_branding_context(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_branding_context(p_organization_id uuid, p_tournament_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_organization public.tournament_organizations%ROWTYPE;
  v_tournament public.tournaments%ROWTYPE;
  v_tournaments jsonb := '[]'::jsonb;
BEGIN
  IF private.current_identity_id() IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_AUTH_REQUIRED';
  END IF;

  SELECT organization.*
  INTO v_organization
  FROM public.tournament_organizations organization
  WHERE organization.id = p_organization_id
    AND organization.status = 'active';

  IF v_organization.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_RESOURCE_FORBIDDEN';
  END IF;

  IF p_tournament_id IS NULL THEN
    IF NOT public.has_tournament_organization_capability(
      p_organization_id,
      'tournaments.read'
    ) THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_RESOURCE_FORBIDDEN';
    END IF;

    SELECT COALESCE(jsonb_agg(jsonb_build_object(
      'id', tournament.id,
      'logoPath', tournament.logo_path
    ) ORDER BY tournament.updated_at DESC, tournament.id), '[]'::jsonb)
    INTO v_tournaments
    FROM public.tournaments tournament
    WHERE tournament.organization_id = p_organization_id
      AND tournament.status <> 'archived';
  ELSE
    SELECT tournament.*
    INTO v_tournament
    FROM public.tournaments tournament
    WHERE tournament.id = p_tournament_id
      AND tournament.organization_id = p_organization_id
      AND tournament.status <> 'archived';

    IF v_tournament.id IS NULL OR NOT (
      public.has_tournament_organization_capability(
        p_organization_id,
        'tournaments.read'
      )
      OR public.can_read_tournament_participant_hub(p_tournament_id, NULL)
    ) THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_RESOURCE_FORBIDDEN';
    END IF;

    v_tournaments := jsonb_build_array(jsonb_build_object(
      'id', v_tournament.id,
      'logoPath', v_tournament.logo_path
    ));
  END IF;

  RETURN jsonb_build_object(
    'organization', jsonb_build_object(
      'id', v_organization.id,
      'name', v_organization.name,
      'logoPath', v_organization.logo_path
    ),
    'tournaments', v_tournaments
  );
END;
$$;


--
-- Name: get_tournament_communications_admin_context(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_communications_admin_context(p_organization_id uuid, p_tournament_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_capabilities text[];
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select public.tournament_communications_role_capabilities(membership.role)
    into v_capabilities
  from public.tournament_organization_members membership
  join public.tournament_organizations organization
    on organization.id = membership.organization_id
  where membership.organization_id = p_organization_id
    and membership.user_id = private.current_identity_id()
    and membership.status = 'active'
    and organization.status = 'active';
  if v_capabilities is null or not ('announcements.read' = any(v_capabilities)) then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  return jsonb_build_object(
    'organizationId',p_organization_id,
    'capabilities',to_jsonb(v_capabilities),
    'scheduledPublishingEnabled',false,
    'channels',jsonb_build_object('internal',true,'push',false,'email',false),
    'tournaments',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',tournament.id,'name',tournament.name,'seasonId',tournament.season_id,
        'seasonName',season.name,'status',tournament.status,
        'categories',coalesce((
          select jsonb_agg(jsonb_build_object('id',category.id,'name',category.name)
            order by category.sort_order,category.name)
          from public.tournament_categories category
          where category.tournament_id = tournament.id and category.status = 'active'
        ),'[]'::jsonb),
        'teams',coalesce((
          select jsonb_agg(jsonb_build_object(
            'id',entry.id,'name',entry.name,'categoryId',entry.category_id
          ) order by entry.name)
          from (
            select *
            from public.tournament_team_entries
            where tournament_id = tournament.id and status = 'approved'
            order by name
            limit 100
          ) entry
        ),'[]'::jsonb),
        'matches',coalesce((
          select jsonb_agg(jsonb_build_object(
            'id',match.id,'categoryId',match.category_id,
            'matchNumber',match.match_number,'scheduledAt',match.scheduled_at
          ) order by match.scheduled_at nulls last,match.match_number)
          from (
            select match.*
            from public.tournament_matches match
            join public.tournament_fixture_versions fixture
              on fixture.id = match.fixture_version_id
             and fixture.organization_id = match.organization_id
             and fixture.status = 'published'
            where match.tournament_id = tournament.id
            order by match.scheduled_at nulls last,match.match_number
            limit 100
          ) match
        ),'[]'::jsonb)
      ) order by season.start_date desc nulls last,tournament.name)
      from public.tournaments tournament
      join public.tournament_seasons season on season.id = tournament.season_id
      where tournament.organization_id = p_organization_id
        and tournament.status <> 'archived'
        and (p_tournament_id is null or tournament.id = p_tournament_id)
    ),'[]'::jsonb),
    'announcements',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',announcement.id,'tournamentId',announcement.tournament_id,
        'categoryId',announcement.category_id,'status',announcement.status,
        'type',announcement.announcement_type,'title',announcement.title,
        'summary',announcement.summary,'priority',announcement.priority,
        'scheduledFor',announcement.scheduled_for,
        'publishedAt',announcement.published_at,
        'recipientCount',announcement.published_recipient_count,
        'version',announcement.version
      ) order by announcement.updated_at desc)
      from (
        select *
        from public.tournament_announcements
        where organization_id = p_organization_id
          and (p_tournament_id is null or tournament_id = p_tournament_id)
        order by updated_at desc
        limit 100
      ) announcement
    ),'[]'::jsonb),
    'documents',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',document.id,'tournamentId',document.tournament_id,
        'categoryId',document.category_id,'status',document.status,
        'type',document.document_type,'title',document.title,
        'acknowledgementMode',document.acknowledgement_mode,
        'activeVersionId',document.active_version_id
      ) order by document.updated_at desc)
      from public.tournament_documents document
      where document.organization_id = p_organization_id
        and (p_tournament_id is null or document.tournament_id = p_tournament_id)
    ),'[]'::jsonb)
  );
end;
$$;


--
-- Name: get_tournament_communications_inbox(uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_communications_inbox(p_tournament_id uuid DEFAULT NULL::uuid, p_filter text DEFAULT 'all'::text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit,20),1),50);
  v_offset integer := least(greatest(coalesce(p_offset,0),0),5000);
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if p_filter not in ('all','unread','important','documents') then
    raise exception using errcode = '22023', message = 'TORNEOS_COMMUNICATION_INVALID_FILTER';
  end if;
  return (
    with eligible as (
      select
        delivery.id delivery_id,
        delivery.status delivery_status,
        delivery.read_at,
        delivery.confirmed_at,
        announcement.id,
        announcement.tournament_id,
        announcement.category_id,
        announcement.status,
        announcement.announcement_type,
        announcement.title,
        announcement.summary,
        announcement.priority,
        announcement.acknowledgement_mode,
        announcement.published_at,
        announcement.version,
        announcement.supersedes_id,
        tournament.name tournament_name,
        season.name season_name,
        organization.name organization_name,
        category.name category_name,
        exists (
          select 1
          from public.tournament_announcements update_announcement
          join public.tournament_announcement_deliveries update_delivery
            on update_delivery.announcement_id = update_announcement.id
           and update_delivery.recipient_user_id = private.current_identity_id()
          where update_announcement.supersedes_id = announcement.id
            and update_announcement.status = 'published'
        ) has_update
      from public.tournament_announcement_deliveries delivery
      join public.tournament_announcements announcement
        on announcement.id = delivery.announcement_id
       and announcement.organization_id = delivery.organization_id
      join public.tournaments tournament on tournament.id = announcement.tournament_id
      join public.tournament_seasons season on season.id = announcement.season_id
      join public.tournament_organizations organization
        on organization.id = announcement.organization_id
      left join public.tournament_categories category
        on category.id = announcement.category_id
      where delivery.recipient_user_id = private.current_identity_id()
        and delivery.status <> 'archived'
        and public.can_access_tournament_communications(announcement.tournament_id)
        and public.can_current_user_access_tournament_announcement(announcement.id)
        and (p_tournament_id is null or announcement.tournament_id = p_tournament_id)
        and (
          p_filter = 'all'
          or (p_filter = 'unread' and delivery.read_at is null)
          or (p_filter = 'important' and announcement.priority in ('important','urgent'))
          or (p_filter = 'documents' and announcement.announcement_type = 'regulation')
        )
    ),
    page as (
      select * from eligible
      order by
        case priority when 'urgent' then 0 when 'important' then 1 else 2 end,
        published_at desc,id desc
      limit v_limit offset v_offset
    )
    select jsonb_build_object(
      'items',coalesce(jsonb_agg(jsonb_build_object(
        'deliveryId',page.delivery_id,
        'deliveryStatus',page.delivery_status,
        'readAt',page.read_at,
        'confirmedAt',page.confirmed_at,
        'id',page.id,
        'tournamentId',page.tournament_id,
        'categoryId',page.category_id,
        'status',page.status,
        'type',page.announcement_type,
        'title',page.title,
        'summary',page.summary,
        'priority',page.priority,
        'acknowledgementMode',page.acknowledgement_mode,
        'publishedAt',page.published_at,
        'version',page.version,
        'updated',page.has_update,
        'tournamentName',page.tournament_name,
        'seasonName',page.season_name,
        'organizationName',page.organization_name,
        'categoryName',page.category_name
      ) order by
        case page.priority when 'urgent' then 0 when 'important' then 1 else 2 end,
        page.published_at desc,page.id desc),'[]'::jsonb),
      'pagination',jsonb_build_object(
        'limit',v_limit,'offset',v_offset,
        'total',(select count(*) from eligible)
      ),
      'unreadCount',(
        select count(*)
        from public.tournament_announcement_deliveries unread
        join public.tournament_announcements unread_announcement
          on unread_announcement.id = unread.announcement_id
        where unread.recipient_user_id = private.current_identity_id()
          and unread.read_at is null
          and unread.status = 'available'
          and public.can_access_tournament_communications(
            unread_announcement.tournament_id
          )
          and public.can_current_user_access_tournament_announcement(
            unread_announcement.id
          )
          and (p_tournament_id is null
            or unread_announcement.tournament_id = p_tournament_id)
      )
    )
    from page
  );
end;
$$;


--
-- Name: get_tournament_competition_context(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_competition_context(p_organization_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_payload jsonb;
  v_seasons jsonb;
  v_tournaments jsonb;
  v_preference jsonb;
  v_active_season_id uuid;
  v_active_tournament_id uuid;
begin
  if private.current_identity_id() is null then raise exception using errcode='42501',message='TORNEOS_AUTH_REQUIRED'; end if;
  if not public.is_tournament_organization_member(p_organization_id) then
    raise exception using errcode='42501',message='TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  v_payload := public.get_tournament_competition_context_organization_legacy(p_organization_id);
  select coalesce(jsonb_agg(item order by item->>'updatedAt' desc),'[]'::jsonb) into v_seasons
  from jsonb_array_elements(v_payload->'seasons') item
  where public.has_tournament_season_access(p_organization_id,(item->>'id')::uuid);
  select coalesce(jsonb_agg(item order by item->>'updatedAt' desc),'[]'::jsonb) into v_tournaments
  from jsonb_array_elements(v_payload->'tournaments') item
  where public.has_tournament_season_access(p_organization_id,(item->>'seasonId')::uuid);
  v_preference := v_payload->'preference';
  v_active_season_id := nullif(v_preference->>'activeSeasonId','')::uuid;
  v_active_tournament_id := nullif(v_preference->>'activeTournamentId','')::uuid;
  if v_active_season_id is null or not public.has_tournament_season_access(p_organization_id,v_active_season_id) then
    select (item->>'id')::uuid into v_active_season_id from jsonb_array_elements(v_seasons) item limit 1;
    v_active_tournament_id := null;
  end if;
  if v_active_tournament_id is not null and not exists (
    select 1 from jsonb_array_elements(v_tournaments) item
    where (item->>'id')::uuid = v_active_tournament_id
  ) then v_active_tournament_id := null; end if;
  return v_payload || jsonb_build_object('seasons',v_seasons,'tournaments',v_tournaments,
    'preference',jsonb_build_object('organizationId',p_organization_id,
      'activeSeasonId',v_active_season_id,'activeTournamentId',v_active_tournament_id,
      'updatedAt',v_preference->'updatedAt'));
end;
$$;


--
-- Name: get_tournament_competition_context_organization_legacy(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_competition_context_organization_legacy(p_organization_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := private.current_identity_id();
  v_preference public.user_tournament_context_preferences%rowtype;
  v_effective_season_id uuid;
  v_effective_tournament_id uuid;
  v_seasons jsonb;
  v_tournaments jsonb;
  v_modalities jsonb;
  v_formats jsonb;
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(
    p_organization_id,
    'tournaments.read'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  select preference.* into v_preference
  from public.user_tournament_context_preferences preference
  where preference.user_id = v_user_id
    and preference.organization_id = p_organization_id;

  if v_preference.user_id is not null
    and (
      v_preference.active_season_id is null
      or exists (
        select 1 from public.tournament_seasons season
        where season.id = v_preference.active_season_id
          and season.organization_id = p_organization_id
          and season.status <> 'archived'
      )
    )
    and (
      v_preference.active_tournament_id is null
      or exists (
        select 1 from public.tournaments tournament
        where tournament.id = v_preference.active_tournament_id
          and tournament.organization_id = p_organization_id
          and tournament.season_id = v_preference.active_season_id
          and tournament.status <> 'archived'
      )
    )
  then
    v_effective_season_id := v_preference.active_season_id;
    v_effective_tournament_id := v_preference.active_tournament_id;
  else
    select tournament.season_id, tournament.id
    into v_effective_season_id, v_effective_tournament_id
    from public.tournaments tournament
    join public.tournament_seasons season on season.id = tournament.season_id
    where tournament.organization_id = p_organization_id
      and tournament.status <> 'archived'
      and season.status <> 'archived'
    order by tournament.updated_at desc, tournament.id
    limit 1;

    if v_effective_season_id is null then
      select season.id
      into v_effective_season_id
      from public.tournament_seasons season
      where season.organization_id = p_organization_id
        and season.status <> 'archived'
      order by season.updated_at desc, season.id
      limit 1;
      v_effective_tournament_id := null;
    end if;
  end if;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'code', modality.code,
      'name', modality.name,
      'teamSize', modality.team_size,
      'recommendedSubstitutes', modality.recommended_substitutes,
      'teamOfRoundSize', modality.team_of_round_size,
      'suggestedDurationMinutes', modality.suggested_duration_minutes,
      'requiresGoalkeeper', modality.requires_goalkeeper
    ) order by modality.team_size
  ), '[]'::jsonb)
  into v_modalities
  from public.tournament_sport_modalities modality;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'code', format.code,
      'name', format.name,
      'description', format.description
    ) order by case format.code
      when 'league' then 1
      when 'knockout' then 2
      when 'groups' then 3
      when 'groups_and_playoffs' then 4
      else 5
    end
  ), '[]'::jsonb)
  into v_formats
  from public.tournament_competition_formats format;

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', season.id,
      'organizationId', season.organization_id,
      'name', season.name,
      'slug', season.slug,
      'status', season.status,
      'startDate', season.start_date,
      'endDate', season.end_date,
      'createdAt', season.created_at,
      'updatedAt', season.updated_at
    ) order by season.updated_at desc, season.id
  ), '[]'::jsonb)
  into v_seasons
  from public.tournament_seasons season
  where season.organization_id = p_organization_id
    and season.status <> 'archived';

  select coalesce(jsonb_agg(
    jsonb_build_object(
      'id', tournament.id,
      'organizationId', tournament.organization_id,
      'seasonId', tournament.season_id,
      'name', tournament.name,
      'slug', tournament.slug,
      'description', tournament.description,
      'status', tournament.status,
      'sportModality', tournament.sport_modality,
      'competitionFormat', tournament.competition_format,
      'genderCategory', tournament.gender_category,
      'teamSize', tournament.team_size,
      'substitutesLimit', tournament.substitutes_limit,
      'startDate', tournament.start_date,
      'endDate', tournament.end_date,
      'registrationOpensAt', tournament.registration_opens_at,
      'registrationClosesAt', tournament.registration_closes_at,
      'formatSettings', tournament.format_settings,
      'createdAt', tournament.created_at,
      'updatedAt', tournament.updated_at,
      'categories', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', category.id,
          'name', category.name,
          'slug', category.slug,
          'description', category.description,
          'status', category.status,
          'sortOrder', category.sort_order,
          'minAge', category.min_age,
          'maxAge', category.max_age,
          'genderCategory', category.gender_category,
          'sportModality', category.sport_modality,
          'teamSize', category.team_size
        ) order by category.sort_order, category.created_at)
        from public.tournament_categories category
        where category.tournament_id = tournament.id
          and category.organization_id = p_organization_id
          and category.status = 'active'
      ), '[]'::jsonb),
      'scoring', (
        select jsonb_build_object(
          'pointsWin', scoring.points_win,
          'pointsDraw', scoring.points_draw,
          'pointsLoss', scoring.points_loss,
          'pointsWalkoverWin', scoring.points_walkover_win,
          'pointsWalkoverLoss', scoring.points_walkover_loss,
          'allowManualPointsAdjustment', scoring.allow_manual_points_adjustment,
          'allowAdministrativeResult', scoring.allow_administrative_result
        )
        from public.tournament_scoring_rules scoring
        where scoring.tournament_id = tournament.id
          and scoring.organization_id = p_organization_id
      ),
      'tiebreaks', coalesce((
        select jsonb_agg(tiebreak.criterion order by tiebreak.sort_order)
        from public.tournament_tiebreak_rules tiebreak
        where tiebreak.tournament_id = tournament.id
          and tiebreak.organization_id = p_organization_id
      ), '[]'::jsonb),
      'discipline', (
        select jsonb_build_object(
          'yellowsForSuspension', discipline.yellows_for_suspension,
          'suspensionMatches', discipline.suspension_matches,
          'directRedSuggestedMatches', discipline.direct_red_suggested_matches,
          'doubleYellowCountsAsRed', discipline.double_yellow_counts_as_red,
          'resetYellowsEachStage', discipline.reset_yellows_each_stage,
          'fairPlayEnabled', discipline.fair_play_enabled,
          'yellowFairPlayPoints', discipline.yellow_fair_play_points,
          'redFairPlayPoints', discipline.red_fair_play_points
        )
        from public.tournament_discipline_rules discipline
        where discipline.tournament_id = tournament.id
          and discipline.organization_id = p_organization_id
      ),
      'checklist', public.tournament_registration_checklist(
        p_organization_id,
        tournament.id
      )
    ) order by tournament.updated_at desc, tournament.id
  ), '[]'::jsonb)
  into v_tournaments
  from public.tournaments tournament
  join public.tournament_seasons season
    on season.id = tournament.season_id
    and season.organization_id = tournament.organization_id
  where tournament.organization_id = p_organization_id
    and tournament.status <> 'archived'
    and season.status <> 'archived';

  return jsonb_build_object(
    'preference', jsonb_build_object(
      'organizationId', p_organization_id,
      'activeSeasonId', v_effective_season_id,
      'activeTournamentId', v_effective_tournament_id,
      'updatedAt', v_preference.updated_at
    ),
    'seasons', v_seasons,
    'tournaments', v_tournaments,
    'modalities', v_modalities,
    'formats', v_formats
  );
end;
$$;


--
-- Name: get_tournament_creation_eligibility(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_creation_eligibility(p_organization_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.is_tournament_organization_member(p_organization_id) then
    raise exception using errcode = '42501', message = 'TORNEOS_PLAN_FORBIDDEN';
  end if;
  return jsonb_build_object(
    'schemaVersion',2,
    'organizationId',p_organization_id,
    'status','free_available',
    'commercialUnit','season',
    'hasConsumedFreeTournament',false
  );
end;
$$;


--
-- Name: get_tournament_fixture_context(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_fixture_context(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_is_manager boolean;
begin
  v_is_manager := not public.has_tournament_organization_capability(
    p_organization_id, 'fixture.read'
  );
  if private.current_identity_id() is null or not exists (
    select 1 from public.tournament_categories category
    join public.tournaments tournament
      on tournament.id = category.tournament_id
      and tournament.organization_id = category.organization_id
    join public.tournament_organizations organization
      on organization.id = category.organization_id
    where category.id = p_category_id
      and category.organization_id = p_organization_id
      and category.tournament_id = p_tournament_id
      and category.status = 'active'
      and tournament.status <> 'archived'
      and organization.status = 'active'
  ) or (
    v_is_manager and not exists (
      select 1
      from public.tournament_competition_participants participant
      join public.tournament_team_managers manager
        on manager.team_entry_id = participant.team_entry_id
        and manager.organization_id = participant.organization_id
      where participant.organization_id = p_organization_id
        and participant.tournament_id = p_tournament_id
        and participant.category_id = p_category_id
        and participant.status = 'active'
        and manager.user_id = private.current_identity_id()
        and manager.status = 'active'
        and not exists (
          select 1
          from public.tournament_organization_members blocked_membership
          where blocked_membership.organization_id = p_organization_id
            and blocked_membership.user_id = private.current_identity_id()
            and blocked_membership.status <> 'active'
        )
    )
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  return jsonb_build_object(
    'participantSet', (
      select jsonb_build_object(
        'id', participant_set.id,
        'versionNumber', participant_set.version_number,
        'status', participant_set.status,
        'participantFingerprint', participant_set.participant_fingerprint,
        'frozenAt', participant_set.frozen_at,
        'invalidatedAt', participant_set.invalidated_at
      )
      from public.tournament_participant_sets participant_set
      where participant_set.organization_id = p_organization_id
        and participant_set.tournament_id = p_tournament_id
        and participant_set.category_id = p_category_id
        and not v_is_manager
        and participant_set.status in ('frozen', 'reopened')
      order by participant_set.version_number desc limit 1
    ),
    'eligibleEntries', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', entry.id, 'name', entry.name, 'shortName', entry.short_name,
        'shieldPath', entry.shield_path, 'primaryColor', entry.primary_color,
        'secondaryColor', entry.secondary_color, 'status', entry.status,
        'categoryId', entry.category_id
      ) order by entry.name, entry.id)
      from public.tournament_team_entries entry
      where entry.organization_id = p_organization_id
        and entry.tournament_id = p_tournament_id
        and entry.category_id = p_category_id
        and entry.status in ('approved', 'withdrawn')
        and (
          not v_is_manager
          or public.is_tournament_team_manager(entry.id, false)
        )
    ), '[]'::jsonb),
    'participants', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', participant.id, 'teamEntryId', participant.team_entry_id,
        'name', participant.snapshot_name, 'shortName', participant.snapshot_short_name,
        'shieldPath', participant.snapshot_shield_path,
        'primaryColor', participant.snapshot_primary_color,
        'secondaryColor', participant.snapshot_secondary_color,
        'seedNumber', participant.seed_number, 'potNumber', participant.pot_number,
        'status', participant.status
      ) order by participant.seed_number nulls last, participant.snapshot_name, participant.id)
      from public.tournament_competition_participants participant
      join public.tournament_participant_sets participant_set
        on participant_set.id = participant.participant_set_id
      where participant.organization_id = p_organization_id
        and participant.tournament_id = p_tournament_id
        and participant.category_id = p_category_id
        and participant_set.status in ('frozen', 'reopened')
        and (
          not v_is_manager
          or public.is_tournament_team_manager(participant.team_entry_id, false)
        )
    ), '[]'::jsonb),
    'pots', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', pot.id, 'name', pot.name, 'number', pot.number,
        'sortOrder', pot.sort_order, 'status', pot.status,
        'members', coalesce((
          select jsonb_agg(jsonb_build_object(
            'participantId', member.participant_id, 'seedNumber', member.seed_number
          ) order by member.seed_number nulls last, member.participant_id)
          from public.tournament_draw_pot_members member where member.pot_id = pot.id
        ), '[]'::jsonb)
      ) order by pot.sort_order, pot.number)
      from public.tournament_draw_pots pot
      join public.tournament_participant_sets participant_set
        on participant_set.id = pot.participant_set_id
      where pot.organization_id = p_organization_id
        and pot.tournament_id = p_tournament_id
        and pot.category_id = p_category_id
        and not v_is_manager
        and pot.status = 'active' and participant_set.status = 'frozen'
    ), '[]'::jsonb),
    'groups', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', group_row.id, 'fixtureVersionId', group_row.fixture_version_id,
        'phaseId', group_row.phase_id, 'name', group_row.name, 'code', group_row.code,
        'sortOrder', group_row.sort_order, 'status', group_row.status,
        'drawSeed', group_row.draw_seed,
        'members', coalesce((
          select jsonb_agg(jsonb_build_object(
            'participantId', member.participant_id, 'positionSeed', member.position_seed
          ) order by member.position_seed nulls last, member.participant_id)
          from public.tournament_group_members member where member.group_id = group_row.id
        ), '[]'::jsonb)
      ) order by group_row.fixture_version_id nulls first, group_row.sort_order, group_row.code)
      from public.tournament_groups group_row
      where group_row.organization_id = p_organization_id
        and group_row.tournament_id = p_tournament_id
        and group_row.category_id = p_category_id
        and not v_is_manager
        and group_row.status <> 'archived'
    ), '[]'::jsonb),
    'versions', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', version.id, 'versionNumber', version.version_number,
        'status', version.status, 'generationMethod', version.generation_method,
        'seed', version.seed, 'configurationSnapshot', version.configuration_snapshot,
        'createdAt', version.created_at, 'publishedAt', version.published_at,
        'invalidatedAt', version.invalidated_at,
        'phaseCount', (select count(*) from public.tournament_phases phase
          where phase.fixture_version_id = version.id),
        'roundCount', (select count(*) from public.tournament_rounds round_row
          where round_row.fixture_version_id = version.id),
        'matchCount', (select count(*) from public.tournament_matches match_row
          where match_row.fixture_version_id = version.id),
        'scheduledCount', (select count(*) from public.tournament_matches match_row
          where match_row.fixture_version_id = version.id
            and match_row.status in ('scheduled', 'ready'))
      ) order by version.version_number desc)
      from public.tournament_fixture_versions version
      where version.organization_id = p_organization_id
        and version.tournament_id = p_tournament_id
        and version.category_id = p_category_id
        and version.status <> 'archived'
        and (
          not v_is_manager
          or exists (
            select 1
            from public.tournament_matches match_row
            where match_row.fixture_version_id = version.id
              and public.can_read_tournament_match(match_row.id)
          )
        )
    ), '[]'::jsonb),
    'phases', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', phase.id, 'fixtureVersionId', phase.fixture_version_id,
        'name', phase.name, 'phaseType', phase.phase_type,
        'sequenceNumber', phase.sequence_number, 'status', phase.status,
        'configuration', phase.configuration
      ) order by phase.fixture_version_id, phase.sequence_number)
      from public.tournament_phases phase
      join public.tournament_fixture_versions version
        on version.id = phase.fixture_version_id
      where version.organization_id = p_organization_id
        and version.tournament_id = p_tournament_id
        and version.category_id = p_category_id
        and version.status <> 'archived'
        and (
          not v_is_manager
          or exists (
            select 1
            from public.tournament_matches match_row
            where match_row.phase_id = phase.id
              and public.can_read_tournament_match(match_row.id)
          )
        )
    ), '[]'::jsonb),
    'rounds', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', round_row.id, 'fixtureVersionId', round_row.fixture_version_id,
        'phaseId', round_row.phase_id, 'groupId', round_row.group_id,
        'roundNumber', round_row.round_number, 'name', round_row.name,
        'status', round_row.status, 'startsAt', round_row.starts_at,
        'endsAt', round_row.ends_at, 'sortOrder', round_row.sort_order
      ) order by round_row.fixture_version_id, round_row.sort_order, round_row.round_number)
      from public.tournament_rounds round_row
      join public.tournament_fixture_versions version
        on version.id = round_row.fixture_version_id
      where version.organization_id = p_organization_id
        and version.tournament_id = p_tournament_id
        and version.category_id = p_category_id
        and version.status <> 'archived'
        and (
          not v_is_manager
          or exists (
            select 1
            from public.tournament_matches match_row
            where match_row.round_id = round_row.id
              and public.can_read_tournament_match(match_row.id)
          )
        )
    ), '[]'::jsonb),
    'matches', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', match_row.id, 'fixtureVersionId', match_row.fixture_version_id,
        'phaseId', match_row.phase_id, 'groupId', match_row.group_id,
        'roundId', match_row.round_id, 'matchNumber', match_row.match_number,
        'legNumber', match_row.leg_number, 'tieKey', match_row.tie_key,
        'homeParticipantId', match_row.home_participant_id,
        'awayParticipantId', match_row.away_participant_id,
        'status', match_row.status, 'scheduledAt', match_row.scheduled_at,
        'cancellationReasonCode', match_row.cancellation_reason_code,
        'cancellationReasonText', match_row.cancellation_reason_text,
        'withdrawnParticipantId', match_row.withdrawn_participant_id,
        'venueId', match_row.venue_id, 'courtId', match_row.court_id,
        'durationMinutes', match_row.duration_minutes,
        'sources', coalesce((
          select jsonb_agg(jsonb_build_object(
            'side', source.side, 'type', source.source_type,
            'participantId', source.participant_id, 'matchId', source.source_match_id,
            'groupId', source.group_id, 'phaseId', source.source_phase_id,
            'tieKey', source.source_tie_key, 'positionNumber', source.position_number,
            'seedNumber', source.seed_number, 'rankNumber', source.rank_number
          ) order by source.side)
          from public.tournament_match_sources source where source.match_id = match_row.id
        ), '[]'::jsonb)
      ) order by match_row.fixture_version_id, match_row.match_number)
      from public.tournament_matches match_row
      join public.tournament_fixture_versions version
        on version.id = match_row.fixture_version_id
      where version.organization_id = p_organization_id
        and version.tournament_id = p_tournament_id
        and version.category_id = p_category_id
        and version.status <> 'archived'
        and (not v_is_manager or public.can_read_tournament_match(match_row.id))
    ), '[]'::jsonb)
  );
end;
$$;


--
-- Name: get_tournament_match_operation_context(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_match_operation_context(p_organization_id uuid, p_match_operation_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when not public.can_read_tournament_match_operation(p_organization_id, operation.match_id)
      then public.raise_tournament_match_error('TORNEOS_MATCH_FORBIDDEN')
    else jsonb_build_object(
      'operation', to_jsonb(operation),
      'outcome', to_jsonb(outcome),
      'score', to_jsonb(score),
      'players', coalesce((
        select jsonb_agg(to_jsonb(player) order by player.team_entry_id, player.lineup_status, player.display_name_snapshot)
        from public.tournament_match_operation_players player
        where player.match_operation_id = operation.id
      ), '[]'::jsonb),
      'events', coalesce((
        select jsonb_agg(to_jsonb(event) order by event.sequence_number)
        from public.tournament_match_events event
        where event.match_operation_id = operation.id
      ), '[]'::jsonb),
      'reviews', coalesce((
        select jsonb_agg(to_jsonb(review) order by review.requested_at)
        from public.tournament_match_reviews review
        where review.match_operation_id = operation.id
      ), '[]'::jsonb),
      'resumptions', coalesce((
        select jsonb_agg(to_jsonb(resumption) order by resumption.created_at)
        from public.tournament_match_resumptions resumption
        where resumption.match_operation_id = operation.id
      ), '[]'::jsonb)
    )
  end
  from public.tournament_match_operations operation
  left join public.tournament_match_outcomes outcome
    on outcome.match_operation_id = operation.id
  left join public.tournament_match_scores score
    on score.match_operation_id = operation.id
  where operation.id = p_match_operation_id
    and operation.organization_id = p_organization_id;
$$;


--
-- Name: get_tournament_match_operations_context(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_match_operations_context(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select case
    when not public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.read'
    ) then public.raise_tournament_match_error('TORNEOS_MATCH_FORBIDDEN')
    else jsonb_build_object(
      'matches', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', match_row.id,
          'categoryId', match_row.category_id,
          'fixtureVersionId', match_row.fixture_version_id,
          'roundId', match_row.round_id,
          'matchNumber', match_row.match_number,
          'scheduledAt', match_row.scheduled_at,
          'planningStatus', match_row.status,
          'cancellationReasonCode', match_row.cancellation_reason_code,
          'cancellationReasonText', match_row.cancellation_reason_text,
          'withdrawnParticipantId', match_row.withdrawn_participant_id,
          'venue', venue.name,
          'court', court.name,
          'homeTeamEntryId', teams.home_team_entry_id,
          'awayTeamEntryId', teams.away_team_entry_id,
          'homeName', home_entry.name,
          'awayName', away_entry.name,
          'homeSquadStatus', home_squad.status,
          'awaySquadStatus', away_squad.status,
          'operationId', operation.id,
          'operationVersion', operation.operation_version,
          'operationStatus', operation.status,
          'matchStatus', operation.match_status,
          'outcomeType', outcome.outcome_type,
          'officialOperationId', official_operation.id,
          'homeScore', official_score.home_score,
          'awayScore', official_score.away_score,
          'hasOpenCorrection', exists (
            select 1 from public.tournament_match_reviews review
            where review.match_operation_id in (
              operation.id, operation.source_operation_id
            )
              and review.review_type = 'correction' and review.status = 'open'
          )
        ) order by match_row.scheduled_at nulls last, match_row.match_number)
        from public.tournament_matches match_row
        join public.tournament_fixture_versions fixture
          on fixture.id = match_row.fixture_version_id and fixture.status = 'published'
        cross join lateral public.tournament_match_team_entries(match_row.id) teams
        join public.tournament_team_entries home_entry
          on home_entry.id = teams.home_team_entry_id
        join public.tournament_team_entries away_entry
          on away_entry.id = teams.away_team_entry_id
        left join public.tournament_venues venue on venue.id = match_row.venue_id
        left join public.tournament_courts court on court.id = match_row.court_id
        left join public.tournament_match_squads home_squad
          on home_squad.match_id = match_row.id
          and home_squad.team_entry_id = teams.home_team_entry_id
          and home_squad.status <> 'superseded'
        left join public.tournament_match_squads away_squad
          on away_squad.match_id = match_row.id
          and away_squad.team_entry_id = teams.away_team_entry_id
          and away_squad.status <> 'superseded'
        left join lateral (
          select candidate.*
          from public.tournament_match_operations candidate
          where candidate.match_id = match_row.id
            and candidate.status <> 'superseded'
          order by candidate.operation_version desc
          limit 1
        ) operation on true
        left join lateral (
          select candidate.id
          from public.tournament_match_operations candidate
          where candidate.match_id = match_row.id
            and candidate.status = 'official'
          order by candidate.operation_version desc
          limit 1
        ) official_operation on true
        left join public.tournament_match_outcomes outcome
          on outcome.match_operation_id = operation.id
        left join public.tournament_match_scores official_score
          on official_score.match_operation_id = official_operation.id
        where match_row.organization_id = p_organization_id
          and match_row.tournament_id = p_tournament_id
          and (p_category_id is null or match_row.category_id = p_category_id)
      ), '[]'::jsonb)
    )
  end;
$$;


--
-- Name: get_tournament_media_admin_context(uuid, uuid, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_media_admin_context(p_organization_id uuid, p_tournament_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 30, p_offset integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_result jsonb;
  v_can_handle_reports boolean;
  v_readiness jsonb;
begin
  if not public.has_tournament_media_capability(p_organization_id,'media.read') then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  if p_limit < 1 or p_limit > 100 or p_offset < 0 then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_FILTER_INVALID';
  end if;
  v_can_handle_reports := public.has_tournament_media_capability(
    p_organization_id,'media.handle_reports'
  );
  v_readiness := public.tournament_media_pipeline_readiness();
  select jsonb_build_object(
    'storage',jsonb_build_object(
      'bucket','tournament-media','private',true,
      'certified',(v_readiness->>'uploadReady')::boolean,
      'uploadReady',(v_readiness->>'uploadReady')::boolean,
      'requiresStagingGate',not (v_readiness->>'uploadReady')::boolean,
      'storageReady',v_readiness->'storageReady',
      'signerReady',v_readiness->'signerReady',
      'processorReady',v_readiness->'processorReady',
      'pixelDecodeReady',v_readiness->'pixelDecodeReady',
      'pixelTranscodeReady',v_readiness->'pixelTranscodeReady',
      'metadataSanitizationReady',v_readiness->'metadataSanitizationReady',
      'antivirusReady',v_readiness->'antivirusReady',
      'cleanupReady',v_readiness->'cleanupReady',
      'blockers',v_readiness->'blockers',
      'pixelTranscode',v_readiness->'pixelTranscode',
      'antivirusScanning',v_readiness->'antivirusScanning',
      'signedUrlTtlSeconds',v_readiness->'signedUrlTtlSeconds',
      'maxFileBytes',12582912,'maxPixels',36000000,
      'allowedMime',jsonb_build_array('image/jpeg','image/png','image/webp'),
      'maxBatchFiles',40
    ),
    'capabilities',to_jsonb(public.tournament_media_role_capabilities(membership.role)),
    'tournaments',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',tournament.id,'name',tournament.name,'seasonId',tournament.season_id,
        'status',tournament.status,'categories',(
          select coalesce(jsonb_agg(jsonb_build_object(
            'id',category.id,'name',category.name
          ) order by category.sort_order,category.name),'[]'::jsonb)
          from public.tournament_categories category
          where category.tournament_id = tournament.id and category.status = 'active'
        ),
        'matches',(
          select coalesce(jsonb_agg(jsonb_build_object(
            'id',match.id,'categoryId',match.category_id,
            'roundId',match.round_id,'matchNumber',match.match_number,
            'scheduledAt',match.scheduled_at,'status',match.status
          ) order by match.scheduled_at nulls last,match.match_number),'[]'::jsonb)
          from public.tournament_matches match
          join public.tournament_fixture_versions fixture
            on fixture.id = match.fixture_version_id
          where match.tournament_id = tournament.id
            and match.status <> 'cancelled'
            and fixture.status = 'published'
            and fixture.invalidated_at is null
        )
      ) order by tournament.updated_at desc)
      from public.tournaments tournament
      where tournament.organization_id = p_organization_id
        and tournament.status <> 'archived'
        and (p_tournament_id is null or tournament.id = p_tournament_id)
    ),'[]'::jsonb),
    'galleries',coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',gallery.id,'tournamentId',gallery.tournament_id,
        'categoryId',gallery.category_id,'roundId',gallery.round_id,
        'matchId',gallery.match_id,'title',gallery.title,
        'description',gallery.description,'status',gallery.status,
        'visibility',gallery.visibility,'coverAssetId',gallery.cover_asset_id,
        'minorRestriction',gallery.minor_restriction,'version',gallery.version,
        'createdAt',gallery.created_at,'updatedAt',gallery.updated_at,
        'publishedAt',gallery.published_at,
        'assets',(
          select coalesce(jsonb_agg(jsonb_build_object(
            'id',asset.id,'safeName',asset.safe_name,
            'mime',asset.detected_mime,'byteSize',asset.byte_size,
            'width',asset.width,'height',asset.height,'status',asset.status,
            'sortOrder',item.sort_order,'caption',item.caption,
            'uploadedAt',asset.created_at,
            'variantsReady',(
              select count(*)
              from public.tournament_media_variants variant
              where variant.asset_id = asset.id
                and variant.kind in ('thumbnail','grid','detail','original')
                and variant.status = 'ready'
                and variant.metadata_stripped
            )
          ) order by item.sort_order),'[]'::jsonb)
          from public.tournament_media_gallery_items item
          join public.tournament_media_assets asset on asset.id = item.asset_id
          where item.gallery_id = gallery.id
        ),
        'reportCount',case when v_can_handle_reports then (
          select count(*) from public.tournament_media_reports report
          where report.gallery_id = gallery.id and report.status in ('open','under_review')
        ) else 0 end
      ) order by gallery.updated_at desc)
      from (
        select *
        from public.tournament_media_galleries gallery_page
        where gallery_page.organization_id = p_organization_id
          and (p_tournament_id is null or gallery_page.tournament_id = p_tournament_id)
          and (p_status is null or gallery_page.status = p_status)
        order by gallery_page.updated_at desc
        limit p_limit offset p_offset
      ) gallery
    ),'[]'::jsonb),
    'reports',case when v_can_handle_reports then coalesce((
      select jsonb_agg(jsonb_build_object(
        'id',report.id,'galleryId',report.gallery_id,'assetId',report.asset_id,
        'reason',report.reason,'detail',report.detail,
        'requestHide',report.request_hide,'status',report.status,
        'createdAt',report.created_at
      ) order by report.created_at desc)
      from public.tournament_media_reports report
      where report.organization_id = p_organization_id
        and report.status in ('open','under_review')
        and (p_tournament_id is null or report.tournament_id = p_tournament_id)
    ),'[]'::jsonb) else '[]'::jsonb end
  ) into v_result
  from public.tournament_organization_members membership
  where membership.organization_id = p_organization_id
    and membership.user_id = private.current_identity_id() and membership.status = 'active';
  return coalesce(v_result,'{}'::jsonb);
end;
$$;


--
-- Name: get_tournament_media_asset_processing_tiers(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_media_asset_processing_tiers(p_organization_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF private.current_identity_id() IS NULL THEN
    RAISE EXCEPTION USING errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  END IF;
  IF NOT public.has_tournament_media_capability(p_organization_id,'media.read') THEN
    RAISE EXCEPTION USING errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  END IF;
  RETURN coalesce((
    SELECT jsonb_object_agg(asset.id::text,asset.processing_tier)
    FROM public.tournament_media_assets asset
    WHERE asset.organization_id = p_organization_id
  ),'{}'::jsonb);
END;
$$;


--
-- Name: get_tournament_media_upload_capability(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_media_upload_capability(p_organization_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF private.current_identity_id() IS NULL THEN
    RAISE EXCEPTION USING errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  END IF;
  IF NOT public.has_tournament_media_capability(p_organization_id,'media.read') THEN
    RAISE EXCEPTION USING errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  END IF;
  RETURN public.tournament_media_effective_readiness();
END;
$$;


--
-- Name: get_tournament_participant_hub(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_participant_hub(p_tournament_id uuid, p_category_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tournament record;
  v_category_id uuid;
  v_fixture_id uuid;
  v_revision_id uuid;
  v_phase_id uuid;
  v_group_id uuid;
  v_my_team_id uuid;
  v_my_player_id uuid;
  v_manager_role text;
  v_organization_role text;
  v_is_historical boolean := false;
  v_can_read_team_private boolean := false;
  v_result jsonb;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;

  select
    tournament.id,
    tournament.organization_id,
    tournament.season_id,
    tournament.name,
    tournament.description,
    tournament.status,
    tournament.sport_modality,
    tournament.competition_format,
    tournament.start_date,
    tournament.end_date,
    season.name season_name,
    season.status season_status,
    organization.name organization_name,
    organization.logo_path
  into v_tournament
  from public.tournaments tournament
  join public.tournament_seasons season
    on season.organization_id = tournament.organization_id
   and season.id = tournament.season_id
  join public.tournament_organizations organization
    on organization.id = tournament.organization_id
   and organization.status = 'active'
  where tournament.id = p_tournament_id;

  if v_tournament.id is null
    or not public.can_read_tournament_participant_hub(p_tournament_id, null)
  then
    raise exception using errcode = '42501', message = 'TORNEOS_HUB_FORBIDDEN';
  end if;

  select membership.role
  into v_organization_role
  from public.tournament_organization_members membership
  where membership.organization_id = v_tournament.organization_id
    and membership.user_id = private.current_identity_id()
    and membership.status = 'active';

  if p_category_id is not null then
    if not public.can_read_tournament_participant_hub(
      p_tournament_id,
      p_category_id
    ) then
      raise exception using errcode = '42501', message = 'TORNEOS_HUB_FORBIDDEN';
    end if;
    v_category_id := p_category_id;
  else
    select preference.category_id
    into v_category_id
    from public.tournament_participant_hub_preferences preference
    where preference.user_id = private.current_identity_id()
      and preference.tournament_id = p_tournament_id
      and public.can_read_tournament_participant_hub(
        p_tournament_id,
        preference.category_id
      );

    if v_category_id is null then
      select entry.category_id
      into v_category_id
      from public.tournament_team_entries entry
      left join public.get_my_current_tournament_roster_players() player
        on player.team_entry_id = entry.id
      left join public.tournament_team_managers manager
        on manager.organization_id = entry.organization_id
       and manager.team_entry_id = entry.id
       and manager.user_id = private.current_identity_id()
       and manager.status = 'active'
       and manager.role in ('captain', 'delegate')
      where entry.organization_id = v_tournament.organization_id
        and entry.tournament_id = p_tournament_id
        and entry.status = 'approved'
        and (player.roster_player_id is not null or manager.id is not null)
      order by (player.roster_player_id is not null) desc, entry.name
      limit 1;
    end if;

    if v_category_id is null and v_organization_role is not null then
      select category.id
      into v_category_id
      from public.tournament_categories category
      where category.organization_id = v_tournament.organization_id
        and category.tournament_id = p_tournament_id
        and category.status = 'active'
      order by category.sort_order, category.name
      limit 1;
    end if;
  end if;

  if v_category_id is null
    or not public.can_read_tournament_participant_hub(
      p_tournament_id,
      v_category_id
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_HUB_FORBIDDEN';
  end if;

  select fixture.id
  into v_fixture_id
  from public.tournament_fixture_versions fixture
  where fixture.organization_id = v_tournament.organization_id
    and fixture.tournament_id = p_tournament_id
    and fixture.category_id = v_category_id
    and fixture.status = 'published';

  select entry.id, player.roster_player_id, manager.role
  into v_my_team_id, v_my_player_id, v_manager_role
  from public.tournament_team_entries entry
  left join public.get_my_current_tournament_roster_players() player
    on player.team_entry_id = entry.id
  left join public.tournament_team_managers manager
    on manager.organization_id = entry.organization_id
   and manager.team_entry_id = entry.id
   and manager.user_id = private.current_identity_id()
   and manager.status = 'active'
   and manager.role in ('captain', 'delegate')
  where entry.organization_id = v_tournament.organization_id
    and entry.tournament_id = p_tournament_id
    and entry.category_id = v_category_id
    and entry.status = 'approved'
    and (player.roster_player_id is not null or manager.id is not null)
  order by
    (player.roster_player_id is not null) desc,
    (manager.id is not null) desc,
    entry.name
  limit 1;

  v_is_historical := v_tournament.status in ('completed', 'archived')
    or v_tournament.season_status = 'archived';
  v_can_read_team_private := not v_is_historical
    and v_manager_role in ('captain', 'delegate');

  select revision.id, revision.phase_id, revision.group_id
  into v_revision_id, v_phase_id, v_group_id
  from public.tournament_standings_revisions revision
  join public.tournament_phases phase on phase.id = revision.phase_id
  where revision.fixture_version_id = v_fixture_id
    and revision.status = 'published'
  order by phase.sequence_number desc, revision.group_id nulls first,
    revision.revision_number desc
  limit 1;

  select jsonb_build_object(
    'tournament', jsonb_build_object(
      'id', v_tournament.id,
      'organizationId', v_tournament.organization_id,
      'organizationName', v_tournament.organization_name,
      'name', v_tournament.name,
      'description', v_tournament.description,
      'status', v_tournament.status,
      'seasonName', v_tournament.season_name,
      'seasonStatus', v_tournament.season_status,
      'sportModality', v_tournament.sport_modality,
      'competitionFormat', v_tournament.competition_format,
      'startDate', v_tournament.start_date,
      'endDate', v_tournament.end_date,
      'logoPath', v_tournament.logo_path,
      'readOnly', v_is_historical
    ),
    'audience', jsonb_build_object(
      'organizationRole', v_organization_role,
      'managerRole', v_manager_role,
      'isPlayer', v_my_player_id is not null,
      'canManageTournament', public.has_tournament_organization_capability(
        v_tournament.organization_id,
        'tournaments.update'
      ),
      'canManageTeam', v_can_read_team_private
    ),
    'categories', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', category.id,
        'name', category.name,
        'slug', category.slug,
        'description', category.description,
        'sportModality', coalesce(
          category.sport_modality,
          v_tournament.sport_modality
        ),
        'teamSize', category.team_size
      ) order by category.sort_order, category.name), '[]'::jsonb)
      from public.tournament_categories category
      where category.organization_id = v_tournament.organization_id
        and category.tournament_id = p_tournament_id
        and category.status = 'active'
        and (
          v_organization_role is not null
          or exists (
            select 1
            from public.tournament_team_entries entry
            left join public.get_my_current_tournament_roster_players() player
              on player.team_entry_id = entry.id
            left join public.tournament_team_managers manager
              on manager.organization_id = entry.organization_id
             and manager.team_entry_id = entry.id
             and manager.user_id = private.current_identity_id()
             and manager.status = 'active'
             and manager.role in ('captain', 'delegate')
            where entry.tournament_id = p_tournament_id
              and entry.category_id = category.id
              and entry.status = 'approved'
              and (
                player.roster_player_id is not null
                or manager.id is not null
              )
          )
        )
    ),
    'activeCategoryId', v_category_id,
    'competition', jsonb_build_object(
      'hasPublishedFixture', v_fixture_id is not null,
      'fixtureVersionId', v_fixture_id,
      'revisionId', v_revision_id,
      'phaseId', v_phase_id,
      'groupId', v_group_id,
      'phases', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'id', phase.id,
          'name', phase.name,
          'type', phase.phase_type,
          'sequence', phase.sequence_number,
          'status', phase.status
        ) order by phase.sequence_number), '[]'::jsonb)
        from public.tournament_phases phase
        where phase.fixture_version_id = v_fixture_id
          and phase.status <> 'archived'
      ),
      'groups', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'id', group_row.id,
          'phaseId', group_row.phase_id,
          'name', group_row.name,
          'code', group_row.code
        ) order by group_row.sort_order, group_row.code), '[]'::jsonb)
        from public.tournament_groups group_row
        where group_row.fixture_version_id = v_fixture_id
          and group_row.status = 'published'
      )
    ),
    'nextMatches', (
      select coalesce(jsonb_agg(match_payload order by scheduled_at nulls last, match_number), '[]'::jsonb)
      from (
        select
          match_row.scheduled_at,
          match_row.match_number,
          jsonb_build_object(
            'matchId', match_row.id,
            'matchNumber', match_row.match_number,
            'roundName', round_row.name,
            'scheduledAt', match_row.scheduled_at,
            'status', match_row.status,
            'venueName', venue.name,
            'courtName', court.name,
            'home', jsonb_build_object(
              'participantId', home.id,
              'teamEntryId', home.team_entry_id,
              'name', home.snapshot_name,
              'shortName', home.snapshot_short_name,
              'shieldPath', home.snapshot_shield_path
            ),
            'away', jsonb_build_object(
              'participantId', away.id,
              'teamEntryId', away.team_entry_id,
              'name', away.snapshot_name,
              'shortName', away.snapshot_short_name,
              'shieldPath', away.snapshot_shield_path
            ),
            'isMyTeam', v_my_team_id is not null and (
              home.team_entry_id = v_my_team_id
              or away.team_entry_id = v_my_team_id
            ),
            'myAvailability', case
              when v_is_historical then null
              else availability.response
            end,
            'myCallupStatus', case
              when v_is_historical then null
              else squad_player.callup_status
            end,
            'myLineupStatus', case
              when v_is_historical then null
              else squad_player.lineup_status
            end
          ) match_payload
        from public.tournament_matches match_row
        join public.tournament_rounds round_row on round_row.id = match_row.round_id
        left join public.tournament_competition_participants home
          on home.id = match_row.home_participant_id
        left join public.tournament_competition_participants away
          on away.id = match_row.away_participant_id
        left join public.tournament_venues venue on venue.id = match_row.venue_id
        left join public.tournament_courts court on court.id = match_row.court_id
        left join public.tournament_match_availability_responses availability
          on availability.match_id = match_row.id
         and availability.roster_player_id = v_my_player_id
        left join public.tournament_match_squads squad
          on squad.match_id = match_row.id
         and squad.team_entry_id = v_my_team_id
         and squad.status in ('submitted', 'locked')
        left join public.tournament_match_squad_players squad_player
          on squad_player.match_squad_id = squad.id
         and squad_player.roster_player_id = v_my_player_id
        where match_row.fixture_version_id = v_fixture_id
          and match_row.status in ('scheduled', 'ready', 'postponed')
          and (match_row.scheduled_at is null or match_row.scheduled_at >= now())
        order by match_row.scheduled_at nulls last, match_row.match_number
        limit 3
      ) matches
    ),
    'recentResults', (
      select coalesce(jsonb_agg(match_payload order by official_at desc), '[]'::jsonb)
      from (
        select
          operation.official_at,
          jsonb_build_object(
            'matchId', match_row.id,
            'roundName', round_row.name,
            'scheduledAt', match_row.scheduled_at,
            'officialAt', operation.official_at,
            'home', jsonb_build_object(
              'teamEntryId', home.team_entry_id,
              'name', home.snapshot_name,
              'shortName', home.snapshot_short_name
            ),
            'away', jsonb_build_object(
              'teamEntryId', away.team_entry_id,
              'name', away.snapshot_name,
              'shortName', away.snapshot_short_name
            ),
            'score', jsonb_build_object(
              'home', score.home_score,
              'away', score.away_score,
              'homePenalties', score.home_penalties,
              'awayPenalties', score.away_penalties
            ),
            'outcomeType', outcome.outcome_type,
            'isMyTeam', v_my_team_id is not null and (
              home.team_entry_id = v_my_team_id
              or away.team_entry_id = v_my_team_id
            )
          ) match_payload
        from public.tournament_matches match_row
        join public.tournament_rounds round_row on round_row.id = match_row.round_id
        join public.tournament_match_operations operation
          on operation.match_id = match_row.id
         and operation.status = 'official'
        join public.tournament_match_outcomes outcome
          on outcome.match_operation_id = operation.id
        left join public.tournament_match_scores score
          on score.match_operation_id = operation.id
        left join public.tournament_competition_participants home
          on home.id = match_row.home_participant_id
        left join public.tournament_competition_participants away
          on away.id = match_row.away_participant_id
        where match_row.fixture_version_id = v_fixture_id
        order by operation.official_at desc
        limit 3
      ) results
    ),
    'standings', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'position', standing.position,
        'participantId', standing.participant_id,
        'teamEntryId', standing.team_entry_id,
        'teamName', participant.snapshot_name,
        'shortName', participant.snapshot_short_name,
        'played', standing.played,
        'goalDifference', standing.goal_difference,
        'points', standing.points,
        'isMyTeam', standing.team_entry_id = v_my_team_id,
        'classificationStatus', standing.classification_status
      ) order by standing.position), '[]'::jsonb)
      from public.tournament_team_standings standing
      join public.tournament_competition_participants participant
        on participant.id = standing.participant_id
      where standing.revision_id = v_revision_id
        and standing.position <= 5
    ),
    'topScorers', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'rosterPlayerId', ranking.roster_player_id,
        'name', ranking.display_name,
        'teamEntryId', ranking.team_entry_id,
        'teamName', ranking.team_name,
        'goals', ranking.goals,
        'assists', ranking.assists,
        'appearances', ranking.appearances,
        'isMe', ranking.roster_player_id = v_my_player_id
      ) order by ranking.goals desc, ranking.assists desc, ranking.display_name), '[]'::jsonb)
      from (
        select
          statistic.roster_player_id,
          player.display_name,
          statistic.team_entry_id,
          entry.name team_name,
          statistic.goals,
          statistic.assists,
          statistic.appearances
        from public.tournament_player_statistics statistic
        join public.tournament_roster_players player
          on player.id = statistic.roster_player_id
        join public.tournament_team_entries entry
          on entry.id = statistic.team_entry_id
        where statistic.revision_id = v_revision_id
        order by statistic.goals desc, statistic.assists desc,
          player.display_name, statistic.roster_player_id
        limit 5
      ) ranking
    ),
    'myStatistics', (
      select jsonb_build_object(
        'appearances', statistic.appearances,
        'starts', statistic.starts,
        'goals', statistic.goals,
        'assists', statistic.assists,
        'yellowCards', statistic.yellow_cards,
        'redCards', statistic.red_cards + statistic.second_yellows
      )
      from public.tournament_player_statistics statistic
      where statistic.revision_id = v_revision_id
        and statistic.roster_player_id = v_my_player_id
    ),
    'mySuspensions', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', suspension.id,
        'sourceType', suspension.source_type,
        'reason', suspension.reason,
        'totalMatches', suspension.total_matches,
        'servedMatches', suspension.served_matches,
        'remainingMatches', greatest(
          suspension.total_matches - suspension.served_matches,
          0
        ),
        'status', suspension.status,
        'sourceMatchId', suspension.source_match_id
      ) order by suspension.created_at desc), '[]'::jsonb)
      from public.tournament_player_suspensions suspension
      join public.tournament_standings_revisions revision
        on revision.id = suspension.revision_id
       and revision.status = 'published'
      where suspension.tournament_id = p_tournament_id
        and suspension.category_id = v_category_id
        and suspension.roster_player_id = v_my_player_id
        and suspension.status in ('active', 'reduced', 'served')
    ),
    'myTeam', (
      select jsonb_build_object(
        'id', entry.id,
        'name', entry.name,
        'shortName', entry.short_name,
        'shieldPath', entry.shield_path,
        'primaryColor', entry.primary_color,
        'secondaryColor', entry.secondary_color,
        'managerRole', v_manager_role,
        'canManage', v_can_read_team_private,
        'roster', (
          select coalesce(jsonb_agg(jsonb_build_object(
            'id', player.id,
            'displayName', player.display_name,
            'shirtNumber', player.shirt_number,
            'primaryPosition', player.primary_position,
            'isGoalkeeper', player.is_goalkeeper,
            'isMe', player.id = v_my_player_id
          ) order by player.shirt_number nulls last, player.display_name), '[]'::jsonb)
          from public.tournament_rosters roster
          join public.tournament_roster_players player
            on player.roster_id = roster.id
           and player.status = 'active'
          where roster.team_entry_id = entry.id
            and roster.status in ('approved', 'locked')
            and roster.id = (
              select roster_latest.id
              from public.tournament_rosters roster_latest
              where roster_latest.team_entry_id = entry.id
                and roster_latest.status in ('approved', 'locked')
              order by roster_latest.version desc
              limit 1
            )
        ),
        'activeSuspensions', (
          select coalesce(jsonb_agg(jsonb_build_object(
            'rosterPlayerId', suspension.roster_player_id,
            'playerName', player.display_name,
            'reason', suspension.reason,
            'remainingMatches', greatest(
              suspension.total_matches - suspension.served_matches,
              0
            )
          ) order by player.display_name), '[]'::jsonb)
          from public.tournament_player_suspensions suspension
          join public.tournament_roster_players player
            on player.id = suspension.roster_player_id
          join public.tournament_standings_revisions revision
            on revision.id = suspension.revision_id
           and revision.status = 'published'
          where v_can_read_team_private
            and suspension.team_entry_id = entry.id
            and suspension.category_id = v_category_id
            and suspension.status in ('active', 'reduced')
        ),
        'nextMatchResponses', (
          select jsonb_build_object(
            'available', count(*) filter (where response.response = 'available'),
            'unavailable', count(*) filter (where response.response = 'unavailable'),
            'maybe', count(*) filter (where response.response = 'maybe'),
            'total', count(*)
          )
          from public.tournament_match_availability_responses response
          where v_can_read_team_private
            and response.team_entry_id = entry.id
            and response.match_id = (
              select next_match.id
              from public.tournament_matches next_match
              left join public.tournament_competition_participants home
                on home.id = next_match.home_participant_id
              left join public.tournament_competition_participants away
                on away.id = next_match.away_participant_id
              where next_match.fixture_version_id = v_fixture_id
                and next_match.status in ('scheduled', 'ready', 'postponed')
                and (home.team_entry_id = entry.id or away.team_entry_id = entry.id)
                and (
                  next_match.scheduled_at is null
                  or next_match.scheduled_at >= now()
                )
              order by next_match.scheduled_at nulls last, next_match.match_number
              limit 1
            )
        )
      )
      from public.tournament_team_entries entry
      where entry.id = v_my_team_id
    ),
    'alerts', (
      select coalesce(jsonb_agg(alert_payload order by priority, label), '[]'::jsonb)
      from (
        select
          1 priority,
          suspension.reason label,
          jsonb_build_object(
            'type', 'suspension',
            'label', suspension.reason,
            'detail', concat(
              greatest(suspension.total_matches - suspension.served_matches, 0),
              ' fecha(s) pendiente(s)'
            )
          ) alert_payload
        from public.tournament_player_suspensions suspension
        join public.tournament_standings_revisions revision
          on revision.id = suspension.revision_id
         and revision.status = 'published'
        where not v_is_historical
          and suspension.roster_player_id = v_my_player_id
          and suspension.category_id = v_category_id
          and suspension.status in ('active', 'reduced')
        union all
        select
          2 priority,
          'Convocatoria' label,
          jsonb_build_object(
            'type', 'callup',
            'label', 'Convocatoria actualizada',
            'detail', case squad_player.lineup_status
              when 'starter' then 'Figurás como titular.'
              when 'substitute' then 'Figurás como suplente.'
              else 'Consultá el estado de tu partido.'
            end
          )
        from public.tournament_match_squad_players squad_player
        join public.tournament_match_squads squad
          on squad.id = squad_player.match_squad_id
         and squad.status in ('submitted', 'locked')
        join public.tournament_matches match_row
          on match_row.id = squad.match_id
         and match_row.fixture_version_id = v_fixture_id
        where not v_is_historical
          and squad_player.roster_player_id = v_my_player_id
          and squad_player.callup_status = 'called_up'
          and (match_row.scheduled_at is null or match_row.scheduled_at >= now())
        order by priority
        limit 4
      ) alerts
    )
  )
  into v_result;

  return v_result;
end;
$$;


--
-- Name: get_tournament_participant_match(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_participant_match(p_match_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_match record;
  v_operation_id uuid;
  v_my_player_id uuid;
  v_my_team_id uuid;
  v_is_historical boolean := false;
  v_result jsonb;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;

  select
    match_row.id,
    match_row.tournament_id,
    match_row.category_id,
    match_row.match_number,
    match_row.status,
    match_row.scheduled_at,
    match_row.duration_minutes,
    round_row.name round_name,
    round_row.round_number,
    phase.name phase_name, group_row.name group_name,
    venue.name venue_name, venue.address venue_address, court.name court_name,
    home.team_entry_id home_team_entry_id, home.snapshot_name home_name,
    home.snapshot_short_name home_short_name,
    home.snapshot_shield_path home_shield_path,
    away.team_entry_id away_team_entry_id, away.snapshot_name away_name,
    away.snapshot_short_name away_short_name,
    away.snapshot_shield_path away_shield_path
  into v_match
  from public.tournament_matches match_row
  join public.tournament_fixture_versions fixture
    on fixture.id = match_row.fixture_version_id
   and fixture.status = 'published'
  join public.tournament_rounds round_row on round_row.id = match_row.round_id
  join public.tournament_phases phase on phase.id = match_row.phase_id
  left join public.tournament_groups group_row on group_row.id = match_row.group_id
  left join public.tournament_venues venue on venue.id = match_row.venue_id
  left join public.tournament_courts court on court.id = match_row.court_id
  left join public.tournament_competition_participants home
    on home.id = match_row.home_participant_id
  left join public.tournament_competition_participants away
    on away.id = match_row.away_participant_id
  where match_row.id = p_match_id;

  if v_match.id is null
    or not public.can_read_tournament_participant_hub(
      v_match.tournament_id,
      v_match.category_id
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_HUB_FORBIDDEN';
  end if;

  select
    tournament.status in ('completed', 'archived')
      or season.status = 'archived'
  into v_is_historical
  from public.tournaments tournament
  join public.tournament_seasons season
    on season.organization_id = tournament.organization_id
   and season.id = tournament.season_id
  where tournament.id = v_match.tournament_id;

  select player.roster_player_id, player.team_entry_id
  into v_my_player_id, v_my_team_id
  from public.get_my_current_tournament_roster_players() player
  where player.team_entry_id in (
      v_match.home_team_entry_id,
      v_match.away_team_entry_id
    )
  order by player.team_entry_id
  limit 1;

  select operation.id
  into v_operation_id
  from public.tournament_match_operations operation
  where operation.match_id = p_match_id
    and operation.status = 'official'
  limit 1;

  select jsonb_build_object(
    'matchId', v_match.id,
    'tournamentId', v_match.tournament_id,
    'categoryId', v_match.category_id,
    'matchNumber', v_match.match_number,
    'status', case when v_operation_id is not null then 'official' else v_match.status end,
    'scheduledAt', v_match.scheduled_at,
    'durationMinutes', v_match.duration_minutes,
    'round', jsonb_build_object(
      'number', v_match.round_number,
      'name', v_match.round_name
    ),
    'phaseName', v_match.phase_name,
    'groupName', v_match.group_name,
    'venue', case when v_match.venue_name is null then null else jsonb_build_object(
      'name', v_match.venue_name,
      'address', v_match.venue_address,
      'courtName', v_match.court_name
    ) end,
    'home', jsonb_build_object(
      'teamEntryId', v_match.home_team_entry_id,
      'name', v_match.home_name,
      'shortName', v_match.home_short_name,
      'shieldPath', v_match.home_shield_path
    ),
    'away', jsonb_build_object(
      'teamEntryId', v_match.away_team_entry_id,
      'name', v_match.away_name,
      'shortName', v_match.away_short_name,
      'shieldPath', v_match.away_shield_path
    ),
    'result', (
      select jsonb_build_object(
        'home', score.home_score,
        'away', score.away_score,
        'homePenalties', score.home_penalties,
        'awayPenalties', score.away_penalties,
        'outcomeType', outcome.outcome_type,
        'officialAt', operation.official_at
      )
      from public.tournament_match_operations operation
      join public.tournament_match_outcomes outcome
        on outcome.match_operation_id = operation.id
      left join public.tournament_match_scores score
        on score.match_operation_id = operation.id
      where operation.id = v_operation_id
    ),
    'officialEvents', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'id', event.id,
        'type', event.event_type,
        'minute', event.minute,
        'period', event.period,
        'teamEntryId', event.team_entry_id,
        'playerName', player.display_name_snapshot,
        'sequence', event.sequence_number
      ) order by event.sequence_number), '[]'::jsonb)
      from public.tournament_match_events event
      left join public.tournament_match_operation_players player
        on player.match_operation_id = event.match_operation_id
       and player.roster_player_id = event.roster_player_id
      join public.tournament_match_outcomes outcome
        on outcome.match_operation_id = event.match_operation_id
       and outcome.events_remain_valid
      where event.match_operation_id = v_operation_id
        and event.voided_at is null
        and event.event_type in (
          'goal', 'own_goal', 'assist', 'penalty_goal', 'penalty_missed',
          'yellow_card', 'second_yellow', 'red_card'
        )
    ),
    'officialLineups', (
      select coalesce(jsonb_agg(jsonb_build_object(
        'teamEntryId', player.team_entry_id,
        'rosterPlayerId', player.roster_player_id,
        'displayName', player.display_name_snapshot,
        'shirtNumber', player.shirt_number_snapshot,
        'position', player.position_snapshot,
        'lineupStatus', player.lineup_status,
        'isCaptain', player.is_captain
      ) order by player.team_entry_id, player.lineup_status, player.display_name_snapshot), '[]'::jsonb)
      from public.tournament_match_operation_players player
      where player.match_operation_id = v_operation_id
        and player.attendance_status in ('present', 'late')
        and player.lineup_status in ('starter', 'substitute')
    ),
    'myContext', case
      when v_my_player_id is null or v_is_historical then null
      else jsonb_build_object(
      'teamEntryId', v_my_team_id,
      'rosterPlayerId', v_my_player_id,
      'availability', (
        select response.response
        from public.tournament_match_availability_responses response
        where response.match_id = p_match_id
          and response.roster_player_id = v_my_player_id
      ),
      'callup', (
        select jsonb_build_object(
          'status', squad_player.callup_status,
          'lineupStatus', squad_player.lineup_status,
          'isCaptain', squad_player.is_captain,
          'attendanceStatus', case
            when v_operation_id is null then null
            else squad_player.attendance_status
          end
        )
        from public.tournament_match_squads squad
        join public.tournament_match_squad_players squad_player
          on squad_player.match_squad_id = squad.id
         and squad_player.roster_player_id = v_my_player_id
        where squad.match_id = p_match_id
          and squad.team_entry_id = v_my_team_id
          and squad.status in ('submitted', 'locked')
        limit 1
      ),
      'suspensions', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'id', suspension.id,
          'reason', suspension.reason,
          'remainingMatches', greatest(
            suspension.total_matches - suspension.served_matches,
            0
          ),
          'status', suspension.status
        ) order by suspension.created_at), '[]'::jsonb)
        from public.tournament_player_suspensions suspension
        join public.tournament_standings_revisions revision
          on revision.id = suspension.revision_id
         and revision.status = 'published'
        where suspension.roster_player_id = v_my_player_id
          and suspension.tournament_id = v_match.tournament_id
          and suspension.category_id = v_match.category_id
          and suspension.status in ('active', 'reduced')
      )
    ) end
  )
  into v_result;

  return v_result;
end;
$$;


--
-- Name: get_tournament_player_portrait_ref(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_player_portrait_ref(p_organization_id uuid, p_roster_player_id uuid, p_variant text DEFAULT 'original'::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_portrait_id uuid;
BEGIN
  IF private.current_identity_id() IS NULL OR p_variant <> 'original'
    OR NOT public.can_read_tournament_player_portrait(
      p_organization_id, p_roster_player_id
    )
  THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_PORTRAIT_FORBIDDEN';
  END IF;
  SELECT id INTO v_portrait_id FROM public.tournament_player_portraits
  WHERE organization_id = p_organization_id
    AND roster_player_id = p_roster_player_id
    AND lifecycle_status = 'active';
  IF v_portrait_id IS NULL THEN RETURN NULL; END IF;
  RETURN jsonb_build_object(
    'kind', 'player_portrait', 'id', v_portrait_id, 'variant', p_variant
  );
END;
$$;


--
-- Name: get_tournament_public_page_settings(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_public_page_settings(p_organization_id uuid, p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_page public.tournament_public_pages%ROWTYPE;
  v_eligible boolean := false;
  v_reason text := 'tournament_unavailable';
BEGIN
  IF private.current_identity_id() IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_AUTH_REQUIRED';
  END IF;
  IF NOT public.has_tournament_organization_capability(
    p_organization_id,
    'tournaments.read'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_RESOURCE_FORBIDDEN';
  END IF;

  SELECT
    organization.status = 'active'
      AND season.status <> 'archived'
      AND tournament.status IN ('registration', 'scheduled', 'active', 'completed'),
    CASE
      WHEN organization.status <> 'active' THEN 'organization_inactive'
      WHEN season.status = 'archived' THEN 'season_archived'
      WHEN tournament.status NOT IN ('registration', 'scheduled', 'active', 'completed')
        THEN 'tournament_not_publishable'
      ELSE NULL
    END
  INTO v_eligible, v_reason
  FROM public.tournaments tournament
  JOIN public.tournament_organizations organization
    ON organization.id = tournament.organization_id
  JOIN public.tournament_seasons season
    ON season.id = tournament.season_id
   AND season.organization_id = tournament.organization_id
  WHERE tournament.id = p_tournament_id
    AND tournament.organization_id = p_organization_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_RESOURCE_FORBIDDEN';
  END IF;

  SELECT page.*
  INTO v_page
  FROM public.tournament_public_pages page
  WHERE page.tournament_id = p_tournament_id
    AND page.organization_id = p_organization_id;

  RETURN jsonb_build_object(
    'published', COALESCE(v_page.status = 'published', false),
    'publicSlug', v_page.public_slug,
    'publicPath', CASE
      WHEN v_page.public_slug IS NULL THEN NULL
      ELSE '/torneos/publico/' || v_page.public_slug
    END,
    'publishedAt', v_page.published_at,
    'eligible', v_eligible,
    'unavailableReason', CASE WHEN v_eligible THEN NULL ELSE v_reason END
  );
END;
$$;


--
-- Name: get_tournament_purchase(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_purchase(p_purchase_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_purchase public.tournament_purchases%rowtype;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_purchase from public.tournament_purchases where id = p_purchase_id;
  if v_purchase.id is null or not (
    v_purchase.buyer_user_id = private.current_identity_id()
    or public.has_tournament_organization_capability(v_purchase.organization_id,'billing.manage')
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_PURCHASE_FORBIDDEN';
  end if;
  return public.tournament_purchase_projection(v_purchase);
end;
$$;


--
-- Name: get_tournament_schedule_context(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_schedule_context(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_is_manager boolean;
begin
  v_is_manager := not public.has_tournament_organization_capability(
    p_organization_id, 'fixture.read'
  );
  if private.current_identity_id() is null or not exists (
    select 1
    from public.tournament_categories category
    join public.tournaments tournament
      on tournament.id = category.tournament_id
      and tournament.organization_id = category.organization_id
    join public.tournament_organizations organization
      on organization.id = category.organization_id
    where category.id = p_category_id
      and category.organization_id = p_organization_id
      and category.tournament_id = p_tournament_id
      and category.status = 'active'
      and tournament.status <> 'archived'
      and organization.status = 'active'
  ) or (
    v_is_manager and not exists (
      select 1
      from public.tournament_matches match_row
      where match_row.organization_id = p_organization_id
        and match_row.tournament_id = p_tournament_id
        and match_row.category_id = p_category_id
        and public.can_read_tournament_match(match_row.id)
    )
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  return jsonb_build_object(
    'venues', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', venue.id, 'name', venue.name, 'address', venue.address,
        'placeId', venue.place_id, 'latitude', venue.latitude,
        'longitude', venue.longitude, 'locality', venue.locality,
        'timezone', venue.timezone, 'status', venue.status, 'notes', venue.notes
      ) order by venue.status, venue.name)
      from public.tournament_venues venue
      where venue.organization_id = p_organization_id
        and (
          not v_is_manager
          or exists (
            select 1
            from public.tournament_matches match_row
            where match_row.venue_id = venue.id
              and match_row.tournament_id = p_tournament_id
              and match_row.category_id = p_category_id
              and public.can_read_tournament_match(match_row.id)
          )
        )
    ), '[]'::jsonb),
    'courts', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', court.id, 'venueId', court.venue_id, 'name', court.name,
        'sportModality', court.sport_modality, 'status', court.status,
        'notes', court.notes
      ) order by court.status, court.name)
      from public.tournament_courts court
      where court.organization_id = p_organization_id
        and (
          not v_is_manager
          or exists (
            select 1
            from public.tournament_matches match_row
            where match_row.court_id = court.id
              and match_row.tournament_id = p_tournament_id
              and match_row.category_id = p_category_id
              and public.can_read_tournament_match(match_row.id)
          )
        )
    ), '[]'::jsonb),
    'windows', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', schedule_window.id, 'categoryId', schedule_window.category_id,
        'venueId', schedule_window.venue_id, 'courtId', schedule_window.court_id,
        'dayOfWeek', schedule_window.day_of_week,
        'specificDate', schedule_window.specific_date,
        'startsAt', schedule_window.starts_at, 'endsAt', schedule_window.ends_at,
        'slotDurationMinutes', schedule_window.slot_duration_minutes,
        'bufferMinutes', schedule_window.buffer_minutes,
        'windowType', schedule_window.window_type,
        'status', schedule_window.status, 'notes', schedule_window.notes
      ) order by schedule_window.status, schedule_window.specific_date nulls last,
        schedule_window.day_of_week, schedule_window.starts_at)
      from public.tournament_schedule_windows schedule_window
      where schedule_window.organization_id = p_organization_id
        and schedule_window.tournament_id = p_tournament_id
        and not v_is_manager
    ), '[]'::jsonb),
    'reschedules', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', reschedule.id, 'matchId', reschedule.match_id,
        'previousScheduledAt', reschedule.previous_scheduled_at,
        'newScheduledAt', reschedule.new_scheduled_at,
        'previousVenueId', reschedule.previous_venue_id,
        'newVenueId', reschedule.new_venue_id,
        'previousCourtId', reschedule.previous_court_id,
        'newCourtId', reschedule.new_court_id,
        'reason', reschedule.reason, 'previousStatus', reschedule.previous_status,
        'newStatus', reschedule.new_status, 'createdAt', reschedule.created_at
      ) order by reschedule.created_at desc)
      from public.tournament_match_reschedules reschedule
      join public.tournament_matches match_row on match_row.id = reschedule.match_id
      where reschedule.organization_id = p_organization_id
        and reschedule.tournament_id = p_tournament_id
        and reschedule.category_id = p_category_id
        and public.can_read_tournament_match(match_row.id)
    ), '[]'::jsonb)
  );
end;
$$;


--
-- Name: get_tournament_season_media_usage(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_season_media_usage(p_organization_id uuid, p_season_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_policy jsonb; v_assets integer; v_pending integer; v_limit integer;
begin
  if not public.has_tournament_season_access(p_organization_id,p_season_id) then
    raise exception using errcode='42501',message='TORNEOS_MEDIA_FORBIDDEN';
  end if;
  v_policy:=public.resolve_effective_tournament_season_entitlements_at(
    p_organization_id,p_season_id,now(),false,null
  );
  select count(*)::integer into v_assets
  from public.tournament_media_assets asset join public.tournaments tournament
    on tournament.organization_id=asset.organization_id and tournament.id=asset.tournament_id
  where asset.organization_id=p_organization_id and tournament.season_id=p_season_id
    and asset.status not in ('rejected','revoked','failed') and asset.storage_state<>'storage_purged';
  select count(*)::integer into v_pending
  from public.tournament_media_upload_sessions session join public.tournaments tournament
    on tournament.organization_id=session.organization_id and tournament.id=session.tournament_id
  where session.organization_id=p_organization_id and tournament.season_id=p_season_id
    and session.status in ('issued','uploaded') and session.expires_at>now();
  v_limit:=(v_policy->'media'->>'galleryAssetLimit')::integer;
  return jsonb_build_object('schemaVersion',1,'organizationId',p_organization_id,
    'seasonId',p_season_id,'plan',v_policy->>'plan','assetCount',v_assets,
    'pendingCount',v_pending,'usage',v_assets+v_pending,'limit',v_limit,
    'remaining',greatest(v_limit-v_assets-v_pending,0));
end;
$$;


--
-- Name: get_tournament_social_snapshot(uuid, uuid, uuid, uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_social_snapshot(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_phase_id uuid, p_piece text, p_round_id uuid DEFAULT NULL::uuid, p_group_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_season_id uuid; v_policy jsonb; v_snapshot jsonb;
begin
  select season_id into v_season_id from public.tournaments
  where organization_id=p_organization_id and id=p_tournament_id;
  if v_season_id is null or not public.has_tournament_season_access(p_organization_id,v_season_id) then
    raise exception using errcode='42501',message='TORNEOS_SOCIAL_FORBIDDEN';
  end if;
  v_policy:=public.resolve_effective_tournament_season_entitlements_at(
    p_organization_id,v_season_id,now(),false,p_tournament_id
  );
  -- Snapshot access is preview/catalog access. Export authorization below is
  -- the product gate; FREE may inspect all eleven families without gaining use.
  v_snapshot:=public.get_tournament_social_snapshot_plan_legacy(
    p_organization_id,p_tournament_id,p_category_id,p_phase_id,p_piece,p_round_id,p_group_id
  );
  return v_snapshot || jsonb_build_object('seasonId',v_season_id,
    'plan',v_policy->>'plan','social',v_policy->'social','branding',v_policy->'branding');
end;
$$;


--
-- Name: get_tournament_social_snapshot_plan_legacy(uuid, uuid, uuid, uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_social_snapshot_plan_legacy(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_phase_id uuid, p_piece text, p_round_id uuid DEFAULT NULL::uuid, p_group_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_scope jsonb;
  v_official jsonb;
  v_standings jsonb;
  v_statistics jsonb;
  v_player_candidates jsonb;
  v_next_fixture jsonb;
  v_round_name text;
  v_round_number integer;
  v_effective_round_id uuid;
  v_sport_modality text;
  v_team_size smallint;
  v_pieces text[] := ARRAY[
    'next_fixture','round_results','standings','scorers','discipline',
    'best_eleven','mvp','round_summary','semifinals','final','champion'
  ];
BEGIN
  IF NOT public.has_tournament_social_capability(p_organization_id, 'social.read') THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_SOCIAL_FORBIDDEN';
  END IF;
  IF p_piece IS NULL OR NOT (p_piece = ANY(v_pieces)) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TORNEOS_SOCIAL_PIECE_INVALID';
  END IF;

  v_scope := public.tournament_social_published_scope(
    p_organization_id, p_tournament_id, p_category_id, p_phase_id
  );
  IF v_scope IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_SOCIAL_SCOPE_UNAVAILABLE';
  END IF;

  SELECT coalesce(category.sport_modality, tournament.sport_modality),
    coalesce(category.team_size, tournament.team_size)
  INTO v_sport_modality, v_team_size
  FROM public.tournaments tournament
  JOIN public.tournament_categories category
    ON category.id = p_category_id
   AND category.tournament_id = tournament.id
   AND category.organization_id = tournament.organization_id
  WHERE tournament.id = p_tournament_id
    AND tournament.organization_id = p_organization_id;

  IF v_sport_modality IS NULL OR v_team_size IS NULL
    OR v_team_size <> ALL(ARRAY[5,6,7,8,9,11]::smallint[])
    OR NOT EXISTS (
      SELECT 1 FROM public.tournament_sport_modalities modality
      WHERE modality.code = v_sport_modality AND modality.team_size = v_team_size
    )
  THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TORNEOS_SOCIAL_TEAM_FORMAT_INVALID';
  END IF;

  IF p_piece = 'next_fixture' THEN
    v_next_fixture := public.tournament_social_next_fixture(
      (v_scope->>'fixtureVersionId')::uuid, p_phase_id, p_group_id
    );
    v_effective_round_id := (v_next_fixture->>'roundId')::uuid;
    v_round_name := v_next_fixture->>'roundName';
    v_round_number := (v_next_fixture->>'roundNumber')::integer;
  ELSE
    v_effective_round_id := p_round_id;
    IF p_round_id IS NOT NULL THEN
      SELECT round.name, round.round_number
      INTO v_round_name, v_round_number
      FROM public.tournament_rounds round
      WHERE round.id = p_round_id
        AND round.fixture_version_id = (v_scope->>'fixtureVersionId')::uuid
        AND round.phase_id = p_phase_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_SOCIAL_SCOPE_UNAVAILABLE';
      END IF;
    END IF;
  END IF;

  IF p_piece IN ('standings','round_summary','champion') THEN
    v_standings := public.get_published_tournament_standings(
      p_tournament_id, p_category_id, p_phase_id, p_group_id
    );
  END IF;
  IF p_piece IN ('scorers','discipline','best_eleven','mvp','round_summary') THEN
    v_statistics := public.get_published_tournament_statistics(
      p_tournament_id, p_category_id, p_phase_id, p_group_id
    );
  END IF;
  IF p_piece IN ('best_eleven','mvp') THEN
    v_player_candidates := public.tournament_social_player_candidates(
      (v_scope->>'fixtureVersionId')::uuid,
      coalesce(v_statistics->'players', '[]'::jsonb)
    );
  END IF;

  v_official := CASE p_piece
    WHEN 'next_fixture' THEN jsonb_build_object(
      'semantics', v_next_fixture->>'semantics',
      'matches', coalesce(v_next_fixture->'matches', '[]'::jsonb)
    )
    WHEN 'round_results' THEN jsonb_build_object(
      'matches', public.tournament_social_match_rows(
        (v_scope->>'fixtureVersionId')::uuid, p_phase_id, p_round_id, true
      )
    )
    WHEN 'semifinals' THEN jsonb_build_object(
      'matches', public.tournament_social_match_rows(
        (v_scope->>'fixtureVersionId')::uuid, p_phase_id, p_round_id, false
      )
    )
    WHEN 'final' THEN jsonb_build_object(
      'matches', public.tournament_social_match_rows(
        (v_scope->>'fixtureVersionId')::uuid, p_phase_id, p_round_id, false
      )
    )
    WHEN 'standings' THEN jsonb_build_object(
      'revision', v_standings->'revision',
      'rows', coalesce(v_standings->'standings', '[]'::jsonb)
    )
    WHEN 'scorers' THEN jsonb_build_object(
      'revisionId', v_statistics->'revisionId',
      'players', coalesce((
        SELECT jsonb_agg(player)
        FROM jsonb_array_elements(coalesce(v_statistics->'players','[]'::jsonb)) player
        WHERE (player->>'goals')::integer > 0
      ), '[]'::jsonb)
    )
    WHEN 'discipline' THEN jsonb_build_object(
      'revisionId', v_statistics->'revisionId',
      'players', coalesce((
        SELECT jsonb_agg(player)
        FROM jsonb_array_elements(coalesce(v_statistics->'discipline','[]'::jsonb)) player
        WHERE (player->>'fairPlayPoints')::integer > 0
      ), '[]'::jsonb)
    )
    WHEN 'round_summary' THEN jsonb_build_object(
      'matches', public.tournament_social_match_rows(
        (v_scope->>'fixtureVersionId')::uuid, p_phase_id, p_round_id, true
      ),
      'leaders', coalesce((
        SELECT jsonb_agg(player)
        FROM jsonb_array_elements(coalesce(v_statistics->'players','[]'::jsonb)) player
        WHERE (player->>'goals')::integer > 0
        LIMIT 5
      ), '[]'::jsonb),
      'topOfTable', coalesce(v_standings->'standings'->0, 'null'::jsonb)
    )
    WHEN 'best_eleven' THEN jsonb_build_object(
      'requiresHumanSelection', true,
      'sportModality', v_sport_modality,
      'teamSize', v_team_size,
      'candidates', v_player_candidates
    )
    WHEN 'mvp' THEN jsonb_build_object(
      'requiresHumanSelection', true,
      'candidates', v_player_candidates
    )
    WHEN 'champion' THEN jsonb_build_object(
      'requiresHumanSelection', true,
      'officialChampion', (
        SELECT jsonb_build_object(
          'participantId', standing->>'participantId',
          'teamName', standing->>'teamName',
          'shortName', standing->>'shortName',
          'shieldPath', standing->>'shieldPath'
        )
        FROM jsonb_array_elements(coalesce(v_standings->'standings','[]'::jsonb)) standing
        WHERE (standing->>'position')::integer = 1
          AND EXISTS (
            SELECT 1 FROM public.tournaments tournament
            WHERE tournament.id = p_tournament_id AND tournament.status = 'completed'
          )
        LIMIT 1
      ),
      'candidates', coalesce(v_standings->'standings', '[]'::jsonb)
    )
  END;

  RETURN jsonb_build_object(
    'schemaVersion', 2,
    'piece', p_piece,
    'generatedAt', now(),
    'source', jsonb_build_object(
      'organizationId', p_organization_id,
      'tournamentId', p_tournament_id,
      'categoryId', p_category_id,
      'phaseId', p_phase_id,
      'groupId', p_group_id,
      'roundId', v_effective_round_id,
      'fixtureVersionId', v_scope->>'fixtureVersionId',
      'standingsRevisionId', coalesce(
        v_standings->'revision'->>'id', v_statistics->>'revisionId'
      ),
      'standingsRevisionNumber', v_standings->'revision'->>'number'
    ),
    'competition', jsonb_build_object(
      'organizationName', v_scope->>'organizationName',
      'tournamentName', v_scope->>'tournamentName',
      'categoryName', v_scope->>'categoryName',
      'phaseName', v_scope->>'phaseName',
      'roundName', v_round_name,
      'roundNumber', v_round_number,
      'sportModality', v_sport_modality,
      'teamSize', v_team_size
    ),
    'official', coalesce(v_official, '{}'::jsonb),
    'capabilities', to_jsonb(
      public.current_user_tournament_social_capabilities(p_organization_id)
    )
  );
END;
$$;


--
-- Name: get_tournament_social_studio_context(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_social_studio_context(p_organization_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_payload jsonb; v_tournaments jsonb;
begin
  v_payload:=public.get_tournament_social_studio_context_organization_legacy(p_organization_id);
  select coalesce(jsonb_agg(item),'[]'::jsonb) into v_tournaments
  from jsonb_array_elements(v_payload->'tournaments') item
  join public.tournaments tournament on tournament.id=(item->>'id')::uuid
  where tournament.organization_id=p_organization_id
    and public.has_tournament_season_access(p_organization_id,tournament.season_id);
  return v_payload || jsonb_build_object('tournaments',v_tournaments,
    'commercialUnit','season','freeBaseFamilies',
    jsonb_build_array('round_results','standings','next_fixture'));
end;
$$;


--
-- Name: get_tournament_social_studio_context_organization_legacy(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_social_studio_context_organization_legacy(p_organization_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_capabilities text[];
begin
  v_capabilities := public.current_user_tournament_social_capabilities(p_organization_id);
  if not ('social.read' = any(v_capabilities)) then
    raise exception using errcode = '42501', message = 'TORNEOS_SOCIAL_FORBIDDEN';
  end if;
  return jsonb_build_object(
    'capabilities', to_jsonb(v_capabilities),
    'brand', jsonb_build_object(
      'organizationName', (
        select name from public.tournament_organizations
        where id = p_organization_id
      ),
      'canHideArma2Logo', 'social.brand_toggle' = any(v_capabilities)
    ),
    'tournaments', coalesce((
      select jsonb_agg(jsonb_build_object(
        'id', tournament.id,
        'name', tournament.name,
        'status', tournament.status,
        'categories', (
          select coalesce(jsonb_agg(jsonb_build_object(
            'id', category.id,
            'name', category.name,
            'phases', (
              select coalesce(jsonb_agg(jsonb_build_object(
                'id', phase.id,
                'name', phase.name,
                'kind', phase.phase_type,
                'fixtureVersionId', fixture.id,
                'rounds', (
                  select coalesce(jsonb_agg(jsonb_build_object(
                    'id', round.id, 'name', round.name,
                    'number', round.round_number, 'startsAt', round.starts_at
                  ) order by round.round_number), '[]'::jsonb)
                  from public.tournament_rounds round
                  where round.phase_id = phase.id
                    and round.fixture_version_id = fixture.id
                )
              ) order by phase.sequence_number), '[]'::jsonb)
              from public.tournament_phases phase
              where phase.fixture_version_id = fixture.id
                and phase.status <> 'archived'
            )
          ) order by category.sort_order, category.name), '[]'::jsonb)
          from public.tournament_categories category
          join public.tournament_fixture_versions fixture
            on fixture.category_id = category.id
           and fixture.status = 'published'
           and fixture.invalidated_at is null
          where category.tournament_id = tournament.id
            and category.status = 'active'
        )
      ) order by tournament.updated_at desc)
      from public.tournaments tournament
      where tournament.organization_id = p_organization_id
        and tournament.status <> 'archived'
    ), '[]'::jsonb)
  );
end;
$$;


--
-- Name: get_tournament_standings_context(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_standings_context(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_phase_id uuid, p_group_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_revision public.tournament_standings_revisions%rowtype;
  v_can_manage boolean;
begin
  if private.current_identity_id() is null or not public.can_read_tournament_projection_scope(
    p_organization_id, p_tournament_id
  ) or not exists (
    select 1
    from public.tournament_categories category
    where category.id = p_category_id
      and category.organization_id = p_organization_id
      and category.tournament_id = p_tournament_id
      and category.status = 'active'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_STANDINGS_FORBIDDEN';
  end if;
  v_can_manage := public.has_tournament_organization_capability(
    p_organization_id, 'standings.rebuild'
  );
  select * into v_revision
  from public.tournament_standings_revisions
  where organization_id = p_organization_id and tournament_id = p_tournament_id
    and category_id = p_category_id and phase_id = p_phase_id
    and group_id is not distinct from p_group_id
    and (status = 'published' or (v_can_manage and status = 'draft'))
  order by case status when 'draft' then 0 else 1 end, revision_number desc
  limit 1;

  return jsonb_build_object(
    'canManage', v_can_manage,
    'revision', case
      when v_revision.id is null then null
      when v_can_manage then jsonb_build_object(
        'id', v_revision.id, 'number', v_revision.revision_number,
        'status', v_revision.status, 'calculatedAt', v_revision.calculated_at,
        'publishedAt', v_revision.published_at, 'reason', v_revision.rebuild_reason,
        'sourceFingerprint', v_revision.source_fingerprint
      )
      else jsonb_build_object(
        'id', v_revision.id, 'number', v_revision.revision_number,
        'status', v_revision.status, 'calculatedAt', v_revision.calculated_at,
        'publishedAt', v_revision.published_at
      )
    end,
    'standings', coalesce((
      select jsonb_agg(jsonb_build_object(
        'position', standing.position, 'participantId', standing.participant_id,
        'teamEntryId', standing.team_entry_id, 'teamName', participant.snapshot_name,
        'participantStatus', participant.status,
        'withdrawnAt', participant.withdrawn_at,
        'withdrawalReasonCode', participant.withdrawal_reason_code,
        'shortName', participant.snapshot_short_name,
        'shieldPath', participant.snapshot_shield_path,
        'played', standing.played, 'won', standing.won, 'drawn', standing.drawn,
        'lost', standing.lost, 'goalsFor', standing.goals_for,
        'goalsAgainst', standing.goals_against,
        'goalDifference', standing.goal_difference, 'points', standing.points,
        'pointsAdjustment', standing.points_adjustment,
        'walkovers', standing.walkovers,
        'administrativeResults', standing.administrative_results,
        'fairPlayPoints', standing.fair_play_points,
        'classificationStatus', standing.classification_status,
        'tiebreakTrace', standing.tiebreak_trace
      ) order by standing.position)
      from public.tournament_team_standings standing
      join public.tournament_competition_participants participant
        on participant.id = standing.participant_id
      where standing.revision_id = v_revision.id
    ), '[]'::jsonb)
  );
end;
$$;


--
-- Name: get_tournament_statistics_context(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_statistics_context(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_phase_id uuid, p_group_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_revision_id uuid;
  v_can_manage boolean;
begin
  if private.current_identity_id() is null or not public.can_read_tournament_projection_scope(
    p_organization_id, p_tournament_id
  ) or not exists (
    select 1
    from public.tournament_categories category
    where category.id = p_category_id
      and category.organization_id = p_organization_id
      and category.tournament_id = p_tournament_id
      and category.status = 'active'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_STATISTICS_FORBIDDEN';
  end if;
  v_can_manage := public.has_tournament_organization_capability(
    p_organization_id, 'statistics.rebuild'
  );
  select id into v_revision_id
  from public.tournament_standings_revisions
  where organization_id = p_organization_id and tournament_id = p_tournament_id
    and category_id = p_category_id and phase_id = p_phase_id
    and group_id is not distinct from p_group_id
    and (status = 'published' or (v_can_manage and status = 'draft'))
  order by case status when 'draft' then 0 else 1 end, revision_number desc limit 1;

  return jsonb_build_object(
    'revisionId', v_revision_id,
    'canManage', v_can_manage,
    'players', coalesce((
      select jsonb_agg(jsonb_build_object(
        'rosterPlayerId', stats.roster_player_id, 'teamEntryId', stats.team_entry_id,
        'name', player.display_name, 'avatarUrl', player.avatar_url,
        'goals', stats.goals, 'ownGoals', stats.own_goals,
        'assists', stats.assists, 'appearances', stats.appearances,
        'starts', stats.starts, 'substituteAppearances', stats.substitute_appearances,
        'yellowCards', stats.yellow_cards, 'secondYellows', stats.second_yellows,
        'redCards', stats.red_cards, 'captaincies', stats.captaincies
      ) order by stats.goals desc, stats.assists desc, player.display_name)
      from public.tournament_player_statistics stats
      join public.tournament_roster_players player on player.id = stats.roster_player_id
      where stats.revision_id = v_revision_id
    ), '[]'::jsonb),
    'teams', coalesce((
      select jsonb_agg(jsonb_build_object(
        'participantId', stats.participant_id, 'teamEntryId', stats.team_entry_id,
        'name', participant.snapshot_name, 'shieldPath', participant.snapshot_shield_path,
        'goals', stats.goals, 'yellowCards', stats.yellow_cards,
        'secondYellows', stats.second_yellows, 'redCards', stats.red_cards,
        'homePlayed', stats.home_played, 'awayPlayed', stats.away_played,
        'administrativeMatches', stats.administrative_matches
      ) order by stats.goals desc, participant.snapshot_name)
      from public.tournament_team_statistics stats
      join public.tournament_competition_participants participant
        on participant.id = stats.participant_id
      where stats.revision_id = v_revision_id
    ), '[]'::jsonb),
    'discipline', coalesce((
      select jsonb_agg(jsonb_build_object(
        'rosterPlayerId', ledger.roster_player_id,
        'teamEntryId', ledger.team_entry_id,
        'name', player.display_name,
        'yellowCards', ledger.yellow_cards,
        'secondYellows', ledger.second_yellows,
        'directReds', ledger.direct_reds,
        'fairPlayPoints', ledger.fair_play_points,
        'automaticSuspensions', ledger.automatic_suspensions,
        'suspensions', coalesce((
          select jsonb_agg(jsonb_build_object(
            'id', suspension.id, 'sourceType', suspension.source_type,
            'totalMatches', suspension.total_matches,
            'servedMatches', suspension.served_matches,
            'status', suspension.status, 'reason', suspension.reason
          ) order by suspension.created_at)
          from public.tournament_player_suspensions suspension
          where suspension.revision_id = ledger.revision_id
            and suspension.roster_player_id = ledger.roster_player_id
        ), '[]'::jsonb)
      ) order by ledger.fair_play_points desc, player.display_name)
      from public.tournament_discipline_ledgers ledger
      join public.tournament_roster_players player
        on player.id = ledger.roster_player_id
      where ledger.revision_id = v_revision_id
    ), '[]'::jsonb)
  );
end;
$$;


--
-- Name: get_tournament_team_photo_state(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_team_photo_state(p_organization_id uuid, p_team_entry_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_actor uuid := private.current_identity_id();
  v_can_manage boolean;
  v_can_moderate boolean;
  v_current public.tournament_team_photos%ROWTYPE;
  v_candidate public.tournament_team_photos%ROWTYPE;
BEGIN
  IF v_actor IS NULL OR NOT public.can_read_tournament_team_photo_as(
    p_organization_id, p_team_entry_id, v_actor
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_TEAM_PHOTO_FORBIDDEN';
  END IF;
  v_can_manage := public.can_manage_tournament_team_visual_assets_as(
    p_organization_id, p_team_entry_id, v_actor, 'team_entries.update');
  v_can_moderate := public.can_moderate_tournament_team_visual_assets_as(
    p_organization_id, p_team_entry_id, v_actor, 'team_entries.update');

  SELECT * INTO v_current FROM public.tournament_team_photos photo
  WHERE photo.organization_id = p_organization_id
    AND photo.team_entry_id = p_team_entry_id
    AND photo.lifecycle_status = 'active'
    AND photo.editorial_status = 'approved';

  IF v_can_manage OR v_can_moderate THEN
    SELECT * INTO v_candidate FROM public.tournament_team_photos photo
    WHERE photo.organization_id = p_organization_id
      AND photo.team_entry_id = p_team_entry_id
      AND photo.lifecycle_status = 'active'
      AND photo.editorial_status IN ('pending_review', 'rejected');
  END IF;

  RETURN jsonb_build_object(
    'organizationId', p_organization_id,
    'teamEntryId', p_team_entry_id,
    'canManage', v_can_manage,
    'canModerate', v_can_moderate,
    'current', CASE WHEN v_current.id IS NULL THEN NULL ELSE jsonb_build_object(
      'teamPhotoId', v_current.id,
      'ref', jsonb_build_object(
        'kind', 'team_photo', 'id', v_current.id, 'variant', 'original'),
      'width', v_current.width, 'height', v_current.height,
      'approvedAt', v_current.approved_at, 'updatedAt', v_current.updated_at
    ) END,
    'candidate', CASE WHEN v_candidate.id IS NULL THEN NULL ELSE jsonb_build_object(
      'teamPhotoId', v_candidate.id,
      'ref', jsonb_build_object(
        'kind', 'team_photo', 'id', v_candidate.id, 'variant', 'original'),
      'width', v_candidate.width, 'height', v_candidate.height,
      'editorialStatus', v_candidate.editorial_status,
      'reviewReason', v_candidate.review_reason,
      'createdAt', v_candidate.created_at, 'updatedAt', v_candidate.updated_at
    ) END
  );
END;
$$;


--
-- Name: get_tournament_team_visual_policy(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_team_visual_policy(p_organization_id uuid, p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_policy text;
BEGIN
  IF private.current_identity_id() IS NULL
    OR NOT public.has_tournament_organization_capability(
      p_organization_id, 'tournaments.read'
    )
  THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_RESOURCE_FORBIDDEN';
  END IF;

  SELECT tournament.team_visual_management_policy
  INTO v_policy
  FROM public.tournaments tournament
  WHERE tournament.id = p_tournament_id
    AND tournament.organization_id = p_organization_id
    AND tournament.status <> 'archived';

  IF v_policy IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_RESOURCE_FORBIDDEN';
  END IF;

  RETURN jsonb_build_object(
    'organizationId', p_organization_id,
    'tournamentId', p_tournament_id,
    'policy', v_policy,
    -- Quien sólo puede leer ve la política pero no el control.
    'canUpdate', public.has_tournament_organization_capability(
      p_organization_id, 'tournaments.update'
    )
  );
END;
$$;


--
-- Name: get_tournament_teams_context(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_teams_context(p_organization_id uuid, p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_result jsonb;
BEGIN
  IF private.current_identity_id() IS NULL
    OR NOT public.has_tournament_organization_capability(
      p_organization_id,
      'team_entries.read'
    )
  THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_RESOURCE_FORBIDDEN';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.tournaments
    WHERE id = p_tournament_id
      AND organization_id = p_organization_id
      AND status <> 'archived'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_RESOURCE_FORBIDDEN';
  END IF;

  SELECT jsonb_build_object(
    'tournamentId', p_tournament_id,
    'settings', COALESCE((
      SELECT jsonb_build_object(
        'minimumPlayers', minimum_players,
        'maximumPlayers', maximum_players,
        'shirtNumberRequired', shirt_number_required,
        'uniqueShirtNumbers', unique_shirt_numbers,
        'positionRequired', position_required,
        'minimumGoalkeepers', minimum_goalkeepers,
        'allowProvisionalPlayers', allow_provisional_players,
        'allowPlayerMultipleTeams', allow_player_multiple_teams,
        'rosterOpensAt', roster_opens_at,
        'rosterClosesAt', roster_closes_at
      )
      FROM public.tournament_roster_settings
      WHERE tournament_id = p_tournament_id
    ), '{}'::jsonb),
    'entries', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'id', entry.id,
        'name', entry.name,
        'shortName', entry.short_name,
        'shieldPath', entry.shield_path,
        'primaryColor', entry.primary_color,
        'secondaryColor', entry.secondary_color,
        'categoryId', entry.category_id,
        'categoryName', category.name,
        'arma2TeamId', entry.arma2_team_id,
        'linked', entry.arma2_team_id IS NOT NULL,
        'status', entry.status,
        'registrationSource', entry.registration_source,
        'submittedAt', entry.submitted_at,
        'updatedAt', entry.updated_at,
        'manager', (
          SELECT jsonb_build_object(
            'displayName', manager.display_name,
            'role', manager.role,
            'status', manager.status
          )
          FROM public.tournament_team_managers manager
          WHERE manager.team_entry_id = entry.id
            AND manager.status <> 'revoked'
          ORDER BY (manager.role = 'captain') DESC, manager.created_at
          LIMIT 1
        ),
        'roster', (
          SELECT jsonb_build_object(
            'id', roster.id,
            'version', roster.version,
            'status', roster.status,
            'playerCount', (
              SELECT count(*)
              FROM public.tournament_roster_players player
              WHERE player.roster_id = roster.id AND player.status = 'active'
            ),
            'goalkeeperCount', (
              SELECT count(*)
              FROM public.tournament_roster_players player
              WHERE player.roster_id = roster.id
                AND player.status = 'active'
                AND player.is_goalkeeper
            )
          )
          FROM public.tournament_rosters roster
          WHERE roster.team_entry_id = entry.id
          ORDER BY roster.version DESC
          LIMIT 1
        ),
        'hasObservations', EXISTS (
          SELECT 1
          FROM public.tournament_team_reviews review
          WHERE review.team_entry_id = entry.id
            AND review.decision = 'changes_requested'
        )
      ) ORDER BY category.sort_order, entry.name)
      FROM public.tournament_team_entries entry
      JOIN public.tournament_categories category ON category.id = entry.category_id
      WHERE entry.organization_id = p_organization_id
        AND entry.tournament_id = p_tournament_id
        AND entry.status <> 'archived'
    ), '[]'::jsonb)
  ) INTO v_result;
  RETURN v_result;
END;
$$;


--
-- Name: get_tournament_workspace_context(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tournament_workspace_context() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := private.current_identity_id();
  v_preference public.user_workspace_preferences%rowtype;
  v_effective_workspace_type text;
  v_effective_organization_id uuid;
  v_organizations jsonb;
begin
  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'TORNEOS_AUTH_REQUIRED';
  end if;

  select preference.*
  into v_preference
  from public.user_workspace_preferences preference
  where preference.user_id = v_user_id;

  if v_preference.user_id is null
    or (
      v_preference.workspace_type = 'tournament_organization'
      and not public.has_tournament_organization_capability(
        v_preference.active_organization_id,
        'workspace.access'
      )
    )
  then
    v_effective_workspace_type := 'personal';
    v_effective_organization_id := null;
  else
    v_effective_workspace_type := v_preference.workspace_type;
    v_effective_organization_id := v_preference.active_organization_id;
  end if;

  select coalesce(
    jsonb_agg(
      jsonb_build_object(
        'id', organization.id,
        'name', organization.name,
        'slug', organization.slug,
        'logoPath', organization.logo_path,
        'status', organization.status,
        'createdAt', organization.created_at,
        'role', membership.role,
        'membershipStatus', membership.status,
        'joinedAt', membership.joined_at,
        'capabilities', to_jsonb(
          public.tournament_role_capabilities(membership.role)
        )
      )
      order by lower(organization.name), organization.id
    ),
    '[]'::jsonb
  )
  into v_organizations
  from public.tournament_organization_members membership
  join public.tournament_organizations organization
    on organization.id = membership.organization_id
  where membership.user_id = v_user_id
    and membership.status = 'active'
    and organization.status = 'active';

  return jsonb_build_object(
    'preference', jsonb_build_object(
      'workspaceType', v_effective_workspace_type,
      'activeOrganizationId', v_effective_organization_id,
      'updatedAt', v_preference.updated_at
    ),
    'organizations', v_organizations
  );
end;
$$;


--
-- Name: grant_tournament_premium(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_tournament_premium(p_organization_id uuid, p_tournament_id uuid, p_source text, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_grant_id uuid;
BEGIN
  IF p_source NOT IN ('purchase','legacy_grant')
    OR p_reason IS NULL
    OR p_reason <> btrim(p_reason)
    OR char_length(p_reason) NOT BETWEEN 8 AND 500
    OR NOT EXISTS (
      SELECT 1 FROM public.tournaments tournament
      WHERE tournament.organization_id = p_organization_id
        AND tournament.id = p_tournament_id
    )
  THEN
    RAISE EXCEPTION USING errcode = '22023', message = 'TORNEOS_PLAN_GRANT_INVALID';
  END IF;

  INSERT INTO public.tournament_plan_grants (
    organization_id,tournament_id,plan_code,source,reason
  ) VALUES (
    p_organization_id,p_tournament_id,'PREMIUM',p_source,p_reason
  )
  ON CONFLICT (organization_id,tournament_id,plan_code,source) DO UPDATE SET
    reason = public.tournament_plan_grants.reason
  RETURNING id INTO v_grant_id;
  RETURN v_grant_id;
END;
$$;


--
-- Name: grant_tournament_season_premium(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.grant_tournament_season_premium(p_organization_id uuid, p_season_id uuid, p_purchase_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_grant_id uuid;
begin
  if p_purchase_id is null or p_reason is null or p_reason <> btrim(p_reason)
    or char_length(p_reason) not between 8 and 500
    or not exists (
      select 1 from public.tournament_seasons season
      where season.organization_id = p_organization_id and season.id = p_season_id
    ) then
    raise exception using errcode = '22023', message = 'TORNEOS_SEASON_PLAN_GRANT_INVALID';
  end if;
  insert into public.tournament_season_plan_grants (
    organization_id,season_id,plan_code,source,origin_purchase_id,reason
  ) values (
    p_organization_id,p_season_id,'PREMIUM','purchase',p_purchase_id,p_reason
  )
  on conflict (origin_purchase_id) do update set reason = public.tournament_season_plan_grants.reason
  returning id into v_grant_id;
  return v_grant_id;
end;
$$;


--
-- Name: handle_tournament_media_report(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_tournament_media_report(p_report_id uuid, p_status text, p_resolution text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_report public.tournament_media_reports%rowtype;
begin
  select * into v_report
  from public.tournament_media_reports where id = p_report_id for update;
  if v_report.id is null or not public.has_tournament_media_capability(
    v_report.organization_id,'media.handle_reports'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  if p_status not in ('under_review','resolved','dismissed') then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_REPORT_INVALID';
  end if;
  if v_report.status = p_status then
    return jsonb_build_object('reportId',p_report_id,'status',p_status);
  end if;
  if v_report.status not in ('open','under_review')
    or (v_report.status = 'under_review' and p_status = 'under_review')
  then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_REPORT_INVALID';
  end if;
  update public.tournament_media_reports
  set status = p_status,
      handled_by = case when p_status in ('resolved','dismissed') then private.current_identity_id() else null end,
      handled_at = case when p_status in ('resolved','dismissed') then now() else null end,
      resolution = case when p_status in ('resolved','dismissed')
        then nullif(btrim(p_resolution),'') else resolution end
  where id = p_report_id;
  perform public.append_tournament_audit(
    v_report.organization_id,'media.report.' || p_status,'media_report',
    p_report_id,null,v_report.tournament_id,jsonb_build_object('status',p_status)
  );
  return jsonb_build_object('reportId',p_report_id,'status',p_status);
end;
$$;


--
-- Name: has_organization_consumed_free_tournament(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_organization_consumed_free_tournament(p_organization_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF private.current_identity_id() IS NULL THEN
    RAISE EXCEPTION USING errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  END IF;
  IF NOT public.is_tournament_organization_member(p_organization_id) THEN
    RAISE EXCEPTION USING errcode = '42501', message = 'TORNEOS_PLAN_FORBIDDEN';
  END IF;
  RETURN EXISTS (
    SELECT 1 FROM public.tournament_organization_plan_state state
    WHERE state.organization_id = p_organization_id
  );
END;
$$;


