    select event.event_type not in ('suspended','revoked')
    from public.tournament_season_plan_grant_events event
    where event.season_grant_id = p_grant_id
    order by event.id desc limit 1
  ),true);
$$;


--
-- Name: is_tournament_team_manager(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_tournament_team_manager(p_team_entry_id uuid, p_require_edit boolean DEFAULT false) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select private.current_identity_id() is not null and exists (
    select 1
    from public.tournament_team_managers manager
    join public.tournament_team_entries entry on entry.id = manager.team_entry_id
    join public.tournament_organizations organization on organization.id = entry.organization_id
    join public.tournaments tournament on tournament.id = entry.tournament_id
    join public.tournament_categories category
      on category.id = entry.category_id
      and category.organization_id = entry.organization_id
      and category.tournament_id = entry.tournament_id
    where manager.team_entry_id = p_team_entry_id
      and manager.user_id = private.current_identity_id()
      and manager.status = 'active'
      and organization.status = 'active'
      and tournament.status <> 'archived'
      and category.status = 'active'
      and entry.status <> 'archived'
      and (
        not p_require_edit
        or (
          manager.role in ('captain', 'delegate')
          and entry.status in ('draft', 'invited', 'in_progress', 'changes_requested')
        )
      )
  );
$$;


--
-- Name: is_tournament_team_roster_member_as(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_tournament_team_roster_member_as(p_team_entry_id uuid, p_actor_user_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT p_actor_user_id IS NOT NULL AND EXISTS (
    SELECT 1
    FROM public.tournament_roster_players player
    WHERE player.team_entry_id = p_team_entry_id
      AND player.status = 'active'
      AND player.roster_id = (
        SELECT roster.id
        FROM public.tournament_rosters roster
        WHERE roster.team_entry_id = p_team_entry_id
          AND roster.status <> 'superseded'
        ORDER BY roster.version DESC
        LIMIT 1
      )
      AND (
        player.arma2_user_id = p_actor_user_id
        OR EXISTS (
          SELECT 1
          FROM public.tournament_provisional_players provisional
          WHERE provisional.organization_id = player.organization_id
            AND provisional.id = player.provisional_player_id
            AND provisional.claim_status = 'claimed'
            AND provisional.claimed_by_user_id = p_actor_user_id
        )
      )
  );
$$;


--
-- Name: FUNCTION is_tournament_team_roster_member_as(p_team_entry_id uuid, p_actor_user_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.is_tournament_team_roster_member_as(p_team_entry_id uuid, p_actor_user_id uuid) IS 'Vínculo autenticable entre un usuario y el plantel vigente de un equipo: fila activa en la última versión no superseded del roster, con cuenta Arma2 vinculada o provisional reclamado.';


--
-- Name: is_valid_tournament_format_settings(text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_valid_tournament_format_settings(p_format text, p_settings jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
begin
  if jsonb_typeof(p_settings) <> 'object' then
    return false;
  end if;

  case p_format
    when 'league' then
      if not (
        p_settings ?& array['rounds', 'qualifiers']
        and not exists (
          select 1 from jsonb_object_keys(p_settings) key
          where key not in ('rounds', 'qualifiers')
        )
        and jsonb_typeof(p_settings->'rounds') = 'string'
        and jsonb_typeof(p_settings->'qualifiers') = 'number'
      ) then
        return false;
      end if;
      return p_settings->>'rounds' in ('single', 'double')
        and (p_settings->>'qualifiers')::integer between 0 and 64;
    when 'knockout' then
      if not (
        p_settings ?& array['legs', 'thirdPlace']
        and not exists (
          select 1 from jsonb_object_keys(p_settings) key
          where key not in ('legs', 'thirdPlace')
        )
        and jsonb_typeof(p_settings->'legs') = 'string'
        and jsonb_typeof(p_settings->'thirdPlace') = 'boolean'
      ) then
        return false;
      end if;
      return p_settings->>'legs' in ('single', 'double')
        and (p_settings->>'thirdPlace')::boolean in (true, false);
    when 'groups' then
      if not (
        p_settings ?& array['groupCount', 'qualifiersPerGroup', 'rounds']
        and not exists (
          select 1 from jsonb_object_keys(p_settings) key
          where key not in ('groupCount', 'qualifiersPerGroup', 'rounds')
        )
        and jsonb_typeof(p_settings->'groupCount') = 'number'
        and jsonb_typeof(p_settings->'qualifiersPerGroup') = 'number'
        and jsonb_typeof(p_settings->'rounds') = 'string'
      ) then
        return false;
      end if;
      return (p_settings->>'groupCount')::integer between 2 and 32
        and (p_settings->>'qualifiersPerGroup')::integer between 1 and 16
        and p_settings->>'rounds' in ('single', 'double');
    when 'groups_and_playoffs' then
      if not (
        p_settings ?& array[
          'groupCount',
          'qualifiersPerGroup',
          'groupRounds',
          'knockoutLegs'
        ]
        and not exists (
          select 1 from jsonb_object_keys(p_settings) key
          where key not in (
            'groupCount',
            'qualifiersPerGroup',
            'groupRounds',
            'knockoutLegs'
          )
        )
        and jsonb_typeof(p_settings->'groupCount') = 'number'
        and jsonb_typeof(p_settings->'qualifiersPerGroup') = 'number'
        and jsonb_typeof(p_settings->'groupRounds') = 'string'
        and jsonb_typeof(p_settings->'knockoutLegs') = 'string'
      ) then
        return false;
      end if;
      return (p_settings->>'groupCount')::integer between 2 and 32
        and (p_settings->>'qualifiersPerGroup')::integer between 1 and 16
        and p_settings->>'groupRounds' in ('single', 'double')
        and p_settings->>'knockoutLegs' in ('single', 'double');
    when 'league_and_playoffs' then
      if not (
        p_settings ?& array['leagueRounds', 'qualifiers', 'knockoutLegs']
        and not exists (
          select 1 from jsonb_object_keys(p_settings) key
          where key not in ('leagueRounds', 'qualifiers', 'knockoutLegs')
        )
        and jsonb_typeof(p_settings->'leagueRounds') = 'string'
        and jsonb_typeof(p_settings->'qualifiers') = 'number'
        and jsonb_typeof(p_settings->'knockoutLegs') = 'string'
      ) then
        return false;
      end if;
      return p_settings->>'leagueRounds' in ('single', 'double')
        and (p_settings->>'qualifiers')::integer between 2 and 64
        and p_settings->>'knockoutLegs' in ('single', 'double');
    else
      return false;
  end case;
exception
  when invalid_text_representation or numeric_value_out_of_range then
    return false;
end;
$$;


--
-- Name: lease_tournament_media_processing_jobs(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lease_tournament_media_processing_jobs(p_worker_id text, p_lease_seconds integer DEFAULT 300, p_limit integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_leases jsonb;
begin
  if p_worker_id is null or p_worker_id !~ '^[a-z0-9][a-z0-9._:-]{2,60}$'
    or p_lease_seconds is null or p_lease_seconds < 30 or p_lease_seconds > 1800
    or p_limit is null or p_limit < 1 or p_limit > 20
  then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_FILTER_INVALID';
  end if;
  -- Leasing is deliberately NOT readiness-gated: when readiness collapses the
  -- worker still has to be able to drain the queue and purge what it wrote.
  with candidate as (
    select job.id
    from public.tournament_media_processing_jobs job
    where job.status = 'queued'
    order by job.created_at
    limit p_limit
    for update skip locked
  ), leased as (
    update public.tournament_media_processing_jobs job
    set status = 'leased',
        attempts = job.attempts + 1,
        lease_token = encode(public.gen_random_bytes(32),'hex'),
        lease_expires_at = now() + make_interval(secs => p_lease_seconds),
        worker_id = p_worker_id,
        updated_at = now()
    from candidate
    where job.id = candidate.id
    returning job.id, job.session_id, job.bucket, job.quarantine_path,
      job.declared_mime, job.expected_bytes, job.lease_token,
      job.lease_expires_at, job.attempts, job.max_attempts,
      job.organization_id, job.gallery_id, job.requested_by
  )
  select coalesce(jsonb_agg(jsonb_build_object(
    'jobId',id,'sessionId',session_id,'bucket',bucket,
    'objectName',quarantine_path,'declaredMime',declared_mime,
    'expectedBytes',expected_bytes,'leaseToken',lease_token,
    'leaseExpiresAt',lease_expires_at,'attempts',attempts,
    'maxAttempts',max_attempts,'organizationId',organization_id,
    'galleryId',gallery_id,'requestedBy',requested_by
  )),'[]'::jsonb) into v_leases from leased;
  return jsonb_build_object('jobs',v_leases,'leasedAt',now());
end;
$_$;


--
-- Name: list_tournament_media_retention_candidates(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_tournament_media_retention_candidates(p_organization_id uuid, p_tournament_id uuid, p_as_of timestamp with time zone DEFAULT now()) RETURNS TABLE(asset_id uuid, gallery_id uuid, sports_round_id uuid, sports_round_number integer, window_exited_at timestamp with time zone, eligible_at timestamp with time zone, bucket text, object_paths jsonb, reason text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  IF p_organization_id IS NULL OR p_tournament_id IS NULL OR p_as_of IS NULL
    OR NOT EXISTS (
      SELECT 1 FROM public.tournaments tournament
      WHERE tournament.organization_id = p_organization_id
        AND tournament.id = p_tournament_id
    )
  THEN
    RAISE EXCEPTION USING errcode = '22023', message = 'TORNEOS_ENTITLEMENT_SCOPE_INVALID';
  END IF;
  RETURN;
END;
$$;


--
-- Name: FUNCTION list_tournament_media_retention_candidates(p_organization_id uuid, p_tournament_id uuid, p_as_of timestamp with time zone); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_tournament_media_retention_candidates(p_organization_id uuid, p_tournament_id uuid, p_as_of timestamp with time zone) IS 'Compatibility read-only surface. FREE/PREMIUM V1 uses a gallery asset quota and never purges historical media because a plan changed.';


--
-- Name: list_tournament_player_portrait_refs(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_tournament_player_portrait_refs(p_organization_id uuid, p_team_entry_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE v_actor uuid := private.current_identity_id();
BEGIN
  IF v_actor IS NULL OR NOT (
    public.can_read_tournament_team_entry(p_organization_id, p_team_entry_id)
    OR public.can_manage_tournament_team_visual_assets_as(
      p_organization_id, p_team_entry_id, v_actor, 'roster_players.update'
    )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_PORTRAIT_FORBIDDEN';
  END IF;
  RETURN jsonb_build_object(
    'organizationId', p_organization_id,
    'teamEntryId', p_team_entry_id,
    'players', coalesce((
      SELECT jsonb_agg(jsonb_build_object(
        'rosterPlayerId', player.id,
        'canManage', public.can_manage_tournament_player_portrait_as(
          p_organization_id, player.id, v_actor
        ),
        'portrait', (
          SELECT CASE WHEN public.can_read_tournament_player_portrait_as(
            p_organization_id, player.id, v_actor
          ) THEN jsonb_build_object(
            'ref', jsonb_build_object(
              'kind', 'player_portrait', 'id', portrait.id, 'variant', 'original'
            ),
            'focalX', portrait.focal_x,
            'focalY', portrait.focal_y,
            'cropZoom', portrait.crop_zoom,
            'width', portrait.width,
            'height', portrait.height,
            'editorialStatus', portrait.editorial_status,
            'publicationConsent', portrait.publication_consent,
            'updatedAt', portrait.updated_at
          ) END
          FROM public.tournament_player_portraits portrait
          WHERE portrait.organization_id = p_organization_id
            AND portrait.roster_player_id = player.id
            AND portrait.lifecycle_status = 'active'
        )
      ) ORDER BY player.shirt_number NULLS LAST, player.display_name)
      FROM public.tournament_roster_players player
      WHERE player.organization_id = p_organization_id
        AND player.team_entry_id = p_team_entry_id
        AND player.status = 'active'
    ), '[]'::jsonb)
  );
END;
$$;


--
-- Name: FUNCTION list_tournament_player_portrait_refs(p_organization_id uuid, p_team_entry_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.list_tournament_player_portrait_refs(p_organization_id uuid, p_team_entry_id uuid) IS 'ImageRef y capability real por jugador del plantel. Nunca devuelve bucket, object_path ni URL firmada.';


--
-- Name: list_tournament_season_member_assignments(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.list_tournament_season_member_assignments(p_organization_id uuid, p_season_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_result jsonb;
begin
  if not public.has_tournament_season_capability(
    p_organization_id,p_season_id,'members.read'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_SEASON_ASSIGNMENT_FORBIDDEN';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',assignment.id,'membershipId',membership.id,'userId',membership.user_id,
    'role',membership.role,'status',membership.status,'assignedAt',assignment.assigned_at
  ) order by membership.role,membership.joined_at),'[]'::jsonb) into v_result
  from public.tournament_season_member_assignments assignment
  join public.tournament_organization_members membership on membership.id = assignment.membership_id
  where assignment.organization_id = p_organization_id and assignment.season_id = p_season_id;
  return v_result;
end;
$$;


--
-- Name: lock_tournament_roster(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lock_tournament_roster(p_organization_id uuid, p_team_entry_id uuid, p_roster_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_entry public.tournament_team_entries%rowtype;
  v_roster public.tournament_rosters%rowtype;
begin
  if private.current_identity_id() is null or not public.has_tournament_organization_capability(
    p_organization_id,
    'rosters.lock'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select * into v_entry
  from public.tournament_team_entries
  where id = p_team_entry_id
    and organization_id = p_organization_id
    and status = 'approved'
  for update;
  select * into v_roster
  from public.tournament_rosters
  where id = p_roster_id
    and organization_id = p_organization_id
    and team_entry_id = p_team_entry_id
    and status = 'approved'
  for update;
  if v_entry.id is null or v_roster.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  update public.tournament_rosters
  set status = 'locked', locked_at = now()
  where id = v_roster.id
  returning * into v_roster;
  perform public.append_tournament_audit(
    p_organization_id,
    'roster.locked',
    'roster',
    v_roster.id,
    v_entry.id,
    v_entry.tournament_id,
    jsonb_build_object('version', v_roster.version)
  );
  return jsonb_build_object(
    'entryId', v_entry.id,
    'rosterId', v_roster.id,
    'status', v_roster.status
  );
end;
$$;


--
-- Name: make_tournament_match_official(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.make_tournament_match_official(p_organization_id uuid, p_match_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_operation public.tournament_match_operations%rowtype;
  v_source public.tournament_match_operations%rowtype;
  v_validation jsonb;
  v_match_id uuid;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select match_id into v_match_id
  from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id;
  if v_match_id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('torneos:match-official:' || v_match_id, 0));
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.make_official'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if v_operation.status = 'official' then
    return public.get_tournament_match_operation_context(
      p_organization_id, v_operation.id
    );
  end if;
  if v_operation.status <> 'validated' then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournament_match_reviews
    where match_operation_id = v_operation.id and status = 'open'
      and review_type <> 'validation'
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_MATCH_REVIEW_OPEN';
  end if;
  v_validation := public.validate_tournament_match_operation_payload(v_operation.id);
  if not (v_validation->>'valid')::boolean then
    raise exception using errcode = '23514', message = 'TORNEOS_MATCH_OPERATION_INVALID';
  end if;
  if v_operation.source_operation_id is not null then
    select * into v_source from public.tournament_match_operations
    where id = v_operation.source_operation_id and match_id = v_operation.match_id for update;
    if v_source.id is null or v_source.status <> 'official'
      or not exists (
        select 1
        from public.tournament_match_reviews review
        where review.match_operation_id = v_source.id
          and review.review_type = 'correction'
          and review.status = 'open'
      )
    then
      raise exception using errcode = '55000', message = 'TORNEOS_MATCH_CORRECTION_STALE';
    end if;
    update public.tournament_match_reviews set
      status = 'approved',
      resolved_by = private.current_identity_id(),
      resolved_at = now(),
      resolution = 'Corrección reemplazada por una nueva versión oficial'
    where match_operation_id = v_source.id
      and review_type = 'correction'
      and status = 'open';
    update public.tournament_match_operations set status = 'superseded', updated_at = now()
    where id = v_source.id;
    perform public.append_tournament_audit(
      p_organization_id, 'match_operation.superseded', 'match_operation',
      v_source.id, null, v_source.tournament_id,
      jsonb_build_object('replacementOperationId', v_operation.id)
    );
  end if;
  update public.tournament_match_operations set
    status = 'official', match_status = 'official', official_by = private.current_identity_id(),
    official_at = now(), closed_at = now(), updated_at = now()
  where id = v_operation.id;
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.made_official', 'match_operation',
    v_operation.id, null, v_operation.tournament_id,
    jsonb_build_object('operationVersion', v_operation.operation_version)
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_operation.id);
end;
$$;


--
-- Name: manage_tournament_media_consent(uuid, uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.manage_tournament_media_consent(p_asset_id uuid, p_roster_player_id uuid, p_subject_user_id uuid, p_use_scope text, p_status text, p_legal_basis text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_asset public.tournament_media_assets%rowtype;
  v_gallery public.tournament_media_galleries%rowtype;
  v_existing public.tournament_media_consents%rowtype;
  v_consent_id uuid;
  v_replacement uuid;
  v_subject_user_id uuid;
begin
  select * into v_asset from public.tournament_media_assets where id = p_asset_id;
  if v_asset.id is null or not public.has_tournament_media_capability(
    v_asset.organization_id,'media.manage_consent'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_asset.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_asset.gallery_id::text,1)
  );
  select * into v_gallery
  from public.tournament_media_galleries
  where id = v_asset.gallery_id
  for update;
  select * into v_asset
  from public.tournament_media_assets
  where id = p_asset_id
  for update;
  if p_roster_player_id is null and p_subject_user_id is null then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_CONSENT_INVALID';
  end if;
  if p_roster_player_id is not null then
    select player.arma2_user_id
    into v_subject_user_id
    from public.tournament_media_relations relation
    join public.tournament_roster_players player
      on player.id = relation.roster_player_id
    join public.tournament_team_entries entry
      on entry.id = player.team_entry_id
    where relation.asset_id = p_asset_id
      and relation.relation_type = 'player'
      and relation.roster_player_id = p_roster_player_id
      and player.status = 'active'
      and entry.organization_id = v_asset.organization_id
      and entry.tournament_id = v_asset.tournament_id;
    if not found
      or (
        p_subject_user_id is not null
        and p_subject_user_id is distinct from v_subject_user_id
      )
    then
      raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_SCOPE_INVALID';
    end if;
  else
    v_subject_user_id := p_subject_user_id;
  end if;
  if p_roster_player_id is null and not exists (
    select 1
    from public.tournament_media_relations relation
    join public.tournament_roster_players player
      on player.id = relation.roster_player_id
    join public.tournament_team_entries entry
      on entry.id = player.team_entry_id
    where relation.asset_id = p_asset_id
      and relation.relation_type = 'player'
      and player.arma2_user_id = v_subject_user_id
      and player.status = 'active'
      and entry.organization_id = v_asset.organization_id
      and entry.tournament_id = v_asset.tournament_id
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_SCOPE_INVALID';
  end if;
  select * into v_existing
  from public.tournament_media_consents consent
  where consent.asset_id = p_asset_id
    and consent.roster_player_id is not distinct from p_roster_player_id
    and consent.subject_user_id is not distinct from v_subject_user_id
    and consent.use_scope = p_use_scope
  for update;
  if v_existing.id is not null
    and v_existing.status = p_status
    and v_existing.legal_basis is not distinct from (
      case when p_status = 'not_required'
        then nullif(btrim(p_legal_basis),'') else null end
    )
  then
    return jsonb_build_object(
      'assetId',p_asset_id,'useScope',p_use_scope,'status',p_status
    );
  end if;
  insert into public.tournament_media_consents (
    organization_id,tournament_id,asset_id,roster_player_id,subject_user_id,
    use_scope,status,legal_basis,managed_by,revoked_at
  ) values (
    v_asset.organization_id,v_asset.tournament_id,p_asset_id,p_roster_player_id,
    v_subject_user_id,p_use_scope,p_status,
    case when p_status = 'not_required' then nullif(btrim(p_legal_basis),'') else null end,
    private.current_identity_id(),case when p_status = 'revoked' then now() else null end
  ) on conflict (
    asset_id,
    (coalesce(roster_player_id, '00000000-0000-0000-0000-000000000000'::uuid)),
    (coalesce(subject_user_id, '00000000-0000-0000-0000-000000000000'::uuid)),
    use_scope
  ) do update set
    status = excluded.status,legal_basis = excluded.legal_basis,
    managed_by = excluded.managed_by,revoked_at = excluded.revoked_at,
    updated_at = now()
  returning id into v_consent_id;
  insert into public.tournament_media_consent_events (
    organization_id,tournament_id,consent_id,asset_id,roster_player_id,
    subject_user_id,use_scope,previous_status,resulting_status,legal_basis,
    actor_user_id
  ) values (
    v_asset.organization_id,v_asset.tournament_id,v_consent_id,p_asset_id,
    p_roster_player_id,v_subject_user_id,p_use_scope,v_existing.status,p_status,
    case when p_status = 'not_required' then nullif(btrim(p_legal_basis),'') else null end,
    private.current_identity_id()
  );
  if p_use_scope = 'view_internal'
    and p_status in ('denied','revoked')
    and v_asset.status = 'published'
  then
    update public.tournament_media_assets
    set status = 'hidden',hidden_at = now()
    where id = p_asset_id;
    if v_gallery.cover_asset_id = p_asset_id then
      select asset.id into v_replacement
      from public.tournament_media_gallery_items item
      join public.tournament_media_assets asset on asset.id = item.asset_id
      where item.gallery_id = v_gallery.id
        and asset.id <> p_asset_id
        and asset.status = 'published'
      order by item.sort_order,asset.created_at
      limit 1;
      if v_replacement is null then
        update public.tournament_media_galleries
        set status = 'archived',cover_asset_id = null,archived_at = now(),
            version = version + 1
        where id = v_gallery.id;
      else
        update public.tournament_media_galleries
        set cover_asset_id = v_replacement,version = version + 1
        where id = v_gallery.id;
      end if;
    end if;
    insert into public.tournament_media_moderation_actions (
      organization_id,tournament_id,gallery_id,asset_id,action,
      previous_status,resulting_status,reason,actor_user_id
    ) values (
      v_asset.organization_id,v_asset.tournament_id,v_asset.gallery_id,p_asset_id,
      'hide','published','hidden','Consentimiento interno denegado o revocado.',
      private.current_identity_id()
    );
  end if;
  perform public.append_tournament_audit(
    v_asset.organization_id,'media.consent.updated','media_asset',p_asset_id,
    null,v_asset.tournament_id,jsonb_build_object(
      'useScope',p_use_scope,'status',p_status
    )
  );
  return jsonb_build_object(
    'assetId',p_asset_id,'useScope',p_use_scope,'status',p_status
  );
end;
$$;


--
-- Name: mark_tournament_announcement_read(uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_tournament_announcement_read(p_announcement_id uuid, p_confirm boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_delivery public.tournament_announcement_deliveries%rowtype;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select delivery.* into v_delivery
  from public.tournament_announcement_deliveries delivery
  join public.tournament_announcements announcement
    on announcement.id = delivery.announcement_id
  where delivery.announcement_id = p_announcement_id
    and delivery.recipient_user_id = private.current_identity_id()
    and delivery.status not in ('archived','revoked')
    and public.can_current_user_access_tournament_announcement(announcement.id)
  for update of delivery;
  if v_delivery.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  update public.tournament_announcement_deliveries
  set read_at = coalesce(read_at,now()),
    confirmed_at = case when p_confirm then coalesce(confirmed_at,now()) else confirmed_at end,
    status = case when p_confirm then 'confirmed' else
      case when status = 'confirmed' then status else 'read' end end
  where id = v_delivery.id;
  return jsonb_build_object(
    'announcementId',p_announcement_id,
    'status',case when p_confirm then 'confirmed' else 'read' end,
    'confirmationIsLegalAcceptance',false
  );
end;
$$;


--
-- Name: mark_tournament_suspension_served(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_tournament_suspension_served(p_suspension_id uuid, p_match_id uuid, p_note text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_suspension public.tournament_player_suspensions%rowtype;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_suspension from public.tournament_player_suspensions
  where id = p_suspension_id;
  if v_suspension.id is null or not public.has_tournament_organization_capability(
    v_suspension.organization_id, 'suspensions.mark_served'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_DISCIPLINE_FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    v_suspension.organization_id::text || ':' || v_suspension.tournament_id::text || ':'
    || v_suspension.category_id::text || ':' || v_suspension.phase_id::text || ':'
    || coalesce(v_suspension.group_id::text, 'all'),
    0
  ));
  select * into strict v_suspension from public.tournament_player_suspensions
  where id = p_suspension_id for update;
  if v_suspension.status not in ('active', 'reduced') then
    if v_suspension.status = 'served' then return v_suspension.id; end if;
    raise exception using errcode = '55000', message = 'TORNEOS_SUSPENSION_NOT_ACTIVE';
  end if;
  if not exists (
    select 1
    from public.tournament_matches match_row
    join public.tournament_competition_participants home
      on home.id = match_row.home_participant_id
    join public.tournament_competition_participants away
      on away.id = match_row.away_participant_id
    join public.tournament_match_operations operation
      on operation.match_id = match_row.id and operation.status = 'official'
    join public.tournament_match_outcomes outcome
      on outcome.match_operation_id = operation.id
      and outcome.counts_for_standings
    where match_row.id = p_match_id
      and match_row.organization_id = v_suspension.organization_id
      and match_row.tournament_id = v_suspension.tournament_id
      and match_row.id is distinct from v_suspension.source_match_id
      and v_suspension.team_entry_id in (home.team_entry_id, away.team_entry_id)
      and (
        (
          v_suspension.source_match_id is null
          and operation.official_at > v_suspension.created_at
        )
        or exists (
          select 1
          from public.tournament_match_operations source_operation
          where source_operation.match_id = v_suspension.source_match_id
            and source_operation.status in ('official', 'superseded')
            and operation.official_at > source_operation.official_at
        )
      )
      and not exists (
        select 1 from public.tournament_match_operation_players operation_player
        where operation_player.match_operation_id = operation.id
          and operation_player.roster_player_id = v_suspension.roster_player_id
          and operation_player.attendance_status not in ('absent', 'excused')
      )
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_SUSPENSION_MATCH_INVALID';
  end if;

  insert into public.tournament_suspension_served_matches (
    suspension_id, organization_id, match_id, marked_by, note
  ) values (
    v_suspension.id, v_suspension.organization_id, p_match_id, private.current_identity_id(), p_note
  ) on conflict (suspension_id, match_id) do nothing;

  update public.tournament_player_suspensions suspension
  set served_matches = least(total_matches, (
      select count(*) from public.tournament_suspension_served_matches served
      where served.suspension_id = suspension.id
    )),
    status = case when (
      select count(*) from public.tournament_suspension_served_matches served
      where served.suspension_id = suspension.id
    ) >= total_matches then 'served' else status end,
    updated_at = now()
  where suspension.id = v_suspension.id;

  perform public.append_tournament_audit(
    v_suspension.organization_id, 'suspension.mark_served', 'player_suspension',
    v_suspension.id, v_suspension.team_entry_id, v_suspension.tournament_id,
    jsonb_build_object('matchId', p_match_id, 'note', p_note)
  );
  return v_suspension.id;
end;
$$;


--
-- Name: normalize_tournament_competition_slug(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_tournament_competition_slug(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select trim(both '-' from regexp_replace(
    regexp_replace(
      translate(
        lower(btrim(coalesce(p_value, ''))),
        'áéíóúüñ',
        'aeiouun'
      ),
      '[^a-z0-9]+',
      '-',
      'g'
    ),
    '-+', '-', 'g'
  ));
$$;


--
-- Name: normalize_tournament_organization_slug(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_tournament_organization_slug(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select trim(both '-' from regexp_replace(
    regexp_replace(
      translate(
        lower(btrim(coalesce(p_value, ''))),
        'áéíóúüñ',
        'aeiouun'
      ),
      '[^a-z0-9]+',
      '-',
      'g'
    ),
    '-+', '-', 'g'
  ));
$$;


--
-- Name: normalize_tournament_person_name(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_tournament_person_name(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select regexp_replace(
    translate(
      lower(btrim(coalesce(p_value, ''))),
      'áéíóúüñ',
      'aeiouun'
    ),
    '[^a-z0-9]+',
    ' ',
    'g'
  );
$$;


--
-- Name: open_tournament_match_operation(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_tournament_match_operation(p_organization_id uuid, p_match_id uuid, p_override_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_match public.tournament_matches%rowtype;
  v_fixture public.tournament_fixture_versions%rowtype;
  v_teams record;
  v_home public.tournament_team_entries%rowtype;
  v_away public.tournament_team_entries%rowtype;
  v_operation public.tournament_match_operations%rowtype;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  perform pg_advisory_xact_lock(hashtextextended('torneos:match-operation:' || p_match_id, 0));
  select * into v_match from public.tournament_matches
  where id = p_match_id and organization_id = p_organization_id for update;
  if v_match.id is null
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.open'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  select * into v_fixture from public.tournament_fixture_versions
  where id = v_match.fixture_version_id for share;
  select * into v_teams from public.tournament_match_team_entries(p_match_id);
  if v_fixture.status <> 'published' or v_fixture.invalidated_at is not null
    or v_match.status not in ('scheduled', 'ready')
    or v_teams.home_team_entry_id is null or v_teams.away_team_entry_id is null
  then
    raise exception using errcode = '22023', message = 'TORNEOS_MATCH_NOT_OPENABLE';
  end if;
  if v_match.scheduled_at is not null
    and now() < v_match.scheduled_at - interval '6 hours'
    and char_length(btrim(coalesce(p_override_reason, ''))) < 3
  then
    raise exception using errcode = '22023', message = 'TORNEOS_MATCH_OPEN_WINDOW';
  end if;
  select * into v_operation from public.tournament_match_operations
  where match_id = p_match_id
    and status in ('draft', 'submitted', 'under_review', 'validated')
  order by operation_version desc
  limit 1;
  if v_operation.id is not null then
    return public.get_tournament_match_operation_context(
      p_organization_id, v_operation.id
    );
  end if;
  if exists (
    select 1
    from public.tournament_match_operations
    where match_id = p_match_id and status = 'official'
  ) then
    raise exception using errcode = '22023',
      message = 'TORNEOS_MATCH_ALREADY_OFFICIAL';
  end if;
  perform 1
  from public.tournament_match_squads
  where match_id = p_match_id and status in ('draft', 'submitted')
  order by team_entry_id
  for update;
  select * into v_home from public.tournament_team_entries
  where id = v_teams.home_team_entry_id;
  select * into v_away from public.tournament_team_entries
  where id = v_teams.away_team_entry_id;
  insert into public.tournament_match_operations (
    organization_id, season_id, tournament_id, category_id, fixture_version_id,
    phase_id, round_id, match_id, home_team_entry_id, away_team_entry_id,
    operation_version, match_snapshot, home_team_snapshot, away_team_snapshot,
    opened_by
  ) values (
    p_organization_id, v_match.season_id, v_match.tournament_id, v_match.category_id,
    v_match.fixture_version_id, v_match.phase_id, v_match.round_id, v_match.id,
    v_home.id, v_away.id,
    coalesce((select max(operation_version) from public.tournament_match_operations
      where match_id = p_match_id), 0) + 1,
    jsonb_build_object(
      'scheduledAt', v_match.scheduled_at, 'venueId', v_match.venue_id,
      'courtId', v_match.court_id, 'durationMinutes', v_match.duration_minutes,
      'matchNumber', v_match.match_number, 'overrideReason', nullif(btrim(p_override_reason), '')
    ),
    jsonb_build_object('id', v_home.id, 'name', v_home.name, 'shortName', v_home.short_name,
      'shieldPath', v_home.shield_path, 'primaryColor', v_home.primary_color),
    jsonb_build_object('id', v_away.id, 'name', v_away.name, 'shortName', v_away.short_name,
      'shieldPath', v_away.shield_path, 'primaryColor', v_away.primary_color),
    private.current_identity_id()
  ) returning * into v_operation;
  insert into public.tournament_match_operation_players (
    organization_id, match_operation_id, match_id, team_entry_id, roster_player_id,
    display_name_snapshot, avatar_url_snapshot, shirt_number_snapshot,
    position_snapshot, is_goalkeeper, is_captain, lineup_status, attendance_status
  )
  select player.organization_id, v_operation.id, player.match_id, player.team_entry_id,
    player.roster_player_id, player.display_name_snapshot, player.avatar_url_snapshot,
    player.shirt_number_snapshot, player.position_snapshot, player.is_goalkeeper,
    player.is_captain, player.lineup_status, player.attendance_status
  from public.tournament_match_squad_players player
  join public.tournament_match_squads squad on squad.id = player.match_squad_id
  where squad.match_id = p_match_id and squad.status = 'submitted'
    and player.callup_status = 'called_up';
  update public.tournament_match_squads set
    status = 'locked', locked_by = private.current_identity_id(), locked_at = now(), updated_at = now()
  where match_id = p_match_id and status = 'submitted';
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.opened', 'match_operation', v_operation.id,
    null, v_match.tournament_id,
    jsonb_build_object('operationVersion', v_operation.operation_version)
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_operation.id);
end;
$$;


--
-- Name: FUNCTION open_tournament_match_operation(p_organization_id uuid, p_match_id uuid, p_override_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.open_tournament_match_operation(p_organization_id uuid, p_match_id uuid, p_override_reason text) IS 'Abre el acta de un partido. Hasta seis horas antes del horario programado la apertura es directa; más temprano exige un motivo en `p_override_reason`. Un partido que no reúne las condiciones para tener acta, y uno con resultado ya oficializado, se responden como errores del cliente. Ninguna de esas negativas es una falla del servidor.';


--
-- Name: postpone_tournament_match(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.postpone_tournament_match(p_organization_id uuid, p_match_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_match public.tournament_matches%rowtype;
  v_reason text := btrim(coalesce(p_reason, ''));
begin
  if private.current_identity_id() is null or char_length(v_reason) not between 3 and 500
    or not public.has_tournament_organization_capability(
      p_organization_id, 'matches.postpone'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select match_row.* into v_match
  from public.tournament_matches match_row
  join public.tournament_fixture_versions version
    on version.id = match_row.fixture_version_id
    and version.status in ('draft', 'published')
    and version.invalidated_at is null
  where match_row.id = p_match_id
    and match_row.organization_id = p_organization_id
    and match_row.status = 'scheduled'
  for update of match_row;
  if v_match.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  insert into public.tournament_match_reschedules (
    organization_id, tournament_id, category_id, fixture_version_id, match_id,
    previous_scheduled_at, previous_venue_id, previous_court_id,
    new_scheduled_at, new_venue_id, new_court_id, reason, actor_user_id,
    previous_status, new_status
  ) values (
    v_match.organization_id, v_match.tournament_id, v_match.category_id,
    v_match.fixture_version_id, v_match.id, v_match.scheduled_at,
    v_match.venue_id, v_match.court_id, null, null, null,
    v_reason, private.current_identity_id(), 'scheduled', 'postponed'
  );
  update public.tournament_matches
  set status = 'postponed', postponed_at = now(),
      scheduled_at = null, venue_id = null, court_id = null
  where id = v_match.id;
  perform public.append_tournament_audit(
    p_organization_id, 'match.postponed', 'match', v_match.id,
    null, v_match.tournament_id,
    jsonb_build_object(
      'reason', v_reason, 'previousScheduledAt', v_match.scheduled_at,
      'venueId', v_match.venue_id, 'courtId', v_match.court_id
    )
  );
  return jsonb_build_object('matchId', v_match.id, 'status', 'postponed');
end;
$$;


--
-- Name: preview_tournament_announcement_audience(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_tournament_announcement_audience(p_announcement_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_announcement public.tournament_announcements%rowtype;
  v_count integer;
  v_teams jsonb;
  v_roles jsonb;
begin
  select * into v_announcement
  from public.tournament_announcements announcement
  where announcement.id = p_announcement_id;
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if v_announcement.id is null
    or not public.has_tournament_communications_capability(
      v_announcement.organization_id,'audiences.preview'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  select count(*),coalesce(jsonb_agg(distinct relation_type),'[]'::jsonb)
    into v_count,v_roles
  from public.resolve_tournament_announcement_recipients(p_announcement_id);
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',entry.id,'name',entry.name
  ) order by entry.name),'[]'::jsonb) into v_teams
  from public.tournament_announcement_audiences audience
  join public.tournament_team_entries entry on entry.id = audience.team_entry_id
  where audience.announcement_id = p_announcement_id;
  return jsonb_build_object(
    'announcementId',p_announcement_id,
    'estimatedRecipients',v_count,
    'roles',v_roles,
    'teams',v_teams,
    'channel','internal_only',
    'revalidatedAt',now()
  );
end;
$$;


--
-- Name: protect_active_tournament_fixture_draft(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_active_tournament_fixture_draft() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_fixture_version_id uuid;
  v_fixture_status text;
  v_tournament_status text;
begin
  v_fixture_version_id := case
    when tg_op = 'DELETE' then old.fixture_version_id
    else new.fixture_version_id
  end;

  select fixture.status, tournament.status
  into v_fixture_status, v_tournament_status
  from public.tournament_fixture_versions fixture
  join public.tournaments tournament on tournament.id = fixture.tournament_id
  where fixture.id = v_fixture_version_id;

  if v_fixture_status = 'draft'
    and v_tournament_status not in ('registration', 'scheduled')
  then
    raise exception using errcode = '55000',
      message = 'TORNEOS_FIXTURE_DRAFT_READ_ONLY';
  end if;

  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$$;


--
-- Name: protect_published_tournament_communication(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_published_tournament_communication() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.status in ('published','superseded','archived','revoked')
    and (
      new.title is distinct from old.title
      or new.summary is distinct from old.summary
      or new.body is distinct from old.body
      or new.priority is distinct from old.priority
      or new.announcement_type is distinct from old.announcement_type
      or new.acknowledgement_mode is distinct from old.acknowledgement_mode
    )
  then
    raise exception using errcode = '23514',
      message = 'TORNEOS_COMMUNICATION_IMMUTABLE';
  end if;
  return new;
end;
$$;


--
-- Name: protect_published_tournament_document_version(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_published_tournament_document_version() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.status in ('published','superseded')
    and (
      new.summary is distinct from old.summary
      or new.body is distinct from old.body
      or new.effective_at is distinct from old.effective_at
    )
  then
    raise exception using errcode = '23514',
      message = 'TORNEOS_DOCUMENT_VERSION_IMMUTABLE';
  end if;
  return new;
end;
$$;


--
-- Name: protect_referenced_tournament_offer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_referenced_tournament_offer() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if exists (
    select 1 from public.tournament_purchases purchase
    where purchase.product_code = old.product_code
      and purchase.offer_code = old.offer_code
      and purchase.offer_version = old.offer_version
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_REFERENCED_OFFER_IMMUTABLE';
  end if;
  return case when tg_op = 'DELETE' then old else new end;
end;
$$;


--
-- Name: protect_tournament_competition_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_tournament_competition_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.organization_id is distinct from old.organization_id then
    raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
  end if;

  if tg_table_name = 'tournament_seasons'
    and (
      to_jsonb(new)->>'id' is distinct from to_jsonb(old)->>'id'
      or to_jsonb(new)->>'created_by' is distinct from to_jsonb(old)->>'created_by'
      or to_jsonb(new)->>'creation_key' is distinct from to_jsonb(old)->>'creation_key'
    )
  then
    raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
  elsif tg_table_name = 'tournaments'
    and (
      to_jsonb(new)->>'id' is distinct from to_jsonb(old)->>'id'
      or to_jsonb(new)->>'season_id' is distinct from to_jsonb(old)->>'season_id'
      or to_jsonb(new)->>'created_by' is distinct from to_jsonb(old)->>'created_by'
      or to_jsonb(new)->>'creation_key' is distinct from to_jsonb(old)->>'creation_key'
    )
  then
    raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
  elsif tg_table_name = 'tournament_categories'
    and (
      to_jsonb(new)->>'id' is distinct from to_jsonb(old)->>'id'
      or to_jsonb(new)->>'tournament_id' is distinct from to_jsonb(old)->>'tournament_id'
    )
  then
    raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
  elsif tg_table_name in (
    'tournament_scoring_rules',
    'tournament_discipline_rules',
    'tournament_tiebreak_rules'
  )
    and to_jsonb(new)->>'tournament_id'
      is distinct from to_jsonb(old)->>'tournament_id'
  then
    raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
  end if;

  return new;
end;
$$;


--
-- Name: protect_tournament_completed_competition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_tournament_completed_competition() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_row jsonb;
  v_tournament_id uuid;
  v_match_id uuid;
  v_operation_id uuid;
  v_status text;
begin
  v_row := coalesce(to_jsonb(new), to_jsonb(old));
  v_tournament_id := nullif(v_row->>'tournament_id', '')::uuid;

  if v_tournament_id is null then
    v_match_id := nullif(v_row->>'match_id', '')::uuid;
    if v_match_id is not null then
      select match_row.tournament_id into v_tournament_id
      from public.tournament_matches match_row
      where match_row.id = v_match_id;
    end if;
  end if;

  if v_tournament_id is null then
    v_operation_id := nullif(v_row->>'match_operation_id', '')::uuid;
    if v_operation_id is not null then
      select operation.tournament_id into v_tournament_id
      from public.tournament_match_operations operation
      where operation.id = v_operation_id;
    end if;
  end if;

  if v_tournament_id is null then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  select tournament.status into v_status
  from public.tournaments tournament
  where tournament.id = v_tournament_id;

  if v_status in ('completed', 'archived') then
    raise exception using errcode = '22023',
      message = 'TORNEOS_COMPETITION_READ_ONLY';
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: FUNCTION protect_tournament_completed_competition(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.protect_tournament_completed_competition() IS 'Una competencia Finalizada o Archivada no admite operaciones competitivas mutables. Las lecturas, la página pública y los recálculos derivados sobre datos existentes siguen disponibles. El rechazo se comunica como error del cliente: para corregir algo hay que reabrir la competencia.';


--
-- Name: protect_tournament_match_child_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_tournament_match_child_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_operation_id uuid;
  v_operation_status text;
begin
  if tg_op = 'DELETE' then
    v_operation_id := old.match_operation_id;
  else
    v_operation_id := new.match_operation_id;
  end if;
  select status into v_operation_status
  from public.tournament_match_operations
  where id = v_operation_id;
  if v_operation_status is distinct from 'draft' then
    raise exception using errcode = '42501',
      message = 'TORNEOS_OFFICIAL_OPERATION_IMMUTABLE';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: protect_tournament_match_operation_history(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_tournament_match_operation_history() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_op = 'DELETE' then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_HISTORY_APPEND_ONLY';
  end if;
  if old.status in ('official', 'superseded', 'voided') and not (
    old.status = 'official'
    and new.status = 'superseded'
    and row(
      new.id, new.organization_id, new.match_id, new.operation_version,
      new.match_snapshot, new.home_team_snapshot, new.away_team_snapshot,
      new.opened_by, new.opened_at, new.submitted_by, new.submitted_at,
      new.validated_by, new.validated_at, new.official_by, new.official_at,
      new.closed_at
    ) is not distinct from row(
      old.id, old.organization_id, old.match_id, old.operation_version,
      old.match_snapshot, old.home_team_snapshot, old.away_team_snapshot,
      old.opened_by, old.opened_at, old.submitted_by, old.submitted_at,
      old.validated_by, old.validated_at, old.official_by, old.official_at,
      old.closed_at
    )
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_OFFICIAL_OPERATION_IMMUTABLE';
  end if;
  return new;
end;
$$;


--
-- Name: protect_tournament_match_planning_transition(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_tournament_match_planning_transition() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.status in ('postponed', 'cancelled', 'unscheduled')
    and new.status is distinct from old.status
    and exists (
      select 1
      from public.tournament_match_operations operation
      where operation.match_id = old.id
        and operation.status not in ('superseded', 'voided')
    )
  then
    raise exception using errcode = '22023',
      message = 'TORNEOS_MATCH_OPERATION_ACTIVE';
  end if;
  return new;
end;
$$;


--
-- Name: FUNCTION protect_tournament_match_planning_transition(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.protect_tournament_match_planning_transition() IS 'Un partido con acta viva no puede postergarse, cancelarse ni volver a sin programar: primero hay que resolver o anular el acta. El rechazo se comunica como error del cliente.';


--
-- Name: protect_tournament_match_squad_players(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_tournament_match_squad_players() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_squad_status text;
begin
  select status into v_squad_status
  from public.tournament_match_squads
  where id = coalesce(new.match_squad_id, old.match_squad_id);
  if v_squad_status is distinct from 'draft' then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_SQUAD_LOCKED';
  end if;
  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: protect_tournament_organization_owner(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_tournament_organization_owner() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.role = 'owner' and old.status = 'active' then
    if tg_op = 'DELETE' then
      raise exception using
        errcode = '23514',
        message = 'TORNEOS_ACTIVE_OWNER_REQUIRED';
    end if;

    if new.organization_id is distinct from old.organization_id
      or new.user_id is distinct from old.user_id
      or new.role is distinct from old.role
      or new.status is distinct from old.status
    then
      raise exception using
        errcode = '23514',
        message = 'TORNEOS_ACTIVE_OWNER_REQUIRED';
    end if;
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


--
-- Name: protect_tournament_purchase_snapshots(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_tournament_purchase_snapshots() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if row(
    new.organization_id,new.tournament_id,new.buyer_user_id,new.product_code,
    new.offer_code,new.offer_version,new.list_amount_snapshot,new.amount_snapshot,
    new.currency,new.provider,new.provider_environment,new.external_reference,new.idempotency_key
  ) is distinct from row(
    old.organization_id,old.tournament_id,old.buyer_user_id,old.product_code,
    old.offer_code,old.offer_version,old.list_amount_snapshot,old.amount_snapshot,
    old.currency,old.provider,old.provider_environment,old.external_reference,old.idempotency_key
  ) then
    raise exception using errcode = '55000', message = 'TORNEOS_PURCHASE_SNAPSHOT_IMMUTABLE';
  end if;
  new.updated_at := now();
  return new;
end;
$$;


--
-- Name: protect_tournament_registration_scope(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.protect_tournament_registration_scope() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if tg_table_name = 'tournament_team_entries' and (
    to_jsonb(new)->>'id' is distinct from to_jsonb(old)->>'id'
    or to_jsonb(new)->>'organization_id' is distinct from to_jsonb(old)->>'organization_id'
    or to_jsonb(new)->>'season_id' is distinct from to_jsonb(old)->>'season_id'
    or to_jsonb(new)->>'tournament_id' is distinct from to_jsonb(old)->>'tournament_id'
    or to_jsonb(new)->>'category_id' is distinct from to_jsonb(old)->>'category_id'
    or to_jsonb(new)->>'created_by' is distinct from to_jsonb(old)->>'created_by'
    or to_jsonb(new)->>'idempotency_key' is distinct from to_jsonb(old)->>'idempotency_key'
  ) then raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
  elsif tg_table_name in ('tournament_team_managers','tournament_rosters','tournament_roster_players')
    and (
      to_jsonb(new)->>'id' is distinct from to_jsonb(old)->>'id'
      or
      to_jsonb(new)->>'organization_id' is distinct from to_jsonb(old)->>'organization_id'
      or to_jsonb(new)->>'team_entry_id' is distinct from to_jsonb(old)->>'team_entry_id'
      or (
        tg_table_name = 'tournament_roster_players'
        and to_jsonb(new)->>'roster_id' is distinct from to_jsonb(old)->>'roster_id'
      )
      or (
        tg_table_name = 'tournament_rosters'
        and to_jsonb(new)->>'version' is distinct from to_jsonb(old)->>'version'
      )
    )
  then raise exception using errcode = '23514', message = 'TORNEOS_SCOPE_IMMUTABLE';
  end if;
  return new;
end;
$$;


--
-- Name: publish_tournament_announcement(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_tournament_announcement(p_announcement_id uuid, p_expected_recipient_count integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_announcement public.tournament_announcements%rowtype;
  v_count integer;
  v_snapshot jsonb;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_announcement
  from public.tournament_announcements announcement
  where announcement.id = p_announcement_id
  for update;
  if v_announcement.id is null
    or not public.has_tournament_communications_capability(
      v_announcement.organization_id,'announcements.publish'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  if v_announcement.status = 'published' then
    return jsonb_build_object(
      'announcementId',v_announcement.id,
      'status','published',
      'recipientCount',v_announcement.published_recipient_count,
      'audienceChanged',false
    );
  end if;
  if v_announcement.status not in ('draft','scheduled') then
    raise exception using errcode = '23514', message = 'TORNEOS_COMMUNICATION_NOT_PUBLISHABLE';
  end if;

  perform pg_advisory_xact_lock(
    hashtextextended(v_announcement.organization_id::text,731)
  );
  if (select count(*) from public.tournament_announcements announcement
      where announcement.organization_id = v_announcement.organization_id
        and announcement.status in ('published','superseded','archived','revoked')
        and announcement.published_at >= now() - interval '1 hour') >= 20
  then
    raise exception using errcode = '54000', message = 'TORNEOS_PUBLISH_RATE_LIMITED';
  end if;
  if not exists (
    select 1 from public.tournament_announcement_audiences audience
    where audience.announcement_id = p_announcement_id
  ) then
    raise exception using errcode = '23514', message = 'TORNEOS_AUDIENCE_REQUIRED';
  end if;
  if exists (
    select 1
    from public.tournament_announcement_links link
    where link.announcement_id = p_announcement_id
      and (
        (link.link_type = 'category' and not exists (
          select 1
          from public.tournament_categories category
          where category.id = link.resource_id
            and category.organization_id = v_announcement.organization_id
            and category.tournament_id = v_announcement.tournament_id
            and category.status = 'active'
        ))
        or (link.link_type = 'match' and not exists (
          select 1
          from public.tournament_matches match
          join public.tournament_fixture_versions fixture
            on fixture.organization_id = match.organization_id
           and fixture.id = match.fixture_version_id
           and fixture.status = 'published'
          where match.id = link.resource_id
            and match.organization_id = v_announcement.organization_id
            and match.tournament_id = v_announcement.tournament_id
        ))
        or (link.link_type = 'document' and not exists (
          select 1
          from public.tournament_documents document
          where document.id = link.resource_id
            and document.organization_id = v_announcement.organization_id
            and document.tournament_id = v_announcement.tournament_id
            and document.status = 'published'
        ))
      )
  ) then
    raise exception using errcode = '42501',
      message = 'TORNEOS_INVALID_COMMUNICATION_LINK';
  end if;

  select count(*) into v_count
  from public.resolve_tournament_announcement_recipients(p_announcement_id);
  if v_count = 0 then
    raise exception using errcode = '23514', message = 'TORNEOS_AUDIENCE_EMPTY';
  end if;
  if v_count > 5000 then
    raise exception using errcode = '54000', message = 'TORNEOS_RECIPIENT_LIMIT_REACHED';
  end if;
  select jsonb_build_object(
    'criteria',coalesce(jsonb_agg(jsonb_build_object(
      'type',audience.audience_type,
      'categoryId',audience.category_id,
      'teamEntryId',audience.team_entry_id,
      'matchId',audience.match_id
    ) order by audience.created_at,audience.id),'[]'::jsonb),
    'recipientCount',v_count,
    'resolvedAt',now()
  ) into v_snapshot
  from public.tournament_announcement_audiences audience
  where audience.announcement_id = p_announcement_id;

  insert into public.tournament_announcement_deliveries (
    organization_id,announcement_id,recipient_user_id,recipient_relation_type
  )
  select v_announcement.organization_id,p_announcement_id,user_id,relation_type
  from public.resolve_tournament_announcement_recipients(p_announcement_id)
  on conflict (announcement_id,recipient_user_id) do nothing;

  if v_announcement.supersedes_id is not null then
    update public.tournament_announcements
    set status = 'superseded'
    where id = v_announcement.supersedes_id
      and organization_id = v_announcement.organization_id
      and tournament_id = v_announcement.tournament_id
      and status = 'published';
    if not found then
      raise exception using errcode = '40001',
        message = 'TORNEOS_CORRECTION_ALREADY_SUPERSEDED';
    end if;
  end if;
  update public.tournament_announcements
  set status = 'published',published_at = now(),scheduled_for = null,
    published_recipient_count = v_count,audience_snapshot = v_snapshot
  where id = p_announcement_id;

  perform public.append_tournament_audit(
    v_announcement.organization_id,'communications.announcement_publish','announcement',
    p_announcement_id,null,v_announcement.tournament_id,
    jsonb_build_object(
      'recipientCount',v_count,
      'previewCount',p_expected_recipient_count,
      'audienceChanged',p_expected_recipient_count is not null
        and p_expected_recipient_count <> v_count,
      'channel','internal_only'
    )
  );
  return jsonb_build_object(
    'announcementId',p_announcement_id,'status','published',
    'recipientCount',v_count,
    'audienceChanged',p_expected_recipient_count is not null
      and p_expected_recipient_count <> v_count
  );
end;
$$;


--
-- Name: publish_tournament_document_version(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_tournament_document_version(p_version_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_version public.tournament_document_versions%rowtype;
  v_document public.tournament_documents%rowtype;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_version
  from public.tournament_document_versions version
  where version.id = p_version_id
  for update;
  if v_version.status = 'published' then
    return jsonb_build_object(
      'documentId',v_version.document_id,'versionId',v_version.id,'status','published'
    );
  end if;
  select * into v_document
  from public.tournament_documents document
  where document.id = v_version.document_id
  for update;
  if v_version.id is null or v_version.status <> 'draft'
    or v_document.status = 'archived'
    or not public.has_tournament_communications_capability(
      v_version.organization_id,'documents.publish'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_DOCUMENT_FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(v_document.id::text,733));
  update public.tournament_document_versions
  set status = 'superseded',superseded_at = now()
  where document_id = v_document.id and status = 'published';
  update public.tournament_document_versions
  set status = 'published',published_by = private.current_identity_id(),published_at = now()
  where id = p_version_id;
  update public.tournament_documents
  set status = 'published',active_version_id = p_version_id
  where id = v_document.id;
  perform public.append_tournament_audit(
    v_document.organization_id,'communications.document_publish','tournament_document',
    v_document.id,null,v_document.tournament_id,
    jsonb_build_object('versionId',p_version_id,'version',v_version.version)
  );
  return jsonb_build_object(
    'documentId',v_document.id,'versionId',p_version_id,'status','published'
  );
end;
$$;


--
-- Name: publish_tournament_fixture(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_tournament_fixture(p_organization_id uuid, p_fixture_version_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_version public.tournament_fixture_versions%rowtype;
  v_previous public.tournament_fixture_versions%rowtype;
  v_validation jsonb;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select version.* into v_version
  from public.tournament_fixture_versions version
  where version.id = p_fixture_version_id
    and version.organization_id = p_organization_id
    and version.status = 'draft'
  for update;
  if v_version.id is null
    or not public.has_tournament_organization_capability(p_organization_id, 'fixture.publish')
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  perform public.assert_tournament_fixture_scope(
    p_organization_id, v_version.tournament_id, v_version.category_id,
    'fixture.publish', array['registration', 'scheduled']::text[]
  );
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:fixture:' || v_version.tournament_id::text || ':' || v_version.category_id::text, 0
  ));
  if exists (
    select 1
    from public.tournament_fixture_versions newer
    where newer.tournament_id = v_version.tournament_id
      and newer.category_id = v_version.category_id
      and newer.status = 'draft'
      and newer.version_number > v_version.version_number
  ) then
    raise exception using errcode = '40001', message = 'TORNEOS_STALE_FIXTURE_VERSION';
  end if;
  v_validation := public.validate_tournament_fixture(p_organization_id, v_version.id);
  if not (v_validation->>'valid')::boolean then
    raise exception using errcode = '23514', message = 'TORNEOS_FIXTURE_INVALID';
  end if;
  select version.* into v_previous
  from public.tournament_fixture_versions version
  where version.tournament_id = v_version.tournament_id
    and version.category_id = v_version.category_id
    and version.status = 'published'
  for update;
  if v_previous.id is not null then
    if not public.has_tournament_organization_capability(
      p_organization_id, 'fixture.supersede'
    ) then
      raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
    end if;
    update public.tournament_fixture_versions
    set status = 'superseded', superseded_at = now()
    where id = v_previous.id;
    perform public.append_tournament_audit(
      p_organization_id, 'fixture.superseded', 'fixture_version', v_previous.id,
      null, v_version.tournament_id,
      jsonb_build_object('supersededByFixtureVersionId', v_version.id)
    );
  end if;
  update public.tournament_fixture_versions
  set status = 'published', published_at = now()
  where id = v_version.id;
  update public.tournament_rounds round_row
  set status = case
      when not exists (
        select 1 from public.tournament_matches match_row
        where match_row.round_id = round_row.id
          and match_row.status not in ('scheduled', 'ready', 'cancelled')
      ) then 'scheduled'
      else 'draft'
    end
  where round_row.fixture_version_id = v_version.id
    and round_row.status <> 'locked';
  update public.tournament_phases phase
  set status = case
      when not exists (
        select 1 from public.tournament_matches match_row
        where match_row.phase_id = phase.id
          and match_row.status not in ('scheduled', 'ready', 'cancelled')
      ) then 'scheduled'
      else 'generated'
    end
  where phase.fixture_version_id = v_version.id;
  update public.tournaments
  set status = 'scheduled'
  where id = v_version.tournament_id
    and organization_id = p_organization_id
    and status = 'registration';
  perform public.append_tournament_audit(
    p_organization_id, 'fixture.published', 'fixture_version', v_version.id,
    null, v_version.tournament_id,
    jsonb_build_object(
      'categoryId', v_version.category_id,
      'versionNumber', v_version.version_number,
      'previousFixtureVersionId', v_previous.id
    )
  );
  return jsonb_build_object(
    'fixtureVersionId', v_version.id,
    'status', 'published',
    'supersededFixtureVersionId', v_previous.id
  );
end;
$$;


--
-- Name: publish_tournament_media_gallery(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_tournament_media_gallery(p_gallery_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_gallery public.tournament_media_galleries%rowtype;
  v_count integer;
begin
  select * into v_gallery
  from public.tournament_media_galleries where id = p_gallery_id;
  if v_gallery.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_gallery.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_gallery_id::text,1)
  );
  select * into v_gallery
  from public.tournament_media_galleries where id = p_gallery_id for update;
  if v_gallery.id is null or not public.has_tournament_media_capability(
    v_gallery.organization_id,'media.publish'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  if v_gallery.status = 'published' then
    return jsonb_build_object(
      'galleryId',p_gallery_id,'status','published','publishedAt',v_gallery.published_at
    );
  end if;
  if v_gallery.status not in ('draft','under_review') then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_GALLERY_NOT_PUBLISHABLE';
  end if;
  select count(*) into v_count
  from public.tournament_media_gallery_items item
  join public.tournament_media_assets asset on asset.id = item.asset_id
  where item.gallery_id = p_gallery_id;
  if v_count < 1 or v_gallery.cover_asset_id is null or not exists (
    select 1 from public.tournament_media_assets asset
    where asset.id = v_gallery.cover_asset_id
      and asset.gallery_id = p_gallery_id and asset.status = 'approved'
  ) or exists (
    select 1
    from public.tournament_media_gallery_items item
    join public.tournament_media_assets asset on asset.id = item.asset_id
    where item.gallery_id = p_gallery_id
      and asset.status <> 'approved'
  ) or exists (
    select 1
    from public.tournament_media_gallery_items item
    where item.gallery_id = p_gallery_id
      and not public.tournament_media_asset_publication_ready(item.asset_id)
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_GALLERY_NOT_PUBLISHABLE';
  end if;
  if exists (
    select 1
    from public.tournament_media_gallery_items item
    where item.gallery_id = p_gallery_id
      and not public.tournament_media_asset_has_internal_consent(item.asset_id)
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_CONSENT_REQUIRED';
  end if;

  update public.tournament_media_assets asset
  set status = 'published',published_at = now()
  where asset.gallery_id = p_gallery_id and asset.status = 'approved';
  update public.tournament_media_galleries
  set status = 'published',submitted_at = coalesce(submitted_at,now()),
      published_by = private.current_identity_id(),published_at = now(),version = version + 1
  where id = p_gallery_id;
  perform public.append_tournament_audit(
    v_gallery.organization_id,'media.gallery.published','media_gallery',
    p_gallery_id,null,v_gallery.tournament_id,jsonb_build_object('assetCount',v_count)
  );
  return jsonb_build_object(
    'galleryId',p_gallery_id,'status','published',
    'publishedAt',now(),'assetCount',v_count
  );
end;
$$;


--
-- Name: publish_tournament_standings_revision(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.publish_tournament_standings_revision(p_revision_id uuid, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_revision public.tournament_standings_revisions%rowtype;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_revision from public.tournament_standings_revisions
  where id = p_revision_id;
  if v_revision.id is null or not public.has_tournament_organization_capability(
    v_revision.organization_id, 'standings.publish'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_STANDINGS_FORBIDDEN';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    v_revision.organization_id::text || ':' || v_revision.tournament_id::text || ':'
    || v_revision.category_id::text || ':' || v_revision.phase_id::text || ':'
    || coalesce(v_revision.group_id::text, 'all'),
    0
  ));
  select * into strict v_revision from public.tournament_standings_revisions
  where id = p_revision_id for update;
  if v_revision.status <> 'draft' then
    if v_revision.status = 'published' then return v_revision.id; end if;
    raise exception using errcode = '22023', message = 'TORNEOS_STANDINGS_NOT_PUBLISHABLE';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 3 then
    raise exception using errcode = '22023', message = 'TORNEOS_STANDINGS_REASON_REQUIRED';
  end if;
  perform 1
  from public.tournament_fixture_versions fixture
  join public.tournaments tournament
    on tournament.id = fixture.tournament_id
    and tournament.organization_id = fixture.organization_id
  join public.tournament_categories category
    on category.id = fixture.category_id
    and category.organization_id = fixture.organization_id
  where fixture.id = v_revision.fixture_version_id
    and fixture.status = 'published'
    and tournament.status <> 'archived'
    and category.status = 'active'
  for share of fixture, tournament, category;
  if not found then
    raise exception using errcode = '22023', message = 'TORNEOS_STANDINGS_NOT_PUBLISHABLE';
  end if;
  perform 1
  from public.tournament_matches match_row
  join public.tournament_phases match_phase on match_phase.id = match_row.phase_id
  join public.tournament_phases selected_phase on selected_phase.id = v_revision.phase_id
  join public.tournament_match_operations operation
    on operation.match_id = match_row.id and operation.status = 'official'
  join public.tournament_match_outcomes outcome
    on outcome.match_operation_id = operation.id
  where match_row.fixture_version_id = v_revision.fixture_version_id
    and (
      (
        match_row.phase_id = v_revision.phase_id
        and match_row.group_id is not distinct from v_revision.group_id
      )
      or match_phase.sequence_number < selected_phase.sequence_number
    )
  order by match_row.match_number, operation.id
  for share of match_row, operation, outcome;
  perform 1
  from public.tournament_points_adjustments adjustment
  where adjustment.fixture_version_id = v_revision.fixture_version_id
    and adjustment.phase_id = v_revision.phase_id
    and adjustment.group_id is not distinct from v_revision.group_id
  order by adjustment.id
  for share;
  if v_revision.source_fingerprint <> public.tournament_projection_source_fingerprint(
    v_revision.fixture_version_id, v_revision.phase_id, v_revision.group_id
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_STANDINGS_STALE';
  end if;

  with effective_override as (
    select distinct on (current_suspension.id)
      current_suspension.id current_suspension_id,
      override_row.action,
      (override_row.new_state->>'totalMatches')::integer total_matches
    from public.tournament_player_suspensions current_suspension
    join public.tournament_player_suspensions previous_suspension
      on previous_suspension.organization_id = current_suspension.organization_id
      and previous_suspension.tournament_id = current_suspension.tournament_id
      and previous_suspension.category_id = current_suspension.category_id
      and previous_suspension.roster_player_id = current_suspension.roster_player_id
      and previous_suspension.source_type = current_suspension.source_type
      and previous_suspension.source_key = current_suspension.source_key
      and previous_suspension.revision_id <> current_suspension.revision_id
    join public.tournament_standings_revisions previous_revision
      on previous_revision.id = previous_suspension.revision_id
      and previous_revision.status in ('published', 'superseded')
    join public.tournament_disciplinary_overrides override_row
      on override_row.suspension_id = previous_suspension.id
    where current_suspension.revision_id = v_revision.id
      and current_suspension.status = 'pending'
    order by current_suspension.id, override_row.created_at desc, override_row.id desc
  )
  update public.tournament_player_suspensions suspension
  set total_matches = effective_override.total_matches,
    status = case when effective_override.action = 'revoke'
      then 'revoked' else 'pending' end,
    updated_at = now()
  from effective_override
  where suspension.id = effective_override.current_suspension_id;

  update public.tournament_standings_revisions
  set status = 'superseded', superseded_at = now()
  where fixture_version_id = v_revision.fixture_version_id
    and phase_id = v_revision.phase_id
    and group_id is not distinct from v_revision.group_id
    and status = 'published';

  update public.tournament_player_suspensions suspension
  set status = 'superseded', updated_at = now()
  from public.tournament_standings_revisions revision
  where suspension.revision_id = revision.id
    and revision.fixture_version_id = v_revision.fixture_version_id
    and revision.phase_id = v_revision.phase_id
    and revision.group_id is not distinct from v_revision.group_id
    and revision.status = 'superseded'
    and suspension.status in ('active', 'reduced');

  with served_history as (
    select distinct on (current_suspension.id, served.match_id)
      current_suspension.id current_suspension_id,
      served.organization_id, served.match_id, served.marked_by,
      served.marked_at, served.note,
      current_suspension.total_matches
    from public.tournament_player_suspensions current_suspension
    join public.tournament_player_suspensions previous_suspension
      on previous_suspension.organization_id = current_suspension.organization_id
      and previous_suspension.tournament_id = current_suspension.tournament_id
      and previous_suspension.category_id = current_suspension.category_id
      and previous_suspension.roster_player_id = current_suspension.roster_player_id
      and previous_suspension.source_type = current_suspension.source_type
      and previous_suspension.source_key = current_suspension.source_key
      and previous_suspension.revision_id <> current_suspension.revision_id
    join public.tournament_standings_revisions previous_revision
      on previous_revision.id = previous_suspension.revision_id
      and previous_revision.status = 'superseded'
    join public.tournament_suspension_served_matches served
      on served.suspension_id = previous_suspension.id
    where current_suspension.revision_id = v_revision.id
      and current_suspension.status = 'pending'
    order by current_suspension.id, served.match_id, served.marked_at, previous_suspension.id
  ), transferable as (
    select served_history.*,
      row_number() over (
        partition by served_history.current_suspension_id
        order by served_history.marked_at, served_history.match_id
      ) served_order
    from served_history
  )
  insert into public.tournament_suspension_served_matches (
    suspension_id, organization_id, match_id, marked_by, marked_at, note
  )
  select current_suspension_id, organization_id, match_id, marked_by,
    marked_at, note
  from transferable
  where served_order <= total_matches
  on conflict (suspension_id, match_id) do nothing;

  update public.tournament_player_suspensions suspension
  set served_matches = least(suspension.total_matches, (
      select count(*) from public.tournament_suspension_served_matches served
      where served.suspension_id = suspension.id
    )),
    status = case when (
      select count(*) from public.tournament_suspension_served_matches served
      where served.suspension_id = suspension.id
    ) >= suspension.total_matches then 'served' else suspension.status end,
    updated_at = now()
  where suspension.revision_id = v_revision.id;

  update public.tournament_standings_revisions
  set status = 'published', published_by = private.current_identity_id(), published_at = now()
  where id = v_revision.id;
  update public.tournament_player_suspensions
  set status = 'active', updated_at = now()
  where revision_id = v_revision.id and status = 'pending';

  perform public.append_tournament_audit(
    v_revision.organization_id, 'standings.publish', 'standings_revision',
    v_revision.id, null, v_revision.tournament_id,
    jsonb_build_object(
      'categoryId', v_revision.category_id, 'phaseId', v_revision.phase_id,
      'groupId', v_revision.group_id, 'reason', btrim(p_reason)
    )
  );
  return v_revision.id;
end;
$$;


--
-- Name: FUNCTION publish_tournament_standings_revision(p_revision_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.publish_tournament_standings_revision(p_revision_id uuid, p_reason text) IS 'Publica una revisión borrador de la tabla. Que la revisión ya no sea publicable o que los resultados oficiales hayan cambiado durante el cálculo se responden como errores del cliente: el organizador recalcula y vuelve a publicar.';


--
-- Name: raise_tournament_match_error(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.raise_tournament_match_error(p_message text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  raise exception using errcode = '42501', message = p_message;
end;
$$;


--
-- Name: rank_tournament_standings(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rank_tournament_standings(p_revision_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare
  v_rule record;
  v_pass integer;
  v_partitions_before integer;
  v_partitions_after integer;
begin
  create temporary table if not exists pg_temp.tournament_rank_work (
    participant_id uuid primary key,
    rank_key text not null default '',
    criterion_value numeric not null default 0,
    mini_points numeric not null default 0,
    mini_goal_difference numeric not null default 0,
    mini_goals_for numeric not null default 0,
    trace jsonb not null default '{}'::jsonb
  ) on commit drop;
  truncate pg_temp.tournament_rank_work;

  insert into pg_temp.tournament_rank_work(participant_id, rank_key, trace)
  select participant_id,
    lpad((1000000 - points)::text, 7, '0'),
    jsonb_build_object('points', points)
  from public.tournament_team_standings
  where revision_id = p_revision_id;

  for v_rule in
    select rule.criterion, rule.sort_order
    from public.tournament_standings_revisions revision
    join public.tournament_tiebreak_rules rule
      on rule.tournament_id = revision.tournament_id
    where revision.id = p_revision_id
    order by rule.sort_order
  loop
    if v_rule.criterion = 'goal_difference' then
      update pg_temp.tournament_rank_work work set criterion_value = standing.goal_difference
      from public.tournament_team_standings standing
      where standing.revision_id = p_revision_id
        and standing.participant_id = work.participant_id;
    elsif v_rule.criterion = 'goals_for' then
      update pg_temp.tournament_rank_work work set criterion_value = standing.goals_for
      from public.tournament_team_standings standing
      where standing.revision_id = p_revision_id
        and standing.participant_id = work.participant_id;
    elsif v_rule.criterion = 'matches_won' then
      update pg_temp.tournament_rank_work work set criterion_value = standing.won
      from public.tournament_team_standings standing
      where standing.revision_id = p_revision_id
        and standing.participant_id = work.participant_id;
    elsif v_rule.criterion = 'fair_play' then
      update pg_temp.tournament_rank_work work set criterion_value = -standing.fair_play_points
      from public.tournament_team_standings standing
      where standing.revision_id = p_revision_id
        and standing.participant_id = work.participant_id;
    elsif v_rule.criterion = 'head_to_head' then
      for v_pass in 1..16 loop
        select count(distinct rank_key) into v_partitions_before
        from pg_temp.tournament_rank_work;

        update pg_temp.tournament_rank_work
        set mini_points = 0, mini_goal_difference = 0, mini_goals_for = 0
        where participant_id is not null;
        update pg_temp.tournament_rank_work work
        set mini_points = coalesce(mini.points, 0),
          mini_goal_difference = coalesce(mini.goal_difference, 0),
          mini_goals_for = coalesce(mini.goals_for, 0)
        from (
        select team.participant_id,
          sum(case
            when team.goals_for > team.goals_against
              and team.outcome_type like 'walkover_%'
              then coalesce(scoring.points_walkover_win, scoring.points_win)
            when team.goals_for < team.goals_against
              and team.outcome_type like 'walkover_%'
              then coalesce(scoring.points_walkover_loss, scoring.points_loss)
            when team.goals_for > team.goals_against then scoring.points_win
            when team.goals_for = team.goals_against then scoring.points_draw
            else scoring.points_loss
          end)::numeric as points,
          sum(team.goals_for - team.goals_against)::numeric as goal_difference,
          sum(team.goals_for)::numeric as goals_for
        from (
          select home_work.rank_key, match_row.home_participant_id as participant_id,
            score.home_score::integer as goals_for, score.away_score::integer as goals_against,
            revision.tournament_id, outcome.outcome_type
          from public.tournament_standings_revisions revision
          join public.tournament_projection_sources source on source.revision_id = revision.id
          join public.tournament_matches match_row on match_row.id = source.match_id
          join public.tournament_match_scores score on score.match_operation_id = source.match_operation_id
          join public.tournament_match_outcomes outcome
            on outcome.match_operation_id = source.match_operation_id
            and outcome.counts_for_standings
          join pg_temp.tournament_rank_work home_work
            on home_work.participant_id = match_row.home_participant_id
          join pg_temp.tournament_rank_work away_work
            on away_work.participant_id = match_row.away_participant_id
            and away_work.rank_key = home_work.rank_key
          where revision.id = p_revision_id
          union all
          select away_work.rank_key, match_row.away_participant_id,
            score.away_score::integer, score.home_score::integer,
            revision.tournament_id, outcome.outcome_type
          from public.tournament_standings_revisions revision
          join public.tournament_projection_sources source on source.revision_id = revision.id
          join public.tournament_matches match_row on match_row.id = source.match_id
          join public.tournament_match_scores score on score.match_operation_id = source.match_operation_id
          join public.tournament_match_outcomes outcome
            on outcome.match_operation_id = source.match_operation_id
            and outcome.counts_for_standings
          join pg_temp.tournament_rank_work away_work
            on away_work.participant_id = match_row.away_participant_id
          join pg_temp.tournament_rank_work home_work
            on home_work.participant_id = match_row.home_participant_id
            and home_work.rank_key = away_work.rank_key
          where revision.id = p_revision_id
        ) team
        join public.tournament_scoring_rules scoring on scoring.tournament_id = team.tournament_id
        group by team.rank_key, team.participant_id
        ) mini
        where mini.participant_id = work.participant_id;

        update pg_temp.tournament_rank_work
        set rank_key = rank_key || ':'
              || lpad((1000000000 - mini_points)::bigint::text, 10, '0') || ':'
              || lpad((1000000000 - mini_goal_difference)::bigint::text, 10, '0') || ':'
              || lpad((1000000000 - mini_goals_for)::bigint::text, 10, '0'),
          trace = trace || jsonb_build_object(
            'head_to_head_' || v_pass::text,
            jsonb_build_object(
              'points', mini_points,
              'goalDifference', mini_goal_difference,
              'goalsFor', mini_goals_for
            )
          )
        where participant_id is not null;

        select count(distinct rank_key) into v_partitions_after
        from pg_temp.tournament_rank_work;
        exit when v_partitions_after = v_partitions_before
          or not exists (
            select 1
            from pg_temp.tournament_rank_work work
            join pg_temp.tournament_rank_work peer
              on peer.participant_id <> work.participant_id
              and peer.rank_key = work.rank_key
          );
      end loop;
      continue;
    else
      update pg_temp.tournament_rank_work work
      set criterion_value = 0
      where work.participant_id is not null;
    end if;

    update pg_temp.tournament_rank_work
    set rank_key = rank_key || ':' || lpad((1000000000 - criterion_value)::bigint::text, 10, '0'),
        trace = trace || jsonb_build_object(v_rule.criterion, criterion_value)
    where participant_id is not null;
  end loop;

  update public.tournament_team_standings standing
  set classification_status = 'manual_review',
      tiebreak_trace = work.trace || jsonb_build_object(
        'manualReview', true,
        'reason', 'Los criterios deportivos configurados no resolvieron el empate.'
      )
  from pg_temp.tournament_rank_work work
  where standing.revision_id = p_revision_id
    and standing.participant_id = work.participant_id
    and exists (
      select 1
      from pg_temp.tournament_rank_work peer
      where peer.participant_id <> work.participant_id
        and peer.rank_key = work.rank_key
    );

  update pg_temp.tournament_rank_work
  set rank_key = rank_key || ':' || participant_id::text,
      trace = trace || jsonb_build_object(
        'deterministicSeed', participant_id,
        'seedPurpose', 'Orden visual estable hasta resolver el empate manual.'
      )
  where participant_id is not null;

  update public.tournament_team_standings standing
  set position = ranked.position,
      tiebreak_trace = coalesce(standing.tiebreak_trace, '{}'::jsonb) || ranked.trace
  from (
    select participant_id, trace,
      row_number() over (order by rank_key)::integer as position
    from pg_temp.tournament_rank_work
  ) ranked
  where standing.revision_id = p_revision_id
    and standing.participant_id = ranked.participant_id;
end;
$$;


--
-- Name: FUNCTION rank_tournament_standings(p_revision_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rank_tournament_standings(p_revision_id uuid) IS 'Ordena la tabla de posiciones de una revisión. Todas las escrituras sobre la tabla temporal de trabajo llevan cláusula `where`, porque el rol `authenticator` de Supabase precarga `safeupdate` y rechazaría un `UPDATE` sin filtro: sin eso, recalcular la tabla desde la aplicación era imposible.';


--
-- Name: ready_tournament_match(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ready_tournament_match(p_organization_id uuid, p_match_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_match public.tournament_matches%rowtype;
begin
  if private.current_identity_id() is null or not public.has_tournament_organization_capability(
    p_organization_id, 'matches.schedule'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select match_row.* into v_match
  from public.tournament_matches match_row
  join public.tournament_fixture_versions version
    on version.id = match_row.fixture_version_id
    and version.status in ('draft', 'published')
    and version.invalidated_at is null
  where match_row.id = p_match_id
    and match_row.organization_id = p_organization_id
    and match_row.status = 'scheduled'
    and match_row.scheduled_at is not null
  for update of match_row;
  if v_match.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  update public.tournament_matches set status = 'ready' where id = v_match.id;
  perform public.append_tournament_audit(
    p_organization_id, 'match.ready', 'match', v_match.id,
    null, v_match.tournament_id, '{}'::jsonb
  );
  return jsonb_build_object('matchId', v_match.id, 'status', 'ready');
end;
$$;


--
-- Name: rebuild_tournament_discipline(uuid, uuid, uuid, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rebuild_tournament_discipline(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_phase_id uuid, p_group_id uuid, p_reason text, p_idempotency_key uuid) RETURNS uuid
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select public.rebuild_tournament_standings(
    p_organization_id, p_tournament_id, p_category_id, p_phase_id,
    p_group_id, p_reason, p_idempotency_key
  );
$$;


--
-- Name: rebuild_tournament_standings(uuid, uuid, uuid, uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.rebuild_tournament_standings(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_phase_id uuid, p_group_id uuid, p_reason text, p_idempotency_key uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_revision public.tournament_standings_revisions%rowtype;
  v_existing_draft public.tournament_standings_revisions%rowtype;
  v_fixture public.tournament_fixture_versions%rowtype;
  v_phase public.tournament_phases%rowtype;
  v_scoring public.tournament_scoring_rules%rowtype;
  v_discipline public.tournament_discipline_rules%rowtype;
  v_number integer;
  v_fingerprint text;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(
    p_organization_id, 'standings.rebuild'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_STANDINGS_FORBIDDEN';
  end if;
  if p_idempotency_key is null or char_length(btrim(coalesce(p_reason, ''))) < 3 then
    raise exception using errcode = '22023', message = 'TORNEOS_STANDINGS_REASON_REQUIRED';
  end if;

  select * into v_revision
  from public.tournament_standings_revisions
  where organization_id = p_organization_id
    and calculated_by = private.current_identity_id()
    and idempotency_key = p_idempotency_key;

  perform pg_advisory_xact_lock(hashtextextended(
    p_organization_id::text || ':' || p_tournament_id::text || ':'
    || p_category_id::text || ':' || p_phase_id::text || ':'
    || coalesce(p_group_id::text, 'all'),
    0
  ));

  select fixture.* into v_fixture
  from public.tournament_fixture_versions fixture
  join public.tournaments tournament
    on tournament.organization_id = fixture.organization_id
    and tournament.id = fixture.tournament_id
  where fixture.organization_id = p_organization_id
    and fixture.tournament_id = p_tournament_id
    and fixture.category_id = p_category_id
    and fixture.status = 'published'
    and tournament.status <> 'archived'
  for update of fixture;
  if v_fixture.id is null then
    raise exception using errcode = '22023', message = 'TORNEOS_STANDINGS_SCOPE_INVALID';
  end if;

  select * into v_phase from public.tournament_phases
  where organization_id = p_organization_id
    and tournament_id = p_tournament_id
    and category_id = p_category_id
    and fixture_version_id = v_fixture.id
    and id = p_phase_id
  for share;
  if v_phase.id is null or (
    p_group_id is not null and not exists (
      select 1 from public.tournament_groups group_row
      where group_row.id = p_group_id
        and group_row.organization_id = p_organization_id
        and group_row.tournament_id = p_tournament_id
        and group_row.category_id = p_category_id
        and group_row.fixture_version_id = v_fixture.id
        and group_row.phase_id = p_phase_id
        and group_row.status = 'published'
    )
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_STANDINGS_SCOPE_INVALID';
  end if;

  if v_revision.id is not null then
    if v_revision.tournament_id <> p_tournament_id
      or v_revision.category_id <> p_category_id
      or v_revision.fixture_version_id <> v_fixture.id
      or v_revision.phase_id <> p_phase_id
      or v_revision.group_id is distinct from p_group_id
      or v_revision.rebuild_reason <> btrim(p_reason)
    then
      raise exception using errcode = '23514', message = 'TORNEOS_IDEMPOTENCY_CONFLICT';
    end if;
    return v_revision.id;
  end if;

  select * into strict v_scoring from public.tournament_scoring_rules
  where tournament_id = p_tournament_id for share;
  select * into strict v_discipline from public.tournament_discipline_rules
  where tournament_id = p_tournament_id for share;
  perform 1
  from public.tournament_tiebreak_rules rule
  where rule.tournament_id = p_tournament_id
  order by rule.sort_order
  for share;

  perform 1
  from public.tournament_matches match_row
  join public.tournament_phases match_phase on match_phase.id = match_row.phase_id
  join public.tournament_match_operations operation
    on operation.match_id = match_row.id and operation.status = 'official'
  join public.tournament_match_outcomes outcome
    on outcome.match_operation_id = operation.id
  where match_row.fixture_version_id = v_fixture.id
    and (
      (
        match_row.phase_id = p_phase_id
        and match_row.group_id is not distinct from p_group_id
      )
      or match_phase.sequence_number < v_phase.sequence_number
    )
  order by match_row.match_number, operation.id
  for share of match_row, operation, outcome;
  perform 1
  from public.tournament_match_operation_players operation_player
  join public.tournament_match_operations operation
    on operation.id = operation_player.match_operation_id
    and operation.status = 'official'
  join public.tournament_matches match_row on match_row.id = operation.match_id
  join public.tournament_phases match_phase on match_phase.id = match_row.phase_id
  where match_row.fixture_version_id = v_fixture.id
    and (
      (
        match_row.phase_id = p_phase_id
        and match_row.group_id is not distinct from p_group_id
      )
      or match_phase.sequence_number < v_phase.sequence_number
    )
  order by operation_player.match_operation_id, operation_player.roster_player_id
  for share of operation_player;
  perform 1
  from public.tournament_match_events event
  join public.tournament_match_operations operation
    on operation.id = event.match_operation_id and operation.status = 'official'
  join public.tournament_matches match_row on match_row.id = operation.match_id
  join public.tournament_phases match_phase on match_phase.id = match_row.phase_id
  where match_row.fixture_version_id = v_fixture.id
    and (
      (
        match_row.phase_id = p_phase_id
        and match_row.group_id is not distinct from p_group_id
      )
      or match_phase.sequence_number < v_phase.sequence_number
    )
  order by event.match_operation_id, event.sequence_number
  for share of event;
  perform 1
  from public.tournament_points_adjustments adjustment
  where adjustment.fixture_version_id = v_fixture.id
    and adjustment.phase_id = p_phase_id
    and adjustment.group_id is not distinct from p_group_id
  order by adjustment.id
  for share;

  v_fingerprint := public.tournament_projection_source_fingerprint(
    v_fixture.id, p_phase_id, p_group_id
  );

  select * into v_existing_draft
  from public.tournament_standings_revisions
  where fixture_version_id = v_fixture.id and phase_id = p_phase_id
    and group_id is not distinct from p_group_id and status = 'draft'
  for update;
  if v_existing_draft.id is not null then
    if v_existing_draft.source_fingerprint = v_fingerprint then
      raise exception using errcode = '22023', message = 'TORNEOS_STANDINGS_DRAFT_EXISTS';
    end if;
    update public.tournament_standings_revisions
    set status = 'discarded', discarded_by = private.current_identity_id(), discarded_at = now(),
      discard_reason = 'Las fuentes oficiales cambiaron antes de la publicación.'
    where id = v_existing_draft.id;
    perform public.append_tournament_audit(
      p_organization_id, 'standings.discard_stale', 'standings_revision',
      v_existing_draft.id, null, p_tournament_id,
      jsonb_build_object(
        'previousFingerprint', v_existing_draft.source_fingerprint,
        'currentFingerprint', v_fingerprint
      )
    );
  end if;

  select coalesce(max(revision_number), 0) + 1 into v_number
  from public.tournament_standings_revisions
  where fixture_version_id = v_fixture.id and phase_id = p_phase_id
    and group_id is not distinct from p_group_id;
  insert into public.tournament_standings_revisions (
    organization_id, season_id, tournament_id, category_id, fixture_version_id,
    phase_id, group_id, revision_number, source_fingerprint,
    configuration_snapshot, rebuild_reason, calculated_by, idempotency_key
  ) values (
    p_organization_id, v_fixture.season_id, p_tournament_id, p_category_id,
    v_fixture.id, p_phase_id, p_group_id, v_number, v_fingerprint,
    jsonb_build_object(
      'scoring', to_jsonb(v_scoring) - 'created_at' - 'updated_at',
      'tiebreaks', coalesce((
        select jsonb_agg(jsonb_build_object(
          'criterion', criterion, 'order', sort_order
        ) order by sort_order)
        from public.tournament_tiebreak_rules where tournament_id = p_tournament_id
      ), '[]'::jsonb),
      'discipline', to_jsonb(v_discipline) - 'created_at' - 'updated_at',
      'algorithmVersion', 2
    ),
    btrim(p_reason), private.current_identity_id(), p_idempotency_key
  ) returning * into v_revision;

  insert into public.tournament_projection_sources (
    revision_id, organization_id, match_operation_id, match_id, official_at
  )
  select v_revision.id, p_organization_id, operation.id, match_row.id, operation.official_at
  from public.tournament_matches match_row
  join public.tournament_match_operations operation
    on operation.match_id = match_row.id and operation.status = 'official'
  join public.tournament_match_outcomes outcome
    on outcome.match_operation_id = operation.id
  where match_row.fixture_version_id = v_fixture.id
    and match_row.phase_id = p_phase_id
    and match_row.group_id is not distinct from p_group_id
    and (outcome.counts_for_standings or outcome.counts_for_player_stats);

  insert into public.tournament_team_standings (
    revision_id, organization_id, tournament_id, category_id, phase_id, group_id,
    participant_id, team_entry_id, played, won, drawn, lost, goals_for,
    goals_against, goal_difference, base_points, points_adjustment, points,
    walkovers, administrative_results, fair_play_points
  )
  with participants as (
    select participant.id, participant.team_entry_id
    from public.tournament_competition_participants participant
    where participant.participant_set_id = v_fixture.participant_set_id
      and participant.status in ('active', 'withdrawn')
      and (
        p_group_id is null
        or exists (
          select 1 from public.tournament_group_members member
          where member.group_id = p_group_id and member.participant_id = participant.id
        )
      )
  ), team_matches as (
    select match_row.home_participant_id as participant_id,
      score.home_score::integer as gf, score.away_score::integer as ga,
      outcome.outcome_type
    from public.tournament_projection_sources source
    join public.tournament_matches match_row on match_row.id = source.match_id
    join public.tournament_match_outcomes outcome
      on outcome.match_operation_id = source.match_operation_id
    join public.tournament_match_scores score
      on score.match_operation_id = source.match_operation_id
    where source.revision_id = v_revision.id and outcome.counts_for_standings
    union all
    select match_row.away_participant_id, score.away_score::integer,
      score.home_score::integer, outcome.outcome_type
    from public.tournament_projection_sources source
    join public.tournament_matches match_row on match_row.id = source.match_id
    join public.tournament_match_outcomes outcome
      on outcome.match_operation_id = source.match_operation_id
    join public.tournament_match_scores score
      on score.match_operation_id = source.match_operation_id
    where source.revision_id = v_revision.id and outcome.counts_for_standings
  ), cards as (
    select event.team_entry_id,
      sum(case
        when event.event_type = 'yellow_card' then v_discipline.yellow_fair_play_points
        when event.event_type = 'second_yellow'
          then case when v_discipline.double_yellow_counts_as_red
            then v_discipline.red_fair_play_points
            else v_discipline.yellow_fair_play_points end
        when event.event_type = 'red_card' then v_discipline.red_fair_play_points
        else 0
      end)::integer fair_play
    from public.tournament_projection_sources source
    join public.tournament_match_events event
      on event.match_operation_id = source.match_operation_id and event.voided_at is null
    join public.tournament_match_outcomes outcome
      on outcome.match_operation_id = source.match_operation_id
      and outcome.events_remain_valid
    where source.revision_id = v_revision.id
    group by event.team_entry_id
  ), aggregated as (
    select participant.id participant_id, participant.team_entry_id,
      count(team_match.*)::integer played,
      count(*) filter (where team_match.gf > team_match.ga)::integer won,
      count(*) filter (where team_match.gf = team_match.ga)::integer drawn,
      count(*) filter (where team_match.gf < team_match.ga)::integer lost,
      coalesce(sum(team_match.gf), 0)::integer gf,
      coalesce(sum(team_match.ga), 0)::integer ga,
      coalesce(sum(case
        when team_match.gf > team_match.ga
          and team_match.outcome_type like 'walkover_%'
          then coalesce(v_scoring.points_walkover_win, v_scoring.points_win)
        when team_match.gf < team_match.ga
          and team_match.outcome_type like 'walkover_%'
          then coalesce(v_scoring.points_walkover_loss, v_scoring.points_loss)
        when team_match.gf > team_match.ga then v_scoring.points_win
        when team_match.gf = team_match.ga then v_scoring.points_draw
        else v_scoring.points_loss
      end), 0)::integer base_points,
      count(*) filter (where team_match.outcome_type like 'walkover_%')::integer walkovers,
      count(*) filter (where team_match.outcome_type = 'administrative_result')::integer administrative
    from participants participant
    left join team_matches team_match on team_match.participant_id = participant.id
    group by participant.id, participant.team_entry_id
  )
  select v_revision.id, p_organization_id, p_tournament_id, p_category_id,
    p_phase_id, p_group_id, aggregated.participant_id, aggregated.team_entry_id,
    aggregated.played, aggregated.won, aggregated.drawn, aggregated.lost,
    aggregated.gf, aggregated.ga, aggregated.gf - aggregated.ga,
    aggregated.base_points,
    coalesce(adjustment.points, 0),
    aggregated.base_points + coalesce(adjustment.points, 0),
    aggregated.walkovers, aggregated.administrative,
    coalesce(cards.fair_play, 0)
  from aggregated
  left join cards on cards.team_entry_id = aggregated.team_entry_id
  left join lateral (
    select sum(points)::integer points
    from public.tournament_points_adjustments
    where organization_id = p_organization_id
      and tournament_id = p_tournament_id and category_id = p_category_id
      and participant_set_id = v_fixture.participant_set_id
      and fixture_version_id = v_fixture.id
      and phase_id = p_phase_id and group_id is not distinct from p_group_id
      and participant_id = aggregated.participant_id and status = 'active'
  ) adjustment on true;

  perform public.rank_tournament_standings(v_revision.id);

  insert into public.tournament_player_statistics (
    revision_id, organization_id, tournament_id, category_id,
    roster_player_id, team_entry_id, squad_calls, appearances, starts,
    substitute_appearances, goals, own_goals, assists, penalty_goals,
    penalties_missed, yellow_cards, second_yellows, red_cards, captaincies
  )
  with players as (
    select operation_player.roster_player_id, operation_player.team_entry_id,
      count(distinct operation_player.match_operation_id)::integer squad_calls,
      count(distinct operation_player.match_operation_id)
        filter (where operation_player.attendance_status in ('present', 'late'))::integer appearances,
      count(distinct operation_player.match_operation_id)
        filter (where operation_player.lineup_status = 'starter'
          and operation_player.attendance_status in ('present', 'late'))::integer starts,
      count(distinct operation_player.match_operation_id)
        filter (where operation_player.lineup_status = 'substitute'
          and operation_player.attendance_status in ('present', 'late'))::integer substitutes,
      count(distinct operation_player.match_operation_id)
        filter (where operation_player.is_captain
          and operation_player.attendance_status in ('present', 'late'))::integer captaincies
    from public.tournament_projection_sources source
    join public.tournament_match_operation_players operation_player
      on operation_player.match_operation_id = source.match_operation_id
    join public.tournament_match_outcomes outcome
      on outcome.match_operation_id = source.match_operation_id
    where source.revision_id = v_revision.id and outcome.counts_for_player_stats
    group by operation_player.roster_player_id, operation_player.team_entry_id
  ), events as (
    select event.roster_player_id,
      count(*) filter (
        where event.event_type in ('goal', 'penalty_goal')
          and not (event.event_type = 'penalty_goal' and event.period = 'penalties')
      )::integer goals,
      count(*) filter (where event.event_type = 'own_goal')::integer own_goals,
      count(*) filter (where event.event_type = 'assist')::integer assists,
      count(*) filter (where event.event_type = 'penalty_goal'
        and event.period <> 'penalties')::integer penalty_goals,
      count(*) filter (where event.event_type = 'penalty_missed')::integer penalties_missed,
      count(*) filter (where event.event_type = 'yellow_card')::integer yellow_cards,
      count(*) filter (where event.event_type = 'second_yellow')::integer second_yellows,
      count(*) filter (where event.event_type = 'red_card')::integer red_cards
    from public.tournament_projection_sources source
    join public.tournament_match_events event
      on event.match_operation_id = source.match_operation_id and event.voided_at is null
    join public.tournament_match_outcomes outcome
      on outcome.match_operation_id = source.match_operation_id
    where source.revision_id = v_revision.id and outcome.counts_for_player_stats
      and outcome.events_remain_valid
      and event.roster_player_id is not null
    group by event.roster_player_id
  )
  select v_revision.id, p_organization_id, p_tournament_id, p_category_id,
    player.roster_player_id, player.team_entry_id, player.squad_calls,
    player.appearances, player.starts, player.substitutes,
    coalesce(event.goals, 0), coalesce(event.own_goals, 0),
    coalesce(event.assists, 0), coalesce(event.penalty_goals, 0),
    coalesce(event.penalties_missed, 0), coalesce(event.yellow_cards, 0),
    coalesce(event.second_yellows, 0), coalesce(event.red_cards, 0),
    player.captaincies
  from players player
  left join events event on event.roster_player_id = player.roster_player_id;

  insert into public.tournament_team_statistics (
    revision_id, organization_id, participant_id, team_entry_id, goals,
    own_goals_benefited, yellow_cards, second_yellows, red_cards,
    home_played, away_played, suspended_matches, administrative_matches
  )
  select v_revision.id, p_organization_id, standing.participant_id,
    standing.team_entry_id, standing.goals_for,
    (select count(*)::integer
      from public.tournament_projection_sources source
      join public.tournament_match_events event
        on event.match_operation_id = source.match_operation_id
        and event.voided_at is null
      join public.tournament_match_outcomes outcome
        on outcome.match_operation_id = source.match_operation_id
        and outcome.events_remain_valid
      where source.revision_id = v_revision.id
        and event.event_type = 'own_goal'
        and event.team_entry_id = standing.team_entry_id),
    coalesce(sum(player_stats.yellow_cards), 0)::integer,
    coalesce(sum(player_stats.second_yellows), 0)::integer,
    coalesce(sum(player_stats.red_cards), 0)::integer,
    (select count(*)::integer from public.tournament_projection_sources source
      join public.tournament_matches match_row on match_row.id = source.match_id
      where source.revision_id = v_revision.id
        and match_row.home_participant_id = standing.participant_id),
    (select count(*)::integer from public.tournament_projection_sources source
      join public.tournament_matches match_row on match_row.id = source.match_id
      where source.revision_id = v_revision.id
        and match_row.away_participant_id = standing.participant_id),
    (select count(*)::integer from public.tournament_projection_sources source
      join public.tournament_match_outcomes outcome
        on outcome.match_operation_id = source.match_operation_id
      join public.tournament_match_operations operation
        on operation.id = source.match_operation_id
      where source.revision_id = v_revision.id
        and outcome.outcome_type = 'suspended'
        and standing.team_entry_id in (
          operation.home_team_entry_id, operation.away_team_entry_id
        )),
    standing.administrative_results
  from public.tournament_team_standings standing
  left join public.tournament_player_statistics player_stats
    on player_stats.revision_id = standing.revision_id
    and player_stats.team_entry_id = standing.team_entry_id
  where standing.revision_id = v_revision.id
  group by standing.participant_id, standing.team_entry_id, standing.goals_for,
    standing.administrative_results;

  with form as (
    select standing.participant_id,
      source.official_at,
      case
        when (
          match_row.home_participant_id = standing.participant_id
          and score.home_score > score.away_score
        ) or (
          match_row.away_participant_id = standing.participant_id
          and score.away_score > score.home_score
        ) then 'W'
        when score.home_score = score.away_score then 'D'
        else 'L'
      end result,
      row_number() over (
        partition by standing.participant_id
        order by source.official_at desc, source.match_id
      ) form_order
    from public.tournament_team_standings standing
    join public.tournament_projection_sources source
      on source.revision_id = standing.revision_id
    join public.tournament_matches match_row
      on match_row.id = source.match_id
      and standing.participant_id in (
        match_row.home_participant_id, match_row.away_participant_id
      )
    join public.tournament_match_outcomes outcome
      on outcome.match_operation_id = source.match_operation_id
      and outcome.counts_for_standings
    join public.tournament_match_scores score
      on score.match_operation_id = source.match_operation_id
    where standing.revision_id = v_revision.id
  ), form_with_first as (
    select form.*,
      first_value(result) over (
        partition by participant_id order by form_order
      ) first_result
    from form
  ), streaks as (
    select form_with_first.*,
      sum(case when result = first_result then 0 else 1 end) over (
        partition by participant_id order by form_order
      ) break_count
    from form_with_first
  ), summary as (
    select participant_id,
      jsonb_agg(result order by form_order) filter (where form_order <= 5) recent_form,
      max(case when form_order = 1 then result end) first_result,
      count(*) filter (where break_count = 0)::integer streak_count
    from streaks
    group by participant_id
  )
  update public.tournament_team_statistics stats
  set recent_form = coalesce(summary.recent_form, '[]'::jsonb),
    streak_type = case summary.first_result
      when 'W' then 'win' when 'D' then 'draw' when 'L' then 'loss' end,
    streak_count = summary.streak_count
  from summary
  where stats.revision_id = v_revision.id
    and stats.participant_id = summary.participant_id;

  create temporary table if not exists pg_temp.tournament_discipline_event_work (
    event_id uuid primary key,
    match_operation_id uuid not null,
    match_id uuid not null,
    phase_id uuid not null,
    phase_sequence integer not null,
    official_at timestamptz not null,
    match_number integer not null,
    team_entry_id uuid not null,
    roster_player_id uuid not null,
    event_type text not null,
    sequence_number integer not null
  ) on commit drop;
  truncate pg_temp.tournament_discipline_event_work;

  insert into pg_temp.tournament_discipline_event_work (
    event_id, match_operation_id, match_id, phase_id, phase_sequence,
    official_at, match_number, team_entry_id, roster_player_id,
    event_type, sequence_number
  )
  select event.id, operation.id, match_row.id, match_row.phase_id,
    match_phase.sequence_number, operation.official_at, match_row.match_number,
    event.team_entry_id, event.roster_player_id, event.event_type,
    event.sequence_number
  from public.tournament_matches match_row
  join public.tournament_phases match_phase on match_phase.id = match_row.phase_id
  join public.tournament_match_operations operation
    on operation.match_id = match_row.id and operation.status = 'official'
  join public.tournament_match_outcomes outcome
    on outcome.match_operation_id = operation.id and outcome.events_remain_valid
  join public.tournament_match_events event
    on event.match_operation_id = operation.id and event.voided_at is null
  join public.tournament_team_standings current_team
    on current_team.revision_id = v_revision.id
    and current_team.team_entry_id = event.team_entry_id
  where match_row.fixture_version_id = v_fixture.id
    and match_phase.sequence_number <= v_phase.sequence_number
    and (
      not v_discipline.reset_yellows_each_stage
      or match_row.phase_id = p_phase_id
    )
    and (
      match_row.phase_id <> p_phase_id
      or match_row.group_id is not distinct from p_group_id
    )
    and event.roster_player_id is not null
    and event.event_type in ('yellow_card', 'second_yellow', 'red_card');

  insert into public.tournament_discipline_ledgers (
    revision_id, organization_id, tournament_id, category_id, phase_id, group_id,
    roster_player_id, team_entry_id, yellow_cards, second_yellows, direct_reds,
    fair_play_points, automatic_suspensions
  )
  select v_revision.id, p_organization_id, p_tournament_id, p_category_id,
    p_phase_id, p_group_id, event.roster_player_id, event.team_entry_id,
    count(*) filter (where event.event_type = 'yellow_card')::integer,
    count(*) filter (where event.event_type = 'second_yellow')::integer,
    count(*) filter (where event.event_type = 'red_card')::integer,
    (
      count(*) filter (where event.event_type = 'yellow_card')
        * v_discipline.yellow_fair_play_points
      + count(*) filter (where event.event_type = 'second_yellow')
        * case when v_discipline.double_yellow_counts_as_red
          then v_discipline.red_fair_play_points
          else v_discipline.yellow_fair_play_points end
      + count(*) filter (where event.event_type = 'red_card')
        * v_discipline.red_fair_play_points
    )::integer,
    floor((
      count(*) filter (where event.event_type = 'yellow_card')
    )::numeric / v_discipline.yellows_for_suspension)::integer
      + count(*) filter (where event.event_type = 'red_card')::integer
      + case when v_discipline.double_yellow_counts_as_red
        then count(*) filter (where event.event_type = 'second_yellow')::integer
        else 0 end
  from pg_temp.tournament_discipline_event_work event
  group by event.roster_player_id, event.team_entry_id;

  insert into public.tournament_player_suspensions (
    revision_id, organization_id, tournament_id, category_id, phase_id, group_id,
    roster_player_id, team_entry_id, source_type, source_key, source_event_id,
    source_match_id, rule_snapshot, total_matches, reason
  )
  select v_revision.id, p_organization_id, p_tournament_id, p_category_id,
    p_phase_id, p_group_id, threshold_event.roster_player_id,
    threshold_event.team_entry_id,
    'yellow_accumulation', 'yellow:' || threshold_event.event_id::text,
    threshold_event.event_id, threshold_event.match_id,
    jsonb_build_object(
      'threshold', v_discipline.yellows_for_suspension,
      'matches', v_discipline.suspension_matches,
      'yellowNumber', threshold_event.yellow_number,
      'resetEachStage', v_discipline.reset_yellows_each_stage
    ),
    v_discipline.suspension_matches,
    'Acumulación de ' || v_discipline.yellows_for_suspension::text || ' amarillas'
  from (
    select yellow_event.*,
      row_number() over (
        partition by yellow_event.roster_player_id
        order by yellow_event.phase_sequence, yellow_event.official_at,
          yellow_event.match_number, yellow_event.sequence_number, yellow_event.event_id
      )::integer yellow_number
    from pg_temp.tournament_discipline_event_work yellow_event
    where yellow_event.event_type = 'yellow_card'
  ) threshold_event
  where threshold_event.phase_id = p_phase_id
    and threshold_event.yellow_number % v_discipline.yellows_for_suspension = 0;

  insert into public.tournament_player_suspensions (
    revision_id, organization_id, tournament_id, category_id, phase_id, group_id,
    roster_player_id, team_entry_id, source_type, source_key, source_event_id,
    source_match_id, rule_snapshot, total_matches, reason
  )
  select v_revision.id, p_organization_id, p_tournament_id, p_category_id,
    p_phase_id, p_group_id, event.roster_player_id, event.team_entry_id,
    case when event.event_type = 'red_card' then 'direct_red' else 'second_yellow' end,
    event.match_id::text || ':' || event.event_type || ':' ||
      event.sequence_number::text,
    event.event_id, event.match_id,
    jsonb_build_object(
      'eventType', event.event_type,
      'matches', case when event.event_type = 'red_card'
        then coalesce(v_discipline.direct_red_suggested_matches, v_discipline.suspension_matches)
        else v_discipline.suspension_matches end
    ),
    case when event.event_type = 'red_card'
      then coalesce(v_discipline.direct_red_suggested_matches, v_discipline.suspension_matches)
      else v_discipline.suspension_matches end,
    case when event.event_type = 'red_card' then 'Roja directa' else 'Segunda amarilla' end
  from pg_temp.tournament_discipline_event_work event
  where event.phase_id = p_phase_id
    and (
      event.event_type = 'red_card'
      or (event.event_type = 'second_yellow' and v_discipline.double_yellow_counts_as_red)
    );

  if v_fingerprint <> public.tournament_projection_source_fingerprint(
    v_fixture.id, p_phase_id, p_group_id
  ) then
    raise exception using errcode = '40001', message = 'TORNEOS_STANDINGS_SOURCES_CHANGED';
  end if;

  perform public.append_tournament_audit(
    p_organization_id, 'standings.rebuild', 'standings_revision',
    v_revision.id, null, p_tournament_id,
    jsonb_build_object(
      'categoryId', p_category_id, 'phaseId', p_phase_id,
      'groupId', p_group_id, 'revisionNumber', v_number,
      'sourceFingerprint', v_fingerprint, 'reason', btrim(p_reason)
    )
  );
  return v_revision.id;
end;
$$;


--
-- Name: FUNCTION rebuild_tournament_standings(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_phase_id uuid, p_group_id uuid, p_reason text, p_idempotency_key uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.rebuild_tournament_standings(p_organization_id uuid, p_tournament_id uuid, p_category_id uuid, p_phase_id uuid, p_group_id uuid, p_reason text, p_idempotency_key uuid) IS 'Recalcula la tabla y devuelve una revisión borrador reproducible. Volver a recalcular sin que las fuentes hayan cambiado se responde como error del cliente: el borrador vigente ya refleja esos datos.';


--
-- Name: record_manual_match_availability(uuid, uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_manual_match_availability(p_organization_id uuid, p_match_id uuid, p_roster_player_id uuid, p_response text, p_reason text, p_comment text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_match public.tournament_matches%rowtype;
  v_player public.tournament_roster_players%rowtype;
  v_response public.tournament_match_availability_responses%rowtype;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if p_response not in ('available', 'unavailable', 'maybe')
    or char_length(btrim(coalesce(p_reason, ''))) not between 3 and 500
  then
    raise exception using errcode = '22023', message = 'TORNEOS_INVALID_AVAILABILITY';
  end if;
  select * into v_match from public.tournament_matches
  where id = p_match_id and organization_id = p_organization_id for share;
  select player.* into v_player
  from public.tournament_roster_players player
  join public.tournament_rosters roster
    on roster.id = player.roster_id
    and roster.status in ('approved', 'locked')
  where player.id = p_roster_player_id
    and player.organization_id = p_organization_id
    and player.status = 'active'
    and player.eligibility_status = 'eligible';
  if v_match.id is null or v_match.status not in ('scheduled', 'ready')
    or v_match.scheduled_at is null or now() >= v_match.scheduled_at
    or v_player.id is null
    or not public.can_manage_tournament_match_squad(
      p_organization_id, p_match_id, v_player.team_entry_id
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournament_match_operations operation
    where operation.match_id = p_match_id
      and operation.status not in ('superseded', 'voided')
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MATCH_OPERATION_ACTIVE';
  end if;
  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:match-availability:' || p_match_id || ':' || v_player.id, 0
  ));
  insert into public.tournament_match_availability_responses (
    organization_id, match_id, team_entry_id, roster_player_id, user_id,
    response, comment, response_source, recorded_by, manual_reason
  ) values (
    p_organization_id, p_match_id, v_player.team_entry_id, v_player.id,
    v_player.arma2_user_id, p_response, nullif(btrim(p_comment), ''),
    'manual', private.current_identity_id(), btrim(p_reason)
  )
  on conflict (match_id, roster_player_id) do update set
    response = excluded.response, comment = excluded.comment,
    user_id = excluded.user_id, response_source = 'manual',
    recorded_by = excluded.recorded_by, manual_reason = excluded.manual_reason,
    responded_at = now(), updated_at = now()
  where public.tournament_match_availability_responses.response_source = 'manual'
  returning * into v_response;
  if v_response.id is null then
    raise exception using errcode = '55000',
      message = 'TORNEOS_MATCH_AVAILABILITY_SELF_AUTHORITATIVE';
  end if;
  perform public.append_tournament_audit(
    p_organization_id, 'match_availability.recorded_manual',
    'match_availability', v_response.id, v_player.team_entry_id,
    v_match.tournament_id, jsonb_build_object('response', p_response, 'source', 'manual')
  );
  return jsonb_build_object('id', v_response.id, 'response', v_response.response);
end;
$$;


--
-- Name: record_tournament_purchase_preference(uuid, text, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_tournament_purchase_preference(p_purchase_id uuid, p_provider text, p_provider_environment text, p_provider_preference_id text, p_preference_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_purchase public.tournament_purchases%rowtype;
begin
  if p_provider_preference_id is null
    or char_length(btrim(p_provider_preference_id)) not between 3 and 200 then
    raise exception using errcode = '22023', message = 'TORNEOS_PREFERENCE_INVALID';
  end if;
  select * into v_purchase from public.tournament_purchases
  where id = p_purchase_id for update;
  if v_purchase.id is null or v_purchase.provider <> p_provider
    or v_purchase.provider_environment <> p_provider_environment then
    raise exception using errcode = '22023', message = 'TORNEOS_PURCHASE_INVALID';
  end if;
  if v_purchase.provider_preference_id is not null then
    if v_purchase.provider_preference_id <> btrim(p_provider_preference_id) then
      raise exception using errcode = '55000', message = 'TORNEOS_PREFERENCE_CONFLICT';
    end if;
    return public.tournament_purchase_projection(v_purchase)
      || jsonb_build_object('idempotentReplay',true);
  end if;
  if v_purchase.status <> 'created' then
    raise exception using errcode = '55000', message = 'TORNEOS_PURCHASE_TRANSITION_INVALID';
  end if;

  update public.tournament_purchases set
    status = 'preference_created',provider_status = 'created',
    provider_preference_id = btrim(p_provider_preference_id),
    preference_expires_at = coalesce(p_preference_expires_at,preference_expires_at),
    last_verified_at = now()
  where id = v_purchase.id returning * into v_purchase;
  insert into public.tournament_purchase_events (
    purchase_id,organization_id,event_type,from_status,to_status,provider_status,
    actor_type
  ) values (
    v_purchase.id,v_purchase.organization_id,'preference.created','created',
    'preference_created','created','service'
  );
  return public.tournament_purchase_projection(v_purchase)
    || jsonb_build_object('idempotentReplay',false);
end;
$$;


