--
-- Name: set_active_tournament_context(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_active_tournament_context(p_organization_id uuid, p_season_id uuid, p_tournament_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := private.current_identity_id();
begin
  if v_user_id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(
    p_organization_id,
    'workspace.access'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_CONTEXT_FORBIDDEN';
  end if;
  perform 1
  from public.tournament_seasons season
  where season.id = p_season_id
    and season.organization_id = p_organization_id
    and season.status <> 'archived'
  for share;

  if not found then
    raise exception using errcode = '42501', message = 'TORNEOS_CONTEXT_FORBIDDEN';
  end if;

  if p_tournament_id is not null then
    perform 1
    from public.tournaments tournament
    where tournament.id = p_tournament_id
      and tournament.organization_id = p_organization_id
      and tournament.season_id = p_season_id
      and tournament.status <> 'archived'
    for share;

    if not found then
      raise exception using errcode = '42501', message = 'TORNEOS_CONTEXT_FORBIDDEN';
    end if;
  end if;

  insert into public.user_tournament_context_preferences (
    user_id,
    organization_id,
    active_season_id,
    active_tournament_id
  )
  values (v_user_id, p_organization_id, p_season_id, p_tournament_id)
  on conflict (user_id, organization_id) do update
  set active_season_id = excluded.active_season_id,
      active_tournament_id = excluded.active_tournament_id;

  return jsonb_build_object(
    'organizationId', p_organization_id,
    'activeSeasonId', p_season_id,
    'activeTournamentId', p_tournament_id
  );
end;
$$;


--
-- Name: set_my_tournament_hub_category(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_my_tournament_hub_category(p_tournament_id uuid, p_category_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_scope record;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;

  select tournament.organization_id, category.name category_name
  into v_scope
  from public.tournaments tournament
  join public.tournament_categories category
    on category.organization_id = tournament.organization_id
   and category.tournament_id = tournament.id
   and category.id = p_category_id
   and category.status = 'active'
  where tournament.id = p_tournament_id;

  if v_scope.organization_id is null
    or not public.can_read_tournament_participant_hub(
      p_tournament_id,
      p_category_id
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_HUB_FORBIDDEN';
  end if;

  insert into public.tournament_participant_hub_preferences (
    user_id,
    organization_id,
    tournament_id,
    category_id
  )
  values (
    private.current_identity_id(),
    v_scope.organization_id,
    p_tournament_id,
    p_category_id
  )
  on conflict (user_id, tournament_id)
  do update
  set organization_id = excluded.organization_id,
      category_id = excluded.category_id,
      updated_at = now();

  return jsonb_build_object(
    'tournamentId', p_tournament_id,
    'categoryId', p_category_id,
    'categoryName', v_scope.category_name,
    'updatedAt', now()
  );
end;
$$;


--
-- Name: set_tournament_announcement_audience(uuid, text, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_tournament_announcement_audience(p_announcement_id uuid, p_audience_type text, p_category_id uuid DEFAULT NULL::uuid, p_team_entry_id uuid DEFAULT NULL::uuid, p_match_id uuid DEFAULT NULL::uuid, p_specific_user_id uuid DEFAULT NULL::uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_announcement public.tournament_announcements%rowtype;
  v_id uuid;
begin
  select * into v_announcement
  from public.tournament_announcements announcement
  where announcement.id = p_announcement_id
  for update;
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if v_announcement.id is null
    or v_announcement.status not in ('draft','scheduled')
    or not public.has_tournament_communications_capability(
      v_announcement.organization_id,'announcements.update_draft'
    )
    or (
      v_announcement.author_user_id <> private.current_identity_id()
      and not public.has_tournament_communications_capability(
        v_announcement.organization_id,'announcements.publish'
      )
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  if (select count(*) from public.tournament_announcement_audiences audience
      where audience.announcement_id = p_announcement_id) >= 12
  then
    raise exception using errcode = '54000', message = 'TORNEOS_AUDIENCE_LIMIT_REACHED';
  end if;
  if p_audience_type = 'category' and not exists (
    select 1 from public.tournament_categories category
    where category.id = p_category_id
      and category.organization_id = v_announcement.organization_id
      and category.tournament_id = v_announcement.tournament_id
      and category.status = 'active'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_INVALID_AUDIENCE';
  elsif p_audience_type = 'team' and not exists (
    select 1 from public.tournament_team_entries entry
    where entry.id = p_team_entry_id
      and entry.organization_id = v_announcement.organization_id
      and entry.tournament_id = v_announcement.tournament_id
      and entry.status = 'approved'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_INVALID_AUDIENCE';
  elsif p_audience_type in ('match','home_team','away_team') and not exists (
    select 1 from public.tournament_matches match
    join public.tournament_fixture_versions fixture
      on fixture.id = match.fixture_version_id
     and fixture.organization_id = match.organization_id
     and fixture.status = 'published'
    where match.id = p_match_id
      and match.organization_id = v_announcement.organization_id
      and match.tournament_id = v_announcement.tournament_id
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_INVALID_AUDIENCE';
  end if;

  insert into public.tournament_announcement_audiences (
    organization_id,announcement_id,audience_type,category_id,team_entry_id,
    match_id,specific_user_id,created_by
  ) values (
    v_announcement.organization_id,p_announcement_id,p_audience_type,
    p_category_id,p_team_entry_id,p_match_id,p_specific_user_id,private.current_identity_id()
  )
  on conflict on constraint tournament_announcement_audiences_unique
  do update set created_by = excluded.created_by
  returning id into v_id;
  return v_id;
end;
$$;


--
-- Name: set_tournament_announcement_link(uuid, text, uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_tournament_announcement_link(p_announcement_id uuid, p_link_type text, p_resource_id uuid, p_external_url text, p_label text, p_sort_order integer) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_announcement public.tournament_announcements%rowtype;
  v_id uuid;
  v_valid boolean := false;
begin
  select * into v_announcement
  from public.tournament_announcements announcement
  where announcement.id = p_announcement_id
  for update;
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if v_announcement.id is null
    or v_announcement.status not in ('draft','scheduled')
    or not public.has_tournament_communications_capability(
      v_announcement.organization_id,'announcements.update_draft'
    )
    or (
      v_announcement.author_user_id <> private.current_identity_id()
      and not public.has_tournament_communications_capability(
        v_announcement.organization_id,'announcements.publish'
      )
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_COMMUNICATION_FORBIDDEN';
  end if;
  if (select count(*) from public.tournament_announcement_links link
      where link.announcement_id = p_announcement_id) >= 5
  then
    raise exception using errcode = '54000', message = 'TORNEOS_LINK_LIMIT_REACHED';
  end if;
  if p_link_type = 'external' then
    v_valid := p_external_url ~
      '^https://[A-Za-z0-9.-]+(?::[0-9]{1,5})?(?:/[^[:space:]]*)?$';
  elsif p_link_type = 'tournament' then
    v_valid := p_resource_id = v_announcement.tournament_id;
  elsif p_link_type = 'category' then
    v_valid := exists (
      select 1 from public.tournament_categories category
      where category.id = p_resource_id
        and category.organization_id = v_announcement.organization_id
        and category.tournament_id = v_announcement.tournament_id
        and category.status = 'active'
    );
  elsif p_link_type = 'match' then
    v_valid := exists (
      select 1 from public.tournament_matches match
      join public.tournament_fixture_versions fixture
        on fixture.organization_id = match.organization_id
       and fixture.id = match.fixture_version_id
       and fixture.status = 'published'
      where match.id = p_resource_id
        and match.organization_id = v_announcement.organization_id
        and match.tournament_id = v_announcement.tournament_id
    );
  elsif p_link_type in ('round','standings','discipline') then
    v_valid := p_resource_id = v_announcement.tournament_id;
  elsif p_link_type = 'document' then
    v_valid := exists (
      select 1 from public.tournament_documents document
      where document.id = p_resource_id
        and document.organization_id = v_announcement.organization_id
        and document.tournament_id = v_announcement.tournament_id
        and document.status = 'published'
    );
  end if;
  if not v_valid then
    raise exception using errcode = '42501', message = 'TORNEOS_INVALID_COMMUNICATION_LINK';
  end if;

  insert into public.tournament_announcement_links (
    organization_id,announcement_id,link_type,resource_id,external_url,label,sort_order
  ) values (
    v_announcement.organization_id,p_announcement_id,p_link_type,p_resource_id,
    nullif(btrim(coalesce(p_external_url,'')),''),btrim(p_label),p_sort_order
  )
  on conflict (announcement_id,sort_order) do update
  set link_type = excluded.link_type,resource_id = excluded.resource_id,
    external_url = excluded.external_url,label = excluded.label
  returning id into v_id;
  return v_id;
end;
$_$;


--
-- Name: set_tournament_branding_reference(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_tournament_branding_reference(p_organization_id uuid, p_entity_kind text, p_entity_id uuid, p_path text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_previous_path text;
  v_tournament_id uuid;
  v_audit_team_id uuid;
  v_expected_folder text;
  v_synced_participant_count integer := 0;
BEGIN
  IF private.current_identity_id() IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_AUTH_REQUIRED';
  END IF;

  v_expected_folder := CASE p_entity_kind
    WHEN 'organization' THEN 'organizations'
    WHEN 'tournament' THEN 'tournaments'
    WHEN 'team' THEN 'teams'
    ELSE NULL
  END;

  IF v_expected_folder IS NULL OR p_entity_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TORNEOS_BRANDING_INVALID_REFERENCE';
  END IF;

  IF p_path IS NOT NULL AND (
    NOT public.is_tournament_branding_path(p_path, v_expected_folder)
    OR split_part(p_path, '/', 1)::uuid <> p_organization_id
    OR split_part(p_path, '/', 3)::uuid <> p_entity_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TORNEOS_BRANDING_INVALID_REFERENCE';
  END IF;

  IF p_entity_kind = 'organization' THEN
    IF p_entity_id <> p_organization_id
      OR NOT public.has_tournament_organization_capability(
        p_organization_id,
        'organization.update'
      )
    THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_BRANDING_FORBIDDEN';
    END IF;

    SELECT organization.logo_path
    INTO v_previous_path
    FROM public.tournament_organizations organization
    WHERE organization.id = p_organization_id
      AND organization.status = 'active'
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_BRANDING_FORBIDDEN';
    END IF;

    UPDATE public.tournament_organizations
    SET logo_path = p_path
    WHERE id = p_organization_id;
  ELSIF p_entity_kind = 'tournament' THEN
    IF NOT public.has_tournament_organization_capability(
      p_organization_id,
      'tournaments.update'
    ) THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_BRANDING_FORBIDDEN';
    END IF;

    SELECT tournament.logo_path, tournament.id
    INTO v_previous_path, v_tournament_id
    FROM public.tournaments tournament
    WHERE tournament.id = p_entity_id
      AND tournament.organization_id = p_organization_id
      AND tournament.status <> 'archived'
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_BRANDING_FORBIDDEN';
    END IF;

    UPDATE public.tournaments
    SET logo_path = p_path
    WHERE id = p_entity_id;
  ELSE
    IF NOT public.can_update_tournament_team_branding(
      p_organization_id,
      p_entity_id
    ) THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_BRANDING_FORBIDDEN';
    END IF;

    SELECT entry.shield_path, entry.tournament_id, entry.id
    INTO v_previous_path, v_tournament_id, v_audit_team_id
    FROM public.tournament_team_entries entry
    WHERE entry.id = p_entity_id
      AND entry.organization_id = p_organization_id
    FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_BRANDING_FORBIDDEN';
    END IF;

    UPDATE public.tournament_team_entries
    SET shield_path = p_path
    WHERE id = p_entity_id;

    -- Participant snapshots keep competitive identity frozen (name, colors,
    -- seeding and membership) while projecting the current visual identity.
    -- Existing fixture, standings and public RPCs already render this field.
    UPDATE public.tournament_competition_participants participant
    SET snapshot_shield_path = p_path
    WHERE participant.organization_id = p_organization_id
      AND participant.team_entry_id = p_entity_id;
    GET DIAGNOSTICS v_synced_participant_count = ROW_COUNT;
  END IF;

  PERFORM public.append_tournament_audit(
    p_organization_id,
    'branding.' || p_entity_kind || CASE WHEN p_path IS NULL THEN '.removed' ELSE '.updated' END,
    p_entity_kind || '_branding',
    p_entity_id,
    v_audit_team_id,
    v_tournament_id,
    jsonb_build_object(
      'hadPrevious', v_previous_path IS NOT NULL,
      'hasCurrent', p_path IS NOT NULL,
      'previousPath', v_previous_path,
      'path', p_path,
      'syncedParticipantCount', v_synced_participant_count
    )
  );

  RETURN jsonb_build_object(
    'entityKind', p_entity_kind,
    'entityId', p_entity_id,
    'previousPath', v_previous_path,
    'path', p_path
  );
END;
$$;


--
-- Name: set_tournament_entitlement_override(uuid, uuid, text, boolean, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_tournament_entitlement_override(p_organization_id uuid, p_tournament_id uuid, p_capability text, p_enabled boolean, p_expires_at timestamp with time zone, p_reason text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_override_id uuid;
BEGIN
  IF p_enabled IS NULL
    OR p_reason IS NULL
    OR btrim(p_reason) <> p_reason
    OR char_length(p_reason) NOT BETWEEN 8 AND 500
    OR (p_expires_at IS NOT NULL AND p_expires_at <= now())
    OR NOT EXISTS (
      SELECT 1 FROM public.tournament_entitlement_capabilities catalog
      WHERE catalog.capability = p_capability
    )
    OR NOT EXISTS (
      SELECT 1 FROM public.tournament_organizations organization
      WHERE organization.id = p_organization_id
    )
  THEN
    RAISE EXCEPTION USING errcode = '22023', message = 'TORNEOS_ENTITLEMENT_OVERRIDE_INVALID';
  END IF;

  IF p_tournament_id IS NULL THEN
    INSERT INTO public.tournament_organization_entitlement_overrides (
      organization_id,capability,enabled,expires_at,reason
    ) VALUES (
      p_organization_id,p_capability,p_enabled,p_expires_at,p_reason
    )
    ON CONFLICT (organization_id,capability) DO UPDATE SET
      enabled = excluded.enabled,
      expires_at = excluded.expires_at,
      reason = excluded.reason
    RETURNING id INTO v_override_id;
  ELSE
    IF NOT EXISTS (
      SELECT 1 FROM public.tournaments tournament
      WHERE tournament.organization_id = p_organization_id
        AND tournament.id = p_tournament_id
    ) THEN
      RAISE EXCEPTION USING errcode = '22023', message = 'TORNEOS_ENTITLEMENT_SCOPE_INVALID';
    END IF;
    INSERT INTO public.tournament_entitlement_overrides (
      organization_id,tournament_id,capability,enabled,expires_at,reason
    ) VALUES (
      p_organization_id,p_tournament_id,p_capability,p_enabled,p_expires_at,p_reason
    )
    ON CONFLICT (organization_id,tournament_id,capability) DO UPDATE SET
      enabled = excluded.enabled,
      expires_at = excluded.expires_at,
      reason = excluded.reason
    RETURNING id INTO v_override_id;
  END IF;

  INSERT INTO public.tournament_audit_log (
    organization_id,actor_user_id,actor_type,action,resource_type,
    resource_id,tournament_id,metadata
  ) VALUES (
    p_organization_id,NULL,'system','entitlement.override_added',
    'entitlement_override',v_override_id,p_tournament_id,
    jsonb_build_object(
      'capability',p_capability,'enabled',p_enabled,
      'expiresAt',p_expires_at,'scope',CASE WHEN p_tournament_id IS NULL
        THEN 'organization' ELSE 'tournament' END
    )
  );
  RETURN v_override_id;
END;
$$;


--
-- Name: set_tournament_match_outcome(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_tournament_match_outcome(p_organization_id uuid, p_match_operation_id uuid, p_outcome jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_operation public.tournament_match_operations%rowtype;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status <> 'draft'
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_outcomes.manage'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if p_outcome->>'outcomeType' in (
    'home_no_show', 'away_no_show', 'double_no_show',
    'walkover_home', 'walkover_away', 'administrative_result'
  ) and not public.has_tournament_organization_capability(
    p_organization_id, 'match_administrative_results.manage'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  insert into public.tournament_match_outcomes (
    match_operation_id, organization_id, match_id, outcome_type,
    started_at, ended_at, suspension_minute, suspension_period,
    events_remain_valid, reason_code, reason_text,
    administrative_home_score, administrative_away_score,
    counts_for_standings, counts_for_player_stats, requires_resolution,
    resolved_by, resolved_at
  ) values (
    v_operation.id, p_organization_id, v_operation.match_id, p_outcome->>'outcomeType',
    (p_outcome->>'startedAt')::timestamptz, (p_outcome->>'endedAt')::timestamptz,
    (p_outcome->>'suspensionMinute')::smallint, p_outcome->>'suspensionPeriod',
    coalesce((p_outcome->>'eventsRemainValid')::boolean, true),
    p_outcome->>'reasonCode', nullif(btrim(p_outcome->>'reasonText'), ''),
    (p_outcome->>'administrativeHomeScore')::smallint,
    (p_outcome->>'administrativeAwayScore')::smallint,
    coalesce((p_outcome->>'countsForStandings')::boolean, false),
    coalesce((p_outcome->>'countsForPlayerStats')::boolean, false),
    coalesce((p_outcome->>'requiresResolution')::boolean, false),
    case when coalesce((p_outcome->>'requiresResolution')::boolean, false) then null else private.current_identity_id() end,
    case when coalesce((p_outcome->>'requiresResolution')::boolean, false) then null else now() end
  )
  on conflict (match_operation_id) do update set
    outcome_type = excluded.outcome_type, started_at = excluded.started_at,
    ended_at = excluded.ended_at, suspension_minute = excluded.suspension_minute,
    suspension_period = excluded.suspension_period,
    events_remain_valid = excluded.events_remain_valid,
    reason_code = excluded.reason_code, reason_text = excluded.reason_text,
    administrative_home_score = excluded.administrative_home_score,
    administrative_away_score = excluded.administrative_away_score,
    counts_for_standings = excluded.counts_for_standings,
    counts_for_player_stats = excluded.counts_for_player_stats,
    requires_resolution = excluded.requires_resolution,
    resolved_by = excluded.resolved_by, resolved_at = excluded.resolved_at,
    updated_at = now();
  update public.tournament_match_operations set
    match_status = case
      when p_outcome->>'outcomeType' = 'played' then 'played'
      when p_outcome->>'outcomeType' = 'suspended' then 'suspended'
      when p_outcome->>'outcomeType' = 'abandoned' then 'abandoned'
      when p_outcome->>'outcomeType' in (
        'home_no_show', 'away_no_show', 'double_no_show',
        'walkover_home', 'walkover_away', 'administrative_result'
      ) then 'administrative'
      else match_status end,
    updated_at = now()
  where id = v_operation.id;
  perform public.append_tournament_audit(
    p_organization_id,
    case when p_outcome->>'outcomeType' = 'suspended'
      then 'match_operation.suspended'
      when p_outcome->>'outcomeType' in ('home_no_show', 'away_no_show', 'double_no_show')
      then 'match_operation.no_show'
      else 'match_operation.outcome_set' end,
    'match_operation', v_operation.id, null, v_operation.tournament_id,
    jsonb_build_object('outcomeType', p_outcome->>'outcomeType')
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_operation.id);
end;
$$;


--
-- Name: set_tournament_match_score(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_tournament_match_score(p_organization_id uuid, p_match_operation_id uuid, p_score jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_operation public.tournament_match_operations%rowtype;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status <> 'draft'
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_scores.manage'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if p_score->>'scoreType' in ('administrative', 'walkover')
    and not public.has_tournament_organization_capability(
      p_organization_id, 'match_administrative_results.manage'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  insert into public.tournament_match_scores (
    match_operation_id, organization_id, match_id, home_score, away_score,
    home_score_first_half, away_score_first_half, home_penalties, away_penalties,
    score_type
  ) values (
    v_operation.id, p_organization_id, v_operation.match_id,
    (p_score->>'homeScore')::smallint, (p_score->>'awayScore')::smallint,
    (p_score->>'homeScoreFirstHalf')::smallint,
    (p_score->>'awayScoreFirstHalf')::smallint,
    (p_score->>'homePenalties')::smallint, (p_score->>'awayPenalties')::smallint,
    p_score->>'scoreType'
  )
  on conflict (match_operation_id) do update set
    home_score = excluded.home_score, away_score = excluded.away_score,
    home_score_first_half = excluded.home_score_first_half,
    away_score_first_half = excluded.away_score_first_half,
    home_penalties = excluded.home_penalties, away_penalties = excluded.away_penalties,
    score_type = excluded.score_type, updated_at = now();
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.score_set', 'match_operation',
    v_operation.id, null, v_operation.tournament_id,
    jsonb_build_object(
      'homeScore', (p_score->>'homeScore')::integer,
      'awayScore', (p_score->>'awayScore')::integer,
      'scoreType', p_score->>'scoreType'
    )
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_operation.id);
end;
$$;


--
-- Name: set_tournament_media_cover(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_tournament_media_cover(p_gallery_id uuid, p_asset_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_gallery public.tournament_media_galleries%rowtype;
begin
  select * into v_gallery
  from public.tournament_media_galleries where id = p_gallery_id;
  if v_gallery.id is null or not public.has_tournament_media_capability(
    v_gallery.organization_id,'media.set_cover'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_gallery.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_gallery.id::text,1)
  );
  select * into v_gallery
  from public.tournament_media_galleries
  where id = p_gallery_id
  for update;
  if v_gallery.status not in ('draft','under_review') then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_GALLERY_IMMUTABLE';
  end if;
  if not exists (
    select 1 from public.tournament_media_assets asset
    where asset.id = p_asset_id and asset.gallery_id = p_gallery_id
      and asset.status in ('approved','published')
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_COVER_INVALID';
  end if;
  update public.tournament_media_galleries
  set cover_asset_id = p_asset_id,version = version + 1
  where id = p_gallery_id;
  perform public.append_tournament_audit(
    v_gallery.organization_id,'media.gallery.cover_set','media_gallery',
    p_gallery_id,null,v_gallery.tournament_id,jsonb_build_object('assetId',p_asset_id)
  );
  return jsonb_build_object('galleryId',p_gallery_id,'coverAssetId',p_asset_id);
end;
$$;


--
-- Name: set_tournament_organization_subscription(uuid, text, timestamp with time zone, timestamp with time zone, timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_tournament_organization_subscription(p_organization_id uuid, p_status text, p_starts_at timestamp with time zone, p_current_period_end timestamp with time zone, p_grace_until timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cancelled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_post_expiration_retention_days integer DEFAULT 90) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
BEGIN
  RAISE EXCEPTION USING errcode = '0A000', message = 'TORNEOS_LEGACY_SUBSCRIPTION_DISABLED';
END;
$$;


--
-- Name: set_tournament_player_portrait_crop(uuid, uuid, numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_tournament_player_portrait_crop(p_organization_id uuid, p_portrait_id uuid, p_focal_x numeric, p_focal_y numeric, p_zoom numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_portrait public.tournament_player_portraits%ROWTYPE;
  v_focal_x numeric(5,4);
  v_focal_y numeric(5,4);
  v_zoom numeric(6,4);
BEGIN
  IF private.current_identity_id() IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_AUTH_REQUIRED';
  END IF;
  IF p_focal_x IS NULL OR p_focal_y IS NULL
    OR p_focal_x < 0 OR p_focal_x > 1
    OR p_focal_y < 0 OR p_focal_y > 1
  THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TORNEOS_PORTRAIT_FOCAL_INVALID';
  END IF;
  IF p_zoom IS NULL OR p_zoom < 1 OR p_zoom > 4 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TORNEOS_PORTRAIT_ZOOM_INVALID';
  END IF;
  v_focal_x := round(p_focal_x, 4);
  v_focal_y := round(p_focal_y, 4);
  v_zoom := round(p_zoom, 4);

  SELECT * INTO v_portrait FROM public.tournament_player_portraits
  WHERE id = p_portrait_id AND organization_id = p_organization_id
    AND lifecycle_status = 'active' FOR UPDATE;
  IF v_portrait.id IS NULL OR NOT public.can_manage_tournament_player_portrait_as(
    p_organization_id, v_portrait.roster_player_id, private.current_identity_id()
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_PORTRAIT_FORBIDDEN';
  END IF;

  UPDATE public.tournament_player_portraits
  SET focal_x = v_focal_x, focal_y = v_focal_y, crop_zoom = v_zoom, updated_at = now()
  WHERE id = p_portrait_id;

  PERFORM public.append_tournament_audit(
    p_organization_id, 'portrait.crop_updated', 'player_portrait', p_portrait_id,
    v_portrait.team_entry_id, v_portrait.tournament_id,
    jsonb_build_object(
      'rosterPlayerId', v_portrait.roster_player_id,
      'focalX', v_focal_x, 'focalY', v_focal_y, 'cropZoom', v_zoom
    )
  );
  RETURN jsonb_build_object(
    'portraitId', p_portrait_id, 'focalX', v_focal_x, 'focalY', v_focal_y,
    'cropZoom', v_zoom
  );
END;
$$;


--
-- Name: FUNCTION set_tournament_player_portrait_crop(p_organization_id uuid, p_portrait_id uuid, p_focal_x numeric, p_focal_y numeric, p_zoom numeric); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_tournament_player_portrait_crop(p_organization_id uuid, p_portrait_id uuid, p_focal_x numeric, p_focal_y numeric, p_zoom numeric) IS 'Encuadre no destructivo del retrato activo: punto focal y zoom normalizados. No modifica el objeto de Storage ni el estado editorial o de consentimiento.';


--
-- Name: set_tournament_player_portrait_editorial_status(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_tournament_player_portrait_editorial_status(p_organization_id uuid, p_portrait_id uuid, p_editorial_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_portrait public.tournament_player_portraits%ROWTYPE;
BEGIN
  IF private.current_identity_id() IS NULL OR p_editorial_status NOT IN ('approved', 'rejected') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TORNEOS_PORTRAIT_STATE_INVALID';
  END IF;
  SELECT * INTO v_portrait FROM public.tournament_player_portraits
  WHERE id = p_portrait_id AND organization_id = p_organization_id
    AND lifecycle_status = 'active' FOR UPDATE;
  IF v_portrait.id IS NULL OR NOT public.can_moderate_tournament_team_visual_assets_as(
    p_organization_id, v_portrait.team_entry_id, private.current_identity_id(), 'roster_players.update'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_PORTRAIT_FORBIDDEN';
  END IF;
  UPDATE public.tournament_player_portraits
  SET editorial_status = p_editorial_status, reviewed_by = private.current_identity_id(),
      reviewed_at = now(), updated_at = now()
  WHERE id = p_portrait_id;
  PERFORM public.append_tournament_audit(
    p_organization_id, 'portrait.reviewed', 'player_portrait', p_portrait_id,
    v_portrait.team_entry_id, v_portrait.tournament_id,
    jsonb_build_object('editorialStatus', p_editorial_status,
      'rosterPlayerId', v_portrait.roster_player_id)
  );
  RETURN jsonb_build_object('portraitId', p_portrait_id,
    'editorialStatus', p_editorial_status);
END;
$$;


--
-- Name: set_tournament_public_page_published(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_tournament_public_page_published(p_organization_id uuid, p_tournament_id uuid, p_published boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE
  v_actor uuid := private.current_identity_id();
  v_tournament public.tournaments%ROWTYPE;
  v_organization public.tournament_organizations%ROWTYPE;
  v_season public.tournament_seasons%ROWTYPE;
  v_page public.tournament_public_pages%ROWTYPE;
  v_candidate text;
  v_prefix text;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_AUTH_REQUIRED';
  END IF;
  IF p_published IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TORNEOS_PUBLIC_PAGE_INVALID_STATE';
  END IF;
  IF NOT public.has_tournament_organization_capability(
    p_organization_id,
    'tournaments.update'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_PUBLIC_PAGE_FORBIDDEN';
  END IF;

  PERFORM pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(p_tournament_id::text, 20260810)
  );

  SELECT tournament.*
  INTO v_tournament
  FROM public.tournaments tournament
  WHERE tournament.id = p_tournament_id
    AND tournament.organization_id = p_organization_id
  FOR UPDATE;
  IF v_tournament.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_PUBLIC_PAGE_FORBIDDEN';
  END IF;

  SELECT organization.* INTO v_organization
  FROM public.tournament_organizations organization
  WHERE organization.id = p_organization_id;
  SELECT season.* INTO v_season
  FROM public.tournament_seasons season
  WHERE season.id = v_tournament.season_id
    AND season.organization_id = p_organization_id;

  IF p_published AND (
    v_organization.status <> 'active'
    OR v_season.status = 'archived'
    OR v_tournament.status NOT IN ('registration', 'scheduled', 'active', 'completed')
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'TORNEOS_PUBLIC_PAGE_NOT_PUBLISHABLE';
  END IF;

  SELECT page.*
  INTO v_page
  FROM public.tournament_public_pages page
  WHERE page.tournament_id = p_tournament_id
    AND page.organization_id = p_organization_id
  FOR UPDATE;

  IF p_published THEN
    IF v_page.tournament_id IS NULL THEN
      v_prefix := regexp_replace(
        left(v_organization.slug || '-' || v_tournament.slug, 82),
        '-+$',
        ''
      );
      LOOP
        v_candidate := v_prefix || '-' || left(
          replace(gen_random_uuid()::text, '-', ''),
          10
        );
        EXIT WHEN NOT EXISTS (
          SELECT 1
          FROM public.tournament_public_pages candidate
          WHERE candidate.public_slug = v_candidate
        );
      END LOOP;

      INSERT INTO public.tournament_public_pages (
        tournament_id,
        organization_id,
        public_slug,
        status,
        published_by,
        published_at
      ) VALUES (
        p_tournament_id,
        p_organization_id,
        v_candidate,
        'published',
        v_actor,
        now()
      )
      RETURNING * INTO v_page;
    ELSE
      UPDATE public.tournament_public_pages
      SET status = 'published',
          published_by = v_actor,
          published_at = now(),
          unpublished_by = NULL,
          unpublished_at = NULL,
          updated_at = now()
      WHERE tournament_id = p_tournament_id
      RETURNING * INTO v_page;
    END IF;
  ELSIF v_page.tournament_id IS NOT NULL THEN
    UPDATE public.tournament_public_pages
    SET status = 'unpublished',
        unpublished_by = v_actor,
        unpublished_at = now(),
        updated_at = now()
    WHERE tournament_id = p_tournament_id
    RETURNING * INTO v_page;
  END IF;

  IF v_page.tournament_id IS NOT NULL THEN
    PERFORM public.append_tournament_audit(
      p_organization_id,
      CASE WHEN p_published THEN 'public_page.published' ELSE 'public_page.unpublished' END,
      'tournament_public_page',
      p_tournament_id,
      NULL,
      p_tournament_id,
      jsonb_build_object('published', p_published)
    );
  END IF;

  RETURN public.get_tournament_public_page_settings(
    p_organization_id,
    p_tournament_id
  );
END;
$_$;


--
-- Name: set_tournament_social_permission(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_tournament_social_permission(p_organization_id uuid, p_user_id uuid, p_can_export boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_role text;
begin
  if not public.has_tournament_social_capability(
    p_organization_id, 'social.manage_permissions'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_SOCIAL_FORBIDDEN';
  end if;
  select membership.role into v_role
  from public.tournament_organization_members membership
  where membership.organization_id = p_organization_id
    and membership.user_id = p_user_id
    and membership.status = 'active';
  if v_role is distinct from 'collaborator' then
    -- Owners and admins already hold everything; nobody else is a member.
    raise exception using errcode = '22023', message = 'TORNEOS_SOCIAL_GRANT_INVALID';
  end if;
  insert into public.tournament_social_permissions (
    organization_id, user_id, can_export, granted_by
  ) values (
    p_organization_id, p_user_id, coalesce(p_can_export, false), private.current_identity_id()
  ) on conflict (organization_id, user_id) do update set
    can_export = excluded.can_export,
    granted_by = excluded.granted_by,
    updated_at = now();
  perform public.append_tournament_audit(
    p_organization_id,
    case when coalesce(p_can_export, false)
      then 'social.export.granted' else 'social.export.revoked' end,
    'organization_member', p_user_id, null, null, '{}'::jsonb
  );
  return jsonb_build_object(
    'organizationId', p_organization_id, 'userId', p_user_id,
    'canExport', coalesce(p_can_export, false)
  );
end;
$$;


--
-- Name: set_tournament_team_photo_editorial_status(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_tournament_team_photo_editorial_status(p_organization_id uuid, p_team_photo_id uuid, p_editorial_status text, p_review_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_photo public.tournament_team_photos%ROWTYPE;
  v_reason text := nullif(btrim(coalesce(p_review_reason, '')), '');
  v_previous_current_id uuid;
BEGIN
  IF private.current_identity_id() IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_AUTH_REQUIRED';
  END IF;
  IF p_editorial_status NOT IN ('approved', 'rejected')
    OR (p_editorial_status = 'approved' AND v_reason IS NOT NULL)
    OR (v_reason IS NOT NULL AND char_length(v_reason) > 500)
  THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TORNEOS_TEAM_PHOTO_STATE_INVALID';
  END IF;

  SELECT * INTO v_photo
  FROM public.tournament_team_photos photo
  WHERE photo.id = p_team_photo_id
    AND photo.organization_id = p_organization_id
    AND photo.lifecycle_status = 'active'
    AND photo.editorial_status = 'pending_review'
  FOR UPDATE;
  -- Una fila que no existe, que ya tiene veredicto o que está en otro estado no
  -- se distingue de una prohibida: las dos respuestas son la misma puerta
  -- cerrada, y separarlas sería contar qué hay del otro lado.
  IF v_photo.id IS NULL OR NOT public.can_moderate_tournament_team_visual_assets_as(
    p_organization_id, v_photo.team_entry_id, private.current_identity_id(), 'team_entries.update'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_TEAM_PHOTO_FORBIDDEN';
  END IF;

  PERFORM 1 FROM public.tournament_team_entries entry
  WHERE entry.id = v_photo.team_entry_id FOR UPDATE;

  IF p_editorial_status = 'approved' THEN
    SELECT photo.id INTO v_previous_current_id
    FROM public.tournament_team_photos photo
    WHERE photo.team_entry_id = v_photo.team_entry_id
      AND photo.lifecycle_status = 'active'
      AND photo.editorial_status = 'approved'
    FOR UPDATE;

    IF v_previous_current_id IS NOT NULL THEN
      UPDATE public.tournament_team_photos
      SET lifecycle_status = 'replaced', replaced_by_id = v_photo.id,
          replaced_at = now(), updated_at = now()
      WHERE id = v_previous_current_id;
    END IF;

    UPDATE public.tournament_team_photos
    SET editorial_status = 'approved', reviewed_by = private.current_identity_id(),
        reviewed_at = now(), approved_at = now(), updated_at = now()
    WHERE id = p_team_photo_id;
  ELSE
    UPDATE public.tournament_team_photos
    SET editorial_status = 'rejected', reviewed_by = private.current_identity_id(),
        reviewed_at = now(), review_reason = v_reason, updated_at = now()
    WHERE id = p_team_photo_id;
  END IF;

  PERFORM public.append_tournament_audit(
    p_organization_id,
    CASE WHEN p_editorial_status = 'approved'
      THEN 'team_photo.approved' ELSE 'team_photo.rejected' END,
    'team_photo', p_team_photo_id, v_photo.team_entry_id, v_photo.tournament_id,
    jsonb_build_object(
      'editorialStatus', p_editorial_status,
      'reviewReason', v_reason,
      'replacedTeamPhotoId', v_previous_current_id
    )
  );

  RETURN jsonb_build_object(
    'teamPhotoId', p_team_photo_id,
    'editorialStatus', p_editorial_status,
    'reviewReason', v_reason,
    'replacedTeamPhotoId', v_previous_current_id
  );
END;
$$;


--
-- Name: set_tournament_team_visual_policy(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_tournament_team_visual_policy(p_organization_id uuid, p_tournament_id uuid, p_policy text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_previous_policy text;
BEGIN
  IF private.current_identity_id() IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_AUTH_REQUIRED';
  END IF;
  IF p_policy IS NULL OR p_policy NOT IN (
    'organization_only', 'delegates', 'roster'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'TORNEOS_VISUAL_POLICY_INVALID';
  END IF;
  IF NOT public.has_tournament_organization_capability(
    p_organization_id, 'tournaments.update'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_VISUAL_POLICY_FORBIDDEN';
  END IF;

  SELECT tournament.team_visual_management_policy
  INTO v_previous_policy
  FROM public.tournaments tournament
  WHERE tournament.id = p_tournament_id
    AND tournament.organization_id = p_organization_id
    AND tournament.status <> 'archived'
  FOR UPDATE;

  IF v_previous_policy IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'TORNEOS_VISUAL_POLICY_FORBIDDEN';
  END IF;

  IF v_previous_policy IS DISTINCT FROM p_policy THEN
    UPDATE public.tournaments
    SET team_visual_management_policy = p_policy
    WHERE id = p_tournament_id;

    -- Auditoría por el mecanismo existente: actor y timestamp los pone
    -- append_tournament_audit, el antes y el después viajan en la metadata.
    PERFORM public.append_tournament_audit(
      p_organization_id,
      'tournament.team_visual_policy_updated',
      'tournament_team_visual_policy',
      p_tournament_id,
      NULL,
      p_tournament_id,
      jsonb_build_object(
        'previousPolicy', v_previous_policy,
        'policy', p_policy
      )
    );
  END IF;

  RETURN jsonb_build_object(
    'organizationId', p_organization_id,
    'tournamentId', p_tournament_id,
    'previousPolicy', v_previous_policy,
    'policy', p_policy,
    'canUpdate', true
  );
END;
$$;


--
-- Name: FUNCTION set_tournament_team_visual_policy(p_organization_id uuid, p_tournament_id uuid, p_policy text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.set_tournament_team_visual_policy(p_organization_id uuid, p_tournament_id uuid, p_policy text) IS 'Cambia la política de autogestión visual del torneo. No modifica assets, metadata, consentimiento ni estado editorial.';


--
-- Name: set_tournament_workspace_preference(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_tournament_workspace_preference(p_workspace_type text, p_organization_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_user_id uuid := private.current_identity_id();
begin
  if v_user_id is null then
    raise exception using
      errcode = '42501',
      message = 'TORNEOS_AUTH_REQUIRED';
  end if;

  if p_workspace_type = 'personal' then
    if p_organization_id is not null then
      raise exception using
        errcode = '22023',
        message = 'TORNEOS_INVALID_WORKSPACE';
    end if;
  elsif p_workspace_type = 'tournament_organization' then
    if p_organization_id is null
      or not public.has_tournament_organization_capability(
        p_organization_id,
        'workspace.access'
      )
    then
      raise exception using
        errcode = '42501',
        message = 'TORNEOS_WORKSPACE_FORBIDDEN';
    end if;
  else
    raise exception using
      errcode = '22023',
      message = 'TORNEOS_INVALID_WORKSPACE';
  end if;

  insert into public.user_workspace_preferences (
    user_id,
    workspace_type,
    active_organization_id
  )
  values (
    v_user_id,
    p_workspace_type,
    p_organization_id
  )
  on conflict (user_id) do update
  set workspace_type = excluded.workspace_type,
      active_organization_id = excluded.active_organization_id;

  return jsonb_build_object(
    'workspaceType', p_workspace_type,
    'activeOrganizationId', p_organization_id
  );
end;
$$;


--
-- Name: start_tournament_competition(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_tournament_competition(p_organization_id uuid, p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tournament public.tournaments%rowtype;
  v_active_categories integer;
  v_categories_without_fixture integer;
  v_unscheduled integer;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  if not public.has_tournament_organization_capability(
    p_organization_id, 'tournaments.start'
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(
    'torneos:competition-lifecycle:' || p_tournament_id::text, 0
  ));

  select tournament.* into v_tournament
  from public.tournaments tournament
  join public.tournament_organizations organization
    on organization.id = tournament.organization_id
    and organization.status = 'active'
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
  for update of tournament;

  if v_tournament.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  if v_tournament.status = 'active' then
    -- Idempotencia: repetir la operación sobre una competencia ya En juego no
    -- es un error y no reescribe `started_at`.
    return jsonb_build_object(
      'id', v_tournament.id,
      'status', v_tournament.status,
      'startedAt', v_tournament.started_at,
      'alreadyStarted', true,
      'unscheduledMatches', (
        select count(*)
        from public.tournament_matches match_row
        join public.tournament_fixture_versions fixture
          on fixture.id = match_row.fixture_version_id
          and fixture.status = 'published'
          and fixture.invalidated_at is null
        where match_row.tournament_id = v_tournament.id
          and match_row.scheduled_at is null
          and match_row.status <> 'cancelled'
      )
    );
  end if;

  if v_tournament.status <> 'scheduled' then
    raise exception using errcode = '22023',
      message = 'TORNEOS_INVALID_TOURNAMENT_TRANSITION';
  end if;

  select count(*) into v_active_categories
  from public.tournament_categories category
  where category.organization_id = p_organization_id
    and category.tournament_id = p_tournament_id
    and category.status = 'active';

  if v_active_categories = 0 then
    raise exception using errcode = '23514',
      message = 'TORNEOS_COMPETITION_WITHOUT_CATEGORIES';
  end if;

  select count(*) into v_categories_without_fixture
  from public.tournament_categories category
  where category.organization_id = p_organization_id
    and category.tournament_id = p_tournament_id
    and category.status = 'active'
    and not exists (
      select 1
      from public.tournament_fixture_versions fixture
      where fixture.organization_id = category.organization_id
        and fixture.tournament_id = category.tournament_id
        and fixture.category_id = category.id
        and fixture.status = 'published'
        and fixture.invalidated_at is null
    );

  if v_categories_without_fixture > 0 then
    raise exception using errcode = '23514',
      message = 'TORNEOS_COMPETITION_FIXTURE_NOT_PUBLISHED';
  end if;

  -- Los partidos sin horario no impiden comenzar: se programan después.
  select count(*) into v_unscheduled
  from public.tournament_matches match_row
  join public.tournament_fixture_versions fixture
    on fixture.id = match_row.fixture_version_id
    and fixture.status = 'published'
    and fixture.invalidated_at is null
  where match_row.tournament_id = p_tournament_id
    and match_row.scheduled_at is null
    and match_row.status <> 'cancelled';

  update public.tournaments
  set status = 'active',
      started_at = now()
  where id = p_tournament_id
  returning * into v_tournament;

  perform public.append_tournament_audit(
    p_organization_id, 'tournament.started', 'tournament', v_tournament.id,
    null, v_tournament.id,
    jsonb_build_object(
      'previousStatus', 'scheduled',
      'nextStatus', 'active',
      'activeCategories', v_active_categories,
      'unscheduledMatches', v_unscheduled
    )
  );

  return jsonb_build_object(
    'id', v_tournament.id,
    'status', v_tournament.status,
    'startedAt', v_tournament.started_at,
    'alreadyStarted', false,
    'unscheduledMatches', v_unscheduled
  );
end;
$$;


--
-- Name: FUNCTION start_tournament_competition(p_organization_id uuid, p_tournament_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.start_tournament_competition(p_organization_id uuid, p_tournament_id uuid) IS 'Lista para comenzar -> En juego. Exige fixture publicado para todas las categorías activas y no exige programación completa.';


--
-- Name: submit_match_squad(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_match_squad(p_organization_id uuid, p_match_id uuid, p_team_entry_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_squad public.tournament_match_squads%rowtype;
  v_match public.tournament_matches%rowtype;
  v_team_size integer;
  v_substitutes_limit integer;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_match from public.tournament_matches
  where id = p_match_id and organization_id = p_organization_id for update;
  select * into v_squad from public.tournament_match_squads
  where match_id = p_match_id and team_entry_id = p_team_entry_id
    and status = 'draft' for update;
  if v_match.id is null or v_match.status not in ('scheduled', 'ready')
    or v_squad.id is null
    or not public.can_manage_tournament_match_squad(
      p_organization_id, p_match_id, p_team_entry_id
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  if exists (
    select 1 from public.tournament_match_operations operation
    where operation.match_id = p_match_id
      and operation.status not in ('superseded', 'voided')
  ) then
    raise exception using errcode = '22023', message = 'TORNEOS_MATCH_OPERATION_ACTIVE';
  end if;
  select coalesce(category.team_size, tournament.team_size),
    coalesce(tournament.substitutes_limit, tournament.team_size)
  into v_team_size, v_substitutes_limit
  from public.tournament_categories category
  join public.tournaments tournament on tournament.id = category.tournament_id
  where category.id = v_match.category_id;
  if (select count(*) from public.tournament_match_squad_players
      where match_squad_id = v_squad.id and lineup_status = 'starter') <> v_team_size
    or (select count(*) from public.tournament_match_squad_players
      where match_squad_id = v_squad.id and callup_status = 'called_up' and is_captain) <> 1
    or (select count(*) from public.tournament_match_squad_players
      where match_squad_id = v_squad.id and callup_status = 'called_up')
      > v_team_size + v_substitutes_limit
    or (select count(*) from public.tournament_match_squad_players
      where match_squad_id = v_squad.id and lineup_status = 'starter'
        and is_goalkeeper) < 1
    or (select count(*) from public.tournament_match_squad_players
      where match_squad_id = v_squad.id and lineup_status = 'starter'
        and is_captain) <> 1
    or exists (
      select 1
      from public.tournament_match_squad_players player
      where player.match_squad_id = v_squad.id
        and (
          player.lineup_status = 'starter'
          or player.is_captain
        )
        and player.attendance_status in ('absent', 'excused')
    )
  then
    raise exception using errcode = '23514', message = 'TORNEOS_INVALID_MATCH_SQUAD';
  end if;
  update public.tournament_match_squads set
    status = 'submitted', submitted_by = private.current_identity_id(), submitted_at = now(), updated_at = now()
  where id = v_squad.id returning * into v_squad;
  perform public.append_tournament_audit(
    p_organization_id, 'match_squad.submitted', 'match_squad', v_squad.id,
    p_team_entry_id, v_match.tournament_id, '{}'::jsonb
  );
  return public.get_match_squad_context(p_organization_id, p_match_id, p_team_entry_id);
end;
$$;


--
-- Name: submit_tournament_match_operation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_tournament_match_operation(p_organization_id uuid, p_match_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_operation public.tournament_match_operations%rowtype;
  v_validation jsonb;
begin
  if private.current_identity_id() is null then
    raise exception using errcode = '42501', message = 'TORNEOS_AUTH_REQUIRED';
  end if;
  select * into v_operation from public.tournament_match_operations
  where id = p_match_operation_id and organization_id = p_organization_id for update;
  if v_operation.id is null or v_operation.status <> 'draft'
    or not public.has_tournament_organization_capability(
      p_organization_id, 'match_operations.submit'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_MATCH_FORBIDDEN';
  end if;
  v_validation := public.validate_tournament_match_operation_payload(v_operation.id);
  if not (v_validation->>'valid')::boolean then
    raise exception using errcode = '23514',
      message = 'TORNEOS_MATCH_OPERATION_INVALID',
      detail = v_validation->'errors'::text;
  end if;
  update public.tournament_match_operations set
    status = 'submitted', match_status = 'awaiting_validation',
    submitted_by = private.current_identity_id(), submitted_at = now(), updated_at = now()
  where id = v_operation.id;
  insert into public.tournament_match_reviews (
    organization_id, match_operation_id, review_type, reason, requested_by
  ) values (
    p_organization_id, v_operation.id, 'validation',
    'Acta presentada para validación', private.current_identity_id()
  );
  perform public.append_tournament_audit(
    p_organization_id, 'match_operation.submitted', 'match_operation',
    v_operation.id, null, v_operation.tournament_id,
    jsonb_build_object('operationVersion', v_operation.operation_version)
  );
  return public.get_tournament_match_operation_context(p_organization_id, v_operation.id);
end;
$$;


--
-- Name: submit_tournament_team_entry(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_tournament_team_entry(p_organization_id uuid, p_team_entry_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_entry public.tournament_team_entries%rowtype;
  v_roster public.tournament_rosters%rowtype;
  v_validation jsonb;
begin
  select * into v_entry from public.tournament_team_entries
  where id = p_team_entry_id and organization_id = p_organization_id for update;
  select * into v_roster from public.tournament_rosters
  where team_entry_id = p_team_entry_id and status in ('draft', 'changes_requested')
  order by version desc limit 1 for update;
  if v_entry.id is null or v_entry.status not in ('in_progress', 'changes_requested')
    or not public.can_edit_tournament_team_entry(
      p_organization_id,
      p_team_entry_id
    )
  then raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN'; end if;
  if not exists (
    select 1 from public.tournament_team_managers
    where team_entry_id = p_team_entry_id and status = 'active'
  ) then raise exception using errcode = '23514', message = 'TORNEOS_MANAGER_REQUIRED'; end if;
  v_validation := public.validate_tournament_roster(p_organization_id, p_team_entry_id, v_roster.id);
  if not (v_validation->>'valid')::boolean then
    raise exception using errcode = '23514', message = 'TORNEOS_ROSTER_INCOMPLETE',
      detail = v_validation::text;
  end if;
  update public.tournament_rosters set status = 'submitted', submitted_at = now()
  where id = v_roster.id returning * into v_roster;
  update public.tournament_team_entries set
    status = 'submitted', submitted_by = private.current_identity_id(), submitted_at = now(),
    reviewed_by = null, reviewed_at = null, rejected_at = null
  where id = v_entry.id returning * into v_entry;
  perform public.append_tournament_audit(
    p_organization_id, 'team_entry.submitted', 'team_entry', v_entry.id,
    v_entry.id, v_entry.tournament_id,
    jsonb_build_object('rosterId', v_roster.id, 'version', v_roster.version)
  );
  return jsonb_build_object('entryId', v_entry.id, 'rosterId', v_roster.id, 'status', v_entry.status, 'validation', v_validation);
end;
$$;


--
-- Name: supersede_tournament_fixture(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.supersede_tournament_fixture(p_organization_id uuid, p_fixture_version_id uuid, p_idempotency_key uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_version public.tournament_fixture_versions%rowtype;
begin
  if private.current_identity_id() is null
    or not public.has_tournament_organization_capability(
      p_organization_id, 'fixture.supersede'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  select version.* into v_version
  from public.tournament_fixture_versions version
  where version.id = p_fixture_version_id
    and version.organization_id = p_organization_id
    and version.status = 'published';
  if v_version.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;
  return public.create_manual_fixture_version(
    p_organization_id, v_version.tournament_id, v_version.category_id,
    v_version.id, p_idempotency_key
  );
end;
$$;


--
-- Name: tag_tournament_media_asset(uuid, text, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tag_tournament_media_asset(p_asset_id uuid, p_relation_type text, p_match_id uuid, p_team_entry_id uuid, p_roster_player_id uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_asset public.tournament_media_assets%rowtype;
  v_gallery public.tournament_media_galleries%rowtype;
  v_category_id uuid;
  v_id uuid;
begin
  select * into v_asset from public.tournament_media_assets where id = p_asset_id;
  select * into v_gallery from public.tournament_media_galleries
  where id = v_asset.gallery_id;
  if v_asset.id is null or not public.has_tournament_media_capability(
    v_asset.organization_id,
    case when p_relation_type = 'player' then 'media.tag_player' else 'media.tag_team' end
  ) then
    raise exception using errcode = '42501', message = 'TORNEOS_MEDIA_FORBIDDEN';
  end if;
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_asset.organization_id::text,0)
  );
  perform pg_catalog.pg_advisory_xact_lock(
    pg_catalog.hashtextextended(v_asset.gallery_id::text,1)
  );
  select * into v_gallery
  from public.tournament_media_galleries
  where id = v_asset.gallery_id
  for update;
  if v_gallery.status not in ('draft','under_review') then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_GALLERY_IMMUTABLE';
  end if;
  if p_relation_type = 'match' then
    select match.category_id into v_category_id from public.tournament_matches match
    where match.id = p_match_id
      and match.organization_id = v_asset.organization_id
      and match.tournament_id = v_asset.tournament_id;
  elsif p_relation_type in ('team','player') then
    select entry.category_id into v_category_id
    from public.tournament_team_entries entry
    where entry.id = p_team_entry_id
      and entry.organization_id = v_asset.organization_id
      and entry.tournament_id = v_asset.tournament_id
      and entry.status = 'approved'
      and (
        p_relation_type = 'team'
        or exists (
          select 1 from public.tournament_roster_players player
          join public.tournament_rosters roster on roster.id = player.roster_id
          where player.id = p_roster_player_id
            and player.team_entry_id = entry.id
            and player.status = 'active'
            and roster.status in ('approved','locked')
        )
      );
  end if;
  if v_category_id is null
    or (v_gallery.category_id is not null and v_gallery.category_id <> v_category_id)
  then
    raise exception using errcode = '22023', message = 'TORNEOS_MEDIA_SCOPE_INVALID';
  end if;
  insert into public.tournament_media_relations (
    organization_id,tournament_id,category_id,asset_id,relation_type,
    match_id,team_entry_id,roster_player_id,created_by
  ) values (
    v_asset.organization_id,v_asset.tournament_id,v_category_id,p_asset_id,
    p_relation_type,p_match_id,p_team_entry_id,p_roster_player_id,private.current_identity_id()
  ) on conflict do nothing returning id into v_id;
  if v_id is null then
    select relation.id into v_id
    from public.tournament_media_relations relation
    where relation.asset_id = p_asset_id
      and relation.relation_type = p_relation_type
      and relation.match_id is not distinct from p_match_id
      and relation.team_entry_id is not distinct from p_team_entry_id
      and relation.roster_player_id is not distinct from p_roster_player_id;
  end if;
  return v_id;
end;
$$;


