--
-- Name: tournament_communications_role_capabilities(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_communications_role_capabilities(p_role text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_role
    when 'owner' then array[
      'announcements.read','announcements.create','announcements.update_draft',
      'announcements.publish','announcements.schedule','announcements.archive',
      'announcements.revoke','documents.read','documents.create',
      'documents.update_draft','documents.publish','documents.archive',
      'audiences.preview','deliveries.read_summary',
      'notification_preferences.manage_self'
    ]::text[]
    when 'admin' then array[
      'announcements.read','announcements.create','announcements.update_draft',
      'announcements.publish','announcements.schedule','announcements.archive',
      'announcements.revoke','documents.read','documents.create',
      'documents.update_draft','documents.publish','documents.archive',
      'audiences.preview','deliveries.read_summary',
      'notification_preferences.manage_self'
    ]::text[]
    when 'collaborator' then array[
      'announcements.read','announcements.create','announcements.update_draft',
      'documents.read','documents.create','documents.update_draft',
      'audiences.preview','notification_preferences.manage_self'
    ]::text[]
    else array['notification_preferences.manage_self']::text[]
  end;
$$;


--
-- Name: tournament_competition_open_commitments(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_competition_open_commitments(p_organization_id uuid, p_tournament_id uuid) RETURNS TABLE(match_id uuid, category_id uuid, match_number integer, reason_code text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select
    match_row.id,
    match_row.category_id,
    match_row.match_number,
    case
      when match_row.home_participant_id is null
        or match_row.away_participant_id is null
        then 'participants_unresolved'
      when not exists (
        select 1
        from public.tournament_match_operations operation
        where operation.match_id = match_row.id
          and operation.status = 'official'
      ) then 'operation_pending'
      when exists (
        select 1
        from public.tournament_match_operations operation
        join public.tournament_match_outcomes outcome
          on outcome.match_operation_id = operation.id
        where operation.match_id = match_row.id
          and operation.status = 'official'
          and outcome.requires_resolution
      ) then 'resolution_pending'
      else 'replay_pending'
    end
  from public.tournament_matches match_row
  join public.tournament_fixture_versions fixture
    on fixture.id = match_row.fixture_version_id
    and fixture.status = 'published'
    and fixture.invalidated_at is null
  join public.tournament_categories category
    on category.organization_id = match_row.organization_id
    and category.tournament_id = match_row.tournament_id
    and category.id = match_row.category_id
    and category.status = 'active'
  where match_row.organization_id = p_organization_id
    and match_row.tournament_id = p_tournament_id
    and match_row.status <> 'cancelled'
    and (
      match_row.home_participant_id is null
      or match_row.away_participant_id is null
      or not exists (
        select 1
        from public.tournament_match_operations operation
        join public.tournament_match_outcomes outcome
          on outcome.match_operation_id = operation.id
        where operation.match_id = match_row.id
          and operation.status = 'official'
          and not outcome.requires_resolution
          and outcome.outcome_type not in ('postponed_before_start', 'resumed_future')
      )
    )

  union all

  select
    match_row.id,
    match_row.category_id,
    match_row.match_number,
    'review_open'
  from public.tournament_match_reviews review
  join public.tournament_match_operations operation
    on operation.id = review.match_operation_id
  join public.tournament_matches match_row
    on match_row.id = operation.match_id
  join public.tournament_fixture_versions fixture
    on fixture.id = match_row.fixture_version_id
    and fixture.status = 'published'
    and fixture.invalidated_at is null
  where match_row.organization_id = p_organization_id
    and match_row.tournament_id = p_tournament_id
    and match_row.status <> 'cancelled'
    and review.status = 'open'
    and review.review_type in (
      'correction', 'dispute_future', 'administrative_resolution'
    );
$$;


--
-- Name: FUNCTION tournament_competition_open_commitments(p_organization_id uuid, p_tournament_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tournament_competition_open_commitments(p_organization_id uuid, p_tournament_id uuid) IS 'Compromisos deportivos todavía abiertos de una competencia. Superconjunto a nivel competencia del predicado de resolve_tournament_qualification: un `cancelled` y un resultado terminal como `not_played` cierran igual, mientras la calificación además exige marcador porque deduce cruces.';


--
-- Name: tournament_match_team_entries(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_match_team_entries(p_match_id uuid) RETURNS TABLE(home_team_entry_id uuid, away_team_entry_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select home_participant.team_entry_id, away_participant.team_entry_id
  from public.tournament_matches match_row
  join public.tournament_fixture_versions fixture
    on fixture.id = match_row.fixture_version_id
  join public.tournament_competition_participants home_participant
    on home_participant.id = match_row.home_participant_id
    and home_participant.participant_set_id = match_row.participant_set_id
  join public.tournament_competition_participants away_participant
    on away_participant.id = match_row.away_participant_id
    and away_participant.participant_set_id = match_row.participant_set_id
  where match_row.id = p_match_id
    and fixture.status = 'published'
    and fixture.invalidated_at is null
    and home_participant.status in ('active', 'withdrawn')
    and away_participant.status in ('active', 'withdrawn');
$$;


--
-- Name: FUNCTION tournament_match_team_entries(p_match_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tournament_match_team_entries(p_match_id uuid) IS 'Equipos de un partido del fixture publicado. Incluye participantes retirados: qué equipos integraban el enfrentamiento es un hecho estructural que el retiro no borra. Quién puede operar el partido lo deciden los guards de cada operación.';


--
-- Name: tournament_media_asset_has_internal_consent(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_media_asset_has_internal_consent(p_asset_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select not exists (
    select 1
    from public.tournament_media_relations relation
    join public.tournament_roster_players player
      on player.id = relation.roster_player_id
    where relation.asset_id = p_asset_id
      and relation.relation_type = 'player'
      and (
        not exists (
          select 1
          from public.tournament_media_consents consent
          where consent.asset_id = relation.asset_id
            and consent.use_scope = 'view_internal'
            and (
              consent.roster_player_id = relation.roster_player_id
              or (
                consent.roster_player_id is null
                and player.arma2_user_id is not null
                and consent.subject_user_id = player.arma2_user_id
              )
            )
            and consent.status in ('allowed','not_required')
        )
        or exists (
          select 1
          from public.tournament_media_consents consent
          where consent.asset_id = relation.asset_id
            and consent.use_scope = 'view_internal'
            and (
              consent.roster_player_id = relation.roster_player_id
              or (
                consent.roster_player_id is null
                and player.arma2_user_id is not null
                and consent.subject_user_id = player.arma2_user_id
              )
            )
            and consent.status not in ('allowed','not_required')
        )
      )
  );
$$;


--
-- Name: tournament_media_asset_publication_ready(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_media_asset_publication_ready(p_asset_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  SELECT coalesce((
    SELECT CASE asset.processing_tier
      -- PROCESSOR_EXTERNAL conserva intacto el contrato fuerte: el worker
      -- decodifica, re-encodea, deriva las cuatro renditions y certifica
      -- que cada una quedó sin metadata.
      WHEN 'processor_external' THEN (
        SELECT count(*)
        FROM public.tournament_media_variants variant
        WHERE variant.asset_id = asset.id
          AND variant.kind IN ('thumbnail','grid','detail','original')
          AND variant.status = 'ready'
          AND variant.metadata_stripped
      ) = 4
      -- MVP_SIMPLE no promete variantes: promete UN objeto normalizado,
      -- verificado server-side y sin carriers de metadata. Se le exige
      -- exactamente eso, que es lo que `authorize_tournament_media_read`
      -- ya sirve para las cuatro kinds.
      WHEN 'mvp_simple' THEN
        asset.metadata_stripped IS TRUE
        AND asset.normalization_verified_at IS NOT NULL
        AND asset.storage_state = 'active'
        AND asset.failure_code IS NULL
        AND asset.detected_mime IN ('image/jpeg','image/png','image/webp')
        AND asset.internal_path IS NOT NULL
        AND asset.internal_path <> ''
        AND asset.checksum_sha256 ~ '^[0-9a-f]{64}$'
        AND asset.byte_size BETWEEN 1 AND 4194304
        AND asset.width BETWEEN 1 AND 1600
        AND asset.height BETWEEN 1 AND 1600
      ELSE false
    END
    FROM public.tournament_media_assets asset
    WHERE asset.id = p_asset_id
  ), false);
$_$;


--
-- Name: FUNCTION tournament_media_asset_publication_ready(p_asset_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tournament_media_asset_publication_ready(p_asset_id uuid) IS 'Readiness de procesamiento por asset según su processing_tier. Fail-closed ante tier desconocido. No sustituye moderación ni consentimiento.';


--
-- Name: tournament_media_attestation_rejection(text, jsonb, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_media_attestation_rejection(p_service text, p_capabilities jsonb, p_ttl_seconds integer) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
declare
  v_allowed text[] := public.tournament_media_capability_allowlist(p_service);
  v_caps jsonb;
  v_evidence jsonb;
  v_self_test jsonb;
  v_checks jsonb;
  v_key text;
  v_probed_at timestamp with time zone;
  v_signatures_at timestamp with time zone;
  v_max_ttl integer := case p_service when 'processor' then 900 else 3600 end;
begin
  if v_allowed is null then
    return 'service_unknown';
  end if;
  if p_ttl_seconds is null or p_ttl_seconds < 60 or p_ttl_seconds > v_max_ttl then
    return 'ttl_out_of_range';
  end if;
  if jsonb_typeof(coalesce(p_capabilities,'null'::jsonb)) <> 'object' then
    return 'payload_not_object';
  end if;
  -- No stray top-level keys: the envelope is exactly two members.
  if exists (
    select 1 from jsonb_object_keys(p_capabilities) as envelope_key
    where envelope_key not in ('capabilities','evidence')
  ) then
    return 'envelope_unknown_key';
  end if;

  v_caps := p_capabilities -> 'capabilities';
  v_evidence := p_capabilities -> 'evidence';
  if jsonb_typeof(coalesce(v_caps,'null'::jsonb)) <> 'object'
    or jsonb_typeof(coalesce(v_evidence,'null'::jsonb)) <> 'object'
  then
    return 'envelope_incomplete';
  end if;

  -- Capabilities: allowlisted names, boolean values, nothing else.
  for v_key in select capability_key from jsonb_object_keys(v_caps) as capability_key loop
    if not (v_key = any (v_allowed)) then
      return 'capability_not_allowlisted:' || v_key;
    end if;
    if jsonb_typeof(v_caps -> v_key) <> 'boolean' then
      return 'capability_not_boolean:' || v_key;
    end if;
  end loop;

  -- Backend binding.
  if coalesce(v_evidence->>'backendFingerprint','')
    <> public.tournament_media_backend_fingerprint()
  then
    return 'backend_fingerprint_mismatch';
  end if;

  -- Freshness of the probe itself, independent of the row's own expiry.
  begin
    v_probed_at := (v_evidence->>'probedAt')::timestamp with time zone;
  exception when others then
    v_probed_at := null;
  end;
  if v_probed_at is null
    or v_probed_at > now() + interval '2 minutes'
    or v_probed_at < now() - interval '10 minutes'
  then
    return 'probe_stale';
  end if;

  -- Self-test: it has to exist, it has to have passed, and every capability
  -- claimed true has to name a check that also passed.
  v_self_test := v_evidence -> 'selfTest';
  if jsonb_typeof(coalesce(v_self_test,'null'::jsonb)) <> 'object'
    or coalesce((v_self_test->>'passed')::boolean, false) is not true
  then
    return 'self_test_absent';
  end if;
  v_checks := v_self_test -> 'checks';
  if jsonb_typeof(coalesce(v_checks,'null'::jsonb)) <> 'object' then
    return 'self_test_checks_absent';
  end if;
  for v_key in
    select capability_key from jsonb_object_keys(v_caps) as capability_key
    where coalesce((v_caps ->> capability_key)::boolean, false)
  loop
    if coalesce((v_checks ->> v_key)::boolean, false) is not true then
      return 'self_test_missing_check:' || v_key;
    end if;
  end loop;

  if p_service = 'processor' then
    if not (coalesce(v_evidence->>'workerType','')
      = any (public.tournament_media_worker_type_allowlist()))
    then
      return 'worker_type_not_allowlisted';
    end if;
    -- A pixel tier without a named, versioned codec is a claim, not evidence.
    if coalesce((v_caps->>'pixelDecode')::boolean, false)
      or coalesce((v_caps->>'pixelTranscode')::boolean, false)
    then
      if coalesce(v_evidence#>>'{codec,name}','') !~ '^[a-z0-9][a-z0-9._+-]{1,40}$'
        or coalesce(v_evidence#>>'{codec,version}','') !~ '^[0-9][0-9a-zA-Z._+-]{0,30}$'
      then
        return 'codec_evidence_absent';
      end if;
    end if;
    if coalesce((v_caps->>'antivirusScanning')::boolean, false) then
      if coalesce(v_evidence#>>'{antivirus,name}','') !~ '^[a-z0-9][a-z0-9._+-]{1,40}$'
        or coalesce(v_evidence#>>'{antivirus,version}','') !~ '^[0-9][0-9a-zA-Z._+-]{0,30}$'
      then
        return 'antivirus_evidence_absent';
      end if;
      begin
        v_signatures_at := (v_evidence#>>'{antivirus,signaturesAt}')::timestamp with time zone;
      exception when others then
        v_signatures_at := null;
      end;
      -- Definitions older than a week are treated as no antivirus at all.
      if v_signatures_at is null
        or v_signatures_at > now() + interval '1 day'
        or v_signatures_at < now() - interval '7 days'
      then
        return 'antivirus_signatures_stale';
      end if;
    end if;
  end if;

  return null;
end;
$_$;


--
-- Name: tournament_media_backend_fingerprint(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_media_backend_fingerprint() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select encode(public.digest(
    coalesce((
      select database.oid::text
      from pg_catalog.pg_database database
      where database.datname = pg_catalog.current_database()
    ), 'no-db')
    || ':' || coalesce((
      select class.oid::text
      from pg_catalog.pg_class class
      join pg_catalog.pg_namespace namespace on namespace.oid = class.relnamespace
      where class.relname = 'tournament_media_service_attestations'
        and namespace.nspname = 'public'
    ), 'no-table')
    || ':tournament-media',
    'sha256'
  ), 'hex');
$$;


--
-- Name: FUNCTION tournament_media_backend_fingerprint(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.tournament_media_backend_fingerprint() IS 'Non-sensitive hash of local catalogue identifiers. Binds a service attestation to THIS backend.';


--
-- Name: tournament_media_capability_allowlist(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_media_capability_allowlist(p_service text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_service
    when 'signer' then array[
      'signedUploadUrls','signedReadUrls','derivesPathServerSide'
    ]
    when 'processor' then array[
      'contentSniffing','pixelDecode','pixelTranscode','metadataStrippingApplied',
      'checksumVerification','variantGeneration','antivirusScanning',
      'storageReadWrite','cleanup'
    ]
    else null
  end::text[];
$$;


--
-- Name: tournament_media_current_pipeline_mode(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_media_current_pipeline_mode() RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT CASE
    WHEN count(*) = 1
      AND min(mode) IN ('DISABLED','MVP_SIMPLE','PROCESSOR_EXTERNAL')
    THEN min(mode)
    ELSE 'DISABLED'
  END
  FROM public.tournament_media_pipeline_configuration
  WHERE singleton;
$$;


--
-- Name: tournament_media_effective_readiness(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_media_effective_readiness() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_mode text := public.tournament_media_current_pipeline_mode();
  v_robust jsonb;
  v_storage jsonb := public.tournament_media_storage_contract_status();
  v_storage_ready boolean;
  v_simple_contract boolean;
  v_ready boolean := false;
  v_blockers jsonb := '[]'::jsonb;
BEGIN
  v_storage_ready :=
    coalesce((v_storage->>'bucketPresent')::boolean,false)
    AND coalesce((v_storage->>'bucketPrivate')::boolean,false)
    AND coalesce((v_storage->>'publicUrlDisabled')::boolean,false)
    AND coalesce((v_storage->>'servicePoliciesPresent')::boolean,false)
    AND coalesce((v_storage->>'clientWriteBlocked')::boolean,false);

  v_simple_contract :=
    pg_catalog.to_regprocedure(
      'public.request_tournament_media_upload_session(uuid,text,text,bigint,uuid)'
    ) IS NOT NULL
    AND pg_catalog.to_regprocedure(
      'public.tournament_media_require_upload_tier(text)'
    ) IS NOT NULL
    AND pg_catalog.to_regprocedure(
      'public.tournament_media_mvp_user_can_upload(uuid,uuid)'
    ) IS NOT NULL
    AND pg_catalog.to_regprocedure(
      'public.authorize_tournament_media_upload_target(uuid,text,uuid)'
    ) IS NOT NULL
    AND pg_catalog.to_regprocedure(
      'public.complete_tournament_media_simple_upload(uuid,uuid,text,text,bigint,integer,integer,text,boolean)'
    ) IS NOT NULL
    AND pg_catalog.to_regprocedure(
      'public.fail_tournament_media_upload_session(uuid,text)'
    ) IS NOT NULL;

  IF v_mode = 'PROCESSOR_EXTERNAL' THEN
    v_robust := public.tournament_media_pipeline_readiness();
    RETURN v_robust || jsonb_build_object(
      'mode',v_mode,'processingTier','processor_external',
      'maxSelectedFileBytes',50331648,'maxConcurrentUploads',3,
      'maxEdge',12000,'allowHeicTranscode',true
    );
  ELSIF v_mode = 'MVP_SIMPLE' THEN
    v_ready := v_storage_ready AND v_simple_contract;
    IF NOT coalesce((v_storage->>'bucketPresent')::boolean,false) THEN
      v_blockers := v_blockers || '"storage.bucket_absent"'::jsonb;
    ELSIF NOT coalesce((v_storage->>'bucketPrivate')::boolean,false) THEN
      v_blockers := v_blockers || '"storage.bucket_public"'::jsonb;
    END IF;
    IF NOT coalesce((v_storage->>'servicePoliciesPresent')::boolean,false) THEN
      v_blockers := v_blockers || '"storage.service_policies_absent"'::jsonb;
    END IF;
    IF NOT coalesce((v_storage->>'clientWriteBlocked')::boolean,false) THEN
      v_blockers := v_blockers || '"storage.client_write_open"'::jsonb;
    END IF;
    IF NOT v_simple_contract THEN
      v_blockers := v_blockers || '"simple.contract_absent"'::jsonb;
    END IF;
    RETURN jsonb_build_object(
      'mode',v_mode,'processingTier','mvp_simple',
      'bucket','tournament-media',
      'private',coalesce((v_storage->>'bucketPrivate')::boolean,false),
      'uploadReady',v_ready,
      'storageReady',v_storage_ready,
      'simpleContractReady',v_simple_contract,
      'signerReady',null,'processorReady',null,
      'blockers',v_blockers,
      'storage',v_storage,
      'maxSelectedFileBytes',8388608,'maxFileBytes',4194304,
      'maxPixels',2560000,'maxEdge',1600,
      'maxBatchFiles',10,'maxConcurrentUploads',2,
      'signedUrlTtlSeconds',300,'allowHeicTranscode',false,
      -- These are honest reduced-tier claims, not attestations.
      'pixelTranscode',false,'antivirusScanning',false
    );
  END IF;
  RETURN jsonb_build_object(
    'mode','DISABLED','processingTier',null,
    'bucket','tournament-media','private',true,'uploadReady',false,
    'blockers',jsonb_build_array('pipeline.disabled'),
    'maxSelectedFileBytes',8388608,'maxFileBytes',4194304,
    'maxPixels',2560000,'maxEdge',1600,
    'maxBatchFiles',10,'maxConcurrentUploads',2,
    'signedUrlTtlSeconds',300,'allowHeicTranscode',false,
    'pixelTranscode',false,'antivirusScanning',false
  );
END;
$$;


--
-- Name: tournament_media_gallery_sports_round(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_media_gallery_sports_round(p_gallery_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  SELECT CASE
    WHEN gallery.match_id IS NULL THEN gallery.round_id
    WHEN match_row.id IS NULL THEN NULL
    WHEN gallery.round_id IS NULL THEN match_row.round_id
    WHEN gallery.round_id = match_row.round_id THEN gallery.round_id
    ELSE NULL
  END
  FROM public.tournament_media_galleries gallery
  LEFT JOIN public.tournament_matches match_row
    ON match_row.id = gallery.match_id
   AND match_row.organization_id = gallery.organization_id
   AND match_row.tournament_id = gallery.tournament_id
  WHERE gallery.id = p_gallery_id;
$$;


--
-- Name: tournament_media_known_object_names(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_media_known_object_names(p_organization_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'organizationId',p_organization_id,
    'objectNames',coalesce((
      select jsonb_agg(distinct name) from (
        select variant.internal_path as name
        from public.tournament_media_variants variant
        where variant.organization_id = p_organization_id
        union all
        select session.internal_path
        from public.tournament_media_upload_sessions session
        where session.organization_id = p_organization_id
          and session.status = 'issued'
          and session.expires_at > now()
      ) owned
    ),'[]'::jsonb)
  );
$$;


--
-- Name: tournament_media_mvp_user_can_upload(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_media_mvp_user_can_upload(p_user_id uuid, p_gallery_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_user_id is not null and exists (
    select 1
    from public.tournament_media_galleries gallery
    join public.tournaments tournament
      on tournament.organization_id=gallery.organization_id and tournament.id=gallery.tournament_id
    join public.tournament_organizations organization on organization.id=gallery.organization_id
    join public.tournament_organization_members membership
      on membership.organization_id=gallery.organization_id
     and membership.user_id=p_user_id and membership.status='active'
     and membership.role in ('owner','admin')
    where gallery.id=p_gallery_id and gallery.status in ('draft','under_review')
      and organization.status='active'
      and (membership.role='owner' or exists (
        select 1 from public.tournament_season_member_assignments assignment
        where assignment.organization_id=gallery.organization_id
          and assignment.season_id=tournament.season_id
          and assignment.membership_id=membership.id
      ))
  );
$$;


--
-- Name: tournament_media_pipeline_readiness(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_media_pipeline_readiness() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_storage jsonb := public.tournament_media_storage_contract_status();
  v_signer public.tournament_media_service_attestations%rowtype;
  v_processor public.tournament_media_service_attestations%rowtype;
  v_signer_caps jsonb := '{}'::jsonb;
  v_processor_caps jsonb := '{}'::jsonb;
  v_processor_evidence jsonb := '{}'::jsonb;
  v_processor_present boolean;
  v_storage_ready boolean;
  v_signer_ready boolean;
  v_processor_ready boolean;
  v_pixel_decode boolean;
  v_pixel_transcode boolean;
  v_metadata boolean;
  v_antivirus boolean;
  v_cleanup boolean;
  v_cleanup_contract boolean;
  v_upload_ready boolean;
  v_blockers text[] := array[]::text[];
begin
  select * into v_signer
  from public.tournament_media_service_attestations
  where service = 'signer' and expires_at > now();
  select * into v_processor
  from public.tournament_media_service_attestations
  where service = 'processor' and expires_at > now();

  if v_signer.service is not null then
    v_signer_caps := coalesce(v_signer.capabilities -> 'capabilities', '{}'::jsonb);
  end if;
  v_processor_present := v_processor.service is not null;
  if v_processor_present then
    v_processor_caps := coalesce(v_processor.capabilities -> 'capabilities', '{}'::jsonb);
    v_processor_evidence := coalesce(v_processor.capabilities -> 'evidence', '{}'::jsonb);
  end if;

  v_storage_ready := (v_storage->>'bucketPresent')::boolean
    and (v_storage->>'bucketPrivate')::boolean
    and (v_storage->>'publicUrlDisabled')::boolean
    and (v_storage->>'servicePoliciesPresent')::boolean
    and (v_storage->>'clientWriteBlocked')::boolean;

  v_signer_ready := v_signer.service is not null
    and coalesce((v_signer_caps->>'signedUploadUrls')::boolean, false)
    and coalesce((v_signer_caps->>'signedReadUrls')::boolean, false)
    and coalesce((v_signer_caps->>'derivesPathServerSide')::boolean, false);

  -- Baseline processor duties. The pixel, metadata and antivirus tiers are
  -- separate gates below; none of them may be inferred from this one.
  v_processor_ready := v_processor_present
    and coalesce((v_processor_caps->>'contentSniffing')::boolean, false)
    and coalesce((v_processor_caps->>'checksumVerification')::boolean, false)
    and coalesce((v_processor_caps->>'variantGeneration')::boolean, false)
    and coalesce((v_processor_caps->>'storageReadWrite')::boolean, false)
    and coalesce(v_processor_evidence->>'workerType','')
      = any (public.tournament_media_worker_type_allowlist());

  v_pixel_decode := v_processor_present
    and coalesce((v_processor_caps->>'pixelDecode')::boolean, false);
  v_pixel_transcode := v_processor_present
    and coalesce((v_processor_caps->>'pixelTranscode')::boolean, false);
  v_metadata := v_processor_present
    and coalesce((v_processor_caps->>'metadataStrippingApplied')::boolean, false);
  v_antivirus := v_processor_present
    and coalesce((v_processor_caps->>'antivirusScanning')::boolean, false);

  -- Cleanup needs both halves: the sweeping contracts have to exist in this
  -- database, and the worker has to say it can execute them.
  v_cleanup_contract :=
    pg_catalog.to_regprocedure('public.cleanup_tournament_media_upload_sessions(integer)') is not null
    and pg_catalog.to_regprocedure('public.cleanup_tournament_media_processing_jobs(integer)') is not null;
  v_cleanup := v_cleanup_contract
    and v_processor_present
    and coalesce((v_processor_caps->>'cleanup')::boolean, false);

  if not (v_storage->>'bucketPresent')::boolean then
    v_blockers := v_blockers || 'storage.bucket_absent'::text;
  elsif not (v_storage->>'bucketPrivate')::boolean then
    v_blockers := v_blockers || 'storage.bucket_public'::text;
  end if;
  if not (v_storage->>'servicePoliciesPresent')::boolean then
    v_blockers := v_blockers || 'storage.service_policies_absent'::text;
  end if;
  if not (v_storage->>'clientWriteBlocked')::boolean then
    v_blockers := v_blockers || 'storage.client_write_open'::text;
  end if;
  if not v_signer_ready then
    v_blockers := v_blockers || 'service.signer_unattested'::text;
  end if;
  if not v_processor_ready then
    v_blockers := v_blockers || 'service.processor_unattested'::text;
  end if;
  if not v_pixel_decode then
    v_blockers := v_blockers || 'processor.pixel_decode_absent'::text;
  end if;
  if not v_pixel_transcode then
    v_blockers := v_blockers || 'processor.pixel_transcode_absent'::text;
  end if;
  if not v_metadata then
    v_blockers := v_blockers || 'processor.metadata_sanitization_absent'::text;
  end if;
  if not v_antivirus then
    v_blockers := v_blockers || 'processor.antivirus_absent'::text;
  end if;
  if not v_cleanup then
    v_blockers := v_blockers || 'cleanup.unavailable'::text;
  end if;

  v_upload_ready := v_storage_ready and v_signer_ready and v_processor_ready
    and v_pixel_decode and v_pixel_transcode and v_metadata
    and v_antivirus and v_cleanup;

  return jsonb_build_object(
    'bucket','tournament-media',
    'private',true,
    'uploadReady',v_upload_ready,
    'storageReady',v_storage_ready,
    'signerReady',v_signer_ready,
    'processorReady',v_processor_ready,
    'pixelDecodeReady',v_pixel_decode,
    'pixelTranscodeReady',v_pixel_transcode,
    'metadataSanitizationReady',v_metadata,
    'antivirusReady',v_antivirus,
    'cleanupReady',v_cleanup,
    'blockers',to_jsonb(v_blockers),
    'signer',case when v_signer.service is null then null else jsonb_build_object(
      'release',v_signer.release,'capabilities',v_signer_caps,
      'expiresAt',v_signer.expires_at
    ) end,
    'processor',case when not v_processor_present then null else jsonb_build_object(
      'release',v_processor.release,'capabilities',v_processor_caps,
      'workerType',v_processor_evidence->>'workerType',
      'codec',v_processor_evidence->'codec',
      'antivirus',jsonb_build_object(
        'name',v_processor_evidence#>>'{antivirus,name}',
        'version',v_processor_evidence#>>'{antivirus,version}',
        'signaturesAt',v_processor_evidence#>>'{antivirus,signaturesAt}'
      ),
      'expiresAt',v_processor.expires_at
    ) end,
    'storage',v_storage,
    'maxFileBytes',12582912,'maxPixels',36000000,
    'allowedMime',jsonb_build_array('image/jpeg','image/png','image/webp'),
    'maxBatchFiles',40,'signedUrlTtlSeconds',300,
    -- Kept for the existing projections. Both are now derived, never constants.
    'pixelTranscode',v_pixel_transcode,
    'antivirusScanning',v_antivirus
  );
end;
$$;


--
-- Name: tournament_media_require_pipeline_ready(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_media_require_pipeline_ready() RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not coalesce(
    (public.tournament_media_pipeline_readiness()->>'uploadReady')::boolean, false
  ) then
    raise exception using errcode = '55000',
      message = 'TORNEOS_MEDIA_PIPELINE_NOT_READY';
  end if;
end;
$$;


--
-- Name: tournament_media_require_upload_tier(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_media_require_upload_tier(p_processing_tier text) RETURNS void
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE
  v_mode text := public.tournament_media_current_pipeline_mode();
BEGIN
  IF p_processing_tier = 'processor_external' THEN
    IF v_mode <> 'PROCESSOR_EXTERNAL'
      OR NOT coalesce(
        (public.tournament_media_pipeline_readiness()->>'uploadReady')::boolean,false
      )
    THEN
      RAISE EXCEPTION USING errcode = '55000',
        message = 'TORNEOS_MEDIA_PIPELINE_NOT_READY';
    END IF;
  ELSIF p_processing_tier = 'mvp_simple' THEN
    IF v_mode <> 'MVP_SIMPLE'
      OR NOT coalesce(
        (public.tournament_media_effective_readiness()->>'uploadReady')::boolean,false
      )
    THEN
      RAISE EXCEPTION USING errcode = '55000',
        message = 'TORNEOS_MEDIA_PIPELINE_NOT_READY';
    END IF;
  ELSE
    RAISE EXCEPTION USING errcode = '55000',
      message = 'TORNEOS_MEDIA_PIPELINE_NOT_READY';
  END IF;
END;
$$;


--
-- Name: tournament_media_role_capabilities(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_media_role_capabilities(p_role text) RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_role
    when 'owner' then array[
      'media.read','media.create_gallery','media.update_gallery','media.upload',
      'media.review','media.publish','media.archive','media.revoke',
      'media.set_cover','media.tag_team','media.tag_player',
      'media.manage_consent','media.handle_reports'
    ]::text[]
    when 'admin' then array[
      'media.read','media.create_gallery','media.update_gallery','media.upload',
      'media.review','media.publish','media.archive','media.revoke',
      'media.set_cover','media.tag_team','media.tag_player',
      'media.manage_consent','media.handle_reports'
    ]::text[]
    when 'collaborator' then array['media.read']::text[]
    else array[]::text[]
  end;
$$;


--
-- Name: tournament_media_storage_contract_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_media_storage_contract_status() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  v_schema_present boolean := to_regclass('storage.buckets') is not null;
  v_bucket_present boolean := false;
  v_bucket_private boolean := false;
  v_public_url_disabled boolean := false;
  v_policy_names text[] := array[]::text[];
  v_write_open_to_clients boolean := false;
begin
  if v_schema_present then
    execute $q$
      select
        count(*) > 0,
        coalesce(bool_and(not bucket.public), false),
        coalesce(bool_and(not bucket.public), false)
      from storage.buckets bucket
      where bucket.id = 'tournament-media'
    $q$ into v_bucket_present, v_bucket_private, v_public_url_disabled;

    execute $q$
      select coalesce(array_agg(policy.policyname::text order by policy.policyname), array[]::text[])
      from pg_policies policy
      where policy.schemaname = 'storage'
        and policy.tablename = 'objects'
        and policy.policyname like 'tournament_media_%'
    $q$ into v_policy_names;

    -- Any policy on storage.objects that names the bucket and is granted to a
    -- client role is a contract violation, whoever created it.
    execute $q$
      select exists (
        select 1
        from pg_policies policy
        where policy.schemaname = 'storage'
          and policy.tablename = 'objects'
          and policy.cmd <> 'SELECT'
          and (policy.roles && array['anon','authenticated','public']::name[])
          and coalesce(policy.qual, '') || coalesce(policy.with_check, '')
            like '%tournament-media%'
      )
    $q$ into v_write_open_to_clients;
  end if;

  return jsonb_build_object(
    'bucket','tournament-media',
    'storageSchemaPresent',v_schema_present,
    'bucketPresent',v_bucket_present,
    'bucketPrivate',v_bucket_private,
    'publicUrlDisabled',v_public_url_disabled,
    'servicePoliciesPresent',(
      v_policy_names @> array[
        'tournament_media_service_read',
        'tournament_media_service_insert',
        'tournament_media_service_update',
        'tournament_media_service_delete'
      ]::text[]
    ),
    'clientWriteBlocked',not v_write_open_to_clients,
    'policies',to_jsonb(v_policy_names)
  );
end;
$_$;


--
-- Name: tournament_media_user_can_upload(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_media_user_can_upload(p_user_id uuid, p_gallery_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select p_user_id is not null and exists (
    select 1
    from public.tournament_media_galleries gallery
    join public.tournaments tournament
      on tournament.organization_id=gallery.organization_id and tournament.id=gallery.tournament_id
    join public.tournament_organizations organization on organization.id=gallery.organization_id
    where gallery.id=p_gallery_id and gallery.status in ('draft','under_review')
      and organization.status='active' and (
        exists (
          select 1 from public.tournament_organization_members membership
          where membership.organization_id=gallery.organization_id
            and membership.user_id=p_user_id and membership.status='active'
            and 'media.upload'=any(public.tournament_media_role_capabilities(membership.role))
            and (membership.role='owner' or exists (
              select 1 from public.tournament_season_member_assignments assignment
              where assignment.organization_id=gallery.organization_id
                and assignment.season_id=tournament.season_id
                and assignment.membership_id=membership.id
            ))
        )
        or exists (
          select 1 from public.tournament_media_assignments assignment
          where assignment.gallery_id=gallery.id and assignment.user_id=p_user_id
            and assignment.status='active' and assignment.can_upload
        )
      )
  );
$$;


--
-- Name: tournament_media_variant_box(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_media_variant_box(p_kind text) RETURNS integer
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select case p_kind
    when 'thumbnail' then 320
    when 'grid' then 800
    when 'detail' then 1600
    else null
  end;
$$;


--
-- Name: tournament_media_variant_geometry(text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_media_variant_geometry(p_kind text, p_width integer, p_height integer) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare
  v_box integer := public.tournament_media_variant_box(p_kind);
  v_longest integer;
  v_width integer;
  v_height integer;
begin
  if p_kind = 'original' then
    return jsonb_build_object('kind','original','width',p_width,'height',p_height);
  end if;
  if v_box is null or p_width is null or p_height is null
    or p_width < 1 or p_height < 1
  then
    return null;
  end if;
  v_longest := greatest(p_width, p_height);
  if v_longest <= v_box then
    v_width := p_width;
    v_height := p_height;
  else
    -- floor(x + 0.5) so PostgreSQL, JavaScript and TypeScript agree bit for bit.
    v_width := greatest(1, floor((p_width::numeric * v_box) / v_longest + 0.5)::integer);
    v_height := greatest(1, floor((p_height::numeric * v_box) / v_longest + 0.5)::integer);
  end if;
  return jsonb_build_object('kind',p_kind,'width',v_width,'height',v_height);
end;
$$;


--
-- Name: tournament_media_variant_plan(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_media_variant_plan(p_width integer, p_height integer) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select coalesce(jsonb_agg(
    public.tournament_media_variant_geometry(kind, p_width, p_height)
    order by ordinality
  ), '[]'::jsonb)
  from unnest(array['thumbnail','grid','detail']::text[])
    with ordinality as variant(kind, ordinality);
$$;


