CREATE FUNCTION public.tournament_media_worker_type_allowlist() RETURNS text[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
  select array['external_image_worker']::text[];
$$;


--
-- Name: tournament_projection_source_fingerprint(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_projection_source_fingerprint(p_fixture_version_id uuid, p_phase_id uuid, p_group_id uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
  with fixture_context as (
    select fixture.*
    from public.tournament_fixture_versions fixture
    where fixture.id = p_fixture_version_id
  ), phase_context as (
    select phase.*
    from public.tournament_phases phase
    where phase.id = p_phase_id
      and phase.fixture_version_id = p_fixture_version_id
  ), official_operations as (
    select match_row.match_number, match_row.phase_id, match_row.group_id,
      operation.id, operation.match_id, operation.operation_version,
      operation.official_at, outcome.outcome_type, outcome.events_remain_valid,
      outcome.counts_for_standings, outcome.counts_for_player_stats,
      outcome.requires_resolution, outcome.administrative_home_score,
      outcome.administrative_away_score, outcome.reason_code,
      score.home_score, score.away_score, score.home_penalties,
      score.away_penalties, score.score_type
    from public.tournament_matches match_row
    join phase_context selected_phase on true
    join public.tournament_phases match_phase
      on match_phase.id = match_row.phase_id
    join public.tournament_match_operations operation
      on operation.match_id = match_row.id and operation.status = 'official'
    join public.tournament_match_outcomes outcome
      on outcome.match_operation_id = operation.id
    left join public.tournament_match_scores score
      on score.match_operation_id = operation.id
    where match_row.fixture_version_id = p_fixture_version_id
      and (
        (
          match_row.phase_id = p_phase_id
          and match_row.group_id is not distinct from p_group_id
        )
        or match_phase.sequence_number < selected_phase.sequence_number
      )
  )
  select encode(public.digest(
    jsonb_build_object(
      'operations', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', operation.id,
          'matchId', operation.match_id,
          'matchNumber', operation.match_number,
          'phaseId', operation.phase_id,
          'groupId', operation.group_id,
          'version', operation.operation_version,
          'officialEpoch', extract(epoch from operation.official_at)::numeric,
          'outcome', operation.outcome_type,
          'eventsRemainValid', operation.events_remain_valid,
          'countsForStandings', operation.counts_for_standings,
          'countsForPlayerStats', operation.counts_for_player_stats,
          'requiresResolution', operation.requires_resolution,
          'administrativeHomeScore', operation.administrative_home_score,
          'administrativeAwayScore', operation.administrative_away_score,
          'reasonCode', operation.reason_code,
          'homeScore', operation.home_score,
          'awayScore', operation.away_score,
          'homePenalties', operation.home_penalties,
          'awayPenalties', operation.away_penalties,
          'scoreType', operation.score_type
        ) order by operation.match_number, operation.id)
        from official_operations operation
      ), '[]'::jsonb),
      'operationPlayers', coalesce((
        select jsonb_agg(jsonb_build_object(
          'operationId', player.match_operation_id,
          'rosterPlayerId', player.roster_player_id,
          'teamEntryId', player.team_entry_id,
          'lineup', player.lineup_status,
          'attendance', player.attendance_status,
          'captain', player.is_captain
        ) order by player.match_operation_id, player.team_entry_id, player.roster_player_id)
        from public.tournament_match_operation_players player
        join official_operations operation
          on operation.id = player.match_operation_id
      ), '[]'::jsonb),
      'events', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', event.id,
          'operationId', event.match_operation_id,
          'matchId', event.match_id,
          'teamEntryId', event.team_entry_id,
          'rosterPlayerId', event.roster_player_id,
          'relatedRosterPlayerId', event.related_roster_player_id,
          'relatedEventId', event.related_event_id,
          'type', event.event_type,
          'minute', event.minute,
          'period', event.period,
          'sequence', event.sequence_number,
          'metadata', event.metadata
        ) order by event.match_operation_id, event.sequence_number, event.id)
        from public.tournament_match_events event
        join official_operations operation
          on operation.id = event.match_operation_id
        where event.voided_at is null
      ), '[]'::jsonb),
      'participants', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', participant.id,
          'teamEntryId', participant.team_entry_id,
          'status', participant.status
        ) order by participant.id)
        from fixture_context fixture
        join public.tournament_competition_participants participant
          on participant.participant_set_id = fixture.participant_set_id
        where p_group_id is null or exists (
          select 1
          from public.tournament_group_members member
          where member.group_id = p_group_id
            and member.participant_id = participant.id
        )
      ), '[]'::jsonb),
      'pointsAdjustments', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', adjustment.id,
          'participantId', adjustment.participant_id,
          'points', adjustment.points,
          'status', adjustment.status,
          'reason', adjustment.reason
        ) order by adjustment.id)
        from fixture_context fixture
        join public.tournament_points_adjustments adjustment
          on adjustment.fixture_version_id = fixture.id
        where adjustment.phase_id = p_phase_id
          and adjustment.group_id is not distinct from p_group_id
      ), '[]'::jsonb),
      'disciplinaryOverrides', coalesce((
        select jsonb_agg(jsonb_build_object(
          'id', override_row.id,
          'suspensionId', override_row.suspension_id,
          'action', override_row.action,
          'newState', override_row.new_state,
          'createdEpoch', extract(epoch from override_row.created_at)::numeric
        ) order by override_row.created_at, override_row.id)
        from fixture_context fixture
        join public.tournament_disciplinary_overrides override_row
          on override_row.organization_id = fixture.organization_id
          and override_row.tournament_id = fixture.tournament_id
      ), '[]'::jsonb),
      'scoring', (
        select to_jsonb(scoring) - 'created_at' - 'updated_at'
        from fixture_context fixture
        join public.tournament_scoring_rules scoring
          on scoring.tournament_id = fixture.tournament_id
      ),
      'tiebreaks', coalesce((
        select jsonb_agg(jsonb_build_object(
          'criterion', rule.criterion,
          'order', rule.sort_order
        ) order by rule.sort_order, rule.criterion)
        from fixture_context fixture
        join public.tournament_tiebreak_rules rule
          on rule.tournament_id = fixture.tournament_id
      ), '[]'::jsonb),
      'discipline', (
        select to_jsonb(discipline) - 'created_at' - 'updated_at'
        from fixture_context fixture
        join public.tournament_discipline_rules discipline
          on discipline.tournament_id = fixture.tournament_id
      ),
      'algorithmVersion', 2
    )::text,
    'sha256'
  ), 'hex');
$$;


SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: tournament_purchases; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tournament_purchases (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    tournament_id uuid,
    buyer_user_id uuid NOT NULL,
    product_code text NOT NULL,
    offer_code text NOT NULL,
    offer_version integer NOT NULL,
    list_amount_snapshot integer NOT NULL,
    amount_snapshot integer NOT NULL,
    currency text NOT NULL,
    provider text NOT NULL,
    provider_environment text NOT NULL,
    provider_preference_id text,
    approved_provider_payment_id text,
    external_reference text NOT NULL,
    idempotency_key uuid NOT NULL,
    status text DEFAULT 'created'::text NOT NULL,
    provider_status text,
    provider_status_detail text,
    preference_expires_at timestamp with time zone,
    last_verified_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    approved_at timestamp with time zone,
    cancelled_at timestamp with time zone,
    refunded_at timestamp with time zone,
    charged_back_at timestamp with time zone,
    activation_attempts integer DEFAULT 0 NOT NULL,
    activation_error_code text,
    entitlement_activated_at timestamp with time zone,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    season_id uuid NOT NULL,
    CONSTRAINT tournament_purchases_activation_attempts_check CHECK ((activation_attempts >= 0)),
    CONSTRAINT tournament_purchases_amount_check CHECK (((list_amount_snapshot > 0) AND (amount_snapshot > 0) AND (amount_snapshot <= list_amount_snapshot))),
    CONSTRAINT tournament_purchases_currency_check CHECK ((currency = 'ARS'::text)),
    CONSTRAINT tournament_purchases_environment_check CHECK ((provider_environment = ANY (ARRAY['local'::text, 'qa'::text]))),
    CONSTRAINT tournament_purchases_external_reference_check CHECK ((external_reference ~ '^arma2:(tournament|season):purchase:[0-9a-f-]{36}$'::text)),
    CONSTRAINT tournament_purchases_metadata_check CHECK (((jsonb_typeof(metadata) = 'object'::text) AND (pg_column_size(metadata) <= 2048))),
    CONSTRAINT tournament_purchases_provider_check CHECK ((provider = 'FAKE'::text)),
    CONSTRAINT tournament_purchases_provider_detail_check CHECK (((provider_status IS NULL) OR ((char_length(provider_status) >= 2) AND (char_length(provider_status) <= 80)))),
    CONSTRAINT tournament_purchases_status_check CHECK ((status = ANY (ARRAY['created'::text, 'preference_created'::text, 'pending'::text, 'approved'::text, 'rejected'::text, 'cancelled'::text, 'expired'::text, 'refunded'::text, 'charged_back'::text])))
);


--
-- Name: TABLE tournament_purchases; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tournament_purchases IS 'Private payment workflow. Snapshots are immutable; effective Premium is resolved from grants, never this table.';


--
-- Name: COLUMN tournament_purchases.tournament_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tournament_purchases.tournament_id IS 'Historical competition target only. NULL for purchases created after season billing.';


--
-- Name: COLUMN tournament_purchases.season_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tournament_purchases.season_id IS 'Commercial target. Mandatory for historical and new purchases.';


--
-- Name: tournament_purchase_projection(public.tournament_purchases); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_purchase_projection(p_purchase public.tournament_purchases) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select jsonb_build_object(
    'schemaVersion',3,'id',p_purchase.id,
    'organizationId',p_purchase.organization_id,'seasonId',p_purchase.season_id,
    'tournamentId',p_purchase.tournament_id,'productCode',p_purchase.product_code,
    'offerCode',p_purchase.offer_code,'offerVersion',p_purchase.offer_version,
    'listAmount',p_purchase.list_amount_snapshot,'amount',p_purchase.amount_snapshot,
    'currency',p_purchase.currency,'provider',p_purchase.provider,
    'providerEnvironment',p_purchase.provider_environment,
    'providerPreferenceId',p_purchase.provider_preference_id,
    'externalReference',p_purchase.external_reference,'status',p_purchase.status,
    'providerStatus',p_purchase.provider_status,
    'providerStatusDetail',p_purchase.provider_status_detail,
    'preferenceExpiresAt',p_purchase.preference_expires_at,
    'approvedAt',p_purchase.approved_at,
    'entitlementActivatedAt',p_purchase.entitlement_activated_at,
    'activationErrorCode',p_purchase.activation_error_code,
    'createdAt',p_purchase.created_at,'updatedAt',p_purchase.updated_at
  );
$$;


--
-- Name: tournament_registration_checklist(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_registration_checklist(p_organization_id uuid, p_tournament_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_tournament public.tournaments%rowtype;
  v_errors text[] := array[]::text[];
  v_warnings text[] := array[]::text[];
  v_category_count integer;
  v_tiebreak_count integer;
  v_tiebreak_min smallint;
  v_tiebreak_max smallint;
  v_has_scoring boolean;
  v_has_discipline boolean;
  v_season_valid boolean;
  v_has_fair_play_tiebreak boolean;
  v_fair_play_enabled boolean;
begin
  if private.current_identity_id() is null
    or not public.has_tournament_organization_capability(
      p_organization_id,
      'tournaments.read'
    )
  then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  select tournament.*
  into v_tournament
  from public.tournaments tournament
  where tournament.id = p_tournament_id
    and tournament.organization_id = p_organization_id
    and tournament.status <> 'archived';

  if v_tournament.id is null then
    raise exception using errcode = '42501', message = 'TORNEOS_RESOURCE_FORBIDDEN';
  end if;

  select exists (
    select 1
    from public.tournament_seasons season
    where season.id = v_tournament.season_id
      and season.organization_id = p_organization_id
      and season.status <> 'archived'
  ) into v_season_valid;

  select count(*) into v_category_count
  from public.tournament_categories category
  where category.organization_id = p_organization_id
    and category.tournament_id = p_tournament_id
    and category.status = 'active';

  select count(*), min(rule.sort_order), max(rule.sort_order)
  into v_tiebreak_count, v_tiebreak_min, v_tiebreak_max
  from public.tournament_tiebreak_rules rule
  where rule.organization_id = p_organization_id
    and rule.tournament_id = p_tournament_id;

  select exists (
    select 1
    from public.tournament_tiebreak_rules rule
    where rule.organization_id = p_organization_id
      and rule.tournament_id = p_tournament_id
      and rule.criterion = 'fair_play'
  ) into v_has_fair_play_tiebreak;

  select exists(
    select 1 from public.tournament_scoring_rules rule
    where rule.organization_id = p_organization_id
      and rule.tournament_id = p_tournament_id
  ) into v_has_scoring;

  select exists(
    select 1
    from public.tournament_discipline_rules rule
    where rule.organization_id = p_organization_id
      and rule.tournament_id = p_tournament_id
  ) into v_has_discipline;

  select coalesce(bool_or(rule.fair_play_enabled), false)
  into v_fair_play_enabled
  from public.tournament_discipline_rules rule
  where rule.organization_id = p_organization_id
    and rule.tournament_id = p_tournament_id;

  if not v_season_valid then
    v_errors := array_append(v_errors, 'season');
  end if;
  if char_length(v_tournament.name) < 3 then
    v_errors := array_append(v_errors, 'name');
  end if;
  if v_tournament.sport_modality is null then
    v_errors := array_append(v_errors, 'sport_modality');
  end if;
  if v_tournament.competition_format is null
    or not public.is_valid_tournament_format_settings(
      v_tournament.competition_format,
      v_tournament.format_settings
    )
  then
    v_errors := array_append(v_errors, 'competition_format');
  end if;
  if v_tournament.start_date is not null
    and v_tournament.end_date is not null
    and v_tournament.end_date < v_tournament.start_date
  then
    v_errors := array_append(v_errors, 'dates');
  end if;
  if v_category_count < 1 then
    v_errors := array_append(v_errors, 'categories');
  end if;
  if not v_has_scoring then
    v_errors := array_append(v_errors, 'scoring');
  end if;
  if v_tiebreak_count < 1
    or v_tiebreak_min <> 1
    or v_tiebreak_max <> v_tiebreak_count
  then
    v_errors := array_append(v_errors, 'tiebreaks');
  end if;
  if not v_has_discipline
    or (v_has_fair_play_tiebreak and not v_fair_play_enabled)
  then
    v_errors := array_append(v_errors, 'discipline');
  end if;
  if v_tournament.start_date is null then
    v_warnings := array_append(v_warnings, 'start_date');
  end if;
  if v_tournament.registration_opens_at is null
    or v_tournament.registration_closes_at is null
  then
    v_warnings := array_append(v_warnings, 'registration_dates');
  end if;

  return jsonb_build_object(
    'ready', cardinality(v_errors) = 0,
    'errors', to_jsonb(v_errors),
    'warnings', to_jsonb(v_warnings),
    'checks', jsonb_build_object(
      'information', char_length(v_tournament.name) >= 3,
      'season', v_season_valid,
      'modality', v_tournament.sport_modality is not null,
      'format', public.is_valid_tournament_format_settings(
        v_tournament.competition_format,
        v_tournament.format_settings
      ),
      'categories', v_category_count > 0,
      'scoring', v_has_scoring,
      'tiebreaks', (
        v_tiebreak_count > 0
        and v_tiebreak_min = 1
        and v_tiebreak_max = v_tiebreak_count
      ),
      'discipline', (
        v_has_discipline
        and (not v_has_fair_play_tiebreak or v_fair_play_enabled)
      )
    )
  );
end;
$$;


