-- Name: tournament_role_capabilities(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.tournament_role_capabilities(p_role text) RETURNS text[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
