    CONSTRAINT tournament_announcements_audience_snapshot_check CHECK (((audience_snapshot IS NULL) OR ((jsonb_typeof(audience_snapshot) = 'object'::text) AND (pg_column_size(audience_snapshot) <= 16384)))),
    CONSTRAINT tournament_announcements_content_check CHECK (((title = btrim(title)) AND ((char_length(title) >= 4) AND (char_length(title) <= 120)) AND (summary = btrim(summary)) AND ((char_length(summary) >= 4) AND (char_length(summary) <= 280)) AND (body = btrim(body)) AND ((char_length(body) >= 4) AND (char_length(body) <= 12000)) AND (title !~ '[<>]'::text) AND (summary !~ '[<>]'::text) AND (body !~ '[<>]'::text))),
    CONSTRAINT tournament_announcements_priority_check CHECK ((priority = ANY (ARRAY['normal'::text, 'important'::text, 'urgent'::text]))),
    CONSTRAINT tournament_announcements_recipient_count_check CHECK (((published_recipient_count IS NULL) OR ((published_recipient_count >= 0) AND (published_recipient_count <= 5000)))),
    CONSTRAINT tournament_announcements_schedule_check CHECK ((((status <> 'scheduled'::text) OR (scheduled_for IS NOT NULL)) AND ((published_at IS NULL) OR (status = ANY (ARRAY['published'::text, 'superseded'::text, 'archived'::text, 'revoked'::text]))) AND ((archived_at IS NULL) OR (status = 'archived'::text)) AND ((revoked_at IS NULL) OR (status = 'revoked'::text)) AND ((revoked_reason IS NULL) OR ((char_length(btrim(revoked_reason)) >= 4) AND (char_length(btrim(revoked_reason)) <= 500))))),
    CONSTRAINT tournament_announcements_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'scheduled'::text, 'published'::text, 'superseded'::text, 'archived'::text, 'cancelled'::text, 'revoked'::text]))),
    CONSTRAINT tournament_announcements_type_check CHECK ((announcement_type = ANY (ARRAY['general'::text, 'registration'::text, 'schedule_change'::text, 'match_update'::text, 'discipline'::text, 'regulation'::text, 'administrative'::text, 'emergency'::text]))),
    CONSTRAINT tournament_announcements_version_check CHECK ((version > 0))
);


