    CONSTRAINT tournament_match_operations_match_status_check CHECK ((match_status = ANY (ARRAY['ready'::text, 'in_progress'::text, 'suspended'::text, 'abandoned'::text, 'played'::text, 'awaiting_validation'::text, 'official'::text, 'administrative'::text, 'voided'::text]))),
    CONSTRAINT tournament_match_operations_notes_check CHECK (((notes IS NULL) OR (char_length(notes) <= 4000))),
    CONSTRAINT tournament_match_operations_snapshot_check CHECK (((jsonb_typeof(match_snapshot) = 'object'::text) AND (jsonb_typeof(home_team_snapshot) = 'object'::text) AND (jsonb_typeof(away_team_snapshot) = 'object'::text) AND (pg_column_size(match_snapshot) <= 16384) AND (pg_column_size(home_team_snapshot) <= 8192) AND (pg_column_size(away_team_snapshot) <= 8192))),
    CONSTRAINT tournament_match_operations_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'submitted'::text, 'under_review'::text, 'validated'::text, 'official'::text, 'correction_requested'::text, 'superseded'::text, 'voided'::text]))),
