    CONSTRAINT tournament_match_scores_values_check CHECK ((((home_score >= 0) AND (home_score <= 99)) AND ((away_score >= 0) AND (away_score <= 99)) AND ((home_score_first_half IS NULL) OR ((home_score_first_half >= 0) AND (home_score_first_half <= home_score))) AND ((away_score_first_half IS NULL) OR ((away_score_first_half >= 0) AND (away_score_first_half <= away_score))) AND ((home_penalties IS NULL) OR ((home_penalties >= 0) AND (home_penalties <= 99))) AND ((away_penalties IS NULL) OR ((away_penalties >= 0) AND (away_penalties <= 99)))))
);


--
-- Name: tournament_match_sources; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tournament_match_sources (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    tournament_id uuid NOT NULL,
    category_id uuid NOT NULL,
    fixture_version_id uuid NOT NULL,
    match_id uuid NOT NULL,
    side text NOT NULL,
    source_type text NOT NULL,
    participant_id uuid,
    source_match_id uuid,
    group_id uuid,
    source_phase_id uuid,
    source_tie_key text,
    position_number integer,
    seed_number integer,
    rank_number integer,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tournament_match_sources_shape_check CHECK ((((source_type = 'participant'::text) AND (participant_id IS NOT NULL) AND (source_match_id IS NULL) AND (group_id IS NULL) AND (source_phase_id IS NULL) AND (source_tie_key IS NULL) AND (position_number IS NULL) AND (seed_number IS NULL) AND (rank_number IS NULL)) OR ((source_type = ANY (ARRAY['winner_of_match'::text, 'loser_of_match'::text])) AND (source_match_id IS NOT NULL) AND (participant_id IS NULL) AND (group_id IS NULL) AND (source_phase_id IS NULL) AND (source_tie_key IS NULL) AND (position_number IS NULL) AND (seed_number IS NULL) AND (rank_number IS NULL)) OR ((source_type = ANY (ARRAY['winner_of_tie'::text, 'loser_of_tie'::text])) AND (source_tie_key IS NOT NULL) AND ((char_length(source_tie_key) >= 3) AND (char_length(source_tie_key) <= 200)) AND (participant_id IS NULL) AND (source_match_id IS NULL) AND (group_id IS NULL) AND (source_phase_id IS NULL) AND (position_number IS NULL) AND (seed_number IS NULL) AND (rank_number IS NULL)) OR ((source_type = 'group_position'::text) AND (group_id IS NOT NULL) AND (position_number > 0) AND (participant_id IS NULL) AND (source_match_id IS NULL) AND (source_phase_id IS NULL) AND (source_tie_key IS NULL) AND (seed_number IS NULL) AND (rank_number IS NULL)) OR ((source_type = 'league_position'::text) AND (source_phase_id IS NOT NULL) AND (rank_number > 0) AND (participant_id IS NULL) AND (source_match_id IS NULL) AND (group_id IS NULL) AND (source_tie_key IS NULL) AND (position_number IS NULL) AND (seed_number IS NULL)) OR ((source_type = 'seed'::text) AND (seed_number > 0) AND (participant_id IS NULL) AND (source_match_id IS NULL) AND (group_id IS NULL) AND (source_phase_id IS NULL) AND (source_tie_key IS NULL) AND (position_number IS NULL) AND (rank_number IS NULL)) OR ((source_type = 'bye'::text) AND (participant_id IS NULL) AND (source_match_id IS NULL) AND (group_id IS NULL) AND (source_phase_id IS NULL) AND (source_tie_key IS NULL) AND (position_number IS NULL) AND (seed_number IS NULL) AND (rank_number IS NULL)))),
    CONSTRAINT tournament_match_sources_side_check CHECK ((side = ANY (ARRAY['home'::text, 'away'::text]))),
    CONSTRAINT tournament_match_sources_type_check CHECK ((source_type = ANY (ARRAY['participant'::text, 'winner_of_match'::text, 'loser_of_match'::text, 'winner_of_tie'::text, 'loser_of_tie'::text, 'group_position'::text, 'league_position'::text, 'seed'::text, 'bye'::text])))
);


