    CONSTRAINT tournament_matches_duration_check CHECK (((duration_minutes IS NULL) OR ((duration_minutes >= 15) AND (duration_minutes <= 240)))),
    CONSTRAINT tournament_matches_leg_check CHECK ((leg_number = ANY (ARRAY[1, 2]))),
    CONSTRAINT tournament_matches_lifecycle_check CHECK ((((status = 'cancelled'::text) AND (cancelled_at IS NOT NULL)) OR ((status <> 'cancelled'::text) AND (cancelled_at IS NULL)))),
    CONSTRAINT tournament_matches_number_check CHECK ((match_number > 0)),
    CONSTRAINT tournament_matches_participants_check CHECK (((home_participant_id IS NULL) OR (away_participant_id IS NULL) OR (home_participant_id <> away_participant_id))),
    CONSTRAINT tournament_matches_schedule_fields_check CHECK ((((scheduled_at IS NULL) AND (venue_id IS NULL) AND (court_id IS NULL)) OR ((scheduled_at IS NOT NULL) AND (venue_id IS NOT NULL) AND (court_id IS NOT NULL) AND (duration_minutes IS NOT NULL)))),
    CONSTRAINT tournament_matches_status_check CHECK ((status = ANY (ARRAY['draft'::text, 'unscheduled'::text, 'scheduled'::text, 'postponed'::text, 'cancelled'::text, 'ready'::text])))
);


