    metadata_stripped boolean,
    normalization_verified_at timestamp with time zone,
    CONSTRAINT tournament_media_assets_checksum_check CHECK ((checksum_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT tournament_media_assets_dimensions_check CHECK ((((width >= 1) AND (width <= 12000)) AND ((height >= 1) AND (height <= 12000)) AND (((width)::bigint * (height)::bigint) <= 36000000))),
    CONSTRAINT tournament_media_assets_failure_check CHECK (((failure_code IS NULL) OR (failure_code ~ '^[A-Z][A-Z0-9_]{2,80}$'::text))),
    CONSTRAINT tournament_media_assets_mime_check CHECK ((detected_mime = ANY (ARRAY['image/jpeg'::text, 'image/png'::text, 'image/webp'::text]))),
    CONSTRAINT tournament_media_assets_mvp_limits_check CHECK (((processing_tier <> 'mvp_simple'::text) OR (((byte_size >= 1) AND (byte_size <= 4194304)) AND ((width >= 1) AND (width <= 1600)) AND ((height >= 1) AND (height <= 1600)) AND (((width)::bigint * (height)::bigint) <= 2560000)))),
    CONSTRAINT tournament_media_assets_path_check CHECK (((internal_path ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}\.(jpg|png|webp)$'::text) AND (internal_path !~~ '%..%'::text))),
    CONSTRAINT tournament_media_assets_processing_tier_check CHECK ((processing_tier = ANY (ARRAY['processor_external'::text, 'mvp_simple'::text]))),
    CONSTRAINT tournament_media_assets_provider_check CHECK (((provider = 'supabase'::text) AND (bucket = 'tournament-media'::text))),
    CONSTRAINT tournament_media_assets_retention_reason_check CHECK (((retention_reason IS NULL) OR ((retention_reason = btrim(retention_reason)) AND ((char_length(retention_reason) >= 8) AND (char_length(retention_reason) <= 240))))),
    CONSTRAINT tournament_media_assets_safe_name_check CHECK ((safe_name ~ '^foto-[0-9a-f]{12}\.(jpg|png|webp)$'::text)),
    CONSTRAINT tournament_media_assets_size_check CHECK (((byte_size >= 1) AND (byte_size <= 12582912))),
    CONSTRAINT tournament_media_assets_status_check CHECK ((status = ANY (ARRAY['uploading'::text, 'processing'::text, 'pending_review'::text, 'approved'::text, 'published'::text, 'rejected'::text, 'hidden'::text, 'revoked'::text, 'failed'::text]))),
    CONSTRAINT tournament_media_assets_storage_lifecycle_check CHECK ((((storage_state = 'active'::text) AND (retention_marked_at IS NULL) AND (storage_purged_at IS NULL) AND (retention_reason IS NULL)) OR ((storage_state = 'retention_marked'::text) AND (retention_marked_at IS NOT NULL) AND (storage_purged_at IS NULL) AND (retention_reason IS NOT NULL)) OR ((storage_state = 'storage_purged'::text) AND (retention_marked_at IS NOT NULL) AND (storage_purged_at IS NOT NULL) AND (storage_purged_at >= retention_marked_at) AND (retention_reason IS NOT NULL)))),
    CONSTRAINT tournament_media_assets_storage_state_check CHECK ((storage_state = ANY (ARRAY['active'::text, 'retention_marked'::text, 'storage_purged'::text])))
);


