    CONSTRAINT tournament_media_processing_jobs_path_check CHECK (((quarantine_path ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}\.(jpg|png|webp)$'::text) AND (quarantine_path !~~ '%..%'::text))),
    CONSTRAINT tournament_media_processing_jobs_provider_check CHECK ((bucket = 'tournament-media'::text)),
    CONSTRAINT tournament_media_processing_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'leased'::text, 'succeeded'::text, 'failed'::text, 'abandoned'::text]))),
    CONSTRAINT tournament_media_processing_jobs_worker_check CHECK (((worker_id IS NULL) OR (worker_id ~ '^[a-z0-9][a-z0-9._:-]{2,60}$'::text)))
);


