    CONSTRAINT tournament_media_upload_sessions_path_check CHECK (((internal_path ~ '^[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}/[0-9a-f-]{36}\.(jpg|png|webp)$'::text) AND (internal_path !~~ '%..%'::text))),
