    CONSTRAINT tournament_media_upload_sessions_provider_check CHECK (((provider = 'supabase'::text) AND (bucket = 'tournament-media'::text))),
    CONSTRAINT tournament_media_upload_sessions_quota_check CHECK (((jsonb_typeof(quota_snapshot) = 'object'::text) AND (pg_column_size(quota_snapshot) <= 4096))),
    CONSTRAINT tournament_media_upload_sessions_safe_name_check CHECK ((safe_name ~ '^foto-[0-9a-f]{12}\.(jpg|png|webp)$'::text)),
    CONSTRAINT tournament_media_upload_sessions_size_check CHECK ((((requested_size >= 1) AND (requested_size <= max_size)) AND (max_size <= 12582912))),
    CONSTRAINT tournament_media_upload_sessions_status_check CHECK ((status = ANY (ARRAY['issued'::text, 'uploaded'::text, 'consumed'::text, 'expired'::text, 'revoked'::text, 'failed'::text]))),
    CONSTRAINT tournament_media_upload_sessions_token_check CHECK ((token_hash ~ '^[0-9a-f]{64}$'::text))
);


