-- Name: tournament_player_portraits; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tournament_player_portraits (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    organization_id uuid NOT NULL,
    tournament_id uuid NOT NULL,
    team_entry_id uuid NOT NULL,
    roster_player_id uuid NOT NULL,
    bucket text DEFAULT 'tournament-player-portraits'::text NOT NULL,
    object_path text NOT NULL,
    mime_type text NOT NULL,
    byte_size bigint NOT NULL,
    width integer NOT NULL,
    height integer NOT NULL,
    focal_x numeric(5,4) DEFAULT 0.5 NOT NULL,
    focal_y numeric(5,4) DEFAULT 0.5 NOT NULL,
    editorial_status text DEFAULT 'pending_review'::text NOT NULL,
    publication_consent text DEFAULT 'unknown'::text NOT NULL,
    lifecycle_status text DEFAULT 'upload_pending'::text NOT NULL,
    uploaded_by uuid,
    reviewed_by uuid,
    consent_actor_user_id uuid,
    replaced_by_id uuid,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    reviewed_at timestamp with time zone,
    consent_changed_at timestamp with time zone,
    replaced_at timestamp with time zone,
    removed_at timestamp with time zone,
    storage_purged_at timestamp with time zone,
    crop_zoom numeric(6,4) DEFAULT 1.0 NOT NULL,
    CONSTRAINT tournament_player_portraits_bucket_check CHECK ((bucket = 'tournament-player-portraits'::text)),
    CONSTRAINT tournament_player_portraits_consent_actor_check CHECK ((((publication_consent = 'unknown'::text) AND (consent_changed_at IS NULL)) OR ((publication_consent = ANY (ARRAY['granted'::text, 'revoked'::text])) AND (consent_changed_at IS NOT NULL)))),
    CONSTRAINT tournament_player_portraits_consent_check CHECK ((publication_consent = ANY (ARRAY['unknown'::text, 'granted'::text, 'revoked'::text]))),
    CONSTRAINT tournament_player_portraits_crop_zoom_check CHECK (((crop_zoom >= (1)::numeric) AND (crop_zoom <= (4)::numeric))),
    CONSTRAINT tournament_player_portraits_dimensions_check CHECK ((((width >= 1) AND (width <= 12000)) AND ((height >= 1) AND (height <= 12000)) AND (((width)::bigint * (height)::bigint) <= 36000000))),
    CONSTRAINT tournament_player_portraits_editorial_check CHECK ((editorial_status = ANY (ARRAY['pending_review'::text, 'approved'::text, 'rejected'::text]))),
    CONSTRAINT tournament_player_portraits_focal_check CHECK ((((focal_x >= (0)::numeric) AND (focal_x <= (1)::numeric)) AND ((focal_y >= (0)::numeric) AND (focal_y <= (1)::numeric)))),
    CONSTRAINT tournament_player_portraits_lifecycle_check CHECK ((lifecycle_status = ANY (ARRAY['upload_pending'::text, 'active'::text, 'delete_pending'::text, 'replaced'::text, 'removed'::text, 'upload_failed'::text]))),
    CONSTRAINT tournament_player_portraits_mime_check CHECK ((mime_type = ANY (ARRAY['image/jpeg'::text, 'image/png'::text, 'image/webp'::text]))),
    CONSTRAINT tournament_player_portraits_path_check CHECK ((object_path = (((((('organizations/'::text || (organization_id)::text) || '/roster-players/'::text) || (roster_player_id)::text) || '/'::text) || (id)::text) ||
CASE mime_type
    WHEN 'image/jpeg'::text THEN '.jpg'::text
    WHEN 'image/png'::text THEN '.png'::text
    WHEN 'image/webp'::text THEN '.webp'::text
    ELSE NULL::text
END))),
    CONSTRAINT tournament_player_portraits_remove_check CHECK ((((lifecycle_status = 'removed'::text) AND (removed_at IS NOT NULL) AND (storage_purged_at IS NOT NULL)) OR ((lifecycle_status <> 'removed'::text) AND (removed_at IS NULL)))),
    CONSTRAINT tournament_player_portraits_replace_check CHECK ((((lifecycle_status = 'replaced'::text) AND (replaced_by_id IS NOT NULL) AND (replaced_at IS NOT NULL)) OR ((lifecycle_status <> 'replaced'::text) AND (replaced_at IS NULL)))),
    CONSTRAINT tournament_player_portraits_review_check CHECK ((((editorial_status = 'pending_review'::text) AND (reviewed_by IS NULL) AND (reviewed_at IS NULL)) OR ((editorial_status = ANY (ARRAY['approved'::text, 'rejected'::text])) AND (reviewed_by IS NOT NULL) AND (reviewed_at IS NOT NULL)))),
    CONSTRAINT tournament_player_portraits_size_check CHECK (((byte_size >= 1) AND (byte_size <= 8388608)))
);


