    CONSTRAINT tournament_team_photos_editorial_check CHECK ((editorial_status = ANY (ARRAY['pending_review'::text, 'approved'::text, 'rejected'::text]))),
    CONSTRAINT tournament_team_photos_lifecycle_check CHECK ((lifecycle_status = ANY (ARRAY['upload_pending'::text, 'active'::text, 'delete_pending'::text, 'replaced'::text, 'removed'::text, 'upload_failed'::text]))),
    CONSTRAINT tournament_team_photos_mime_check CHECK ((mime_type = ANY (ARRAY['image/jpeg'::text, 'image/png'::text, 'image/webp'::text]))),
    CONSTRAINT tournament_team_photos_path_check CHECK ((object_path = (((((('organizations/'::text || (organization_id)::text) || '/team-entries/'::text) || (team_entry_id)::text) || '/'::text) || (id)::text) ||
CASE mime_type
    WHEN 'image/jpeg'::text THEN '.jpg'::text
    WHEN 'image/png'::text THEN '.png'::text
    WHEN 'image/webp'::text THEN '.webp'::text
    ELSE NULL::text
END))),
    CONSTRAINT tournament_team_photos_remove_check CHECK ((((lifecycle_status = 'removed'::text) AND (removed_at IS NOT NULL) AND (storage_purged_at IS NOT NULL)) OR ((lifecycle_status <> 'removed'::text) AND (removed_at IS NULL) AND (storage_purged_at IS NULL)))),
    CONSTRAINT tournament_team_photos_replace_check CHECK ((((lifecycle_status = 'replaced'::text) AND (replaced_at IS NOT NULL)) OR ((lifecycle_status <> 'replaced'::text) AND (replaced_at IS NULL) AND (replaced_by_id IS NULL)))),
    CONSTRAINT tournament_team_photos_review_check CHECK ((((editorial_status = 'pending_review'::text) AND (reviewed_by IS NULL) AND (reviewed_at IS NULL) AND (approved_at IS NULL) AND (review_reason IS NULL)) OR ((editorial_status = 'approved'::text) AND (reviewed_by IS NOT NULL) AND (reviewed_at IS NOT NULL) AND (approved_at IS NOT NULL) AND (review_reason IS NULL)) OR ((editorial_status = 'rejected'::text) AND (reviewed_by IS NOT NULL) AND (reviewed_at IS NOT NULL) AND (approved_at IS NULL) AND ((review_reason IS NULL) OR ((review_reason = btrim(review_reason)) AND ((char_length(review_reason) >= 1) AND (char_length(review_reason) <= 500))))))),
    CONSTRAINT tournament_team_photos_revoke_check CHECK ((((revoked_at IS NULL) AND (revoked_by IS NULL)) OR ((revoked_at IS NOT NULL) AND (revoked_by IS NOT NULL) AND (editorial_status = 'approved'::text) AND (lifecycle_status = 'replaced'::text) AND (replaced_by_id IS NULL)))),
    CONSTRAINT tournament_team_photos_size_check CHECK (((byte_size >= 1) AND (byte_size <= 8388608)))
);


--
-- Name: TABLE tournament_team_photos; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tournament_team_photos IS 'Foto grupal del plantel, privada y moderada, propiedad de tournament_team_entries.id. Distinta del escudo: el escudo es marca pública, esto es una fotografía de personas.';


--
-- Name: COLUMN tournament_team_photos.object_path; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tournament_team_photos.object_path IS 'Path interno e inmutable de Storage. Nunca se expone como ImageRef ni se persiste una URL firmada.';


--
-- Name: COLUMN tournament_team_photos.checksum_sha256; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tournament_team_photos.checksum_sha256 IS 'SHA-256 de los bytes efectivamente almacenados, calculado por el Edge function. Obligatorio en todo estado desde el que la fila pueda mostrarse.';


--
-- Name: COLUMN tournament_team_photos.replaced_by_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.tournament_team_photos.replaced_by_id IS 'Qué foto ocupó su lugar. NULL en una revocación: retirar la vigente no promueve ninguna anterior.';


