    organization_id uuid NOT NULL,
    team_entry_id uuid NOT NULL,
    roster_id uuid NOT NULL,
    decision text NOT NULL,
    reason text NOT NULL,
    issues jsonb DEFAULT '[]'::jsonb NOT NULL,
    created_by uuid NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tournament_team_reviews_decision_check CHECK ((decision = ANY (ARRAY['changes_requested'::text, 'approved'::text, 'rejected'::text]))),
    CONSTRAINT tournament_team_reviews_issues_check CHECK ((jsonb_typeof(issues) = 'array'::text)),
    CONSTRAINT tournament_team_reviews_reason_check CHECK (((reason = btrim(reason)) AND ((char_length(reason) >= 3) AND (char_length(reason) <= 1200))))
);


--
-- Name: tournament_team_standings; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tournament_team_standings (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    revision_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    tournament_id uuid NOT NULL,
    category_id uuid NOT NULL,
    phase_id uuid NOT NULL,
    group_id uuid,
    participant_id uuid NOT NULL,
    team_entry_id uuid NOT NULL,
    "position" integer,
    played integer DEFAULT 0 NOT NULL,
    won integer DEFAULT 0 NOT NULL,
    drawn integer DEFAULT 0 NOT NULL,
    lost integer DEFAULT 0 NOT NULL,
    goals_for integer DEFAULT 0 NOT NULL,
    goals_against integer DEFAULT 0 NOT NULL,
    goal_difference integer DEFAULT 0 NOT NULL,
    base_points integer DEFAULT 0 NOT NULL,
    points_adjustment integer DEFAULT 0 NOT NULL,
    points integer DEFAULT 0 NOT NULL,
    walkovers integer DEFAULT 0 NOT NULL,
    administrative_results integer DEFAULT 0 NOT NULL,
    fair_play_points integer DEFAULT 0 NOT NULL,
    classification_status text DEFAULT 'pending'::text NOT NULL,
    tiebreak_trace jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tournament_team_standings_classification_check CHECK ((classification_status = ANY (ARRAY['pending'::text, 'qualified'::text, 'eliminated'::text, 'playoff'::text, 'manual_review'::text]))),
    CONSTRAINT tournament_team_standings_counts_check CHECK (((played >= 0) AND (won >= 0) AND (drawn >= 0) AND (lost >= 0) AND (goals_for >= 0) AND (goals_against >= 0) AND (walkovers >= 0) AND (administrative_results >= 0) AND (fair_play_points >= 0) AND (played = ((won + drawn) + lost)) AND (goal_difference = (goals_for - goals_against)) AND (points = (base_points + points_adjustment)))),
    CONSTRAINT tournament_team_standings_trace_check CHECK (((jsonb_typeof(tiebreak_trace) = 'object'::text) AND (pg_column_size(tiebreak_trace) <= 16384))),
    CONSTRAINT tournament_team_standings_values_check CHECK ((("position" IS NULL) OR ("position" > 0)))
);


--
-- Name: TABLE tournament_team_standings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.tournament_team_standings IS 'Immutable table rows belonging to one standings revision.';


--
-- Name: tournament_team_statistics; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.tournament_team_statistics (
    revision_id uuid NOT NULL,
    organization_id uuid NOT NULL,
    participant_id uuid NOT NULL,
    team_entry_id uuid NOT NULL,
    goals integer DEFAULT 0 NOT NULL,
    own_goals_benefited integer DEFAULT 0 NOT NULL,
    yellow_cards integer DEFAULT 0 NOT NULL,
    second_yellows integer DEFAULT 0 NOT NULL,
    red_cards integer DEFAULT 0 NOT NULL,
    home_played integer DEFAULT 0 NOT NULL,
    away_played integer DEFAULT 0 NOT NULL,
    suspended_matches integer DEFAULT 0 NOT NULL,
    administrative_matches integer DEFAULT 0 NOT NULL,
    recent_form jsonb DEFAULT '[]'::jsonb NOT NULL,
    streak_type text,
    streak_count integer DEFAULT 0 NOT NULL,
    CONSTRAINT tournament_team_statistics_counts_check CHECK (((goals >= 0) AND (own_goals_benefited >= 0) AND (yellow_cards >= 0) AND (second_yellows >= 0) AND (red_cards >= 0) AND (home_played >= 0) AND (away_played >= 0) AND (suspended_matches >= 0) AND (administrative_matches >= 0) AND (streak_count >= 0))),
    CONSTRAINT tournament_team_statistics_form_check CHECK (((jsonb_typeof(recent_form) = 'array'::text) AND (jsonb_array_length(recent_form) <= 5))),
    CONSTRAINT tournament_team_statistics_streak_check CHECK (((streak_type IS NULL) OR (streak_type = ANY (ARRAY['win'::text, 'draw'::text, 'loss'::text, 'unbeaten'::text]))))
);


