    sort_order smallint NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT tournament_tiebreak_rules_criterion_check CHECK ((criterion = ANY (ARRAY['goal_difference'::text, 'goals_for'::text, 'head_to_head'::text, 'matches_won'::text, 'fair_play'::text, 'playoff_match'::text, 'draw'::text]))),
    CONSTRAINT tournament_tiebreak_rules_order_check CHECK (((sort_order >= 1) AND (sort_order <= 7)))
);


